def _portal_raw_connection():

    if USA_DATABASE_CLOUD:

        try:
            import libsql
        except ImportError as errore:
            raise RuntimeError(
                "La modalità Cloud richiede il pacchetto libsql."
            ) from errore

        chiave = "_turso_connessione_raw"

        conn = st.session_state.get(
            chiave
        )

        if conn is None:

            conn = libsql.connect(
                database=TURSO_DATABASE_URL,
                auth_token=TURSO_AUTH_TOKEN
            )

            st.session_state[
                chiave
            ] = conn

        return conn

    return sqlite3.connect(
        DB_PATH
    )


def _portal_close(
    conn
):

    if USA_DATABASE_CLOUD:
        return

    try:
        conn.close()
    except Exception:
        pass


def password_hash_sicuro(
    password
):
    """
    PBKDF2-HMAC-SHA256 con salt casuale.
    Nel DB non viene mai salvata la password in chiaro.
    """

    if len(
        str(
            password
        )
    ) < 8:
        raise ValueError(
            "La password deve contenere almeno 8 caratteri."
        )

    salt = secrets.token_bytes(
        16
    )

    iterazioni = 260000

    digest = hashlib.pbkdf2_hmac(
        "sha256",
        str(
            password
        ).encode(
            "utf-8"
        ),
        salt,
        iterazioni
    )

    return (
        "pbkdf2_sha256"
        + "$"
        + str(
            iterazioni
        )
        + "$"
        + salt.hex()
        + "$"
        + digest.hex()
    )


def verifica_password_sicura(
    password,
    hash_salvato
):

    try:

        algoritmo, iterazioni, salt_hex, digest_hex = (
            str(
                hash_salvato
            ).split(
                "$",
                3
            )
        )

        if algoritmo != "pbkdf2_sha256":
            return False

        digest = hashlib.pbkdf2_hmac(
            "sha256",
            str(
                password
            ).encode(
                "utf-8"
            ),
            bytes.fromhex(
                salt_hex
            ),
            int(
                iterazioni
            )
        )

        return hmac.compare_digest(
            digest.hex(),
            digest_hex
        )

    except Exception:
        return False


@st.cache_resource(show_spinner=False)
def inizializza_portale_auth():
    """
    Schema minimo necessario PRIMA del login.
    Le CREATE TABLE sono eseguite una sola volta per sessione.
    """

    if st.session_state.get(
        "_ml05_portal_schema_ok",
        False
    ):
        return

    conn = _portal_raw_connection()
    cur = conn.cursor()

    try:

        cur.execute("""
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL UNIQUE,
                email TEXT,
                password_hash TEXT,
                is_active INTEGER NOT NULL DEFAULT 1,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS leagues (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                nome TEXT NOT NULL,
                stagione TEXT,
                modalita TEXT NOT NULL DEFAULT 'MANTRA',
                stato TEXT NOT NULL DEFAULT 'DRAFT',
                created_by_user_id INTEGER,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS teams (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER NOT NULL,
                nome TEXT NOT NULL,
                owner_user_id INTEGER,
                posizione INTEGER,
                is_active INTEGER NOT NULL DEFAULT 1,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(league_id, nome)
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS league_members (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                team_id INTEGER,
                is_admin INTEGER NOT NULL DEFAULT 0,
                is_auctioneer INTEGER NOT NULL DEFAULT 0,
                is_team_member INTEGER NOT NULL DEFAULT 1,
                is_active INTEGER NOT NULL DEFAULT 1,
                joined_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(league_id, user_id, team_id)
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS league_rules (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER NOT NULL UNIQUE,
                partecipanti INTEGER NOT NULL DEFAULT 10,
                max_giocatori INTEGER NOT NULL DEFAULT 30,
                min_portieri INTEGER NOT NULL DEFAULT 2,
                budget_iniziale REAL NOT NULL DEFAULT 500,
                incremento_minimo REAL NOT NULL DEFAULT 1,
                soglia_budget REAL NOT NULL DEFAULT 500,
                moltiplicatore_oltre_soglia REAL NOT NULL DEFAULT 3,
                tipo_asta TEXT NOT NULL DEFAULT 'CHIAMATA',
                fonte_listone TEXT NOT NULL DEFAULT 'Fantacalcio.it',
                regolamento_bloccato INTEGER NOT NULL DEFAULT 0,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS audit_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER,
                user_id INTEGER,
                team_id INTEGER,
                azione TEXT NOT NULL,
                entita TEXT,
                entita_id TEXT,
                dettagli_json TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)

        conn.commit()

        st.session_state[
            "_ml05_portal_schema_ok"
        ] = True

    finally:
        _portal_close(
            conn
        )


def autentica_portale(
    username,
    password
):

    username = str(
        username
    ).strip()

    conn = _portal_raw_connection()
    cur = conn.cursor()

    try:

        cur.execute("""
            SELECT
                id,
                username,
                password_hash,
                is_active
            FROM users
            WHERE LOWER(username) = LOWER(?)
            LIMIT 1
        """, (
            username,
        ))

        riga = cur.fetchone()

        if not riga:
            return None

        user_id, username_db, password_hash, is_active = riga

        if int(
            is_active
            or 0
        ) != 1:
            return None

        if not password_hash:
            # Account legacy creati nelle release precedenti:
            # non possono essere autenticati senza una password.
            return {
                "legacy_password_missing":
                    True,

                "username":
                    str(
                        username_db
                    )
            }

        if not verifica_password_sicura(
            password,
            password_hash
        ):
            return None

        return {
            "user_id":
                int(
                    user_id
                ),

            "username":
                str(
                    username_db
                )
        }

    finally:
        _portal_close(
            conn
        )


def crea_lega_da_portale(
    dati_lega,
    squadre
):
    """
    Creazione atomica della lega completa dal portale pubblico.

    Ogni riga squadra crea:
    USER + TEAM + MEMBERSHIP + RUOLI.
    È obbligatorio almeno un ADMIN.
    """

    squadre_valide = []

    for posizione, squadra in enumerate(
        squadre,
        start=1
    ):

        username = str(
            squadra.get(
                "username",
                ""
            )
        ).strip()

        password = str(
            squadra.get(
                "password",
                ""
            )
        )

        if not username:
            raise ValueError(
                f"Manca il nome della Squadra {posizione}."
            )

        if len(
            password
        ) < 8:
            raise ValueError(
                f"La password di {username} deve avere almeno 8 caratteri."
            )

        squadre_valide.append({
            **squadra,
            "username":
                username,

            "password_hash":
                password_hash_sicuro(
                    password
                )
        })

    usernames_norm = [
        x[
            "username"
        ].casefold()
        for x in squadre_valide
    ]

    if len(
        usernames_norm
    ) != len(
        set(
            usernames_norm
        )
    ):
        raise ValueError(
            "I nomi squadra/username devono essere tutti diversi."
        )

    if not any(
        bool(
            x.get(
                "is_admin"
            )
        )
        for x in squadre_valide
    ):
        raise ValueError(
            "Devi indicare almeno una squadra come ADMIN."
        )

    conn = _portal_raw_connection()
    cur = conn.cursor()

    try:

        # Gli username sono globali: non possono essere duplicati
        # tra leghe diverse.
        for squadra in squadre_valide:

            cur.execute("""
                SELECT id
                FROM users
                WHERE LOWER(username) = LOWER(?)
                LIMIT 1
            """, (
                squadra[
                    "username"
                ],
            ))

            if cur.fetchone():
                raise ValueError(
                    f"Lo username '{squadra['username']}' è già utilizzato."
                )

        # Creatore tecnico = primo Admin definito nel wizard.
        primo_admin = next(
            x
            for x in squadre_valide
            if bool(
                x.get(
                    "is_admin"
                )
            )
        )

        # Crea prima l'utente Admin per poterlo registrare come creator.
        cur.execute("""
            INSERT INTO users (
                username,
                password_hash,
                is_active,
                created_at,
                updated_at
            )
            VALUES (?, ?, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
        """, (
            primo_admin[
                "username"
            ],
            primo_admin[
                "password_hash"
            ]
        ))

        primo_admin_id = int(
            cur.lastrowid
        )

        cur.execute("""
            INSERT INTO leagues (
                nome,
                stagione,
                modalita,
                stato,
                created_by_user_id,
                created_at,
                updated_at
            )
            VALUES (?, ?, ?, 'DRAFT', ?,
                    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
        """, (
            dati_lega[
                "nome"
            ],
            dati_lega[
                "stagione"
            ],
            dati_lega[
                "modalita"
            ],
            primo_admin_id
        ))

        league_id = int(
            cur.lastrowid
        )

        cur.execute("""
            INSERT INTO league_rules (
                league_id,
                partecipanti,
                max_giocatori,
                min_portieri,
                budget_iniziale,
                incremento_minimo,
                tipo_incremento_asta,
                incrementi_scalari_json,
                soglia_budget,
                moltiplicatore_oltre_soglia,
                tipo_asta,
                fonte_listone,
                budget_illimitato,
                fair_play_finanziario,
                regolamento_bloccato,
                created_at,
                updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0,
                    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
        """, (
            league_id,
            int(
                dati_lega[
                    "partecipanti"
                ]
            ),
            int(
                dati_lega[
                    "max_giocatori"
                ]
            ),
            int(
                dati_lega[
                    "min_portieri"
                ]
            ),
            float(
                dati_lega[
                    "budget_iniziale"
                ]
            ),
            float(
                dati_lega[
                    "incremento_minimo"
                ]
            ),
            str(dati_lega.get("tipo_incremento_asta") or "FISSO"),
            json.dumps(dati_lega.get("incrementi_scalari") or [], ensure_ascii=False),
            float(
                dati_lega[
                    "soglia_budget"
                ]
            ),
            float(
                dati_lega[
                    "moltiplicatore"
                ]
            ),
            dati_lega[
                "tipo_asta"
            ],
            dati_lega[
                "fonte_listone"
            ],
            1 if dati_lega.get("budget_illimitato") else 0,
            1 if dati_lega.get("fair_play_finanziario") else 0
        ))

        for posizione, squadra in enumerate(
            squadre_valide,
            start=1
        ):

            if squadra[
                "username"
            ].casefold() == primo_admin[
                "username"
            ].casefold():

                user_id = (
                    primo_admin_id
                )

            else:

                cur.execute("""
                    INSERT INTO users (
                        username,
                        password_hash,
                        is_active,
                        created_at,
                        updated_at
                    )
                    VALUES (?, ?, 1,
                            CURRENT_TIMESTAMP,
                            CURRENT_TIMESTAMP)
                """, (
                    squadra[
                        "username"
                    ],
                    squadra[
                        "password_hash"
                    ]
                ))

                user_id = int(
                    cur.lastrowid
                )

            cur.execute("""
                INSERT INTO teams (
                    league_id,
                    nome,
                    owner_user_id,
                    posizione,
                    is_active,
                    created_at,
                    updated_at
                )
                VALUES (?, ?, ?, ?, 1,
                        CURRENT_TIMESTAMP,
                        CURRENT_TIMESTAMP)
            """, (
                league_id,
                squadra[
                    "username"
                ],
                user_id,
                posizione
            ))

            team_id = int(
                cur.lastrowid
            )

            cur.execute("""
                INSERT INTO league_members (
                    league_id,
                    user_id,
                    team_id,
                    is_admin,
                    is_auctioneer,
                    is_team_member,
                    is_active,
                    joined_at
                )
                VALUES (?, ?, ?, ?, ?, 1, 1, CURRENT_TIMESTAMP)
            """, (
                league_id,
                user_id,
                team_id,
                1
                if squadra.get(
                    "is_admin"
                )
                else 0,
                1
                if squadra.get(
                    "is_auctioneer"
                )
                else 0
            ))

        cur.execute("""
            INSERT INTO audit_log (
                league_id,
                user_id,
                team_id,
                azione,
                entita,
                entita_id,
                dettagli_json,
                created_at
            )
            VALUES (?, ?, NULL,
                    'LEAGUE_CREATED_FROM_PORTAL',
                    'LEAGUE', ?, ?, CURRENT_TIMESTAMP)
        """, (
            league_id,
            primo_admin_id,
            str(
                league_id
            ),
            json.dumps(
                {
                    "nome":
                        dati_lega[
                            "nome"
                        ],

                    "partecipanti":
                        int(
                            dati_lega[
                                "partecipanti"
                            ]
                        ),

                    "users":
                        [
                            {
                                "username":
                                    x[
                                        "username"
                                    ],

                                "admin":
                                    bool(
                                        x.get(
                                            "is_admin"
                                        )
                                    ),

                                "auctioneer":
                                    bool(
                                        x.get(
                                            "is_auctioneer"
                                        )
                                    )
                            }
                            for x in squadre_valide
                        ]
                },
                ensure_ascii=False
            )
        ))

        conn.commit()

        return league_id

    except Exception:

        try:
            conn.rollback()
        except Exception:
            pass

        raise

    finally:
        _portal_close(
            conn
        )



