def _alias_nome_listone(
    nome_fonte,
    squadra_fonte
):
    squadra_key = _normalizza_nome_goal(
        squadra_fonte
    )

    nome_key = _normalizza_nome_goal(
        nome_fonte
    )

    return ALIAS_NOMI_FORMAZIONI.get(
        (
            squadra_key,
            nome_key
        )
    )


def _indice_formazioni_listone():
    """
    V119: indice O(1)/per-squadra per il matching delle Formazioni Tipo.
    Prima ogni nome scansionava l'intero listone più volte.
    """
    if (
        "df_completo" not in globals()
        or df_completo is None
        or df_completo.empty
        or "Nome" not in df_completo.columns
    ):
        return {}, {}

    sig = (
        _workspace_runtime_key if "_workspace_runtime_key" in globals() else "",
        len(df_completo),
        tuple(
            pd.to_numeric(
                df_completo.get("Id", pd.Series(dtype=int)),
                errors="coerce"
            ).fillna(-1).astype(int).tolist()
        )
    )
    chiave = "_ml35_formazioni_index_" + str(hash(sig))

    cached = st.session_state.get(chiave)
    if isinstance(cached, tuple) and len(cached) == 2:
        return cached

    esatti = {}
    per_squadra = {}

    for _, riga in df_completo.iterrows():
        nome_norm = _normalizza_nome_goal(riga.get("Nome", ""))
        squadra_norm = _normalizza_nome_goal(riga.get("Squadra", ""))
        if not nome_norm:
            continue

        esatti[(squadra_norm, nome_norm)] = riga
        per_squadra.setdefault(squadra_norm, []).append(
            (nome_norm, riga)
        )

    st.session_state[chiave] = (esatti, per_squadra)
    return esatti, per_squadra


def _trova_giocatore_listone(
    nome_goal,
    squadra_goal=""
):
    if (
        "df_completo" not in globals()
        or df_completo is None
        or df_completo.empty
        or "Nome" not in df_completo.columns
    ):
        return None

    target = _normalizza_nome_goal(nome_goal)
    squadra_target = _normalizza_nome_goal(squadra_goal)

    if not target:
        return None

    esatti, per_squadra = _indice_formazioni_listone()

    alias_esatto = _alias_nome_listone(
        nome_goal,
        squadra_goal
    )

    if alias_esatto:
        alias_norm = _normalizza_nome_goal(alias_esatto)
        riga = esatti.get((squadra_target, alias_norm))
        if riga is not None:
            return riga

    riga = esatti.get((squadra_target, target))
    if riga is not None:
        return riga

    # Se la squadra è nota, analizziamo solo i ~25-30 giocatori di quella
    # squadra invece dell'intero listone.
    if squadra_target:
        candidati_base = per_squadra.get(squadra_target, [])
        if not candidati_base:
            candidati_base = [
                item
                for sq, righe in per_squadra.items()
                if squadra_target in sq or sq in squadra_target
                for item in righe
            ]
        bonus_squadra = 30
    else:
        candidati_base = [
            item
            for righe in per_squadra.values()
            for item in righe
        ]
        bonus_squadra = 0

    token_target = set(target.split())
    candidati = []

    for normalizzato, riga in candidati_base:
        if normalizzato == target:
            return riga

        token_listone = set(normalizzato.split())
        intersezione = token_target & token_listone

        if intersezione:
            punteggio = (
                bonus_squadra
                + len(intersezione) * 10
                - abs(len(token_target) - len(token_listone))
            )
            if target in normalizzato or normalizzato in target:
                punteggio += 8
            candidati.append((punteggio, riga))

    if candidati:
        candidati.sort(key=lambda x: x[0], reverse=True)
        soglia = 20 if squadra_target else 9
        if candidati[0][0] >= soglia:
            return candidati[0][1]

    # Fallback fuzzy prudente, ancora limitato alla squadra quando nota.
    import difflib

    fuzzy = []
    for nome_norm, riga in candidati_base:
        similarita = difflib.SequenceMatcher(
            None,
            target,
            nome_norm
        ).ratio()

        if similarita >= 0.84:
            fuzzy.append((similarita, riga))

    fuzzy.sort(key=lambda x: x[0], reverse=True)

    if fuzzy:
        migliore = fuzzy[0]
        secondo = fuzzy[1][0] if len(fuzzy) > 1 else 0
        if migliore[0] >= 0.84 and (migliore[0] - secondo) >= 0.05:
            return migliore[1]

    return None




def diagnostica_nomi_formazioni_senza_riscontro():
    """
    Restituisce un elenco dei nomi presenti nelle Formazioni Tipo
    che non trovano alcuna corrispondenza nel listone corrente.

    Non viene mostrato al prossimo aggiornamento nell'interfaccia.
    È utile per futuri controlli dopo aggiornamenti del listone.
    """

    dati = carica_probabili_web()

    if (
        not dati
        or "df_completo" not in globals()
        or df_completo is None
        or df_completo.empty
    ):
        return []

    mancanti = []
    gia_visti = set()

    for squadra in dati.get(
        "squadre",
        []
    ):

        nome_squadra = squadra.get(
            "squadra",
            ""
        )

        nomi = []

        for giocatore in squadra.get(
            "formazione",
            []
        ):
            nomi.append(
                giocatore.get(
                    "nome",
                    ""
                )
            )

        for coppia in (
            squadra.get(
                "ballottaggi",
                []
            )
            or []
        ):
            nomi.extend(
                [
                    coppia.get(
                        "a",
                        ""
                    ),
                    coppia.get(
                        "b",
                        ""
                    )
                ]
            )

        for nome in nomi:

            chiave = (
                _normalizza_nome_goal(
                    nome_squadra
                ),
                _normalizza_nome_goal(
                    nome
                )
            )

            if (
                not chiave[1]
                or chiave in gia_visti
            ):
                continue

            gia_visti.add(
                chiave
            )

            if _trova_giocatore_listone(
                nome,
                nome_squadra
            ) is None:

                mancanti.append({
                    "Squadra":
                        nome_squadra,

                    "Nome formazione":
                        nome
                })

    return mancanti


def _ruoli_mantra_goal(
    nome_goal,
    squadra_goal=""
):
    riga = _trova_giocatore_listone(
        nome_goal,
        squadra_goal
    )

    if riga is None:
        return []

    rm = str(
        riga.get(
            "RM",
            ""
        )
        or ""
    ).strip()

    if not rm:
        return []

    return [
        ruolo.strip()
        for ruolo in rm.split(
            ";"
        )
        if ruolo.strip()
    ]


def _gruppo_tattico_da_ruolo(ruolo):
    ruolo = str(
        ruolo
        or ""
    ).strip().upper()

    if ruolo == "POR":
        return "P"

    if ruolo in {
        "DC",
        "B",
        "DD",
        "DS"
    }:
        return "D"

    if ruolo in {
        "E",
        "M",
        "C"
    }:
        return "C"

    if ruolo in {
        "W",
        "T",
        "A",
        "PC"
    }:
        return "A"

    return ""


def _ruolo_singolo_per_linea(
    ruoli,
    gruppo_linea
):
    """
    Mostra UN SOLO ruolo Mantra, scegliendo quello più coerente
    con la linea tattica in cui il giocatore viene collocato.
    """

    ruoli = [
        str(
            r
        ).strip()
        for r in (
            ruoli
            or []
        )
        if str(
            r
        ).strip()
    ]

    if not ruoli:
        return "—"

    preferenze = {
        "P": [
            "Por"
        ],
        "D": [
            "Ds",
            "Dd",
            "Dc",
            "B"
        ],
        "C": [
            "E",
            "M",
            "C"
        ],
        "A": [
            "W",
            "T",
            "A",
            "Pc"
        ]
    }

    for preferito in preferenze.get(
        gruppo_linea,
        []
    ):

        for ruolo in ruoli:

            if ruolo.upper() == preferito.upper():
                return ruolo

    return ruoli[
        0
    ]


def _gruppi_linee_goal(
    modulo,
    numero_linee
):
    """
    Le linee GOAL arrivano come:
    P ; D ; C/... ; A

    Restituiamo il gruppo tattico di ciascuna linea
    nello stesso ordine della fonte.
    """

    if numero_linee <= 1:
        return [
            "P"
        ]

    # Prima linea = portiere.
    gruppi = [
        "P"
    ]

    # Seconda = difesa.
    if numero_linee >= 2:
        gruppi.append(
            "D"
        )

    # Ultima = attacco.
    linee_intermedie = max(
        0,
        numero_linee - 3
    )

    for indice in range(
        linee_intermedie
    ):
        # Se ci sono più linee tra difesa e attacco,
        # l'ultima intermedia è più offensiva.
        if (
            linee_intermedie > 1
            and indice
            == linee_intermedie - 1
        ):
            gruppi.append(
                "A"
            )
        else:
            gruppi.append(
                "C"
            )

    if numero_linee >= 3:
        gruppi.append(
            "A"
        )

    return gruppi[
        :numero_linee
    ]


def _goal_visual_lines(
    squadra
):
    """
    Mantiene ESATTAMENTE le linee tattiche pubblicate da GOAL.
    Restituisce attacco -> ... -> portiere, come richiesto dal campo.
    """

    linee = squadra.get(
        "linee_fonte",
        []
    ) or []

    gruppi = _gruppi_linee_goal(
        squadra.get(
            "modulo",
            ""
        ),
        len(
            linee
        )
    )

    coppie = list(
        zip(
            linee,
            gruppi
        )
    )

    return list(
        reversed(
            coppie
        )
    )


def _stesso_giocatore(
    nome_a,
    nome_b
):

    return (
        _normalizza_nome_goal(
            nome_a
        )
        == _normalizza_nome_goal(
            nome_b
        )
    )


def _ballottaggio_del_titolare(
    squadra,
    nome_titolare
):
    """
    Cerca la PRIMA coppia Fantacalcio.it che coinvolge il titolare.

    Se la fonte scrive:
        Piccoli/Dovbyk
    e Dovbyk è nell'XI, restituisce Piccoli.

    Se scrive:
        Bellanova/Zappacosta
    e Bellanova è nell'XI, restituisce Zappacosta.

    Massimo un concorrente per card.
    """

    for coppia in (
        squadra.get(
            "ballottaggi",
            []
        )
        or []
    ):

        a = coppia.get(
            "a",
            ""
        )

        b = coppia.get(
            "b",
            ""
        )

        if _stesso_giocatore(
            nome_titolare,
            a
        ):

            return b

        if _stesso_giocatore(
            nome_titolare,
            b
        ):

            return a

    return None



def stato_giocatore_formazione(
    nome_giocatore,
    squadra
):
    """
    Restituisce lo stato corrente del giocatore nel listone:
      MIO         -> acquistato dalla nostra rosa
      AVVERSARIO  -> acquistato da un avversario
      DISPONIBILE -> ancora libero

    Il matching usa la stessa funzione già impiegata per ruoli Mantra
    e specialisti, quindi resta coerente col resto dell'app.
    """

    try:

        riga = _trova_giocatore_listone(
            nome_giocatore,
            squadra
        )

        if riga is None:
            return "DISPONIBILE"

        stato = str(
            riga.get(
                "Stato",
                "DISPONIBILE"
            )
            or "DISPONIBILE"
        ).strip().upper()

        if stato in {
            "MIO",
            "AVVERSARIO"
        }:
            return stato

    except Exception:
        pass

    return "DISPONIBILE"


def html_nome_formazione(
    nome_giocatore,
    squadra,
    classe_css,
    colore
):
    """
    Applica la resa grafica richiesta:
    - ⭐ prima del nome se il giocatore è nella nostra rosa
    - nome barrato se è stato acquistato da un avversario
    """

    stato = stato_giocatore_formazione(
        nome_giocatore,
        squadra
    )

    nome_html = html.escape(
        str(
            nome_giocatore
        )
    )

    if stato == "MIO":

        contenuto = (
            "⭐ "
            + nome_html
        )

        style_extra = ""

    elif stato == "AVVERSARIO":

        contenuto = nome_html

        style_extra = (
            "text-decoration-line:line-through;"
            "text-decoration-color:#000000;"
            "text-decoration-thickness:3px;"
            "opacity:0.72;"
        )

    else:

        contenuto = nome_html
        style_extra = ""

    return (
        '<span class="'
        + classe_css
        + '" style="color:'
        + colore
        + ' !important;'
        + style_extra
        + '">'
        + contenuto
        + '</span>'
    )


def mostra_probabile(
    squadra
):
    """
    CARD V10:

    CASO 1 - nessun ballottaggio:
        TITOLARE VERDE + ruoli Mantra

    CASO 2 - ballottaggio esplicito Fantacalcio.it:
        TITOLARE BLU + ruoli Mantra
        CONCORRENTE BLU + ruoli Mantra

    Nessun altro nome viene mostrato nella card.
    """

    linee_originali = squadra.get(
        "linee_fonte",
        []
    ) or []

    righe_html = ""

    # Fantacalcio.it pubblica:
    # portiere -> difesa -> centrocampo/... -> attacco.
    # Sul campo mostriamo attacco -> ... -> portiere.
    for linea in reversed(
        linee_originali
    ):

        giocatori_html = ""

        nomi_validi = list(
            reversed(
                [
                    nome
                    for nome in linea
                    if _goal_nome_valido(
                        nome
                    )
                ]
            )
        )

        for nome_raw in nomi_validi:

            concorrente = (
                _ballottaggio_del_titolare(
                    squadra,
                    nome_raw
                )
            )

            in_ballottaggio = bool(
                concorrente
            )

            colore_principale = (
                "#2563eb"
                if in_ballottaggio
                else "#16a34a"
            )

            nome = str(
                nome_raw
            )

            ruoli = _ruoli_mantra_goal(
                nome_raw,
                squadra.get(
                    "squadra",
                    ""
                )
            )

            ruolo = html.escape(
                ";".join(
                    ruoli
                )
                if ruoli
                else "—"
            )

            secondo_html = ""

            if concorrente:

                nome_alt = str(
                    concorrente
                )

                ruoli_alt = (
                    _ruoli_mantra_goal(
                        concorrente,
                        squadra.get(
                            "squadra",
                            ""
                        )
                    )
                )

                ruolo_alt = html.escape(
                    ";".join(
                        ruoli_alt
                    )
                    if ruoli_alt
                    else "—"
                )

                secondo_html = (
                    '<div class="pf-sub-player">'
                    + html_nome_formazione(
                        nome_alt,
                        squadra.get(
                            "squadra",
                            ""
                        ),
                        "pf-sub-name",
                        "#2563eb"
                    )
                    + '<span class="pf-sub-role">'
                    + ruolo_alt
                    + '</span>'
                    '</div>'
                )

            giocatori_html += (
                '<div class="pf-player pf-player-goal">'
                '<div class="pf-main-player">'
                + html_nome_formazione(
                    nome,
                    squadra.get(
                        "squadra",
                        ""
                    ),
                    "pf-name",
                    colore_principale
                )
                + '<span class="pf-mantra-role">'
                + ruolo
                + '</span>'
                '</div>'
                + secondo_html
                + '</div>'
            )

        numero_card_linea = max(
            1,
            len(
                nomi_validi
            )
        )

        righe_html += (
            '<div class="pf-line pf-line-count-'
            + str(
                numero_card_linea
            )
            + '">'
            + giocatori_html
            + '</div>'
        )

    titolo = html.escape(
        str(
            squadra.get(
                "squadra",
                ""
            )
        )
    )

    modulo = html.escape(
        str(
            squadra.get(
                "modulo",
                ""
            )
        )
    )

    st.markdown(
        '<div class="pf-team">'
        + titolo
        + '<span>'
        + modulo
        + '</span></div>'
        + '<div class="pf-pitch">'
        + righe_html
        + '</div>',
        unsafe_allow_html=True
    )

    specialisti = _specialisti_squadra(
        squadra.get(
            "squadra",
            ""
        )
    )

    rigoristi = ", ".join(
        specialisti.get(
            "rigoristi",
            []
        )[
            :3
        ]
    ) or "—"

    piazzati = ", ".join(
        specialisti.get(
            "calci_piazzati",
            []
        )[
            :3
        ]
    ) or "—"

    st.markdown(
        f"""
        <div style="
            background:#ffffff;
            border:1px solid #dbe3ec;
            border-top:0;
            border-radius:0 0 10px 10px;
            padding:8px 12px 10px 12px;
            margin-top:-2px;
            font-size:1.00rem;
            line-height:1.45;
            color:#334155;
        ">
            <div>
                <b>⚽ Rigoristi:</b>
                {html.escape(rigoristi)}
            </div>
            <div>
                <b>🎯 Calci piazzati:</b>
                {html.escape(piazzati)}
            </div>
        </div>
        """,
        unsafe_allow_html=True
    )

def leggi_budget_asta():

    conn = get_connection()
    cur = conn.cursor()

    try:

        cur.execute("""
            SELECT valore
            FROM configurazione_app
            WHERE chiave = 'budget_asta'
        """)

        riga = cur.fetchone()

    finally:

        chiudi_connessione(
            conn
        )

    if not riga:

        return float(
            SOGLIA_BASE
        )

    try:

        return float(
            riga[0]
        )

    except Exception:

        return float(
            SOGLIA_BASE
        )


def salva_budget_asta(
    valore
):

    try:

        valore = round(
            max(
                0.0,
                float(
                    valore
                )
            ),
            2
        )

    except Exception:

        valore = float(
            SOGLIA_BASE
        )

    conn = get_connection()
    cur = conn.cursor()

    try:

        cur.execute("""
            INSERT INTO configurazione_app (
                chiave,
                valore
            )
            VALUES (
                'budget_asta',
                ?
            )

            ON CONFLICT(chiave)
            DO UPDATE SET
                valore = excluded.valore
        """, (
            str(
                valore
            ),
        ))

        conn.commit()

    finally:

        chiudi_connessione(
            conn
        )

    return valore


def leggi_budget_squadra_autorevole(league_id, team_id):
    """Legge il budget della squadra dalla fonte autorevole condivisa da tutti i livelli."""
    try:
        league_id = int(league_id)
        team_id = int(team_id)
    except Exception:
        return float(SOGLIA_BASE)

    conn = _portal_raw_connection()
    try:
        cur = conn.cursor()
        cur.execute("""
            SELECT COALESCE(tb.budget_impostato, lr.budget_iniziale, ?)
            FROM teams t
            LEFT JOIN league_rules lr
              ON lr.league_id=t.league_id
            LEFT JOIN team_budgets tb
              ON tb.league_id=t.league_id
             AND tb.team_id=t.id
            WHERE t.league_id=? AND t.id=?
            LIMIT 1
        """, (SOGLIA_BASE, league_id, team_id))
        riga = cur.fetchone()
        return float(riga[0] if riga and riga[0] is not None else SOGLIA_BASE)
    finally:
        _portal_close(conn)


def salva_budget_squadra_autorevole(league_id, team_id, valore):
    """Salva il budget SOLO per la squadra indicata; Admin/Banditore restano read-only."""
    try:
        league_id = int(league_id)
        team_id = int(team_id)
        valore = round(max(0.0, float(valore)), 2)
    except Exception:
        return float(SOGLIA_BASE)

    conn = _portal_raw_connection()
    try:
        cur = conn.cursor()
        cur.execute("""
            INSERT INTO team_budgets (
                league_id, team_id, budget_impostato,
                valore_acquisti, spesa_effettiva, updated_at
            )
            SELECT
                ?, ?, ?,
                COALESCE(tb.valore_acquisti, 0),
                COALESCE(tb.spesa_effettiva, 0),
                CURRENT_TIMESTAMP
            FROM (SELECT 1) x
            LEFT JOIN team_budgets tb
              ON tb.league_id=? AND tb.team_id=?
            ON CONFLICT(league_id,team_id)
            DO UPDATE SET
                budget_impostato=excluded.budget_impostato,
                updated_at=CURRENT_TIMESTAMP
        """, (league_id, team_id, valore, league_id, team_id))
        conn.commit()
        return valore
    finally:
        _portal_close(conn)


def aggiorna_budget_da_widget():
    # V154: il budget e' modificabile esclusivamente dal livello SQUADRA.
    # Tutti i livelli leggono pero' la stessa riga team_budgets.
    modalita = str(
        st.session_state.get("ml_modalita_accesso")
        or st.session_state.get("modalita_accesso")
        or ""
    ).upper()

    league_id = st.session_state.get("ml_league_id")
    team_id = st.session_state.get("ml_sidebar_team_id") or st.session_state.get("ml_team_id")

    # Protezione server-side: Admin e Banditore non possono mai salvare il budget,
    # anche se il widget venisse manipolato lato client.
    if modalita != "SQUADRA":
        if league_id is not None and team_id is not None:
            budget_db = leggi_budget_squadra_autorevole(league_id, team_id)
            st.session_state["budget_asta_corrente"] = budget_db
            st.session_state["budget_asta_input"] = budget_db
        return

    try:
        nuovo_budget = round(
            max(0.0, float(st.session_state.get("budget_asta_input", SOGLIA_BASE))),
            2
        )
    except Exception:
        nuovo_budget = float(SOGLIA_BASE)

    if league_id is not None and team_id is not None:
        budget_salvato = salva_budget_squadra_autorevole(
            league_id, team_id, nuovo_budget
        )
    else:
        # Fallback solo per eventuali contesti legacy privi di squadra/lega.
        budget_salvato = salva_budget_asta(nuovo_budget)

    st.session_state["budget_asta_corrente"] = float(budget_salvato)
    st.session_state["budget_asta_input"] = float(budget_salvato)
    st.session_state.pop("_ml16_sidebar_metrics", None)


