def calcola_spesa_effettiva(
    valore_acquisti
):

    valore = round(
        float(
            valore_acquisti
            or 0
        ),
        2
    )

    if valore <= SOGLIA_BASE:

        return valore

    eccedenza = round(
        valore
        - SOGLIA_BASE,
        2
    )

    return round(
        SOGLIA_BASE
        + eccedenza * 3,
        2
    )


