TABELLE_SNAPSHOT = [
    "giocatori",
    "costi_svincoli",
    "operazioni"
]


def pulisci_testo_snapshot(
    testo
):

    testo = str(
        testo
        or "OPERAZIONE"
    ).strip()

    caratteri = []

    for carattere in testo:

        if carattere.isalnum():

            caratteri.append(
                carattere
            )

        elif carattere in (
            " ",
            "-",
            "_"
        ):

            caratteri.append(
                "_"
            )

    risultato = "".join(
        caratteri
    )

    while "__" in risultato:

        risultato = (
            risultato.replace(
                "__",
                "_"
            )
        )

    return (
        risultato.strip("_")
        or "OPERAZIONE"
    )


def estrai_tabella_snapshot(
    conn,
    nome_tabella
):

    cur = conn.cursor()

    cur.execute(
        f"SELECT * FROM {nome_tabella}"
    )

    righe = cur.fetchall()

    colonne = [
        descrizione[0]
        for descrizione
        in cur.description
    ]

    return {
        "colonne":
            colonne,

        "righe":
            [
                list(
                    riga
                )
                for riga
                in righe
            ]
    }


def serializza_stato_database(
    conn
):

    contenuto = {
        "versione":
            1,

        "creato_il":
            datetime.now().isoformat(),

        "tabelle":
            {}
    }

    for nome_tabella in (
        TABELLE_SNAPSHOT
    ):

        contenuto[
            "tabelle"
        ][
            nome_tabella
        ] = estrai_tabella_snapshot(
            conn,
            nome_tabella
        )

    return json.dumps(
        contenuto,
        ensure_ascii=False
    )


def elimina_snapshot_eccessivi(
    conn
):

    cur = conn.cursor()

    cur.execute("""
        SELECT id
        FROM snapshot_archivio
        ORDER BY id DESC
    """)

    ids = [
        riga[0]
        for riga
        in cur.fetchall()
    ]

    da_eliminare = ids[
        MAX_SNAPSHOT:
    ]

    for snapshot_id in (
        da_eliminare
    ):

        cur.execute("""
            DELETE FROM snapshot_archivio
            WHERE id = ?
        """, (
            snapshot_id,
        ))

    conn.commit()


def crea_snapshot_database(
    motivo="MANUALE"
):

    conn = get_connection()

    try:

        stato_json = (
            serializza_stato_database(
                conn
            )
        )

        cur = conn.cursor()

        cur.execute("""
            INSERT INTO snapshot_archivio (
                motivo,
                contenuto_json,
                data_creazione
            )
            VALUES (
                ?, ?,
                CURRENT_TIMESTAMP
            )
        """, (
            pulisci_testo_snapshot(
                motivo
            ),
            stato_json
        ))

        conn.commit()

        elimina_snapshot_eccessivi(
            conn
        )

        try:
            elenco_snapshot.clear()
        except Exception:
            pass

        return True

    finally:

        chiudi_connessione(conn)


@st.cache_data(show_spinner=False)
def elenco_snapshot(
    profilo_cache
):

    conn = get_connection()

    try:

        cur = conn.cursor()

        cur.execute("""
            SELECT
                id,
                motivo,
                data_creazione

            FROM snapshot_archivio

            ORDER BY id DESC

            LIMIT ?
        """, (
            MAX_SNAPSHOT,
        ))

        righe = cur.fetchall()

        risultato = []

        for riga in righe:

            snapshot_id = (
                riga[0]
            )

            motivo = str(
                riga[1]
                or "SNAPSHOT"
            )

            data_raw = str(
                riga[2]
                or ""
            )

            data_testo = (
                data_raw
            )

            try:

                data_ora = (
                    datetime.fromisoformat(
                        data_raw.replace(
                            "Z",
                            "+00:00"
                        )
                    )
                )

                data_testo = (
                    data_ora.strftime(
                        "%d/%m/%Y %H:%M:%S"
                    )
                )

            except Exception:

                pass

            risultato.append({
                "id":
                    snapshot_id,

                "path":
                    snapshot_id,

                "file":
                    f"snapshot_{snapshot_id}",

                "data":
                    data_testo,

                "motivo":
                    motivo.replace(
                        "_",
                        " "
                    )
            })

        return risultato

    finally:

        chiudi_connessione(conn)


def ripristina_snapshot_database(
    snapshot_id
):

    # Prima salviamo sempre lo stato corrente.
    crea_snapshot_database(
        "PRIMA_DEL_RIPRISTINO"
    )

    conn = get_connection()

    try:

        cur = conn.cursor()

        cur.execute("""
            SELECT contenuto_json
            FROM snapshot_archivio
            WHERE id = ?
        """, (
            int(
                snapshot_id
            ),
        ))

        riga = cur.fetchone()

        if riga is None:

            raise FileNotFoundError(
                "Snapshot non trovato."
            )

        contenuto = json.loads(
            riga[0]
        )

        tabelle = contenuto.get(
            "tabelle",
            {}
        )

        # Svuotiamo prima le tabelle operative.
        # L'archivio snapshot NON viene cancellato.
        for nome_tabella in [
            "costi_svincoli",
            "operazioni",
            "giocatori"
        ]:

            cur.execute(
                f"DELETE FROM {nome_tabella}"
            )

        # Ripristino dei dati.
        for nome_tabella in (
            TABELLE_SNAPSHOT
        ):

            dati = tabelle.get(
                nome_tabella
            )

            if not dati:

                continue

            colonne = dati.get(
                "colonne",
                []
            )

            righe = dati.get(
                "righe",
                []
            )

            if (
                not colonne
                or not righe
            ):

                continue

            elenco_colonne = (
                ", ".join(
                    colonne
                )
            )

            placeholders = (
                ", ".join(
                    [
                        "?"
                        for _ in colonne
                    ]
                )
            )

            query = (
                f"INSERT INTO "
                f"{nome_tabella} "
                f"({elenco_colonne}) "
                f"VALUES "
                f"({placeholders})"
            )

            for valori in righe:

                cur.execute(
                    query,
                    tuple(
                        valori
                    )
                )

        conn.commit()

        invalida_cache_dati()

        return True

    finally:

        chiudi_connessione(conn)


def crea_backup_logico_bytes():

    conn = get_connection()

    try:

        contenuto = (
            serializza_stato_database(
                conn
            )
        )

        return contenuto.encode(
            "utf-8"
        )

    finally:

        chiudi_connessione(conn)


