TABELLE_SEPARATE_PER_PROFILO = [
    "giocatori",
    "costi_svincoli",
    "operazioni",
    "snapshot_archivio",
    "configurazione_app"
]


def _riscrivi_sql_per_profilo(
    sql
):

    testo = str(
        sql
    )

    if not SUFFIX_PROFILO:
        return testo

    # Sostituisce solo identificatori completi.
    # In questo modo tutto il codice esistente continua a usare
    # i nomi standard delle tabelle, ma GOSTOBAR lavora su copie
    # completamente separate.
    for nome_base in sorted(
        TABELLE_SEPARATE_PER_PROFILO,
        key=len,
        reverse=True
    ):

        testo = re.sub(
            rf"\b{re.escape(nome_base)}\b",
            nome_tabella_profilo(
                nome_base
            ),
            testo
        )

    return testo


class _CursorProfilo:

    def __init__(
        self,
        cursor
    ):

        self._cursor = cursor


    @property
    def description(
        self
    ):

        return self._cursor.description


    @property
    def lastrowid(
        self
    ):

        return getattr(
            self._cursor,
            "lastrowid",
            None
        )


    def execute(
        self,
        sql,
        parametri=()
    ):

        self._cursor.execute(
            _riscrivi_sql_per_profilo(
                sql
            ),
            parametri
        )

        return self


    def executemany(
        self,
        sql,
        seq_parametri
    ):

        self._cursor.executemany(
            _riscrivi_sql_per_profilo(
                sql
            ),
            seq_parametri
        )

        return self


    def fetchone(
        self
    ):

        return self._cursor.fetchone()


    def fetchall(
        self
    ):

        return self._cursor.fetchall()


    def __iter__(
        self
    ):

        return iter(
            self._cursor
        )


    def __getattr__(
        self,
        nome
    ):

        return getattr(
            self._cursor,
            nome
        )


class _ConnessioneProfilo:

    def __init__(
        self,
        connessione
    ):

        self._connessione = connessione


    def cursor(
        self
    ):

        return _CursorProfilo(
            self._connessione.cursor()
        )


    def execute(
        self,
        sql,
        parametri=()
    ):

        cursore = self.cursor()

        return cursore.execute(
            sql,
            parametri
        )


    def executemany(
        self,
        sql,
        seq_parametri
    ):

        cursore = self.cursor()

        return cursore.executemany(
            sql,
            seq_parametri
        )


    def commit(
        self
    ):

        return self._connessione.commit()


    def rollback(
        self
    ):

        return self._connessione.rollback()


    def close(
        self
    ):

        return self._connessione.close()


    def __enter__(
        self
    ):

        return self


    def __exit__(
        self,
        exc_type,
        exc_value,
        traceback
    ):

        if exc_type is None:

            try:
                self.commit()
            except Exception:
                pass

        return False


    def __getattr__(
        self,
        nome
    ):

        return getattr(
            self._connessione,
            nome
        )


def _get_raw_connection():

    if USA_DATABASE_CLOUD:

        try:

            import libsql

        except ImportError as errore:

            raise RuntimeError(
                "La modalità Cloud richiede il pacchetto libsql. "
                "Installa le dipendenze da requirements.txt."
            ) from errore

        chiave = "_turso_connessione_raw"

        conn = st.session_state.get(
            chiave
        )

        if conn is None:

            conn = libsql.connect(
                database=(
                    TURSO_DATABASE_URL
                ),
                auth_token=(
                    TURSO_AUTH_TOKEN
                )
            )

            st.session_state[
                chiave
            ] = conn

        return conn

    return sqlite3.connect(
        DB_PATH
    )


def get_connection():

    return _ConnessioneProfilo(
        _get_raw_connection()
    )

def chiudi_connessione(
    conn
):

    # In Cloud la connessione viene mantenuta viva per tutta
    # la sessione: evita handshake e riconnessioni ripetute.
    if USA_DATABASE_CLOUD:
        return

    try:
        conn.close()
    except Exception:
        pass


@st.cache_resource(show_spinner=False)
def inizializza_database(
    profilo_cache
):

    conn = get_connection()
    cur = conn.cursor()

    cur.execute("""
        CREATE TABLE IF NOT EXISTS giocatori (

            id INTEGER PRIMARY KEY,

            ruolo_classico TEXT,
            ruolo_mantra TEXT,

            nome TEXT NOT NULL,
            squadra TEXT,

            quotazione_attuale REAL,
            quotazione_iniziale REAL,
            differenza REAL,

            quotazione_attuale_mantra REAL,
            quotazione_iniziale_mantra REAL,
            differenza_mantra REAL,

            fvm REAL,
            fvm_mantra REAL,

            stato TEXT
                DEFAULT 'DISPONIBILE',

            prezzo_acquisto REAL
                DEFAULT NULL,

            ultimo_aggiornamento TEXT
                DEFAULT CURRENT_TIMESTAMP
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS costi_svincoli (

            id INTEGER PRIMARY KEY AUTOINCREMENT,

            operazione_id INTEGER,

            giocatore_id INTEGER,

            nome_giocatore TEXT,

            importo REAL NOT NULL,

            data_operazione TEXT
                DEFAULT CURRENT_TIMESTAMP
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS operazioni (

            id INTEGER PRIMARY KEY AUTOINCREMENT,

            tipo TEXT NOT NULL,

            giocatore_id INTEGER NOT NULL,

            nome_giocatore TEXT,

            stato_prima TEXT,

            prezzo_prima REAL,

            stato_dopo TEXT,

            prezzo_dopo REAL,

            costo_svincolo REAL
                DEFAULT 0,

            data_operazione TEXT
                DEFAULT CURRENT_TIMESTAMP
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS snapshot_archivio (

            id INTEGER PRIMARY KEY AUTOINCREMENT,

            motivo TEXT NOT NULL,

            contenuto_json TEXT NOT NULL,

            data_creazione TEXT
                DEFAULT CURRENT_TIMESTAMP
        )
    """)


    cur.execute("""
        CREATE TABLE IF NOT EXISTS configurazione_app (

            chiave TEXT PRIMARY KEY,

            valore TEXT
        )
    """)


    # La cronologia viene gestita direttamente in Python.
    # Rimuoviamo l'eventuale trigger creato dalle release precedenti:
    # su Turso/libsql può generare ValueError durante alcuni ripristini.
    cur.execute("""
        DROP TRIGGER IF EXISTS trg_operazioni_post_insert
    """)

    colonne = {
        r[1]
        for r in cur.execute(
            "PRAGMA table_info(giocatori)"
        ).fetchall()
    }

    if "stato" not in colonne:

        cur.execute("""
            ALTER TABLE giocatori
            ADD COLUMN stato TEXT
            DEFAULT 'DISPONIBILE'
        """)

    if "prezzo_acquisto" not in colonne:

        cur.execute("""
            ALTER TABLE giocatori
            ADD COLUMN prezzo_acquisto REAL
            DEFAULT NULL
        """)

    cur.execute("""
        UPDATE giocatori

        SET stato = 'DISPONIBILE'

        WHERE stato IS NULL
           OR TRIM(stato) = ''
    """)

    conn.commit()
    chiudi_connessione(conn)

    # --------------------------------------------------------
    # PRIMA APERTURA DI GOSTOBAR
    # --------------------------------------------------------
    # Clona il listone di IBBINI IDIOTA ma NON il suo stato d'asta.
    # Quindi GOSTOBAR parte con tutti i giocatori DISPONIBILI,
    # rosa vuota, prezzi vuoti e cronologia vuota.
    if PROFILO_ATTIVO == "GOSTOBAR":

        raw_conn = _get_raw_connection()
        raw_cur = raw_conn.cursor()

        try:

            raw_cur.execute("""
                SELECT COUNT(*)
                FROM giocatori_gostobar
            """)

            quanti_gostobar = int(
                raw_cur.fetchone()[0]
                or 0
            )

            if quanti_gostobar == 0:

                raw_cur.execute("""
                    SELECT COUNT(*)
                    FROM giocatori
                """)

                quanti_base = int(
                    raw_cur.fetchone()[0]
                    or 0
                )

                if quanti_base > 0:

                    raw_cur.execute("""
                        INSERT INTO giocatori_gostobar (
                            id,
                            ruolo_classico,
                            ruolo_mantra,
                            nome,
                            squadra,
                            quotazione_attuale,
                            quotazione_iniziale,
                            differenza,
                            quotazione_attuale_mantra,
                            quotazione_iniziale_mantra,
                            differenza_mantra,
                            fvm,
                            fvm_mantra,
                            stato,
                            prezzo_acquisto,
                            ultimo_aggiornamento
                        )

                        SELECT
                            id,
                            ruolo_classico,
                            ruolo_mantra,
                            nome,
                            squadra,
                            quotazione_attuale,
                            quotazione_iniziale,
                            differenza,
                            quotazione_attuale_mantra,
                            quotazione_iniziale_mantra,
                            differenza_mantra,
                            fvm,
                            fvm_mantra,
                            'DISPONIBILE',
                            NULL,
                            CURRENT_TIMESTAMP

                        FROM giocatori
                    """)

                    raw_conn.commit()

        finally:

            if not USA_DATABASE_CLOUD:

                try:
                    raw_conn.close()
                except Exception:
                    pass



# ============================================================
# MULTILEGA 0.1 - DATABASE FOUNDATION
# ============================================================
#
# Questa release NON sostituisce ancora le tabelle legacy:
# l'app continua a funzionare esattamente come V82.
#
# Le nuove tabelle sono additive e preparano:
# UTENTE -> LEGA -> RUOLO -> SQUADRA -> ROSA
#
# La V82 congelata resta la baseline di sicurezza.
# ============================================================

MULTILEGA_SCHEMA_VERSION = "5.6.2"

LEGA_LEGACY_NOME = "FANTAELEGANZA 26/27"


def _ml_fetch_id(
    cur,
    query,
    parametri
):
    cur.execute(
        query,
        parametri
    )
    riga = cur.fetchone()

    if not riga:
        return None

    return int(
        riga[0]
    )


def inizializza_database_multilega():
    """
    Crea lo schema MULTILEGA senza alterare il funzionamento legacy.

    Le tabelle create qui NON rientrano in
    TABELLE_SEPARATE_PER_PROFILO: sono globali e condivise.
    """

    conn = get_connection()
    cur = conn.cursor()

    try:

        cur.execute("""
            CREATE TABLE IF NOT EXISTS multilega_meta (
                chiave TEXT PRIMARY KEY,
                valore TEXT
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL UNIQUE,
                email TEXT,
                password_hash TEXT,
                is_active INTEGER NOT NULL DEFAULT 1,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS leagues (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                nome TEXT NOT NULL,
                stagione TEXT,
                modalita TEXT NOT NULL DEFAULT 'MANTRA',
                stato TEXT NOT NULL DEFAULT 'DRAFT',
                created_by_user_id INTEGER,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS teams (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER NOT NULL,
                nome TEXT NOT NULL,
                owner_user_id INTEGER,
                posizione INTEGER,
                is_active INTEGER NOT NULL DEFAULT 1,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(league_id, nome)
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS league_members (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                team_id INTEGER,
                is_admin INTEGER NOT NULL DEFAULT 0,
                is_auctioneer INTEGER NOT NULL DEFAULT 0,
                is_team_member INTEGER NOT NULL DEFAULT 1,
                is_active INTEGER NOT NULL DEFAULT 1,
                joined_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(league_id, user_id, team_id)
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS league_rules (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER NOT NULL UNIQUE,
                partecipanti INTEGER NOT NULL DEFAULT 10,
                max_giocatori INTEGER NOT NULL DEFAULT 30,
                min_portieri INTEGER NOT NULL DEFAULT 2,
                budget_iniziale REAL NOT NULL DEFAULT 500,
                incremento_minimo REAL NOT NULL DEFAULT 1,
                soglia_budget REAL NOT NULL DEFAULT 500,
                moltiplicatore_oltre_soglia REAL NOT NULL DEFAULT 3,
                tipo_asta TEXT NOT NULL DEFAULT 'CHIAMATA',
                fonte_listone TEXT NOT NULL DEFAULT 'Fantacalcio.it',
                regolamento_bloccato INTEGER NOT NULL DEFAULT 0,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS team_budgets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER NOT NULL,
                team_id INTEGER NOT NULL,
                budget_impostato REAL NOT NULL DEFAULT 500,
                valore_acquisti REAL NOT NULL DEFAULT 0,
                spesa_effettiva REAL NOT NULL DEFAULT 0,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(league_id, team_id)
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS rosters (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER NOT NULL,
                team_id INTEGER NOT NULL,
                player_id INTEGER NOT NULL,
                prezzo_acquisto REAL,
                fonte TEXT NOT NULL DEFAULT 'LEGACY',
                assigned_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(league_id, team_id, player_id)
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS league_player_catalog (
                league_id INTEGER NOT NULL,
                player_id INTEGER NOT NULL,
                ruolo_classico TEXT,
                ruolo_mantra TEXT,
                nome TEXT NOT NULL,
                squadra TEXT,
                quotazione_attuale REAL,
                quotazione_iniziale REAL,
                differenza REAL,
                quotazione_attuale_mantra REAL,
                quotazione_iniziale_mantra REAL,
                differenza_mantra REAL,
                fvm REAL,
                fvm_mantra REAL,
                uploaded_by_user_id INTEGER,
                uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (league_id, player_id)
            )
        """)

        cur.execute("""
            CREATE INDEX IF NOT EXISTS ix_league_player_catalog_nome
            ON league_player_catalog(league_id, nome)
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS iqr_profiles (
                league_id INTEGER NOT NULL,
                team_id INTEGER NOT NULL,
                iqr_corrente REAL NOT NULL DEFAULT 0,
                max_giocatori INTEGER NOT NULL DEFAULT 30,
                giocatori_rosa INTEGER NOT NULL DEFAULT 0,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (league_id, team_id)
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS player_evaluations (
                league_id INTEGER NOT NULL,
                team_id INTEGER NOT NULL,
                player_id INTEGER NOT NULL,
                iqr_prima REAL NOT NULL DEFAULT 0,
                iqr_dopo REAL NOT NULL DEFAULT 0,
                delta_iqr REAL NOT NULL DEFAULT 0,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (league_id, team_id, player_id)
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS league_players (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER NOT NULL,
                player_id INTEGER NOT NULL,
                stato TEXT NOT NULL DEFAULT 'DISPONIBILE',
                assigned_team_id INTEGER,
                prezzo_assegnazione REAL,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(league_id, player_id)
            )
        """)

        cur.execute("""
            CREATE TABLE IF NOT EXISTS audit_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER NOT NULL,
                user_id INTEGER,
                team_id INTEGER,
                azione TEXT NOT NULL,
                entita TEXT,
                entita_id TEXT,
                dettagli_json TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)

        cur.execute("""
            INSERT INTO multilega_meta (
                chiave,
                valore
            )
            VALUES (
                'schema_version',
                ?
            )
            ON CONFLICT(chiave)
            DO UPDATE SET
                valore = excluded.valore
        """, (
            MULTILEGA_SCHEMA_VERSION,
        ))

        conn.commit()

    finally:

        chiudi_connessione(
            conn
        )


def migra_profili_legacy_in_multilega():
    """
    Registra IBBINI IDIOTA e GOSTOBAR nel nuovo schema.

    Non cambia il comportamento dell'app:
    crea solamente la mappatura multilega necessaria
    alle release successive.
    """

    conn = get_connection()
    cur = conn.cursor()

    try:

        # ----------------------------------------------------
        # UTENTI LEGACY
        # ----------------------------------------------------
        for username in PROFILI_APP:

            cur.execute("""
                INSERT INTO users (
                    username,
                    is_active
                )
                VALUES (?, 1)
                ON CONFLICT(username)
                DO UPDATE SET
                    is_active = 1,
                    updated_at = CURRENT_TIMESTAMP
            """, (
                username,
            ))

        # ----------------------------------------------------
        # LEGA LEGACY
        # ----------------------------------------------------
        admin_id = _ml_fetch_id(
            cur,
            "SELECT id FROM users WHERE username = ?",
            (
                "IBBINI IDIOTA",
            )
        )

        cur.execute("""
            SELECT id
            FROM leagues
            WHERE nome = ?
            ORDER BY id
            LIMIT 1
        """, (
            LEGA_LEGACY_NOME,
        ))

        riga_lega = cur.fetchone()

        if riga_lega:

            league_id = int(
                riga_lega[0]
            )

        else:

            cur.execute("""
                INSERT INTO leagues (
                    nome,
                    stagione,
                    modalita,
                    stato,
                    created_by_user_id
                )
                VALUES (
                    ?,
                    '2026/27',
                    'MANTRA',
                    'LEGACY_MIGRATION',
                    ?
                )
            """, (
                LEGA_LEGACY_NOME,
                admin_id
            ))

            league_id = int(
                cur.lastrowid
            )

        # ----------------------------------------------------
        # REGOLAMENTO BASE
        # ----------------------------------------------------
        cur.execute("""
            INSERT INTO league_rules (
                league_id,
                partecipanti,
                max_giocatori,
                min_portieri,
                budget_iniziale,
                incremento_minimo,
                soglia_budget,
                moltiplicatore_oltre_soglia,
                tipo_asta,
                fonte_listone
            )
            VALUES (
                ?,
                2,
                30,
                2,
                500,
                1,
                500,
                3,
                'CHIAMATA',
                'Fantacalcio.it'
            )
            ON CONFLICT(league_id)
            DO NOTHING
        """, (
            league_id,
        ))

        # ----------------------------------------------------
        # SQUADRE + MEMBERSHIP
        # ----------------------------------------------------
        for posizione, username in enumerate(
            PROFILI_APP,
            start=1
        ):

            user_id = _ml_fetch_id(
                cur,
                "SELECT id FROM users WHERE username = ?",
                (
                    username,
                )
            )

            cur.execute("""
                INSERT INTO teams (
                    league_id,
                    nome,
                    owner_user_id,
                    posizione,
                    is_active
                )
                VALUES (?, ?, ?, ?, 1)
                ON CONFLICT(league_id, nome)
                DO UPDATE SET
                    owner_user_id = excluded.owner_user_id,
                    posizione = excluded.posizione,
                    is_active = 1,
                    updated_at = CURRENT_TIMESTAMP
            """, (
                league_id,
                username,
                user_id,
                posizione
            ))

            team_id = _ml_fetch_id(
                cur,
                """
                SELECT id
                FROM teams
                WHERE league_id = ?
                  AND nome = ?
                """,
                (
                    league_id,
                    username
                )
            )

            cur.execute("""
                INSERT INTO league_members (
                    league_id,
                    user_id,
                    team_id,
                    is_admin,
                    is_auctioneer,
                    is_team_member,
                    is_active
                )
                VALUES (?, ?, ?, ?, ?, 1, 1)
                ON CONFLICT(league_id, user_id, team_id)
                DO UPDATE SET
                    is_admin = excluded.is_admin,
                    is_auctioneer = excluded.is_auctioneer,
                    is_team_member = 1,
                    is_active = 1
            """, (
                league_id,
                user_id,
                team_id,
                1 if username == "IBBINI IDIOTA" else 0,
                1 if username == "IBBINI IDIOTA" else 0
            ))

        conn.commit()

        return league_id

    finally:

        chiudi_connessione(
            conn
        )



def assegna_ruoli_utenti_esistenti_v138():
    """
    V138 - migrazione idempotente richiesta per gli utenti già esistenti.

    GOSTOBAR:
      - SQUADRA

    IBBINI IDIOTA:
      - SQUADRA
      - BANDITORE
      - ADMIN

    Non crea nuovi account e non modifica password.
    Opera solo sulle leghe in cui l'utente è già presente o possiede
    una squadra esistente.
    """
    guard = "_v138_existing_roles_done"
    if st.session_state.get(guard):
        return

    configurazione = {
        "GOSTOBAR": {
            "admin": 0,
            "auctioneer": 0,
            "team": 1,
        },
        "IBBINI IDIOTA": {
            "admin": 1,
            "auctioneer": 1,
            "team": 1,
        },
    }

    conn = _portal_raw_connection()
    cur = conn.cursor()

    try:
        for username, permessi in configurazione.items():
            cur.execute("""
                SELECT id
                FROM users
                WHERE LOWER(username)=LOWER(?)
                  AND is_active=1
                LIMIT 1
            """, (username,))
            r_user = cur.fetchone()
            if not r_user:
                continue

            user_id = int(r_user[0])

            # Tutte le leghe dove l'utente è già presente tramite membership
            # oppure possiede/ha una squadra con il proprio nome.
            cur.execute("""
                SELECT DISTINCT league_id
                FROM (
                    SELECT league_id
                    FROM league_members
                    WHERE user_id=?

                    UNION

                    SELECT league_id
                    FROM teams
                    WHERE owner_user_id=?
                       OR LOWER(nome)=LOWER(?)
                )
            """, (user_id, user_id, username))

            league_ids = [
                int(r[0])
                for r in (cur.fetchall() or [])
                if r[0] is not None
            ]

            for league_id in league_ids:
                # Identifica la squadra reale dell'utente.
                cur.execute("""
                    SELECT id
                    FROM teams
                    WHERE league_id=?
                      AND is_active=1
                      AND (
                          owner_user_id=?
                          OR LOWER(nome)=LOWER(?)
                      )
                    ORDER BY
                        CASE WHEN owner_user_id=? THEN 0 ELSE 1 END,
                        id
                    LIMIT 1
                """, (
                    league_id,
                    user_id,
                    username,
                    user_id
                ))
                r_team = cur.fetchone()
                team_id = int(r_team[0]) if r_team else None

                # Normalizza eventuali membership già esistenti.
                # GOSTOBAR non deve risultare Admin/Banditore.
                # IBBINI mantiene Admin/Banditore su tutte le membership.
                cur.execute("""
                    UPDATE league_members
                    SET is_admin=?,
                        is_auctioneer=?,
                        is_active=1
                    WHERE league_id=?
                      AND user_id=?
                """, (
                    int(permessi["admin"]),
                    int(permessi["auctioneer"]),
                    league_id,
                    user_id
                ))

                if team_id is not None:
                    # La membership di squadra è quella che abilita SQUADRA.
                    cur.execute("""
                        INSERT INTO league_members (
                            league_id,
                            user_id,
                            team_id,
                            is_admin,
                            is_auctioneer,
                            is_team_member,
                            is_active,
                            joined_at
                        )
                        VALUES (?,?,?,?,?,1,1,CURRENT_TIMESTAMP)
                        ON CONFLICT(league_id,user_id,team_id)
                        DO UPDATE SET
                            is_admin=excluded.is_admin,
                            is_auctioneer=excluded.is_auctioneer,
                            is_team_member=1,
                            is_active=1
                    """, (
                        league_id,
                        user_id,
                        team_id,
                        int(permessi["admin"]),
                        int(permessi["auctioneer"])
                    ))

                    # Mantiene ownership coerente.
                    cur.execute("""
                        UPDATE teams
                        SET owner_user_id=?,
                            updated_at=CURRENT_TIMESTAMP
                        WHERE league_id=?
                          AND id=?
                    """, (
                        user_id,
                        league_id,
                        team_id
                    ))

                # Membership senza team: mai qualificata come SQUADRA.
                cur.execute("""
                    UPDATE league_members
                    SET is_team_member=0
                    WHERE league_id=?
                      AND user_id=?
                      AND team_id IS NULL
                """, (
                    league_id,
                    user_id
                ))

        conn.commit()
        st.session_state[guard] = True

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)



def sincronizza_legacy_in_multilega():
    """
    Copia nel nuovo schema una fotografia dei dati legacy correnti.

    In V83 il sistema legacy resta la fonte autorevole.
    Le nuove tabelle servono a verificare e preparare
    l'isolamento league_id/team_id.
    """

    league_id = migra_profili_legacy_in_multilega()

    raw_conn = _get_raw_connection()
    raw_cur = raw_conn.cursor()

    try:

        for username in PROFILI_APP:

            raw_cur.execute(
                "SELECT id FROM users WHERE username = ?",
                (
                    username,
                )
            )
            r_user = raw_cur.fetchone()

            if not r_user:
                continue

            user_id = int(
                r_user[0]
            )

            raw_cur.execute("""
                SELECT id
                FROM teams
                WHERE league_id = ?
                  AND nome = ?
            """, (
                league_id,
                username
            ))
            r_team = raw_cur.fetchone()

            if not r_team:
                continue

            team_id = int(
                r_team[0]
            )

            tabella_giocatori = (
                "giocatori"
                if username == "IBBINI IDIOTA"
                else "giocatori_gostobar"
            )

            tabella_config = (
                "configurazione_app"
                if username == "IBBINI IDIOTA"
                else "configurazione_app_gostobar"
            )

            # Budget legacy
            budget = 500.0

            try:

                raw_cur.execute(
                    f"""
                    SELECT valore
                    FROM {tabella_config}
                    WHERE chiave = 'budget_asta'
                    """
                )

                r_budget = raw_cur.fetchone()

                if r_budget and r_budget[0] not in (
                    None,
                    ""
                ):
                    budget = float(
                        r_budget[0]
                    )

            except Exception:
                budget = 500.0

            # Rosa legacy
            try:

                raw_cur.execute(
                    f"""
                    SELECT
                        id,
                        COALESCE(prezzo_acquisto, 0)
                    FROM {tabella_giocatori}
                    WHERE stato = 'MIO'
                    """
                )

                rosa_legacy = (
                    raw_cur.fetchall()
                    or []
                )

            except Exception:
                rosa_legacy = []

            # La fotografia viene ricostruita ad ogni avvio V83.
            raw_cur.execute("""
                DELETE FROM rosters
                WHERE league_id = ?
                  AND team_id = ?
                  AND fonte = 'LEGACY'
            """, (
                league_id,
                team_id
            ))

            valore_acquisti = 0.0

            for player_id, prezzo in rosa_legacy:

                prezzo = float(
                    prezzo
                    or 0
                )

                valore_acquisti += prezzo

                raw_cur.execute("""
                    INSERT INTO rosters (
                        league_id,
                        team_id,
                        player_id,
                        prezzo_acquisto,
                        fonte,
                        updated_at
                    )
                    VALUES (?, ?, ?, ?, 'LEGACY', CURRENT_TIMESTAMP)
                    ON CONFLICT(league_id, team_id, player_id)
                    DO UPDATE SET
                        prezzo_acquisto = excluded.prezzo_acquisto,
                        fonte = 'LEGACY',
                        updated_at = CURRENT_TIMESTAMP
                """, (
                    league_id,
                    team_id,
                    int(
                        player_id
                    ),
                    prezzo
                ))

            raw_cur.execute("""
                INSERT INTO team_budgets (
                    league_id,
                    team_id,
                    budget_impostato,
                    valore_acquisti,
                    spesa_effettiva,
                    updated_at
                )
                VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                ON CONFLICT(league_id, team_id)
                DO UPDATE SET
                    budget_impostato = excluded.budget_impostato,
                    valore_acquisti = excluded.valore_acquisti,
                    spesa_effettiva = excluded.spesa_effettiva,
                    updated_at = CURRENT_TIMESTAMP
            """, (
                league_id,
                team_id,
                budget,
                valore_acquisti,
                valore_acquisti
            ))

        raw_conn.commit()

        return league_id

    finally:

        if not USA_DATABASE_CLOUD:

            try:
                raw_conn.close()
            except Exception:
                pass


def imposta_contesto_multilega_sessione(
    league_id
):
    """
    Espone nel session_state il contesto multilega corrente.
    L'interfaccia V83 continua comunque a utilizzare il legacy.
    """

    conn = get_connection()
    cur = conn.cursor()

    try:

        cur.execute(
            "SELECT id FROM users WHERE username = ?",
            (
                PROFILO_ATTIVO,
            )
        )
        r_user = cur.fetchone()

        cur.execute("""
            SELECT id
            FROM teams
            WHERE league_id = ?
              AND nome = ?
        """, (
            league_id,
            PROFILO_ATTIVO
        ))
        r_team = cur.fetchone()

        st.session_state[
            "ml_schema_version"
        ] = MULTILEGA_SCHEMA_VERSION

        st.session_state[
            "ml_league_id"
        ] = int(
            league_id
        )

        st.session_state[
            "ml_user_id"
        ] = (
            int(
                r_user[0]
            )
            if r_user
            else None
        )

        st.session_state[
            "ml_team_id"
        ] = (
            int(
                r_team[0]
            )
            if r_team
            else None
        )

    finally:

        chiudi_connessione(
            conn
        )




# ============================================================
# MULTILEGA 0.2 - ACCESSI UTENTE -> LEGA -> SQUADRA
# ============================================================

def elenca_accessi_multilega(
    username
):
    cache_key = "_v139_accessi_" + str(username).strip().casefold()
    cached = st.session_state.get(cache_key)
    if isinstance(cached, list):
        return [dict(x) for x in cached]



    conn = get_connection()
    cur = conn.cursor()

    try:

        cur.execute("""
            SELECT
                u.id,
                l.id,
                l.nome,
                COALESCE(l.stagione, ''),
                COALESCE(l.modalita, ''),
                COALESCE(l.stato, ''),
                t.id,
                COALESCE(t.nome, ''),
                lm.is_admin,
                lm.is_auctioneer,
                lm.is_team_member
            FROM users u

            JOIN league_members lm
              ON lm.user_id = u.id
             AND lm.is_active = 1

            JOIN leagues l
              ON l.id = lm.league_id

            LEFT JOIN teams t
              ON t.id = lm.team_id
             AND t.is_active = 1

            WHERE u.username = ?
              AND u.is_active = 1

            ORDER BY
                l.nome,
                t.posizione,
                t.nome
        """, (
            username,
        ))

        righe = (
            cur.fetchall()
            or []
        )

        accessi = []

        for riga in righe:

            (
                user_id,
                league_id,
                league_nome,
                stagione,
                modalita,
                league_stato,
                team_id,
                team_nome,
                is_admin,
                is_auctioneer,
                is_team_member
            ) = riga

            ruoli = []

            if int(is_admin or 0) == 1:
                ruoli.append(
                    "ADMIN"
                )

            if int(is_auctioneer or 0) == 1:
                ruoli.append(
                    "BANDITORE"
                )

            if int(is_team_member or 0) == 1:
                ruoli.append(
                    "SQUADRA"
                )

            accessi.append({
                "user_id":
                    int(user_id),

                "league_id":
                    int(league_id),

                "league_nome":
                    str(league_nome),

                "stagione":
                    str(stagione or ""),

                "modalita":
                    str(modalita or ""),

                "league_stato":
                    str(league_stato or ""),

                "team_id":
                    (
                        int(team_id)
                        if team_id is not None
                        else None
                    ),

                "team_nome":
                    str(team_nome or ""),

                "ruoli":
                    ruoli
            })

        st.session_state[cache_key] = [dict(x) for x in accessi]
        return accessi

    finally:

        chiudi_connessione(
            conn
        )


def accesso_multilega_corrente():
    """
    Verifica che il contesto salvato in sessione appartenga davvero
    all'utente attivo. Nessun team_id viene accettato solo perché
    presente nel browser/session_state.
    """

    league_id = st.session_state.get(
        "ml_league_id"
    )

    team_id = st.session_state.get(
        "ml_team_id"
    )

    user_id = st.session_state.get(
        "ml_user_id"
    )

    if (
        league_id is None
        or user_id is None
    ):
        return None

    accessi = elenca_accessi_multilega(
        PROFILO_ATTIVO
    )

    for accesso in accessi:

        if (
            int(accesso["league_id"])
            == int(league_id)
            and int(accesso["user_id"])
            == int(user_id)
            and (
                accesso["team_id"]
                == team_id
            )
        ):

            return accesso

    return None


def applica_accesso_multilega(accesso):
    """
    V136 - separazione netta del contesto operativo.

    Le credenziali identificano l'utente.
    La sessione sceglie poi UNA modalità di accesso:
      - SQUADRA
      - BANDITORE
      - ADMIN

    Lo stesso account può quindi essere aperto contemporaneamente in
    sessioni/browser/device differenti con modalità diverse.
    """
    modalita_accesso = str(
        accesso.get("modalita_accesso")
        or st.session_state.get("ml_modalita_accesso")
        or ""
    ).strip().upper()

    if modalita_accesso not in ("SQUADRA", "BANDITORE", "ADMIN"):
        # Compatibilità con vecchi accessi salvati in sessione.
        ruoli = [str(x).upper() for x in accesso.get("ruoli", [])]
        if "SQUADRA" in ruoli and accesso.get("team_id") is not None:
            modalita_accesso = "SQUADRA"
        elif "BANDITORE" in ruoli:
            modalita_accesso = "BANDITORE"
        elif "ADMIN" in ruoli:
            modalita_accesso = "ADMIN"
        else:
            raise PermissionError("Nessun livello di accesso valido.")

    ruoli_autorizzati = [
        str(x).upper()
        for x in accesso.get("ruoli", [])
    ]

    richiesto_db = {
        "SQUADRA": "SQUADRA",
        "BANDITORE": "BANDITORE",
        "ADMIN": "ADMIN",
    }[modalita_accesso]

    if richiesto_db not in ruoli_autorizzati:
        raise PermissionError(
            f"L'utente non dispone del livello {modalita_accesso}."
        )

    if (
        modalita_accesso == "SQUADRA"
        and accesso.get("team_id") is None
    ):
        raise PermissionError(
            "L'accesso SQUADRA richiede una squadra associata."
        )

    st.session_state["ml_schema_version"] = MULTILEGA_SCHEMA_VERSION
    st.session_state["ml_user_id"] = int(accesso["user_id"])
    st.session_state["ml_league_id"] = int(accesso["league_id"])
    st.session_state["ml_league_nome"] = accesso["league_nome"]
    st.session_state["ml_stagione"] = accesso["stagione"]
    st.session_state["ml_modalita"] = accesso["modalita"]

    # Salviamo i ruoli realmente autorizzati separatamente dal ruolo attivo.
    st.session_state["ml_ruoli_autorizzati"] = list(ruoli_autorizzati)
    st.session_state["ml_modalita_accesso"] = modalita_accesso

    # V153 - la sidebar appartiene sempre alla SQUADRA dell'utente.
    # Conserviamo quindi il riferimento alla squadra anche quando il contesto
    # operativo ADMIN/BANDITORE azzera volutamente ml_team_id.
    _sidebar_team_id = accesso.get("team_id")
    _sidebar_team_nome = str(accesso.get("team_nome") or "")

    if _sidebar_team_id is None:
        # Fallback robusto: cerca la squadra posseduta dall'utente nella lega.
        _conn_sidebar = _portal_raw_connection()
        _cur_sidebar = _conn_sidebar.cursor()
        try:
            _cur_sidebar.execute("""
                SELECT id, COALESCE(nome,'')
                FROM teams
                WHERE league_id=?
                  AND owner_user_id=?
                  AND is_active=1
                ORDER BY posizione, id
                LIMIT 1
            """, (int(accesso["league_id"]), int(accesso["user_id"])))
            _r_sidebar = _cur_sidebar.fetchone()
            if _r_sidebar:
                _sidebar_team_id = int(_r_sidebar[0])
                _sidebar_team_nome = str(_r_sidebar[1] or "")
        finally:
            _portal_close(_conn_sidebar)

    if _sidebar_team_id is not None:
        st.session_state["ml_sidebar_team_id"] = int(_sidebar_team_id)
        st.session_state["ml_sidebar_team_nome"] = _sidebar_team_nome

    # RUOLI_ATTIVI deve contenere esclusivamente il ruolo della pagina corrente.
    if modalita_accesso == "SQUADRA":
        st.session_state["ml_ruoli"] = ["TEAM"]
        st.session_state["ml_team_id"] = int(accesso["team_id"])
        st.session_state["ml_team_nome"] = str(accesso.get("team_nome") or "")
    elif modalita_accesso == "BANDITORE":
        st.session_state["ml_ruoli"] = ["AUCTIONEER"]
        st.session_state["ml_team_id"] = None
        st.session_state["ml_team_nome"] = ""
    else:
        st.session_state["ml_ruoli"] = ["ADMIN"]
        st.session_state["ml_team_id"] = None
        st.session_state["ml_team_nome"] = ""




def logout_completo_v143():
    """
    Torna davvero alla schermata login.

    Pulisce sia il contesto multilega sia lo stato di autenticazione.
    """
    azzera_contesto_multilega()

    chiavi_logout = [
        "profilo_attivo",
        "profilo_login_select",
        "auth_user_id",
        "auth_ok",
        "auth_username",
        "ml_accesso_validato",
        "ml_modalita_accesso",
        "ml_ruoli",
        "ml_ruoli_autorizzati",
        "pagina",
    ]

    for chiave in chiavi_logout:
        st.session_state.pop(chiave, None)

    # Pulisce anche la cache accessi della sessione precedente.
    for chiave in list(st.session_state.keys()):
        if str(chiave).startswith("_v139_accessi_"):
            st.session_state.pop(chiave, None)



def azzera_contesto_multilega():
    """
    Torna alla schermata LE MIE LEGHE senza scollegare l'utente.
    """

    for chiave in [
        "ml_user_id",
        "ml_league_id",
        "ml_team_id",
        "ml_league_nome",
        "ml_team_nome",
        "ml_ruoli",
        "ml_ruoli_autorizzati",
        "ml_modalita_accesso",
        "ml_stagione",
        "ml_modalita",
        "ml_accesso_validato",
        "ml_workspace_suffix",
        "ml_runtime_workspace_key"
    ]:

        st.session_state.pop(
            chiave,
            None
        )


def schermata_le_mie_leghe(accessi):
    """
    V136 - dopo il login si sceglie LEGA + LIVELLO DI ACCESSO.

    Le credenziali restano uniche.
    Il livello operativo viene selezionato per questa singola sessione.
    """
    st.markdown(
        """
        <style>
        div[data-testid="stMainBlockContainer"] {
            padding-top: 1.4rem !important;
        }
        .ml136-wrap {max-width:940px;margin:0 auto;}
        .ml136-header {
            background:linear-gradient(110deg,#061f3a 0%,#0b3158 100%);
            border:2px solid #ffc21c;border-radius:18px;
            padding:22px 26px;margin-bottom:20px;color:white;
        }
        .ml136-title {font-size:28px;font-weight:950;line-height:1;}
        .ml136-title span {color:#ffc21c;}
        .ml136-user {margin-top:8px;color:#cbd5e1;font-size:14px;}
        .ml136-card {
            background:white;border:1px solid #dbe3ec;border-radius:14px;
            padding:17px 19px;margin:0 0 12px 0;
            box-shadow:0 3px 12px rgba(15,23,42,.05);
        }
        .ml136-league {
            color:#071a2f;font-size:20px;line-height:1.1;font-weight:950;
        }
        .ml136-meta {color:#64748b;font-size:12px;margin-top:5px;}
        .ml136-team {
            color:#071a2f;font-size:14px;font-weight:850;margin-top:9px;
        }
        </style>
        """,
        unsafe_allow_html=True
    )

    st.markdown(
        (
            '<div class="ml136-wrap"><div class="ml136-header">'
            '<div class="ml136-title">FANTAELEGANZA '
            '<span>ACCESSO</span></div>'
            '<div class="ml136-user">Utente: '
            + html.escape(PROFILO_ATTIVO)
            + ' · scegli la lega e il livello con cui entrare</div>'
            '</div></div>'
        ),
        unsafe_allow_html=True
    )

    if not accessi:
        st.error("Questo utente non è associato ad alcuna lega attiva.")
        if st.button("← CAMBIA UTENTE", key="ml136_logout_empty"):
            logout_completo_v143()
            st.rerun()
        st.stop()

    # V137: i permessi possono trovarsi su membership diverse della stessa
    # lega (es. riga ADMIN senza team + riga TEAM con team). Li aggreghiamo
    # per lega senza perdere la membership concreta della squadra.
    gruppi = {}

    for accesso in accessi:
        lid = int(accesso["league_id"])

        gruppo = gruppi.setdefault(lid, {
            "league_id": lid,
            "league_nome": accesso["league_nome"],
            "stagione": accesso["stagione"],
            "modalita": accesso["modalita"],
            "ruoli_lega": set(),
            "SQUADRA": None,
            "BANDITORE": None,
            "ADMIN": None,
        })

        ruoli_riga = {
            str(x).upper()
            for x in accesso.get("ruoli", [])
        }
        gruppo["ruoli_lega"].update(ruoli_riga)

        # SQUADRA deve usare la membership che contiene davvero team_id.
        if (
            "SQUADRA" in ruoli_riga
            and accesso.get("team_id") is not None
            and gruppo["SQUADRA"] is None
        ):
            gruppo["SQUADRA"] = dict(accesso)

        # BANDITORE/ADMIN possono essere membership senza team.
        if (
            "BANDITORE" in ruoli_riga
            and gruppo["BANDITORE"] is None
        ):
            gruppo["BANDITORE"] = dict(accesso)

        if (
            "ADMIN" in ruoli_riga
            and gruppo["ADMIN"] is None
        ):
            gruppo["ADMIN"] = dict(accesso)

    # Se una stessa membership contiene più permessi, ogni modalità riceve
    # comunque l'insieme completo dei ruoli autorizzati della lega.
    for gruppo in gruppi.values():
        ruoli_lega = sorted(gruppo["ruoli_lega"])
        for modalita_accesso in ("SQUADRA", "BANDITORE", "ADMIN"):
            accesso_ruolo = gruppo.get(modalita_accesso)
            if accesso_ruolo is not None:
                accesso_ruolo["ruoli"] = list(ruoli_lega)

    st.caption(
        "Le stesse credenziali possono essere utilizzate contemporaneamente "
        "su più browser o dispositivi. Ogni sessione mantiene il proprio "
        "livello di accesso."
    )

    def _entra_modalita(accesso_base, modalita_accesso):
        st.session_state["_v139_enter_started"] = time.perf_counter()
        accesso_scelto = dict(accesso_base)
        accesso_scelto["modalita_accesso"] = modalita_accesso

        applica_accesso_multilega(accesso_scelto)
        st.session_state["ml_accesso_validato"] = dict(accesso_scelto)

        pagina_iniziale = {
            "SQUADRA": "DASHBOARD",
            "BANDITORE": "GESTIONE ASTA",
            "ADMIN": "GESTIONE LEGA",
        }[modalita_accesso]
        st.session_state["pagina"] = pagina_iniziale

        # Pulisce esclusivamente cache di UI/workspace del contesto precedente.
        for k in list(st.session_state.keys()):
            if (
                str(k).startswith("_df_")
                or str(k).startswith("_ultime_")
                or str(k).startswith("_costi_")
                or str(k).startswith("pdf_")
                or str(k).startswith("_ml16_sidebar_metrics")
            ):
                st.session_state.pop(k, None)

    for lid, gruppo in sorted(
        gruppi.items(),
        key=lambda x: str(x[1]["league_nome"]).casefold()
    ):
        meta = " · ".join(
            x for x in (gruppo["stagione"], gruppo["modalita"]) if x
        )

        team_nome = ""
        if gruppo["SQUADRA"] is not None:
            team_nome = str(gruppo["SQUADRA"].get("team_nome") or "")

        st.markdown(
            (
                '<div class="ml136-card">'
                '<div class="ml136-league">'
                + html.escape(str(gruppo["league_nome"]))
                + '</div>'
                '<div class="ml136-meta">'
                + html.escape(meta)
                + '</div>'
                + (
                    '<div class="ml136-team">Squadra: '
                    + html.escape(team_nome)
                    + '</div>'
                    if team_nome else ""
                )
                + '</div>'
            ),
            unsafe_allow_html=True
        )

        disponibili = [
            x for x in ("SQUADRA", "BANDITORE", "ADMIN")
            if gruppo[x] is not None
        ]

        if not disponibili:
            st.warning(
                "Questa membership non ha ancora un livello operativo "
                "SQUADRA, BANDITORE o ADMIN assegnato."
            )
            continue

        cols = st.columns(len(disponibili))

        for col, ruolo in zip(cols, disponibili):
            with col:
                icona = {
                    "SQUADRA": "👕",
                    "BANDITORE": "🔨",
                    "ADMIN": "⚙️",
                }[ruolo]

                st.button(
                    f"{icona} ENTRA COME {ruolo}",
                    type="primary" if ruolo == "SQUADRA" else "secondary",
                    use_container_width=True,
                    key=f"ml136_{lid}_{ruolo}",
                    on_click=_entra_modalita,
                    args=(gruppo[ruolo], ruolo)
                )

    st.markdown("---")

    if st.button(
        "← CAMBIA UTENTE",
        use_container_width=False,
        key="ml136_cambia_utente"
    ):
        logout_completo_v143()
        st.rerun()

    st.stop()





# ============================================================
# MULTILEGA 0.3 - ADMIN LEGA
# ============================================================

def crea_lega_multilega(
    nome,
    stagione,
    modalita,
    partecipanti,
    max_giocatori,
    min_portieri,
    budget_iniziale,
    incremento_minimo,
    soglia_budget,
    moltiplicatore_oltre_soglia,
    tipo_asta,
    fonte_listone,
    budget_illimitato=False,
    fair_play_finanziario=False,
    tipo_incremento_asta="FISSO",
    incrementi_scalari=None
):
    """
    Crea atomicamente:
    - league
    - league_rules
    - N squadre placeholder
    - membership ADMIN del creatore
    - audit log
    """

    tipo_incremento_asta, incremento_minimo, incrementi_scalari = _normalizza_incrementi_scalari_v187(
        tipo_incremento_asta, incremento_minimo, incrementi_scalari
    )

    conn = get_connection()
    cur = conn.cursor()

    try:

        cur.execute(
            "SELECT id FROM users WHERE username = ?",
            (
                PROFILO_ATTIVO,
            )
        )

        r_user = cur.fetchone()

        if not r_user:
            raise ValueError(
                "Utente multilega non trovato."
            )

        user_id = int(
            r_user[0]
        )

        cur.execute("""
            INSERT INTO leagues (
                nome,
                stagione,
                modalita,
                stato,
                created_by_user_id,
                created_at,
                updated_at
            )
            VALUES (
                ?, ?, ?, 'DRAFT', ?,
                CURRENT_TIMESTAMP,
                CURRENT_TIMESTAMP
            )
        """, (
            nome.strip(),
            stagione.strip(),
            modalita,
            user_id
        ))

        league_id = int(
            cur.lastrowid
        )

        cur.execute("""
            INSERT INTO league_rules (
                league_id,
                partecipanti,
                max_giocatori,
                min_portieri,
                budget_iniziale,
                incremento_minimo,
                tipo_incremento_asta,
                incrementi_scalari_json,
                soglia_budget,
                moltiplicatore_oltre_soglia,
                tipo_asta,
                fonte_listone,
                budget_illimitato,
                fair_play_finanziario,
                regolamento_bloccato,
                created_at,
                updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0,
                    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
        """, (
            league_id,
            int(partecipanti),
            int(max_giocatori),
            int(min_portieri),
            float(budget_iniziale),
            float(incremento_minimo),
            tipo_incremento_asta,
            json.dumps(incrementi_scalari, ensure_ascii=False),
            float(soglia_budget),
            float(moltiplicatore_oltre_soglia),
            tipo_asta,
            fonte_listone.strip(),
            1 if budget_illimitato else 0,
            1 if fair_play_finanziario else 0
        ))

        # L'Admin inizialmente appartiene alla lega senza essere
        # obbligatoriamente proprietario di una squadra.
        cur.execute("""
            INSERT INTO league_members (
                league_id,
                user_id,
                team_id,
                is_admin,
                is_auctioneer,
                is_team_member,
                is_active,
                joined_at
            )
            VALUES (?, ?, NULL, 1, 0, 0, 1, CURRENT_TIMESTAMP)
        """, (
            league_id,
            user_id
        ))

        for posizione in range(
            1,
            int(partecipanti) + 1
        ):

            cur.execute("""
                INSERT INTO teams (
                    league_id,
                    nome,
                    owner_user_id,
                    posizione,
                    is_active,
                    created_at,
                    updated_at
                )
                VALUES (?, ?, NULL, ?, 1,
                        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
            """, (
                league_id,
                f"Squadra {posizione}",
                posizione
            ))

        cur.execute("""
            INSERT INTO audit_log (
                league_id,
                user_id,
                team_id,
                azione,
                entita,
                entita_id,
                dettagli_json,
                created_at
            )
            VALUES (?, ?, NULL, 'LEAGUE_CREATED',
                    'LEAGUE', ?, ?, CURRENT_TIMESTAMP)
        """, (
            league_id,
            user_id,
            str(league_id),
            json.dumps(
                {
                    "nome":
                        nome.strip(),

                    "partecipanti":
                        int(partecipanti),

                    "budget":
                        float(budget_iniziale),

                    "modalita":
                        modalita
                },
                ensure_ascii=False
            )
        ))

        conn.commit()

        return league_id

    except Exception:

        try:
            conn.rollback()
        except Exception:
            pass

        raise

    finally:

        chiudi_connessione(
            conn
        )



def invalida_cache_admin_multilega():
    for chiave in list(st.session_state.keys()):
        if str(chiave).startswith("_v139_accessi_"):
            st.session_state.pop(chiave, None)
            continue
        if chiave.startswith((
            "_ml16_admin_leghe_",
            "_ml16_admin_rules_",
            "_ml16_admin_teams_",
            "_ml16_admin_teamdetails_"
        )):
            st.session_state.pop(chiave, None)


def leghe_amministrate_multilega():
    """
    Elenco compatto delle leghe in cui l'utente corrente è ADMIN.
    Una sola query.
    """

    cache_key="_ml16_admin_leghe_"+str(st.session_state.get("auth_user_id",""))
    cached=st.session_state.get(cache_key)
    if isinstance(cached,list):
        return [dict(x) for x in cached]

    conn = get_connection()
    cur = conn.cursor()

    try:

        cur.execute("""
            SELECT
                l.id,
                l.nome,
                COALESCE(l.stagione, ''),
                COALESCE(l.modalita, ''),
                COALESCE(l.stato, ''),
                r.partecipanti,
                r.max_giocatori,
                r.min_portieri,
                r.budget_iniziale,
                r.incremento_minimo,
                r.soglia_budget,
                r.moltiplicatore_oltre_soglia,
                COALESCE(r.tipo_asta, ''),
                COALESCE(r.fonte_listone, ''),
                COALESCE(r.tipo_incremento_asta,'FISSO'),
                COALESCE(r.incrementi_scalari_json,'[]'),
                COALESCE(r.budget_illimitato,0),
                COALESCE(r.fair_play_finanziario,0),
                r.regolamento_bloccato,
                (
                    SELECT COUNT(*)
                    FROM teams t
                    WHERE t.league_id = l.id
                      AND t.is_active = 1
                ) AS squadre_attive
            FROM league_members lm

            JOIN users u
              ON u.id = lm.user_id

            JOIN leagues l
              ON l.id = lm.league_id

            JOIN league_rules r
              ON r.league_id = l.id

            WHERE u.username = ?
              AND lm.is_admin = 1
              AND lm.is_active = 1

            ORDER BY l.id DESC
        """, (
            PROFILO_ATTIVO,
        ))

        colonne = [
            "league_id",
            "nome",
            "stagione",
            "modalita",
            "stato",
            "partecipanti",
            "max_giocatori",
            "min_portieri",
            "budget_iniziale",
            "incremento_minimo",
            "soglia_budget",
            "moltiplicatore",
            "tipo_asta",
            "fonte_listone",
            "tipo_incremento_asta",
            "incrementi_scalari_json",
            "budget_illimitato",
            "fair_play_finanziario",
            "regolamento_bloccato",
            "squadre_attive"
        ]

        risultato = [
            dict(zip(colonne, riga))
            for riga in (cur.fetchall() or [])
        ]
        st.session_state[cache_key]=[dict(x) for x in risultato]
        return risultato

    finally:

        chiudi_connessione(
            conn
        )


