def dettagli_squadre_lega_multilega(league_id):
    """
    Restituisce squadre, proprietari e ruoli correnti.
    I ruoli sono sempre letti dal DB, non dalla sessione browser.
    """
    league_id = int(league_id)
    cache_key="_ml16_admin_teamdetails_"+str(league_id)
    cached=st.session_state.get(cache_key)
    if isinstance(cached,list):
        return [dict(x) for x in cached]

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT
                t.id,
                t.nome,
                t.posizione,
                t.owner_user_id,
                COALESCE(u.username, ''),
                COALESCE(MAX(lm.is_admin), 0),
                COALESCE(MAX(lm.is_auctioneer), 0),
                COALESCE(MAX(lm.is_team_member), 1),
                COALESCE(MAX(lm.is_active), 1)
            FROM teams t
            LEFT JOIN users u
              ON u.id = t.owner_user_id
            LEFT JOIN league_members lm
              ON lm.league_id = t.league_id
             AND lm.user_id = t.owner_user_id
             AND lm.is_active = 1
            WHERE t.league_id = ?
              AND t.is_active = 1
            GROUP BY
                t.id,t.nome,t.posizione,t.owner_user_id,u.username
            ORDER BY t.posizione, t.id
        """, (league_id,))
        risultato = [
            {
                "team_id": int(r[0]),
                "nome": str(r[1] or ""),
                "posizione": int(r[2] or 0),
                "owner_user_id": int(r[3]) if r[3] is not None else None,
                "username": str(r[4] or ""),
                "is_admin": bool(r[5]),
                "is_auctioneer": bool(r[6]),
                "is_team_member": bool(r[7]),
                "is_active": bool(r[8]),
            }
            for r in (cur.fetchall() or [])
        ]
        st.session_state[cache_key]=[dict(x) for x in risultato]
        return risultato
    finally:
        _portal_close(conn)


def aggiorna_ruoli_squadra_multilega(league_id, team_id, is_admin, is_auctioneer):
    """
    Modifica i ruoli ADMIN/BANDITORE della squadra.
    TEAM resta sempre attivo per le squadre operative.
    Non consente di eliminare l'ultimo Admin della lega.
    """
    league_id = int(league_id)
    team_id = int(team_id)
    current_admin = int(st.session_state.get("auth_user_id") or 0)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT COUNT(*)
            FROM league_members
            WHERE league_id = ?
              AND user_id = ?
              AND is_admin = 1
              AND is_active = 1
        """, (league_id, current_admin))
        if int(cur.fetchone()[0] or 0) == 0:
            raise PermissionError("Operazione riservata all'Admin della lega.")

        cur.execute("""
            SELECT t.owner_user_id, t.nome, COALESCE(lm.is_admin,0), COALESCE(lm.is_auctioneer,0)
            FROM teams t
            LEFT JOIN league_members lm
              ON lm.league_id=t.league_id
             AND lm.team_id=t.id
             AND lm.user_id=t.owner_user_id
            WHERE t.league_id=? AND t.id=? AND t.is_active=1
            LIMIT 1
        """, (league_id, team_id))
        r = cur.fetchone()
        if not r:
            raise ValueError("Squadra non trovata.")

        owner_user_id = int(r[0]) if r[0] is not None else None
        nome = str(r[1] or "")
        old_admin = bool(r[2])
        old_auctioneer = bool(r[3])

        if owner_user_id is None:
            raise ValueError("La squadra non ha un account proprietario associato.")

        if old_admin and not bool(is_admin):
            cur.execute("""
                SELECT COUNT(DISTINCT user_id)
                FROM league_members
                WHERE league_id=?
                  AND is_admin=1
                  AND is_active=1
                  AND user_id<>?
            """, (league_id, owner_user_id))
            if int(cur.fetchone()[0] or 0) == 0:
                raise ValueError(
                    "Non puoi togliere il ruolo Admin all'unico Admin della lega. "
                    "Assegna prima il ruolo Admin a un'altra squadra."
                )

        cur.execute("""
            UPDATE league_members
            SET is_admin=?,
                is_auctioneer=?,
                is_team_member=1,
                is_active=1
            WHERE league_id=?
              AND team_id=?
              AND user_id=?
        """, (
            1 if is_admin else 0,
            1 if is_auctioneer else 0,
            league_id,
            team_id,
            owner_user_id
        ))

        if cur.rowcount == 0:
            cur.execute("""
                INSERT INTO league_members
                (league_id,user_id,team_id,is_admin,is_auctioneer,is_team_member,is_active,joined_at)
                VALUES (?,?,?,?,?,1,1,CURRENT_TIMESTAMP)
            """, (
                league_id,
                owner_user_id,
                team_id,
                1 if is_admin else 0,
                1 if is_auctioneer else 0
            ))

        cur.execute("""
            INSERT INTO audit_log
            (league_id,user_id,team_id,azione,entita,entita_id,dettagli_json,created_at)
            VALUES (?,?,?,'ROLES_UPDATED','TEAM',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            current_admin,
            team_id,
            str(team_id),
            json.dumps({
                "team": nome,
                "admin_prima": old_admin,
                "admin_dopo": bool(is_admin),
                "banditore_prima": old_auctioneer,
                "banditore_dopo": bool(is_auctioneer)
            }, ensure_ascii=False)
        ))

        conn.commit()
        invalida_cache_admin_multilega()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)


def reset_password_squadra_multilega(league_id, team_id, nuova_password):
    """
    Reset amministrativo: l'Admin imposta una nuova password.
    La password non viene mai salvata nell'audit.
    """
    league_id = int(league_id)
    team_id = int(team_id)
    nuova_password = str(nuova_password)

    if len(nuova_password) < 8:
        raise ValueError("La nuova password deve contenere almeno 8 caratteri.")

    current_admin = int(st.session_state.get("auth_user_id") or 0)
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT COUNT(*)
            FROM league_members
            WHERE league_id=? AND user_id=? AND is_admin=1 AND is_active=1
        """, (league_id, current_admin))
        if int(cur.fetchone()[0] or 0) == 0:
            raise PermissionError("Operazione riservata all'Admin della lega.")

        cur.execute("""
            SELECT t.owner_user_id, t.nome, COALESCE(u.username,'')
            FROM teams t
            LEFT JOIN users u ON u.id=t.owner_user_id
            WHERE t.league_id=? AND t.id=? AND t.is_active=1
            LIMIT 1
        """, (league_id, team_id))
        r = cur.fetchone()
        if not r or r[0] is None:
            raise ValueError("Account della squadra non trovato.")

        owner_user_id = int(r[0])
        nome = str(r[1] or "")
        username = str(r[2] or "")

        cur.execute("""
            UPDATE users
            SET password_hash=?,
                updated_at=CURRENT_TIMESTAMP
            WHERE id=? AND is_active=1
        """, (password_hash_sicuro(nuova_password), owner_user_id))

        cur.execute("""
            INSERT INTO audit_log
            (league_id,user_id,team_id,azione,entita,entita_id,dettagli_json,created_at)
            VALUES (?,?,?,'PASSWORD_RESET','USER',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            current_admin,
            team_id,
            str(owner_user_id),
            json.dumps({"team": nome, "username": username}, ensure_ascii=False)
        ))
        conn.commit()
        invalida_cache_admin_multilega()
        return username
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)


def collega_utente_esistente_lega(
    league_id, username, nome_squadra, is_admin=False, is_auctioneer=False
):
    """
    Collega alla lega un account globale già esistente creando per esso
    una nuova squadra. Non modifica password o dati dell'account.
    """
    league_id = int(league_id)
    username = str(username).strip()
    nome_squadra = str(nome_squadra).strip()

    if not username:
        raise ValueError("Inserisci lo username dell'account esistente.")
    if not nome_squadra:
        raise ValueError("Inserisci il nome della squadra.")

    current_admin = int(st.session_state.get("auth_user_id") or 0)
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT COUNT(*) FROM league_members
            WHERE league_id=? AND user_id=? AND is_admin=1 AND is_active=1
        """, (league_id, current_admin))
        if int(cur.fetchone()[0] or 0) == 0:
            raise PermissionError("Operazione riservata all'Admin della lega.")

        cur.execute("""
            SELECT id, username FROM users
            WHERE LOWER(username)=LOWER(?) AND is_active=1
            LIMIT 1
        """, (username,))
        r = cur.fetchone()
        if not r:
            raise ValueError("Account esistente non trovato.")
        user_id = int(r[0])
        username_db = str(r[1])

        cur.execute("""
            SELECT COUNT(*) FROM league_members
            WHERE league_id=? AND user_id=? AND is_active=1
        """, (league_id, user_id))
        if int(cur.fetchone()[0] or 0) > 0:
            raise ValueError("Questo account è già associato alla lega.")

        cur.execute("""
            SELECT COUNT(*) FROM teams
            WHERE league_id=? AND LOWER(nome)=LOWER(?) AND is_active=1
        """, (league_id, nome_squadra))
        if int(cur.fetchone()[0] or 0) > 0:
            raise ValueError("Esiste già una squadra con questo nome nella lega.")

        cur.execute("""
            SELECT COALESCE(MAX(posizione),0)+1
            FROM teams WHERE league_id=?
        """, (league_id,))
        posizione = int(cur.fetchone()[0] or 1)

        cur.execute("""
            INSERT INTO teams
            (league_id,nome,owner_user_id,posizione,is_active,created_at,updated_at)
            VALUES (?,?,?,?,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
        """, (league_id, nome_squadra, user_id, posizione))
        team_id = int(cur.lastrowid)

        cur.execute("""
            INSERT INTO league_members
            (league_id,user_id,team_id,is_admin,is_auctioneer,is_team_member,is_active,joined_at)
            VALUES (?,?,?,?,?,1,1,CURRENT_TIMESTAMP)
        """, (
            league_id, user_id, team_id,
            1 if is_admin else 0,
            1 if is_auctioneer else 0
        ))

        cur.execute("""
            UPDATE league_rules
            SET partecipanti=(
                SELECT COUNT(*) FROM teams
                WHERE league_id=? AND is_active=1
            ),
            updated_at=CURRENT_TIMESTAMP
            WHERE league_id=?
        """, (league_id, league_id))

        cur.execute("""
            INSERT INTO audit_log
            (league_id,user_id,team_id,azione,entita,entita_id,dettagli_json,created_at)
            VALUES (?,?,?,'EXISTING_USER_LINKED','TEAM',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            current_admin,
            team_id,
            str(team_id),
            json.dumps({
                "username": username_db,
                "team": nome_squadra,
                "admin": bool(is_admin),
                "auctioneer": bool(is_auctioneer)
            }, ensure_ascii=False)
        ))

        conn.commit()
        invalida_cache_admin_multilega()
        return team_id
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)


STATI_LEGA_AMMESSI = [
    "DRAFT",
    "CONFIGURAZIONE",
    "PRONTA",
    "ASTA",
    "CHIUSA"
]



def aggiorna_specifiche_lega_multilega(
    league_id, nome, stagione, modalita, partecipanti,
    max_giocatori, min_portieri, budget_iniziale,
    incremento_minimo, soglia_budget, moltiplicatore,
    tipo_asta, fonte_listone, budget_illimitato=False,
    fair_play_finanziario=False, tipo_incremento_asta="FISSO",
    incrementi_scalari=None
):
    """Aggiorna atomicamente le specifiche base della lega amministrata."""
    league_id = int(league_id)
    nome = str(nome or "").strip()
    stagione = str(stagione or "").strip()
    modalita = str(modalita or "").strip().upper()
    partecipanti = int(partecipanti)
    max_giocatori = int(max_giocatori)
    min_portieri = int(min_portieri)
    budget_iniziale = float(budget_iniziale)
    incremento_minimo = float(incremento_minimo)
    soglia_budget = float(soglia_budget)
    moltiplicatore = int(moltiplicatore)
    tipo_asta = str(tipo_asta or "").strip()
    fonte_listone = str(fonte_listone or "").strip() or "Fantacalcio.it"
    budget_illimitato = bool(budget_illimitato)
    fair_play_finanziario = bool(fair_play_finanziario)
    tipo_incremento_asta, incremento_minimo, incrementi_scalari = _normalizza_incrementi_scalari_v187(
        tipo_incremento_asta, incremento_minimo, incrementi_scalari
    )

    if not nome:
        raise ValueError("Il nome della lega non può essere vuoto.")
    if not stagione:
        raise ValueError("La stagione non può essere vuota.")
    if modalita not in ("MANTRA", "CLASSIC"):
        raise ValueError("Modalità lega non valida.")
    if partecipanti < 2 or partecipanti > 30:
        raise ValueError("I partecipanti devono essere compresi tra 2 e 30.")
    if max_giocatori < 20 or max_giocatori > 50:
        raise ValueError("I componenti massimi della rosa devono essere compresi tra 20 e 50.")
    if min_portieri < 1 or min_portieri > 20 or min_portieri > max_giocatori:
        raise ValueError("I portieri minimi devono essere compresi tra 1 e 20 e non superare la rosa.")
    if (not budget_illimitato) and (budget_iniziale < 1 or budget_iniziale > 100000):
        raise ValueError("Il budget limitato deve essere compreso tra 1 e 100000.")
    if not fair_play_finanziario:
        soglia_budget = float(budget_iniziale)
        moltiplicatore = 1
    elif soglia_budget < 0:
        raise ValueError("La soglia budget del Fair Play Finanziario non può essere negativa.")
    if moltiplicatore < 1:
        raise ValueError("Il moltiplicatore deve essere almeno 1.")
    if tipo_asta not in TIPI_ASTA_FANTA_LIVE:
        raise ValueError("Tipologia asta non valida.")

    current_admin = int(st.session_state.get("auth_user_id") or 0)
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""SELECT COUNT(*) FROM league_members
                       WHERE league_id=? AND user_id=? AND is_admin=1 AND is_active=1""",
                    (league_id, current_admin))
        if int(cur.fetchone()[0] or 0) == 0:
            raise PermissionError("Operazione riservata all'Admin della lega.")

        cur.execute("""SELECT l.nome,l.stagione,l.modalita,
                              r.partecipanti,r.max_giocatori,r.min_portieri,
                              r.budget_iniziale,r.incremento_minimo,r.soglia_budget,
                              r.moltiplicatore_oltre_soglia,r.tipo_asta,r.fonte_listone,
                               COALESCE(r.budget_illimitato,0),COALESCE(r.fair_play_finanziario,0)
                       FROM leagues l JOIN league_rules r ON r.league_id=l.id
                       WHERE l.id=? LIMIT 1""", (league_id,))
        prima = cur.fetchone()
        if not prima:
            raise ValueError("Lega non trovata.")

        # Il numero partecipanti corrisponde alle squadre attive. In aumento
        # vengono creati slot placeholder; in diminuzione si eliminano soltanto
        # slot liberi, mai squadre già associate a utenti o con giocatori.
        cur.execute("""SELECT id,nome,owner_user_id,posizione FROM teams
                       WHERE league_id=? AND is_active=1 ORDER BY posizione,id""", (league_id,))
        teams = cur.fetchall() or []
        attuali = len(teams)

        if partecipanti > attuali:
            cur.execute("SELECT COALESCE(MAX(posizione),0) FROM teams WHERE league_id=?", (league_id,))
            pos = int(cur.fetchone()[0] or 0)
            for _ in range(partecipanti - attuali):
                pos += 1
                cur.execute("""INSERT INTO teams
                               (league_id,nome,owner_user_id,posizione,is_active,created_at,updated_at)
                               VALUES (?,?,NULL,?,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)""",
                            (league_id, f"Squadra {pos}", pos))

        elif partecipanti < attuali:
            da_togliere = attuali - partecipanti
            eliminabili = []
            for team_id, team_nome, owner_id, posizione in reversed(teams):
                if owner_id is not None:
                    continue
                cur.execute("""SELECT COUNT(*) FROM league_members
                               WHERE league_id=? AND team_id=? AND is_active=1""", (league_id, int(team_id)))
                if int(cur.fetchone()[0] or 0) > 0:
                    continue
                # Se esiste league_players, uno slot con giocatori non è eliminabile.
                try:
                    cur.execute("SELECT COUNT(*) FROM league_players WHERE league_id=? AND team_id=?", (league_id, int(team_id)))
                    if int(cur.fetchone()[0] or 0) > 0:
                        continue
                except Exception:
                    pass
                eliminabili.append(int(team_id))
                if len(eliminabili) >= da_togliere:
                    break
            if len(eliminabili) < da_togliere:
                raise ValueError(
                    "Non posso ridurre i partecipanti a %d: esistono squadre già assegnate o con giocatori. "
                    "Rimuovi prima le squadre interessate dalla sezione Squadre." % partecipanti
                )
            for team_id in eliminabili:
                cur.execute("DELETE FROM league_members WHERE league_id=? AND team_id=?", (league_id, team_id))
                cur.execute("DELETE FROM teams WHERE league_id=? AND id=?", (league_id, team_id))

        cur.execute("""UPDATE leagues
                       SET nome=?, stagione=?, modalita=?, updated_at=CURRENT_TIMESTAMP
                       WHERE id=?""", (nome, stagione, modalita, league_id))
        cur.execute("""UPDATE league_rules SET
                       partecipanti=?, max_giocatori=?, min_portieri=?,
                       budget_iniziale=?, incremento_minimo=?, tipo_incremento_asta=?, incrementi_scalari_json=?, soglia_budget=?,
                       moltiplicatore_oltre_soglia=?, tipo_asta=?, fonte_listone=?,
                       budget_illimitato=?, fair_play_finanziario=?,
                       updated_at=CURRENT_TIMESTAMP
                       WHERE league_id=?""",
                    (partecipanti, max_giocatori, min_portieri, budget_iniziale,
                     incremento_minimo, tipo_incremento_asta,
                     json.dumps(incrementi_scalari, ensure_ascii=False),
                     soglia_budget, moltiplicatore, tipo_asta,
                     fonte_listone, 1 if budget_illimitato else 0,
                     1 if fair_play_finanziario else 0, league_id))

        dettagli = {
            "prima": list(prima),
            "dopo": {
                "nome": nome, "stagione": stagione, "modalita": modalita,
                "partecipanti": partecipanti, "max_giocatori": max_giocatori,
                "min_portieri": min_portieri, "budget_iniziale": budget_iniziale,
                "incremento_minimo": incremento_minimo,
                "tipo_incremento_asta": tipo_incremento_asta,
                "incrementi_scalari": incrementi_scalari,
                "soglia_budget": soglia_budget,
                "moltiplicatore": moltiplicatore, "tipo_asta": tipo_asta,
                "fonte_listone": fonte_listone,
                "budget_illimitato": budget_illimitato,
                "fair_play_finanziario": fair_play_finanziario
            }
        }
        cur.execute("""INSERT INTO audit_log
                       (league_id,user_id,team_id,azione,entita,entita_id,dettagli_json,created_at)
                       VALUES (?,?,NULL,'LEAGUE_SETTINGS_UPDATED','LEAGUE',?,?,CURRENT_TIMESTAMP)""",
                    (league_id, current_admin, str(league_id),
                     json.dumps(dettagli, ensure_ascii=False)))
        conn.commit()
        invalida_cache_admin_multilega()
        # Dati condivisi con le altre viste della lega.
        invalida_cache_dati()
    except Exception:
        try: conn.rollback()
        except Exception: pass
        raise
    finally:
        _portal_close(conn)

def aggiorna_stato_lega_multilega(league_id, nuovo_stato):
    league_id = int(league_id)
    nuovo_stato = str(nuovo_stato).strip().upper()
    if nuovo_stato not in STATI_LEGA_AMMESSI:
        raise ValueError("Stato lega non valido.")

    current_admin = int(st.session_state.get("auth_user_id") or 0)
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT COUNT(*) FROM league_members
            WHERE league_id=? AND user_id=? AND is_admin=1 AND is_active=1
        """, (league_id, current_admin))
        if int(cur.fetchone()[0] or 0) == 0:
            raise PermissionError("Operazione riservata all'Admin della lega.")

        cur.execute("SELECT stato FROM leagues WHERE id=? LIMIT 1", (league_id,))
        r = cur.fetchone()
        if not r:
            raise ValueError("Lega non trovata.")
        stato_prima = str(r[0] or "")

        cur.execute("""
            UPDATE leagues SET stato=?, updated_at=CURRENT_TIMESTAMP
            WHERE id=?
        """, (nuovo_stato, league_id))

        cur.execute("""
            INSERT INTO audit_log
            (league_id,user_id,team_id,azione,entita,entita_id,dettagli_json,created_at)
            VALUES (?,?,NULL,'LEAGUE_STATUS_UPDATED','LEAGUE',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            current_admin,
            str(league_id),
            json.dumps({"prima": stato_prima, "dopo": nuovo_stato}, ensure_ascii=False)
        ))
        conn.commit()
        invalida_cache_admin_multilega()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)


def rinomina_squadra_multilega(
    league_id,
    team_id,
    nuovo_nome
):
    nuovo_nome = nuovo_nome.strip()

    if not nuovo_nome:
        raise ValueError(
            "Il nome squadra non può essere vuoto."
        )

    conn = get_connection()
    cur = conn.cursor()

    try:

        # Autorizzazione server-side: utente corrente deve essere Admin.
        cur.execute("""
            SELECT COUNT(*)
            FROM league_members lm
            JOIN users u
              ON u.id = lm.user_id
            WHERE lm.league_id = ?
              AND u.username = ?
              AND lm.is_admin = 1
              AND lm.is_active = 1
        """, (
            int(league_id),
            PROFILO_ATTIVO
        ))

        autorizzato = int(
            cur.fetchone()[0]
            or 0
        ) > 0

        if not autorizzato:
            raise PermissionError(
                "Operazione riservata all'Admin della lega."
            )

        cur.execute("""
            UPDATE teams
            SET nome = ?,
                updated_at = CURRENT_TIMESTAMP
            WHERE id = ?
              AND league_id = ?
        """, (
            nuovo_nome,
            int(team_id),
            int(league_id)
        ))

        if cur.rowcount == 0:
            raise ValueError(
                "Squadra non trovata."
            )

        conn.commit()
        invalida_cache_admin_multilega()

    finally:

        chiudi_connessione(
            conn
        )




def aggiungi_squadra_multilega(league_id, username, password, is_admin=False, is_auctioneer=False):
    league_id=int(league_id)
    username=str(username).strip()
    password=str(password)
    if not username:
        raise ValueError("Inserisci il nome squadra / username.")
    if len(password)<8:
        raise ValueError("La password iniziale deve contenere almeno 8 caratteri.")

    user_admin=int(st.session_state.get("auth_user_id"))
    conn=_portal_raw_connection(); cur=conn.cursor()
    try:
        cur.execute("""SELECT COUNT(*) FROM league_members
                       WHERE league_id=? AND user_id=? AND is_admin=1 AND is_active=1""",
                    (league_id,user_admin))
        if int(cur.fetchone()[0] or 0)==0:
            raise PermissionError("Operazione riservata all'Admin della lega.")

        cur.execute("SELECT id FROM users WHERE LOWER(username)=LOWER(?) LIMIT 1",(username,))
        if cur.fetchone():
            raise ValueError("Questo username è già utilizzato. Usa un nome squadra diverso.")

        cur.execute("SELECT COALESCE(MAX(posizione),0)+1 FROM teams WHERE league_id=?",(league_id,))
        posizione=int(cur.fetchone()[0] or 1)

        cur.execute("""INSERT INTO users
                       (username,password_hash,is_active,created_at,updated_at)
                       VALUES (?,?,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)""",
                    (username,password_hash_sicuro(password)))
        new_user_id=int(cur.lastrowid)

        cur.execute("""INSERT INTO teams
                       (league_id,nome,owner_user_id,posizione,is_active,created_at,updated_at)
                       VALUES (?,?,?,?,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)""",
                    (league_id,username,new_user_id,posizione))
        team_id=int(cur.lastrowid)

        cur.execute("""INSERT INTO league_members
                       (league_id,user_id,team_id,is_admin,is_auctioneer,is_team_member,is_active,joined_at)
                       VALUES (?,?,?,?,?,1,1,CURRENT_TIMESTAMP)""",
                    (league_id,new_user_id,team_id,1 if is_admin else 0,1 if is_auctioneer else 0))

        # Mantiene il numero partecipanti coerente con le squadre attive.
        cur.execute("""UPDATE league_rules
                       SET partecipanti=(SELECT COUNT(*) FROM teams
                                         WHERE league_id=? AND is_active=1),
                           updated_at=CURRENT_TIMESTAMP
                       WHERE league_id=?""",(league_id,league_id))

        cur.execute("""INSERT INTO audit_log
                       (league_id,user_id,team_id,azione,entita,entita_id,dettagli_json,created_at)
                       VALUES (?,?,?,'TEAM_ADDED','TEAM',?,?,CURRENT_TIMESTAMP)""",
                    (league_id,user_admin,team_id,str(team_id),
                     json.dumps({"username":username,"admin":bool(is_admin),
                                 "auctioneer":bool(is_auctioneer)},ensure_ascii=False)))
        conn.commit()
        invalida_cache_admin_multilega()
        return team_id
    except Exception:
        try: conn.rollback()
        except Exception: pass
        raise
    finally:
        _portal_close(conn)


def rimuovi_squadra_multilega(league_id, team_id):
    league_id=int(league_id); team_id=int(team_id)
    user_admin=int(st.session_state.get("auth_user_id"))
    conn=_portal_raw_connection(); cur=conn.cursor()
    try:
        cur.execute("""SELECT COUNT(*) FROM league_members
                       WHERE league_id=? AND user_id=? AND is_admin=1 AND is_active=1""",
                    (league_id,user_admin))
        if int(cur.fetchone()[0] or 0)==0:
            raise PermissionError("Operazione riservata all'Admin della lega.")

        cur.execute("""SELECT nome,owner_user_id FROM teams
                       WHERE id=? AND league_id=? AND is_active=1 LIMIT 1""",(team_id,league_id))
        r=cur.fetchone()
        if not r: raise ValueError("Squadra non trovata.")
        nome=str(r[0] or "")
        owner_user_id=int(r[1]) if r[1] is not None else None

        # Impedisce di lasciare la lega senza alcun Admin.
        if owner_user_id is not None:
            cur.execute("""SELECT is_admin FROM league_members
                           WHERE league_id=? AND team_id=? AND user_id=? AND is_active=1 LIMIT 1""",
                        (league_id,team_id,owner_user_id))
            m=cur.fetchone()
            if m and int(m[0] or 0)==1:
                cur.execute("""SELECT COUNT(DISTINCT user_id) FROM league_members
                               WHERE league_id=? AND is_admin=1 AND is_active=1
                                 AND user_id<>?""",(league_id,owner_user_id))
                if int(cur.fetchone()[0] or 0)==0:
                    raise ValueError("Non puoi rimuovere l'unico Admin della lega. Assegna prima il ruolo Admin a un'altra squadra.")

        # Pulisce dati team-scoped presenti nello schema.
        cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
        presenti={str(x[0]) for x in cur.fetchall()}
        for tabella in ["bids","assignments","player_evaluations","iqr_profiles","rosters","team_budgets"]:
            if tabella not in presenti: continue
            cur.execute(f"PRAGMA table_info({tabella})")
            cols={str(x[1]) for x in cur.fetchall()}
            if "league_id" in cols and "team_id" in cols:
                cur.execute(f"DELETE FROM {tabella} WHERE league_id=? AND team_id=?",(league_id,team_id))

        cur.execute("DELETE FROM league_members WHERE league_id=? AND team_id=?",(league_id,team_id))
        cur.execute("DELETE FROM teams WHERE league_id=? AND id=?",(league_id,team_id))

        cur.execute("""UPDATE league_rules
                       SET partecipanti=(SELECT COUNT(*) FROM teams
                                         WHERE league_id=? AND is_active=1),
                           updated_at=CURRENT_TIMESTAMP
                       WHERE league_id=?""",(league_id,league_id))

        cur.execute("""INSERT INTO audit_log
                       (league_id,user_id,team_id,azione,entita,entita_id,dettagli_json,created_at)
                       VALUES (?,?,NULL,'TEAM_REMOVED','TEAM',?,?,CURRENT_TIMESTAMP)""",
                    (league_id,user_admin,str(team_id),
                     json.dumps({"nome":nome},ensure_ascii=False)))
        conn.commit()
        invalida_cache_admin_multilega()
        return nome
    except Exception:
        try: conn.rollback()
        except Exception: pass
        raise
    finally:
        _portal_close(conn)



def elimina_lega_multilega(
    league_id
):
    """
    Elimina definitivamente una lega e tutti i dati ad essa collegati.

    Sicurezza:
    - l'utente autenticato deve essere ADMIN attivo della lega;
    - gli account USERS globali NON vengono eliminati;
    - la cancellazione è transazionale;
    - supporta anche tabelle multilega future se già presenti.
    """

    league_id = int(
        league_id
    )

    user_id = int(
        st.session_state.get(
            "auth_user_id"
        )
    )

    conn = _portal_raw_connection()
    cur = conn.cursor()

    try:

        cur.execute("""
            SELECT
                l.nome
            FROM leagues l
            JOIN league_members lm
              ON lm.league_id = l.id
            WHERE l.id = ?
              AND lm.user_id = ?
              AND lm.is_admin = 1
              AND lm.is_active = 1
            LIMIT 1
        """, (
            league_id,
            user_id
        ))

        riga = cur.fetchone()

        if not riga:
            raise PermissionError(
                "Non sei autorizzato a eliminare questa lega."
            )

        nome_lega = str(
            riga[0]
            or ""
        )

        # Rileva le tabelle realmente presenti.
        cur.execute("""
            SELECT name
            FROM sqlite_master
            WHERE type = 'table'
        """)

        tabelle_presenti = {
            str(
                r[0]
            )
            for r in cur.fetchall()
        }

        # Prima le tabelle figlie, poi la lega.
        # L'elenco comprende anche le strutture previste per
        # le prossime fasi dell'asta live.
        tabelle_legate = [
            "bids",
            "assignments",
            "auction_calls",
            "auction_lots",
            "auction_sessions",
            "player_evaluations",
            "iqr_profiles",
            "rosters",
            "team_budgets",
            "league_player_catalog",
            "league_players",
            "league_members",
            "teams",
            "league_rules",
            "audit_log",
        ]

        for tabella in tabelle_legate:

            if tabella not in tabelle_presenti:
                continue

            cur.execute(
                f"PRAGMA table_info({tabella})"
            )

            colonne = {
                str(
                    r[1]
                )
                for r in cur.fetchall()
            }

            if "league_id" in colonne:

                cur.execute(
                    f"DELETE FROM {tabella} WHERE league_id = ?",
                    (
                        league_id,
                    )
                )

        cur.execute("""
            DELETE FROM leagues
            WHERE id = ?
        """, (
            league_id,
        ))

        conn.commit()
        invalida_cache_admin_multilega()

        return nome_lega

    except Exception:

        try:
            conn.rollback()
        except Exception:
            pass

        raise

    finally:

        _portal_close(
            conn
        )




def prepara_export_rose_multilega(league_id):
    """
    V120 - prepara gli export delle rose della lega.

    PERFORMANCE:
    viene invocata solo su click esplicito dell'Admin; non aggiunge query
    all'apertura della pagina Gestione Lega.

    Restituisce:
    - dataframe completo normalizzato;
    - CSV UTF-8 BOM, separatore ';';
    - XLSX con foglio TUTTE_LE_ROSE + un foglio per squadra;
    - riepilogo squadre/budget.
    """
    import io

    league_id = int(league_id)

    conn = _portal_raw_connection()
    try:
        df = pd.read_sql_query("""
            SELECT
                t.id AS TeamId,
                t.nome AS Squadra,
                c.player_id AS Id,
                c.nome AS Nome,
                c.squadra AS Squadra_Appartenenza,
                c.ruolo_classico AS Ruolo,
                c.ruolo_mantra AS Ruolo_Mantra,
                ro.prezzo_acquisto AS Prezzo,
                c.quotazione_attuale AS Quotazione,
                c.quotazione_attuale_mantra AS Quotazione_Mantra,
                c.fvm AS FVM,
                c.fvm_mantra AS FVM_Mantra
            FROM rosters ro
            JOIN teams t
              ON t.id=ro.team_id
             AND t.league_id=ro.league_id
            JOIN league_player_catalog c
              ON c.player_id=ro.player_id
             AND c.league_id=ro.league_id
            WHERE ro.league_id=?
              AND t.is_active=1
            ORDER BY t.posizione,t.id,c.nome COLLATE NOCASE
        """, conn, params=(league_id,))

        riepilogo = pd.read_sql_query("""
            SELECT
                t.id AS TeamId,
                t.nome AS Squadra,
                COALESCE(tb.budget_impostato,lr.budget_iniziale,500) AS Budget,
                COALESCE(tb.valore_acquisti,0) AS Valore_Acquisti,
                COALESCE(tb.spesa_effettiva,0) AS Spesa_Effettiva,
                (
                    COALESCE(tb.budget_impostato,lr.budget_iniziale,500)
                    - COALESCE(tb.spesa_effettiva,0)
                ) AS Residuo,
                COUNT(ro.id) AS Giocatori
            FROM teams t
            LEFT JOIN league_rules lr
              ON lr.league_id=t.league_id
            LEFT JOIN team_budgets tb
              ON tb.league_id=t.league_id
             AND tb.team_id=t.id
            LEFT JOIN rosters ro
              ON ro.league_id=t.league_id
             AND ro.team_id=t.id
            WHERE t.league_id=?
              AND t.is_active=1
            GROUP BY
                t.id,t.nome,t.posizione,
                tb.budget_impostato,lr.budget_iniziale,
                tb.valore_acquisti,tb.spesa_effettiva
            ORDER BY t.posizione,t.id
        """, conn, params=(league_id,))
    finally:
        _portal_close(conn)

    # CSV di scambio: mantiene anche l'ID ufficiale del giocatore,
    # utile per un successivo mapping/import automatico.
    colonne_csv = [
        "Squadra",
        "Id",
        "Nome",
        "Squadra_Appartenenza",
        "Ruolo",
        "Ruolo_Mantra",
        "Prezzo",
        "Quotazione",
        "Quotazione_Mantra",
    ]

    for col in colonne_csv:
        if col not in df.columns:
            df[col] = pd.Series(dtype="object")

    csv_bytes = (
        df[colonne_csv]
        .to_csv(
            index=False,
            sep=";",
            lineterminator="\n"
        )
        .encode("utf-8-sig")
    )

    # XLSX completo, generato solo su richiesta.
    xlsx_buffer = io.BytesIO()
    with pd.ExcelWriter(
        xlsx_buffer,
        engine="openpyxl"
    ) as writer:
        df.to_excel(
            writer,
            sheet_name="TUTTE_LE_ROSE",
            index=False
        )
        riepilogo.to_excel(
            writer,
            sheet_name="RIEPILOGO",
            index=False
        )

        if not df.empty:
            for nome_team, gruppo in df.groupby("Squadra", sort=False):
                nome_foglio = str(nome_team or "SQUADRA")
                for ch in r'[]:*?/\\':
                    nome_foglio = nome_foglio.replace(ch, "_")
                nome_foglio = nome_foglio[:31] or "SQUADRA"

                gruppo.drop(
                    columns=["TeamId"],
                    errors="ignore"
                ).to_excel(
                    writer,
                    sheet_name=nome_foglio,
                    index=False
                )

    xlsx_bytes = xlsx_buffer.getvalue()

    return {
        "df": df,
        "riepilogo": riepilogo,
        "csv": csv_bytes,
        "xlsx": xlsx_bytes,
        "numero_giocatori": int(len(df)),
        "numero_squadre": int(riepilogo.shape[0]),
    }


def invalida_export_rose_multilega(league_id=None):
    """Elimina gli export già preparati dopo una modifica d'asta/rosa."""
    prefisso = "_ml36_export_rose_"
    for key in list(st.session_state.keys()):
        if not str(key).startswith(prefisso):
            continue
        if league_id is None or str(key) == f"{prefisso}{int(league_id)}":
            st.session_state.pop(key, None)





