def importa_listone_lega_da_admin(league_id, df):
    """
    V110 - Il listone è di proprietà della LEGA, non del singolo profilo.

    Solo ADMIN può caricarlo/aggiornarlo. Tutti i team della stessa lega
    leggono lo stesso catalogo centrale.
    """
    league_id = int(league_id)
    user_id = int(st.session_state.get("auth_user_id") or 0)

    conn = _portal_raw_connection()
    cur = conn.cursor()

    def _clean(v):
        if v is None:
            return None
        try:
            if pd.isna(v):
                return None
        except Exception:
            pass
        return v

    def _num(v):
        v = _clean(v)
        if v is None or v == "":
            return None
        try:
            return float(v)
        except Exception:
            return None

    try:
        cur.execute("""
            SELECT COUNT(*)
            FROM league_members
            WHERE league_id=? AND user_id=? AND is_active=1 AND is_admin=1
        """, (league_id, user_id))
        if int(cur.fetchone()[0] or 0) == 0:
            raise PermissionError("Solo l'Admin della lega può caricare il listone.")

        obbligatorie = {"Id","R","RM","Nome","Squadra"}
        mancanti = obbligatorie - set(str(c).strip() for c in df.columns)
        if mancanti:
            raise ValueError(
                "Formato listone non valido. Colonne mancanti: "
                + ", ".join(sorted(mancanti))
            )

        cur.execute("""
            CREATE TABLE IF NOT EXISTS league_player_catalog (
                league_id INTEGER NOT NULL,
                player_id INTEGER NOT NULL,
                ruolo_classico TEXT,
                ruolo_mantra TEXT,
                nome TEXT NOT NULL,
                squadra TEXT,
                quotazione_attuale REAL,
                quotazione_iniziale REAL,
                differenza REAL,
                quotazione_attuale_mantra REAL,
                quotazione_iniziale_mantra REAL,
                differenza_mantra REAL,
                fvm REAL,
                fvm_mantra REAL,
                uploaded_by_user_id INTEGER,
                uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (league_id, player_id)
            )
        """)

        cur.execute("""
            SELECT player_id
            FROM league_player_catalog
            WHERE league_id=?
        """, (league_id,))
        esistenti = {int(r[0]) for r in (cur.fetchall() or [])}

        righe = []
        ids_importati = set()

        for _, row in df.iterrows():
            try:
                player_id = int(row.get("Id"))
            except Exception:
                continue

            nome = str(row.get("Nome","") or "").strip()
            if not nome:
                continue

            ids_importati.add(player_id)
            righe.append((
                league_id,
                player_id,
                str(row.get("R","") or "").strip(),
                str(row.get("RM","") or "").strip(),
                nome,
                str(row.get("Squadra","") or "").strip(),
                _num(row.get("Qt.A")),
                _num(row.get("Qt.I")),
                _num(row.get("Diff.")),
                _num(row.get("Qt.A M")),
                _num(row.get("Qt.I M")),
                _num(row.get("Diff.M")),
                _num(row.get("FVM")),
                _num(row.get("FVM M")),
                user_id
            ))

        if not righe:
            raise ValueError("Il file non contiene giocatori validi.")

        # Upsert a blocchi.
        DIM = 50
        for i in range(0, len(righe), DIM):
            blocco = righe[i:i+DIM]
            ph_riga = "(" + ",".join(["?"]*15) + ")"
            ph = ",".join([ph_riga]*len(blocco))
            params = []
            for r in blocco:
                params.extend(r)

            cur.execute(f"""
                INSERT INTO league_player_catalog (
                    league_id,player_id,ruolo_classico,ruolo_mantra,nome,squadra,
                    quotazione_attuale,quotazione_iniziale,differenza,
                    quotazione_attuale_mantra,quotazione_iniziale_mantra,
                    differenza_mantra,fvm,fvm_mantra,uploaded_by_user_id
                )
                VALUES {ph}
                ON CONFLICT(league_id,player_id)
                DO UPDATE SET
                    ruolo_classico=excluded.ruolo_classico,
                    ruolo_mantra=excluded.ruolo_mantra,
                    nome=excluded.nome,
                    squadra=excluded.squadra,
                    quotazione_attuale=excluded.quotazione_attuale,
                    quotazione_iniziale=excluded.quotazione_iniziale,
                    differenza=excluded.differenza,
                    quotazione_attuale_mantra=excluded.quotazione_attuale_mantra,
                    quotazione_iniziale_mantra=excluded.quotazione_iniziale_mantra,
                    differenza_mantra=excluded.differenza_mantra,
                    fvm=excluded.fvm,
                    fvm_mantra=excluded.fvm_mantra,
                    uploaded_by_user_id=excluded.uploaded_by_user_id,
                    updated_at=CURRENT_TIMESTAMP
            """, tuple(params))

        # Inserisce i nuovi giocatori anche nello stato operativo della lega.
        cur.execute("""
            INSERT INTO league_players (
                league_id,player_id,stato,assigned_team_id,
                prezzo_assegnazione,updated_at
            )
            SELECT
                c.league_id,c.player_id,'DISPONIBILE',NULL,NULL,CURRENT_TIMESTAMP
            FROM league_player_catalog c
            WHERE c.league_id=?
              AND NOT EXISTS (
                  SELECT 1
                  FROM league_players lp
                  WHERE lp.league_id=c.league_id
                    AND lp.player_id=c.player_id
              )
        """, (league_id,))

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,azione,entita,entita_id,
                dettagli_json,created_at
            )
            VALUES (?,?,'LEAGUE_LIST_UPLOAD','LEAGUE',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            user_id,
            str(league_id),
            json.dumps({
                "righe": len(righe),
                "nuovi": len(ids_importati - esistenti),
                "aggiornati": len(ids_importati & esistenti),
            }, ensure_ascii=False)
        ))

        conn.commit()

        # Sincronizza subito tutti i workspace team già creati.
        cur.execute("""
            SELECT id
            FROM teams
            WHERE league_id=? AND is_active=1
            ORDER BY id
        """, (league_id,))
        team_ids = [int(r[0]) for r in (cur.fetchall() or [])]

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)

    for team_id in team_ids:
        try:
            sincronizza_listone_lega_nel_workspace(league_id, team_id)
        except Exception:
            pass

    invalida_cache_dati()

    return {
        "totale": len(righe),
        "nuovi": len(ids_importati - esistenti),
        "aggiornati": len(ids_importati & esistenti),
    }


def carica_listone_centrale_lega(league_id, forza=False):
    """
    V119: cache di sessione del listone centrale.
    Evita un round-trip Turso ogni volta che si entra/esce da LISTONE.
    Le operazioni di scrittura invalidano la cache.
    """
    league_id = int(league_id)
    chiave = f"_ml35_listone_centrale_{league_id}"

    if not forza:
        cached = st.session_state.get(chiave)
        if isinstance(cached, pd.DataFrame):
            return cached

    conn = _portal_raw_connection()
    try:
        df = pd.read_sql_query("""
            SELECT
                c.player_id AS Id,
                c.ruolo_classico AS R,
                c.ruolo_mantra AS RM,
                c.nome AS Nome,
                c.squadra AS Squadra,
                c.quotazione_attuale AS "Qt.A",
                c.quotazione_iniziale AS "Qt.I",
                c.differenza AS "Diff.",
                c.quotazione_attuale_mantra AS "Qt.A M",
                c.quotazione_iniziale_mantra AS "Qt.I M",
                c.differenza_mantra AS "Diff.M",
                c.fvm AS FVM,
                c.fvm_mantra AS "FVM M",
                COALESCE(lp.stato,'DISPONIBILE') AS Stato,
                lp.prezzo_assegnazione AS Prezzo
            FROM league_player_catalog c
            LEFT JOIN league_players lp
              ON lp.league_id=c.league_id
             AND lp.player_id=c.player_id
            WHERE c.league_id=?
            ORDER BY c.nome
        """, conn, params=(league_id,))
    finally:
        _portal_close(conn)

    st.session_state[chiave] = df
    return df




def sincronizza_listone_lega_nel_workspace(league_id, team_id):
    """
    Copia/aggiorna il catalogo centrale della lega nel workspace locale del team.
    Non sovrascrive gli stati MIO/prezzi della rosa; quelli vengono riallineati
    separatamente da rosters.
    """
    league_id = int(league_id)
    team_id = int(team_id)
    tab = "giocatori_ml_l" + str(league_id) + "_t" + str(team_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT name FROM sqlite_master
            WHERE type='table' AND name=? LIMIT 1
        """, (tab,))
        if not cur.fetchone():
            return False

        cur.execute("""
            SELECT
                player_id,ruolo_classico,ruolo_mantra,nome,squadra,
                quotazione_attuale,quotazione_iniziale,differenza,
                quotazione_attuale_mantra,quotazione_iniziale_mantra,
                differenza_mantra,fvm,fvm_mantra
            FROM league_player_catalog
            WHERE league_id=?
        """, (league_id,))
        righe = cur.fetchall() or []

        for r in righe:
            cur.execute(
                f"""
                INSERT INTO {tab} (
                    id,ruolo_classico,ruolo_mantra,nome,squadra,
                    quotazione_attuale,quotazione_iniziale,differenza,
                    quotazione_attuale_mantra,quotazione_iniziale_mantra,
                    differenza_mantra,fvm,fvm_mantra,stato,
                    prezzo_acquisto,ultimo_aggiornamento
                )
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,'DISPONIBILE',NULL,CURRENT_TIMESTAMP)
                ON CONFLICT(id) DO UPDATE SET
                    ruolo_classico=excluded.ruolo_classico,
                    ruolo_mantra=excluded.ruolo_mantra,
                    nome=excluded.nome,
                    squadra=excluded.squadra,
                    quotazione_attuale=excluded.quotazione_attuale,
                    quotazione_iniziale=excluded.quotazione_iniziale,
                    differenza=excluded.differenza,
                    quotazione_attuale_mantra=excluded.quotazione_attuale_mantra,
                    quotazione_iniziale_mantra=excluded.quotazione_iniziale_mantra,
                    differenza_mantra=excluded.differenza_mantra,
                    fvm=excluded.fvm,
                    fvm_mantra=excluded.fvm_mantra,
                    ultimo_aggiornamento=CURRENT_TIMESTAMP
                """,
                tuple(r)
            )

        conn.commit()
        return True
    finally:
        _portal_close(conn)


def parse_file_listone_fantacalcio(contenuto):
    excel = pd.ExcelFile(
        io.BytesIO(contenuto),
        engine="openpyxl"
    )

    foglio_tutti = None
    for nome_foglio in excel.sheet_names:
        if str(nome_foglio).strip().upper() == "TUTTI":
            foglio_tutti = nome_foglio
            break

    if foglio_tutti is None:
        raise ValueError("Non trovo il foglio Tutti.")

    df_excel = pd.read_excel(
        io.BytesIO(contenuto),
        sheet_name=foglio_tutti,
        engine="openpyxl",
        header=1
    )

    df_excel = (
        df_excel
        .dropna(axis=1, how="all")
        .dropna(axis=0, how="all")
    )
    df_excel.columns = [str(c).strip() for c in df_excel.columns]

    obbligatorie = {"Id","R","RM","Nome","Squadra"}
    mancanti = obbligatorie - set(df_excel.columns)
    if mancanti:
        raise ValueError(
            "Formato non valido. Colonne mancanti: "
            + ", ".join(sorted(mancanti))
        )

    return df_excel



def importa_listone_nel_database(df):

    """
    Importazione ottimizzata per database Cloud.

    Obiettivi:
    - evitare centinaia di round-trip verso Turso;
    - aggiornare solo i giocatori realmente cambiati;
    - eseguire UPSERT multi-riga a blocchi;
    - mantenere stato e prezzo dei giocatori già presenti.
    """

    # L'import del listone può coinvolgere centinaia di righe.
    # Per mantenere l'operazione veloce sul Cloud NON creiamo
    # al prossimo aggiornamento uno snapshot completo qui.
    #
    # Se serve un punto di sicurezza, usa il pulsante Snapshot
    # prima di caricare il nuovo listone.

    conn = get_connection()
    cur = conn.cursor()

    def pulisci_valore(
        valore
    ):

        if valore is None:
            return None

        try:
            if pd.isna(
                valore
            ):
                return None
        except Exception:
            pass

        return valore

    def normalizza_numero(
        valore
    ):

        valore = pulisci_valore(
            valore
        )

        if valore is None:
            return None

        try:
            return float(
                valore
            )
        except Exception:
            return valore

    try:

        # ----------------------------------------------------
        # 1. UNA SOLA LETTURA DELLO STATO ATTUALE
        # ----------------------------------------------------

        cur.execute("""
            SELECT
                id,
                ruolo_classico,
                ruolo_mantra,
                nome,
                squadra,
                quotazione_attuale,
                quotazione_iniziale,
                differenza,
                quotazione_attuale_mantra,
                quotazione_iniziale_mantra,
                differenza_mantra,
                fvm,
                fvm_mantra

            FROM giocatori
        """)

        esistenti = {}

        for riga in cur.fetchall():

            giocatore_id = int(
                riga[0]
            )

            esistenti[
                giocatore_id
            ] = (
                str(
                    riga[1]
                    or ""
                ).strip(),

                str(
                    riga[2]
                    or ""
                ).strip(),

                str(
                    riga[3]
                    or ""
                ).strip(),

                str(
                    riga[4]
                    or ""
                ).strip(),

                normalizza_numero(
                    riga[5]
                ),

                normalizza_numero(
                    riga[6]
                ),

                normalizza_numero(
                    riga[7]
                ),

                normalizza_numero(
                    riga[8]
                ),

                normalizza_numero(
                    riga[9]
                ),

                normalizza_numero(
                    riga[10]
                ),

                normalizza_numero(
                    riga[11]
                ),

                normalizza_numero(
                    riga[12]
                )
            )

        # ----------------------------------------------------
        # 2. PREPARAZIONE LOCALE: NESSUNA QUERY PER GIOCATORE
        # ----------------------------------------------------

        da_scrivere = []
        nuovi = 0
        aggiornati = 0

        for _, row in df.iterrows():

            try:

                giocatore_id = int(
                    row[
                        "Id"
                    ]
                )

            except Exception:

                continue

            nome = str(
                row.get(
                    "Nome",
                    ""
                )
                or ""
            ).strip()

            if not nome:
                continue

            dati_confronto = (
                str(
                    row.get(
                        "R",
                        ""
                    )
                    or ""
                ).strip(),

                str(
                    row.get(
                        "RM",
                        ""
                    )
                    or ""
                ).strip(),

                nome,

                str(
                    row.get(
                        "Squadra",
                        ""
                    )
                    or ""
                ).strip(),

                normalizza_numero(
                    row.get(
                        "Qt.A"
                    )
                ),

                normalizza_numero(
                    row.get(
                        "Qt.I"
                    )
                ),

                normalizza_numero(
                    row.get(
                        "Diff."
                    )
                ),

                normalizza_numero(
                    row.get(
                        "Qt.A M"
                    )
                ),

                normalizza_numero(
                    row.get(
                        "Qt.I M"
                    )
                ),

                normalizza_numero(
                    row.get(
                        "Diff.M"
                    )
                ),

                normalizza_numero(
                    row.get(
                        "FVM"
                    )
                ),

                normalizza_numero(
                    row.get(
                        "FVM M"
                    )
                )
            )

            precedente = (
                esistenti.get(
                    giocatore_id
                )
            )

            if precedente is None:

                nuovi += 1

            elif precedente == dati_confronto:

                # Giocatore identico: nessuna scrittura Cloud.
                continue

            else:

                aggiornati += 1

            da_scrivere.append(
                (
                    giocatore_id,
                    *dati_confronto
                )
            )

        # ----------------------------------------------------
        # 3. UPSERT MULTI-RIGA A BLOCCHI
        # ----------------------------------------------------
        #
        # 13 parametri per giocatore.
        # 50 giocatori = 650 parametri per query:
        # abbastanza piccolo per restare compatibile e riduce
        # enormemente i round-trip verso Turso.

        DIMENSIONE_BLOCCO = 50

        colonne = """
            id,
            ruolo_classico,
            ruolo_mantra,
            nome,
            squadra,
            quotazione_attuale,
            quotazione_iniziale,
            differenza,
            quotazione_attuale_mantra,
            quotazione_iniziale_mantra,
            differenza_mantra,
            fvm,
            fvm_mantra
        """

        update_sql = """
            ruolo_classico = excluded.ruolo_classico,
            ruolo_mantra = excluded.ruolo_mantra,
            nome = excluded.nome,
            squadra = excluded.squadra,
            quotazione_attuale = excluded.quotazione_attuale,
            quotazione_iniziale = excluded.quotazione_iniziale,
            differenza = excluded.differenza,
            quotazione_attuale_mantra = excluded.quotazione_attuale_mantra,
            quotazione_iniziale_mantra = excluded.quotazione_iniziale_mantra,
            differenza_mantra = excluded.differenza_mantra,
            fvm = excluded.fvm,
            fvm_mantra = excluded.fvm_mantra,
            ultimo_aggiornamento = CURRENT_TIMESTAMP
        """

        for inizio in range(
            0,
            len(
                da_scrivere
            ),
            DIMENSIONE_BLOCCO
        ):

            blocco = da_scrivere[
                inizio:
                inizio
                + DIMENSIONE_BLOCCO
            ]

            if not blocco:
                continue

            placeholders_riga = (
                "("
                + ", ".join(
                    [
                        "?"
                        for _ in range(
                            13
                        )
                    ]
                )
                + ")"
            )

            placeholders = ", ".join(
                [
                    placeholders_riga
                    for _ in blocco
                ]
            )

            parametri = []

            for valori in blocco:

                parametri.extend(
                    valori
                )

            query = f"""
                INSERT INTO giocatori (
                    {colonne}
                )

                VALUES
                    {placeholders}

                ON CONFLICT(id) DO UPDATE SET
                    {update_sql}
            """

            cur.execute(
                query,
                tuple(
                    parametri
                )
            )

        # Un solo commit finale.
        conn.commit()

    finally:

        chiudi_connessione(
            conn
        )

    # Ricaricheremo i dati una sola volta dopo l'import.
    invalida_cache_dati()

    # Memorizza data e ora dell'ultimo upload completato con successo.
    st.session_state[
        "ultimo_upload_listone"
    ] = datetime.now(
        ZoneInfo(
            "Europe/Rome"
        )
    ).strftime(
        "%d/%m/%Y alle %H:%M:%S"
    )

    return (
        nuovi,
        aggiornati
    )


# ============================================================
# LETTURA DATABASE
# ============================================================

def carica_tutti_giocatori():

    chiave = "_df_giocatori_sessione"

    if chiave in st.session_state:

        # Il DataFrame è già mantenuto coerente dalle operazioni.
        # Restituiamo il riferimento per evitare copie da 500+ righe
        # a ogni rerun; le funzioni che devono modificarlo usano .copy().
        return st.session_state[
            chiave
        ]

    conn = get_connection()

    df = pd.read_sql_query("""
        SELECT

            id AS Id,

            ruolo_classico AS R,
            ruolo_mantra AS RM,

            nome AS Nome,
            squadra AS Squadra,

            quotazione_attuale
                AS "Qt.A",

            quotazione_iniziale
                AS "Qt.I",

            differenza
                AS "Diff.",

            quotazione_attuale_mantra
                AS "Qt.A M",

            quotazione_iniziale_mantra
                AS "Qt.I M",

            differenza_mantra
                AS "Diff.M",

            fvm AS FVM,

            fvm_mantra
                AS "FVM M",

            stato AS Stato,

            prezzo_acquisto
                AS Prezzo

        FROM giocatori
    """, conn)

    chiudi_connessione(
        conn
    )

    st.session_state[
        chiave
    ] = df.copy()

    return df


# ============================================================
# OPERAZIONI
# ============================================================

def esegui_operazione(
    giocatore_id,
    tipo,
    nuovo_stato,
    nuovo_prezzo=None,
    costo_svincolo=0
):

    # Recupera lo stato precedente dalla copia già in memoria.
    df_corrente = carica_tutti_giocatori()

    giocatore_id_db = int(
        giocatore_id
    )

    riga = df_corrente[
        df_corrente["Id"]
        == giocatore_id_db
    ]

    if riga.empty:
        return

    precedente = riga.iloc[0]

    # Tutti i parametri vengono convertiti in tipi Python nativi.
    # È importante con Turso/libsql perché valori pandas/numpy
    # possono produrre ValueError in alcuni percorsi operativi.
    nome = str(
        precedente.get(
            "Nome",
            ""
        )
    )

    stato_prima = str(
        precedente.get(
            "Stato",
            ""
        )
    )

    prezzo_prima_raw = precedente.get(
        "Prezzo"
    )

    prezzo_prima = (
        None
        if pd.isna(
            prezzo_prima_raw
        )
        else float(
            prezzo_prima_raw
        )
    )

    tipo_db = str(
        tipo
    )

    nuovo_stato_db = str(
        nuovo_stato
    )

    nuovo_prezzo_db = (
        None
        if nuovo_prezzo is None
        or pd.isna(
            nuovo_prezzo
        )
        else float(
            nuovo_prezzo
        )
    )

    costo_svincolo_db = float(
        costo_svincolo
        or 0
    )

    conn = get_connection()
    cur = conn.cursor()

    try:

        # ------------------------------------------------------
        # 1. REGISTRA OPERAZIONE
        # ------------------------------------------------------

        cur.execute("""
            INSERT INTO operazioni (

                tipo,
                giocatore_id,
                nome_giocatore,

                stato_prima,
                prezzo_prima,

                stato_dopo,
                prezzo_dopo,

                costo_svincolo
            )

            VALUES (
                ?, ?, ?,
                ?, ?,
                ?, ?,
                ?
            )
        """, (
            tipo_db,
            giocatore_id_db,
            nome,
            stato_prima,
            prezzo_prima,
            nuovo_stato_db,
            nuovo_prezzo_db,
            costo_svincolo_db
        ))

        # lastrowid non è sempre affidabile allo stesso modo
        # tra sqlite3 e libsql: recuperiamo esplicitamente l'id.
        cur.execute(
            "SELECT last_insert_rowid()"
        )

        riga_id = cur.fetchone()

        operazione_id = (
            int(
                riga_id[0]
            )
            if riga_id
            and riga_id[0] is not None
            else 0
        )

        # ------------------------------------------------------
        # 2. EVENTUALE COSTO SVINCOLO
        # ------------------------------------------------------

        if costo_svincolo_db > 0:

            cur.execute("""
                INSERT INTO costi_svincoli (
                    operazione_id,
                    giocatore_id,
                    nome_giocatore,
                    importo
                )
                VALUES (?, ?, ?, ?)
            """, (
                operazione_id,
                giocatore_id_db,
                nome,
                costo_svincolo_db
            ))

        # ------------------------------------------------------
        # 3. AGGIORNA STATO GIOCATORE
        # ------------------------------------------------------

        cur.execute("""
            UPDATE giocatori

            SET
                stato = ?,
                prezzo_acquisto = ?

            WHERE id = ?
        """, (
            nuovo_stato_db,
            nuovo_prezzo_db,
            giocatore_id_db
        ))

        # ------------------------------------------------------
        # 4. CRONOLOGIA: CONSERVA SOLO LE ULTIME 10 OPERAZIONI
        # ------------------------------------------------------

        cur.execute("""
            DELETE FROM operazioni

            WHERE id NOT IN (
                SELECT id
                FROM operazioni
                ORDER BY id DESC
                LIMIT ?
            )
        """, (
            int(
                MAX_UNDO
            ),
        ))

        conn.commit()

    except Exception:

        try:
            conn.rollback()
        except Exception:
            pass

        raise

    finally:

        chiudi_connessione(
            conn
        )

    # ----------------------------------------------------------
    # AGGIORNAMENTO CACHE LOCALE
    # ----------------------------------------------------------

    maschera = (
        st.session_state[
            "_df_giocatori_sessione"
        ]["Id"]
        == giocatore_id_db
    )

    st.session_state[
        "_df_giocatori_sessione"
    ].loc[
        maschera,
        "Stato"
    ] = nuovo_stato_db

    st.session_state[
        "_df_giocatori_sessione"
    ].loc[
        maschera,
        "Prezzo"
    ] = nuovo_prezzo_db

    aggiorna_cronologia_locale_dopo_operazione(
        operazione_id,
        tipo_db,
        giocatore_id_db,
        nome,
        stato_prima,
        prezzo_prima,
        nuovo_stato_db,
        nuovo_prezzo_db,
        costo_svincolo_db
    )

    if costo_svincolo_db > 0:

        st.session_state[
            "_costi_svincoli_sessione"
        ] = round(
            calcola_costi_svincoli()
            + costo_svincolo_db,
            2
        )

    if "backup_cloud_bytes" in st.session_state:
        st.session_state.backup_cloud_bytes = None

    if "pdf_rosa_moduli" in st.session_state:
        st.session_state.pdf_rosa_moduli = None

def carica_ultime_operazioni():

    chiave = "_ultime_operazioni_sessione"

    if chiave in st.session_state:

        return st.session_state[chiave]

    conn = get_connection()

    df = pd.read_sql_query("""
        SELECT

            id AS Id,

            tipo AS Operazione,

            giocatore_id
                AS GiocatoreId,

            nome_giocatore
                AS Giocatore,

            stato_prima
                AS StatoPrima,

            prezzo_prima
                AS PrezzoPrima,

            stato_dopo
                AS StatoDopo,

            prezzo_dopo
                AS PrezzoDopo,

            costo_svincolo
                AS CostoSvincolo,

            data_operazione
                AS Data

        FROM operazioni

        ORDER BY id DESC

        LIMIT 10
    """, conn)

    chiudi_connessione(
        conn
    )

    st.session_state[
        chiave
    ] = df.copy()

    return df


def aggiorna_cronologia_locale_dopo_operazione(
    operazione_id,
    tipo,
    giocatore_id,
    nome,
    stato_prima,
    prezzo_prima,
    stato_dopo,
    prezzo_dopo,
    costo_svincolo
):

    chiave = "_ultime_operazioni_sessione"

    colonne = [
        "Id",
        "Operazione",
        "GiocatoreId",
        "Giocatore",
        "StatoPrima",
        "PrezzoPrima",
        "StatoDopo",
        "PrezzoDopo",
        "CostoSvincolo",
        "Data"
    ]

    nuova = pd.DataFrame(
        [
            {
                "Id": int(
                    operazione_id
                    or 0
                ),
                "Operazione": tipo,
                "GiocatoreId": int(
                    giocatore_id
                ),
                "Giocatore": nome,
                "StatoPrima": stato_prima,
                "PrezzoPrima": prezzo_prima,
                "StatoDopo": stato_dopo,
                "PrezzoDopo": prezzo_dopo,
                "CostoSvincolo": float(
                    costo_svincolo
                    or 0
                ),
                "Data": datetime.now(
                    ZoneInfo(
                        "Europe/Rome"
                    )
                ).strftime(
                    "%Y-%m-%d %H:%M:%S"
                )
            }
        ],
        columns=colonne
    )

    precedente = (
        st.session_state.get(
            chiave
        )
    )

    if (
        precedente is None
        or precedente.empty
    ):

        storico = nuova

    else:

        storico = pd.concat(
            [
                nuova,
                precedente
            ],
            ignore_index=True
        ).head(
            MAX_UNDO
        )

    st.session_state[
        chiave
    ] = storico

def annulla_ultima_operazione():

    operazioni = (
        carica_ultime_operazioni()
    )

    if operazioni.empty:
        return False

    ultima = operazioni.iloc[0]

    operazione_id = int(
        ultima["Id"]
    )

    giocatore_id = int(
        ultima["GiocatoreId"]
    )

    stato_prima = ultima[
        "StatoPrima"
    ]

    prezzo_prima = ultima[
        "PrezzoPrima"
    ]

    costo_svincolo = float(
        ultima[
            "CostoSvincolo"
        ]
        or 0
    )

    conn = get_connection()
    cur = conn.cursor()

    cur.execute("""
        UPDATE giocatori

        SET
            stato = ?,
            prezzo_acquisto = ?

        WHERE id = ?
    """, (
        stato_prima,
        (
            None
            if pd.isna(
                prezzo_prima
            )
            else float(
                prezzo_prima
            )
        ),
        giocatore_id
    ))

    if costo_svincolo > 0:

        cur.execute("""
            DELETE FROM costi_svincoli

            WHERE operazione_id = ?
        """, (
            operazione_id,
        ))

    cur.execute("""
        DELETE FROM operazioni

        WHERE id = ?
    """, (
        operazione_id,
    ))

    conn.commit()

    chiudi_connessione(
        conn
    )

    # Aggiorna subito la copia in memoria.
    df_sessione = (
        carica_tutti_giocatori()
    )

    maschera = (
        df_sessione["Id"]
        == giocatore_id
    )

    df_sessione.loc[
        maschera,
        "Stato"
    ] = stato_prima

    df_sessione.loc[
        maschera,
        "Prezzo"
    ] = (
        None
        if pd.isna(
            prezzo_prima
        )
        else float(
            prezzo_prima
        )
    )

    st.session_state[
        "_df_giocatori_sessione"
    ] = df_sessione

    # Rimuove localmente l'operazione appena annullata.
    storico = st.session_state.get(
        "_ultime_operazioni_sessione"
    )

    if (
        storico is not None
        and not storico.empty
    ):

        st.session_state[
            "_ultime_operazioni_sessione"
        ] = (
            storico[
                storico["Id"]
                != operazione_id
            ]
            .reset_index(
                drop=True
            )
        )

    if costo_svincolo > 0:

        st.session_state[
            "_costi_svincoli_sessione"
        ] = round(
            max(
                0.0,
                calcola_costi_svincoli()
                - costo_svincolo
            ),
            2
        )

    if "backup_cloud_bytes" in st.session_state:
        st.session_state.backup_cloud_bytes = None

    if "pdf_rosa_moduli" in st.session_state:
        st.session_state.pdf_rosa_moduli = None

    return True



def ripristina_tutti_giocatori_avversari():
    """
    Rende nuovamente DISPONIBILI tutti i giocatori attualmente
    assegnati agli avversari del profilo attivo.

    Non modifica:
    - la propria rosa;
    - i prezzi dei propri acquisti;
    - i costi di svincolo.

    Elimina dalla cronologia UNDO solo le operazioni collegate
    allo stato AVVERSARIO, così non rimangono riferimenti incoerenti.
    """

    df_corrente = carica_tutti_giocatori()

    avversari = (
        df_corrente[
            df_corrente["Stato"] == "AVVERSARIO"
        ]
        .copy()
    )

    if avversari.empty:
        return 0

    conn = get_connection()
    cur = conn.cursor()

    try:

        cur.execute("""
            UPDATE giocatori

            SET
                stato = 'DISPONIBILE',
                prezzo_acquisto = NULL

            WHERE stato = 'AVVERSARIO'
        """)

        # Rimuove soltanto le operazioni che coinvolgono lo stato
        # AVVERSARIO. Le operazioni della propria rosa restano intatte.
        cur.execute("""
            DELETE FROM operazioni

            WHERE stato_dopo = 'AVVERSARIO'
               OR stato_prima = 'AVVERSARIO'
        """)

        conn.commit()

    except Exception:

        try:
            conn.rollback()
        except Exception:
            pass

        raise

    finally:

        chiudi_connessione(
            conn
        )

    # Aggiorna subito la copia in memoria.
    if "_df_giocatori_sessione" in st.session_state:

        df_sessione = (
            st.session_state[
                "_df_giocatori_sessione"
            ]
            .copy()
        )

        mask = (
            df_sessione["Stato"]
            == "AVVERSARIO"
        )

        df_sessione.loc[
            mask,
            "Stato"
        ] = "DISPONIBILE"

        df_sessione.loc[
            mask,
            "Prezzo"
        ] = None

        st.session_state[
            "_df_giocatori_sessione"
        ] = df_sessione

    # Forza il ricaricamento della cronologia.
    st.session_state.pop(
        "_ultime_operazioni_sessione",
        None
    )

    if "backup_cloud_bytes" in st.session_state:
        st.session_state.backup_cloud_bytes = None

    if "pdf_rosa_moduli" in st.session_state:
        st.session_state.pdf_rosa_moduli = None

    return int(
        len(
            avversari
        )
    )


def elimina_tutta_la_rosa():
    df_corrente = carica_tutti_giocatori()
    rosa = df_corrente[df_corrente["Stato"] == "MIO"].copy()
    if rosa.empty:
        return 0

    conn = get_connection()
    cur = conn.cursor()
    cur.execute("""
        UPDATE giocatori
        SET stato = 'DISPONIBILE',
            prezzo_acquisto = NULL
        WHERE stato = 'MIO'
    """)
    cur.execute("DELETE FROM costi_svincoli")
    cur.execute("DELETE FROM operazioni")
    conn.commit()
    chiudi_connessione(conn)

    if "_df_giocatori_sessione" in st.session_state:
        df_sessione = st.session_state["_df_giocatori_sessione"]
        mask = df_sessione["Stato"] == "MIO"
        df_sessione.loc[mask, "Stato"] = "DISPONIBILE"
        df_sessione.loc[mask, "Prezzo"] = None
        st.session_state["_df_giocatori_sessione"] = df_sessione

    try:
        carica_ultime_operazioni.clear()
    except Exception:
        pass
    try:
        calcola_costi_svincoli.clear()
    except Exception:
        pass

    if "backup_cloud_bytes" in st.session_state:
        st.session_state.backup_cloud_bytes = None

    return int(len(rosa))


# ============================================================
# ECONOMIA DATABASE
# ============================================================

def calcola_valore_acquisti_attivi():

    df = carica_tutti_giocatori()

    if (
        df is None
        or df.empty
        or "Stato" not in df.columns
        or "Prezzo" not in df.columns
    ):
        return 0.0

    prezzi = pd.to_numeric(
        df.loc[
            df["Stato"] == "MIO",
            "Prezzo"
        ],
        errors="coerce"
    ).fillna(0)

    return round(
        float(
            prezzi.sum()
        ),
        2
    )


def calcola_costi_svincoli():

    chiave = "_costi_svincoli_sessione"

    if chiave in st.session_state:

        return round(
            float(
                st.session_state[
                    chiave
                ]
                or 0
            ),
            2
        )

    conn = get_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            COALESCE(
                SUM(importo),
                0
            )

        FROM costi_svincoli
    """)

    riga = cur.fetchone()

    chiudi_connessione(
        conn
    )

    totale = round(
        float(
            (
                riga[0]
                if riga
                else 0
            )
            or 0
        ),
        2
    )

    st.session_state[
        chiave
    ] = totale

    return totale

def calcola_valore_acquisti_totale():

    return round(
        calcola_valore_acquisti_attivi()
        + calcola_costi_svincoli(),
        2
    )


# ============================================================
# CACHE DATI CLOUD
# ============================================================

def invalida_cache_dati():

    chiavi_sessione = [
        "backup_cloud_bytes",
        "pdf_rosa_moduli",
        "_df_giocatori_sessione",
        "_ultime_operazioni_sessione",
        "_costi_svincoli_sessione",
        "_ml16_sidebar_metrics"
    ]

    # Cache V119 derivate da dati di lega/team.
    for _k in list(st.session_state.keys()):
        if (
            str(_k).startswith("_ml35_listone_centrale_")
            or str(_k).startswith("_ml35_venduti_")
            or str(_k).startswith("_ml35_formazioni_index_")
            or str(_k).startswith("_ml35_moduli_")
            or str(_k).startswith("_ml36_export_rose_")
            or str(_k).startswith("_ml37_console_workspace_ready_")
            or str(_k).startswith("_ml38_workspace_boot_")
        ):
            st.session_state.pop(_k, None)

    for chiave in chiavi_sessione:

        if chiave in st.session_state:

            if chiave in (
                "backup_cloud_bytes",
                "pdf_rosa_moduli"
            ):

                st.session_state[
                    chiave
                ] = None

            else:

                del st.session_state[
                    chiave
                ]

    try:
        elenco_snapshot.clear()
    except Exception:
        pass


