# ============================================================
# REGOLE ROSA
# ============================================================

def conta_portieri(df_rosa):

    if df_rosa is None:
        return 0

    if df_rosa.empty:
        return 0

    if "RM" not in df_rosa.columns:
        return 0

    return int(
        df_rosa["RM"]
        .apply(
            e_portiere
        )
        .sum()
    )


def verifica_acquisto_regole(
    df_rosa,
    nuovo_ruolo
):

    numero_attuale = len(
        df_rosa
    )

    portieri_attuali = (
        conta_portieri(
            df_rosa
        )
    )

    if numero_attuale >= MAX_GIOCATORI:

        return (
            False,
            "La rosa ha già raggiunto "
            f"il limite di {MAX_GIOCATORI} giocatori."
        )

    nuovo_e_portiere = (
        e_portiere(
            nuovo_ruolo
        )
    )

    numero_dopo = (
        numero_attuale
        + 1
    )

    portieri_dopo = (
        portieri_attuali
        + (
            1
            if nuovo_e_portiere
            else 0
        )
    )

    slot_rimanenti = (
        MAX_GIOCATORI
        - numero_dopo
    )

    portieri_necessari = max(
        0,
        MIN_PORTIERI
        - portieri_dopo
    )

    if (
        slot_rimanenti
        < portieri_necessari
    ):

        return (
            False,
            "Gli slot rimanenti devono "
            "essere riservati ai portieri."
        )

    return (
        True,
        ""
    )


# ============================================================
# COPERTURA RUOLO / MODULO
# ============================================================

def percentuale_copertura_ruolo(
    df_rosa,
    ruolo_posizione
):
    """
    100% = almeno 4 giocatori compatibili con quel ruolo/slot.
    La percentuale cresce linearmente:
    0 giocatori = 0%
    1 giocatore  = 25%
    2 giocatori  = 50%
    3 giocatori  = 75%
    4 o più      = 100%
    """

    possibili = giocatori_compatibili(
        df_rosa,
        ruolo_posizione
    )

    numero = len(
        possibili
    )

    percentuale = min(
        100.0,
        (
            numero
            / 4
        )
        * 100.0
    )

    return (
        numero,
        percentuale
    )


def qualita_media_ruolo_slot(
    df_rosa,
    ruolo_posizione
):
    """
    Qualità media (0-100) dei giocatori compatibili con uno slot.

    Usa lo stesso punteggio individuale dell'IQR:
    Verde 100 / Blu 70 / Rosso 40 / Nero 0-20.
    Se non esistono giocatori compatibili, la qualità è 0%.
    """

    possibili = giocatori_compatibili(
        df_rosa,
        ruolo_posizione
    )

    if possibili.empty:
        return 0.0

    punteggi = []

    for _, giocatore in possibili.iterrows():

        punteggi.append(
            punteggio_qualita_giocatore(
                giocatore.get(
                    "RM",
                    ""
                ),
                giocatore.get(
                    "FVM M"
                )
            )
        )

    if not punteggi:
        return 0.0

    return round(
        sum(
            punteggi
        )
        / len(
            punteggi
        ),
        1
    )


def colore_percentuale_copertura(
    percentuale
):
    """
    Rosso sotto il 60%, nero dal 60% in su.
    """

    if float(
        percentuale
        or 0
    ) < 60:
        return "#dc2626"

    return "#111827"


def calcola_copertura_modulo(
    df_rosa,
    nome_modulo
):

    totale_ruoli = 0
    ruoli_al_100 = 0
    somma_percentuali = 0.0

    for _, posizioni in MODULI[
        nome_modulo
    ]:

        for _, ruolo_slot in posizioni:

            totale_ruoli += 1

            numero, percentuale = (
                percentuale_copertura_ruolo(
                    df_rosa,
                    ruolo_slot
                )
            )

            somma_percentuali += (
                percentuale
            )

            if numero >= 4:
                ruoli_al_100 += 1

    percentuale_media = (
        somma_percentuali
        / totale_ruoli
        if totale_ruoli
        else 0
    )

    return (
        ruoli_al_100,
        totale_ruoli,
        percentuale_media
    )


def analizza_modulo(
    df_rosa,
    nome_modulo
):
    """
    Analisi strategica del modulo.

    Nuove definizioni:
    - SLOT SCOPERTO: slot con 2 o meno giocatori compatibili.
    - SLOT DEBOLE: slot che non raggiunge almeno 3 giocatori
      compatibili oppure non raggiunge almeno il 50% di qualità media.
      Gli slot allo 0% sono inclusi al prossimo aggiornamento tra i deboli.

    Il punteggio strategico considera:
    - copertura media;
    - penalità di profondità per gli slot scoperti;
    - penalità qualitativa per gli slot deboli.

    Penalità:
    - 6 punti per ogni slot scoperto;
    - 4 punti per ogni slot debole.
    """

    dati_slot = []

    for _, posizioni in MODULI[
        nome_modulo
    ]:

        for _, ruolo_slot in posizioni:

            numero, percentuale = (
                percentuale_copertura_ruolo(
                    df_rosa,
                    ruolo_slot
                )
            )

            qualita_media = (
                qualita_media_ruolo_slot(
                    df_rosa,
                    ruolo_slot
                )
            )

            dati_slot.append({
                "Ruolo": ruolo_slot,
                "Numero": int(
                    numero
                ),
                "Copertura": float(
                    percentuale
                ),
                "Qualita": float(
                    qualita_media
                )
            })

    if not dati_slot:

        return {
            "Modulo": nome_modulo,
            "Punteggio": 0.0,
            "Copertura media": 0.0,
            "Scoperti": 0,
            "Deboli": 0,
            "Ruoli deboli": "",
            "Al 100%": 0,
            "Totale slot": 0
        }

    copertura_media = (
        sum(
            s["Copertura"]
            for s in dati_slot
        )
        / len(
            dati_slot
        )
    )

    scoperti = sum(
        1
        for s in dati_slot
        if s["Numero"] <= 2
    )

    slot_deboli = [
        s
        for s in dati_slot
        if (
            s["Numero"] < 3
            or s["Qualita"] < 50
        )
    ]

    deboli = len(
        slot_deboli
    )

    ruoli_deboli = ", ".join(
        s["Ruolo"]
        for s in slot_deboli
    )

    al_100 = sum(
        1
        for s in dati_slot
        if s["Numero"] >= 4
    )

    penalita = (
        scoperti * 6
        + deboli * 4
    )

    punteggio = max(
        0.0,
        min(
            100.0,
            copertura_media
            - penalita
        )
    )

    return {
        "Modulo": nome_modulo,
        "Punteggio": round(
            punteggio,
            1
        ),
        "Copertura media": round(
            copertura_media,
            1
        ),
        "Scoperti": scoperti,
        "Deboli": deboli,
        "Ruoli deboli": ruoli_deboli,
        "Al 100%": al_100,
        "Totale slot": len(
            dati_slot
        )
    }

def classifica_moduli(
    df_rosa
):
    """
    Restituisce la classifica dei moduli dal più adatto al meno adatto.
    """

    risultati = [
        analizza_modulo(
            df_rosa,
            nome_modulo
        )
        for nome_modulo in MODULI
    ]

    risultati = sorted(
        risultati,
        key=lambda x: (
            -x["Punteggio"],
            x["Scoperti"],
            x["Deboli"],
            -x["Copertura media"],
            x["Modulo"]
        )
    )

    for posizione, risultato in enumerate(
        risultati,
        start=1
    ):

        risultato["Posizione"] = (
            posizione
        )

    return risultati


def classifica_moduli_fast(df_rosa):
    """V119 - memoizzazione di sessione della classifica moduli."""
    if df_rosa is None:
        return []

    ids = tuple(
        sorted(
            int(x)
            for x in pd.to_numeric(
                df_rosa.get("Id", pd.Series(dtype=int)),
                errors="coerce"
            ).dropna().tolist()
        )
    )
    sig = (
        _workspace_runtime_key if "_workspace_runtime_key" in globals() else "",
        ids,
        len(df_rosa),
    )
    chiave = "_ml35_moduli_" + str(hash(sig))

    cached = st.session_state.get(chiave)
    if cached is not None:
        return cached

    valore = classifica_moduli(df_rosa)
    st.session_state[chiave] = valore
    return valore





