        'width:82%;'
        'height:48px;'
        'margin:0 auto 10px auto;'
        'padding-top:14px;'
        'box-sizing:border-box;'
        '">'

        '<div style="'
        'width:100%;'
        'height:31px;'
        'display:flex;'
        'overflow:hidden;'
        'box-sizing:border-box;'
        '">'

        '<div style="'
        'width:40%;'
        'height:31px;'
        'background:#050505;'
        '"></div>'

        '<div style="'
        'width:25%;'
        'height:31px;'
        'background:#ff1616;'
        '"></div>'

        '<div style="'
        'width:20%;'
        'height:31px;'
        'background:#0b6df5;'
        '"></div>'

        '<div style="'
        'width:15%;'
        'height:31px;'
        'background:#16a34a;'
        '"></div>'

        '</div>'

        f'<div style="'
        f'position:absolute;'
        f'top:0;'
        f'left:{posizione_popup:.1f}%;'
        f'width:0;'
        f'height:0;'
        f'transform:translateX(-50%);'
        f'border-left:10px solid transparent;'
        f'border-right:10px solid transparent;'
        f'border-top:14px solid #ffffff;'
