def inizializza_listone_lega_asta(league_id, forza=False):
    """
    V116 - inizializzazione asta ottimizzata.

    Evita di eseguire CREATE/ALTER/backfill/INSERT/COMMIT ad ogni lettura
    del Banditore. Con Turso quei round-trip ripetuti erano il principale
    collo di bottiglia.
    """
    league_id = int(league_id)

    _guard_key = f"_auction_schema_ready_v129_{league_id}"
    if not forza and st.session_state.get(_guard_key):
        return

    conn = _portal_raw_connection()
    cur = conn.cursor()
    _dirty = False

    try:
        cur.execute("""
            SELECT name
            FROM sqlite_master
            WHERE type='table'
              AND name IN (
                  'iqr_profiles',
                  'player_evaluations',
                  'auction_assignment_history',
                  'auction_sessions',
                  'auction_lots',
                  'auction_calls',
                  'bids'
              )
        """)
        _presenti = {str(r[0]) for r in (cur.fetchall() or [])}

        _richieste = {
            "iqr_profiles",
            "player_evaluations",
            "auction_assignment_history",
            "auction_sessions",
            "auction_lots",
            "auction_calls",
            "bids",
        }

        _schema_completo = _richieste.issubset(_presenti)

        if _schema_completo:
            cur.execute("PRAGMA table_info(auction_lots)")
            _cols_lot = {str(r[1]) for r in (cur.fetchall() or [])}
            _schema_completo = {
                "closing_by_user_id",
                "closing_at",
                "current_bid",
                "current_team_id",
                "bid_count",
                "version",
                "bid_deadline_ts",
                "auto_assign_claimed",
            }.issubset(_cols_lot)

        if not _schema_completo:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS iqr_profiles (
                    league_id INTEGER NOT NULL,
                    team_id INTEGER NOT NULL,
                    iqr_corrente REAL NOT NULL DEFAULT 0,
                    max_giocatori INTEGER NOT NULL DEFAULT 30,
                    giocatori_rosa INTEGER NOT NULL DEFAULT 0,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    PRIMARY KEY (league_id, team_id)
                )
            """)

            cur.execute("""
                CREATE TABLE IF NOT EXISTS player_evaluations (
                    league_id INTEGER NOT NULL,
                    team_id INTEGER NOT NULL,
                    player_id INTEGER NOT NULL,
                    iqr_prima REAL NOT NULL DEFAULT 0,
                    iqr_dopo REAL NOT NULL DEFAULT 0,
                    delta_iqr REAL NOT NULL DEFAULT 0,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    PRIMARY KEY (league_id, team_id, player_id)
                )
            """)

            cur.execute("""
                CREATE TABLE IF NOT EXISTS auction_assignment_history (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    league_id INTEGER NOT NULL,
                    player_id INTEGER NOT NULL,
                    team_id INTEGER NOT NULL,
                    prezzo REAL NOT NULL,
                    stato TEXT NOT NULL DEFAULT 'ACTIVE',
                    assigned_by_user_id INTEGER,
                    assigned_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    undone_by_user_id INTEGER,
                    undone_at TEXT
                )
            """)

            cur.execute("""
                CREATE TABLE IF NOT EXISTS auction_sessions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    league_id INTEGER NOT NULL UNIQUE,
                    stato TEXT NOT NULL DEFAULT 'READY',
                    current_lot_id INTEGER,
                    started_by_user_id INTEGER,
                    started_at TEXT,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                )
            """)

            cur.execute("""
                CREATE TABLE IF NOT EXISTS auction_lots (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    league_id INTEGER NOT NULL,
                    player_id INTEGER NOT NULL,
                    stato TEXT NOT NULL DEFAULT 'OPEN',
                    opened_by_user_id INTEGER,
                    opened_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    closed_at TEXT,
                    assigned_team_id INTEGER,
                    final_price REAL,
                    closing_by_user_id INTEGER,
                    closing_at TEXT,
                    current_bid REAL,
                    current_team_id INTEGER,
                    bid_count INTEGER NOT NULL DEFAULT 0,
                    version INTEGER NOT NULL DEFAULT 0,
                    bid_deadline_ts REAL,
                    auto_assign_claimed INTEGER NOT NULL DEFAULT 0
                )
            """)

            cur.execute("PRAGMA table_info(auction_lots)")
            _cols_lot = {str(r[1]) for r in (cur.fetchall() or [])}

            _migrazioni = {
                "closing_by_user_id":
                    "ALTER TABLE auction_lots ADD COLUMN closing_by_user_id INTEGER",
                "closing_at":
                    "ALTER TABLE auction_lots ADD COLUMN closing_at TEXT",
                "current_bid":
                    "ALTER TABLE auction_lots ADD COLUMN current_bid REAL",
                "current_team_id":
                    "ALTER TABLE auction_lots ADD COLUMN current_team_id INTEGER",
                "bid_count":
                    "ALTER TABLE auction_lots ADD COLUMN bid_count INTEGER NOT NULL DEFAULT 0",
                "version":
                    "ALTER TABLE auction_lots ADD COLUMN version INTEGER NOT NULL DEFAULT 0",
                "bid_deadline_ts":
                    "ALTER TABLE auction_lots ADD COLUMN bid_deadline_ts REAL",
                "auto_assign_claimed":
                    "ALTER TABLE auction_lots ADD COLUMN auto_assign_claimed INTEGER NOT NULL DEFAULT 0",
            }

            for _colonna, _sql in _migrazioni.items():
                if _colonna not in _cols_lot:
                    cur.execute(_sql)
                    _dirty = True

            cur.execute("""
                CREATE TABLE IF NOT EXISTS auction_calls (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    league_id INTEGER NOT NULL,
                    team_id INTEGER NOT NULL,
                    player_id INTEGER NOT NULL,
                    tipo_asta TEXT NOT NULL,
                    stato TEXT NOT NULL DEFAULT 'PENDING',
                    created_by_user_id INTEGER NOT NULL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    handled_by_user_id INTEGER,
                    handled_at TEXT
                )
            """)

            cur.execute("""
                CREATE INDEX IF NOT EXISTS ix_auction_calls_league_state
                ON auction_calls(league_id, stato, id)
            """)

            cur.execute("""
                CREATE TABLE IF NOT EXISTS bids (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    league_id INTEGER NOT NULL,
                    lot_id INTEGER NOT NULL,
                    team_id INTEGER NOT NULL,
                    user_id INTEGER NOT NULL,
                    amount REAL NOT NULL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                )
            """)

            cur.execute("""
                CREATE UNIQUE INDEX IF NOT EXISTS ux_bids_lot_amount
                ON bids(lot_id, amount)
            """)

            cur.execute("""
                CREATE INDEX IF NOT EXISTS ix_bids_lot_id
                ON bids(lot_id, id)
            """)

            try:
                cur.execute("""
                    UPDATE auction_lots
                    SET current_bid = (
                            SELECT MAX(b.amount)
                            FROM bids b
                            WHERE b.lot_id=auction_lots.id
                              AND b.league_id=auction_lots.league_id
                        ),
                        current_team_id = (
                            SELECT b2.team_id
                            FROM bids b2
                            WHERE b2.lot_id=auction_lots.id
                              AND b2.league_id=auction_lots.league_id
                            ORDER BY b2.amount DESC, b2.id ASC
                            LIMIT 1
                        ),
                        bid_count = (
                            SELECT COUNT(*)
                            FROM bids b3
                            WHERE b3.lot_id=auction_lots.id
                              AND b3.league_id=auction_lots.league_id
                        )
                    WHERE current_bid IS NULL
                      AND EXISTS (
                          SELECT 1
                          FROM bids bx
                          WHERE bx.lot_id=auction_lots.id
                            AND bx.league_id=auction_lots.league_id
                      )
                """)
            except Exception:
                pass

            _dirty = True

        # Controllo aggregato dei soli dati mancanti.
        cur.execute("""
            SELECT
                EXISTS(
                    SELECT 1
                    FROM auction_sessions
                    WHERE league_id=?
                ),
                EXISTS(
                    SELECT 1
                    FROM league_player_catalog c
                    WHERE c.league_id=?
                      AND NOT EXISTS (
                          SELECT 1
                          FROM league_players lp
                          WHERE lp.league_id=c.league_id
                            AND lp.player_id=c.player_id
                      )
                ),
                EXISTS(
                    SELECT 1
                    FROM teams t
                    WHERE t.league_id=?
                      AND t.is_active=1
                      AND NOT EXISTS (
                          SELECT 1
                          FROM team_budgets b
                          WHERE b.league_id=t.league_id
                            AND b.team_id=t.id
                      )
                )
        """, (league_id, league_id, league_id))

        _check = cur.fetchone() or (0, 0, 0)
        _sessione_esiste = bool(_check[0])
        _mancano_players = bool(_check[1])
        _mancano_budget = bool(_check[2])

        if not _sessione_esiste:
            cur.execute("""
                INSERT INTO auction_sessions (
                    league_id, stato, current_lot_id, updated_at
                )
                VALUES (?, 'READY', NULL, CURRENT_TIMESTAMP)
                ON CONFLICT(league_id) DO NOTHING
            """, (league_id,))
            _dirty = True

        if _mancano_players:
            cur.execute("""
                INSERT INTO league_players (
                    league_id, player_id, stato,
                    assigned_team_id, prezzo_assegnazione, updated_at
                )
                SELECT ?, c.player_id, 'DISPONIBILE',
                       NULL, NULL, CURRENT_TIMESTAMP
                FROM league_player_catalog c
                WHERE c.league_id=?
                  AND NOT EXISTS (
                      SELECT 1
                      FROM league_players lp
                      WHERE lp.league_id=?
                        AND lp.player_id=c.player_id
                  )
            """, (league_id, league_id, league_id))
            _dirty = True

        if _mancano_budget:
            cur.execute("""
                INSERT INTO team_budgets (
                    league_id, team_id, budget_impostato,
                    valore_acquisti, spesa_effettiva, updated_at
                )
                SELECT
                    ?, t.id,
                    COALESCE(r.budget_iniziale,500),
                    0,0,CURRENT_TIMESTAMP
                FROM teams t
                LEFT JOIN league_rules r
                  ON r.league_id=t.league_id
                WHERE t.league_id=? AND t.is_active=1
                  AND NOT EXISTS (
                      SELECT 1
                      FROM team_budgets b
                      WHERE b.league_id=?
                        AND b.team_id=t.id
                  )
            """, (league_id, league_id, league_id))
            _dirty = True

        if _dirty:
            conn.commit()

        st.session_state[_guard_key] = True

    finally:
        _portal_close(conn)


def invalida_inizializzazione_asta_multilega(league_id=None):
    if league_id is None:
        for _k in list(st.session_state.keys()):
            if str(_k).startswith("_auction_schema_ready_v116_"):
                st.session_state.pop(_k, None)
        return

    st.session_state.pop(
        f"_auction_schema_ready_v116_{int(league_id)}",
        None
    )


def lotto_corrente_multilega(league_id):
    league_id = int(league_id)
    inizializza_listone_lega_asta(league_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT
                l.id,
                l.player_id,
                l.stato,
                l.opened_at,
                COALESCE(g.nome,''),
                COALESCE(g.squadra,''),
                COALESCE(g.ruolo_mantra,''),
                COALESCE(g.fvm_mantra,g.fvm,0),
                COALESCE(g.quotazione_attuale_mantra,g.quotazione_attuale,0),
                l.closing_at,
                l.current_bid,
                l.current_team_id,
                COALESCE(l.bid_count,0),
                COALESCE(l.version,0),
                l.bid_deadline_ts
            FROM auction_sessions s
            LEFT JOIN auction_lots l ON l.id=s.current_lot_id
            LEFT JOIN league_player_catalog g ON g.player_id=l.player_id AND g.league_id=s.league_id
            WHERE s.league_id=?
            LIMIT 1
        """, (league_id,))
        r = cur.fetchone()

        if not r or r[0] is None:
            return None

        return {
            "lot_id": int(r[0]),
            "player_id": int(r[1]),
            "stato": str(r[2] or ""),
            "opened_at": str(r[3] or ""),
            "nome": str(r[4] or ""),
            "squadra": str(r[5] or ""),
            "ruolo_mantra": str(r[6] or ""),
            "fvm": float(r[7] or 0),
            "quotazione": float(r[8] or 0),
            "closing_at": str(r[9] or ""),
            "current_bid": float(r[10]) if r[10] is not None else None,
            "current_team_id": int(r[11]) if r[11] is not None else None,
            "bid_count": int(r[12] or 0),
            "version": int(r[13] or 0),
            "bid_deadline_ts": float(r[14]) if r[14] is not None else None,
        }
    finally:
        _portal_close(conn)




def assicura_schema_movimenti_rosa_v149(league_id):
    """
    Costi non rimborsabili generati da SVINCOLO.
    ELIMINA invece rimuove ogni costo residuo.
    """
    league_id = int(league_id)
    guard = f"_v149_release_schema_{league_id}"
    if st.session_state.get(guard):
        return

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            CREATE TABLE IF NOT EXISTS auction_release_costs (
                league_id INTEGER NOT NULL,
                team_id INTEGER NOT NULL,
                player_id INTEGER NOT NULL,
                costo REAL NOT NULL DEFAULT 0,
                active INTEGER NOT NULL DEFAULT 1,
                created_by_user_id INTEGER,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (league_id, player_id)
            )
        """)
        cur.execute("""
            CREATE INDEX IF NOT EXISTS ix_release_costs_team
            ON auction_release_costs(league_id, team_id, active)
        """)
        conn.commit()
        st.session_state[guard] = True
    finally:
        _portal_close(conn)



def assicura_schema_storico_asta_v147(league_id):
    """
    Crea/aggiorna lo storico autorevole dei giocatori CHIAMATI.

    V162: la verifica delle colonne strutturali viene eseguita SEMPRE sul DB,
    anche se la sessione Streamlit aveva gia' impostato il guard di schema.
    Questo evita errori dopo un hot-update del codice (es. colonna active
    introdotta mentre la sessione era gia' aperta).
    """
    league_id = int(league_id)

    # V164 - schema check una sola volta per sessione/lega.
    # Le CREATE/PRAGMA su DB remoto erano una delle principali cause di latenza
    # dello Storico Asta. Il suffisso versione forza comunque una verifica dopo
    # ogni aggiornamento strutturale del codice.
    fast_guard = f"_v163_storico_schema_ready_{league_id}"
    if st.session_state.get(fast_guard):
        return

    assicura_schema_movimenti_rosa_v149(league_id)
    guard = f"_v147_storico_schema_{league_id}"

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        # Questa parte NON va mai saltata dal guard: e' una migrazione
        # idempotente e deve poter riparare DB creati con versioni precedenti.
        cur.execute("""
            CREATE TABLE IF NOT EXISTS auction_called_players (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                league_id INTEGER NOT NULL,
                player_id INTEGER NOT NULL,
                fonte TEXT NOT NULL DEFAULT 'LOT',
                lot_id INTEGER,
                called_by_user_id INTEGER,
                called_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                active INTEGER NOT NULL DEFAULT 1,
                UNIQUE(league_id, player_id)
            )
        """)

        cur.execute("PRAGMA table_info(auction_called_players)")
        _called_cols = {str(_r[1]) for _r in (cur.fetchall() or [])}
        if "active" not in _called_cols:
            cur.execute(
                "ALTER TABLE auction_called_players "
                "ADD COLUMN active INTEGER NOT NULL DEFAULT 1"
            )
            conn.commit()

        # V162 - tombstone autorevole dello Storico Asta.
        # Serve a impedire che backfill, vecchi lotti o cache possano far
        # ricomparire un giocatore svincolato/eliminato.
        cur.execute("""
            CREATE TABLE IF NOT EXISTS auction_history_exclusions (
                league_id INTEGER NOT NULL,
                player_id INTEGER NOT NULL,
                reason TEXT NOT NULL,
                excluded_by_user_id INTEGER,
                excluded_at TEXT DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (league_id, player_id)
            )
        """)
        cur.execute("""
            CREATE INDEX IF NOT EXISTS ix_history_exclusions_league
            ON auction_history_exclusions(league_id, player_id)
        """)
        conn.commit()

        # Dopo avere garantito la struttura, il resto del backfill/schema puo'
        # essere evitato se gia' completato in questa sessione.
        if st.session_state.get(guard):
            st.session_state[fast_guard] = True
            return

        cur.execute("""
            CREATE INDEX IF NOT EXISTS ix_called_players_league_called
            ON auction_called_players(league_id, called_at, id)
        """)
        cur.execute("""
            CREATE INDEX IF NOT EXISTS ix_auction_lots_league_player_id
            ON auction_lots(league_id, player_id, id)
        """)

        # Backfill: tutti i lotti già aperti in passato sono giocatori chiamati.
        cur.execute("""
            INSERT INTO auction_called_players (
                league_id,player_id,fonte,lot_id,
                called_by_user_id,called_at,updated_at
            )
            SELECT
                l.league_id,l.player_id,'LOT',l.id,
                l.opened_by_user_id,
                COALESCE(l.opened_at,CURRENT_TIMESTAMP),
                CURRENT_TIMESTAMP
            FROM auction_lots l
            WHERE l.league_id=?
            ON CONFLICT(league_id,player_id)
            DO NOTHING
        """, (league_id,))

        # Backfill chiamate team gestite/saltate.
        cur.execute("""
            INSERT INTO auction_called_players (
                league_id,player_id,fonte,lot_id,
                called_by_user_id,called_at,updated_at
            )
            SELECT
                c.league_id,c.player_id,'CALL',NULL,
                COALESCE(c.handled_by_user_id,c.created_by_user_id),
                COALESCE(c.handled_at,c.created_at,CURRENT_TIMESTAMP),
                CURRENT_TIMESTAMP
            FROM auction_calls c
            WHERE c.league_id=?
              AND UPPER(COALESCE(c.stato,'')) IN
                  ('OPENED','ASSIGNED','SKIPPED')
            ON CONFLICT(league_id,player_id)
            DO NOTHING
        """, (league_id,))

        # Backfill dei "PROSSIMO GIOCATORE" RANDOM/ALFABETICO precedenti a V147.
        try:
            cur.execute("""
                SELECT COALESCE(skipped_players_json,'[]')
                FROM auction_mode_state
                WHERE league_id=?
                LIMIT 1
            """, (league_id,))
            r = cur.fetchone()
            skipped = json.loads(r[0] if r and r[0] else "[]")
            for pid in skipped:
                try:
                    pid = int(pid)
                except Exception:
                    continue
                cur.execute("""
                    INSERT INTO auction_called_players (
                        league_id,player_id,fonte,lot_id,
                        called_by_user_id,called_at,updated_at
                    )
                    VALUES (?,?,'SKIPPED',NULL,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
                    ON CONFLICT(league_id,player_id)
                    DO NOTHING
                """, (
                    league_id,
                    pid,
                    int(st.session_state.get("auth_user_id") or 0)
                ))
        except Exception:
            pass

        conn.commit()
        st.session_state[guard] = True
        st.session_state[fast_guard] = True
    finally:
        _portal_close(conn)


def registra_giocatore_chiamato_v147(
    cur, league_id, player_id, fonte, lot_id=None
):
    # V162 - una nuova chiamata rende nuovamente visibile il giocatore.
    cur.execute("""
        DELETE FROM auction_history_exclusions
        WHERE league_id=? AND player_id=?
    """, (int(league_id), int(player_id)))

    cur.execute("""
        INSERT INTO auction_called_players (
            league_id,player_id,fonte,lot_id,
            called_by_user_id,called_at,updated_at
        )
        VALUES (?,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
        ON CONFLICT(league_id,player_id)
        DO UPDATE SET
            fonte=excluded.fonte,
            lot_id=CASE
                WHEN UPPER(COALESCE(excluded.fonte,''))='SKIPPED' THEN NULL
                ELSE COALESCE(excluded.lot_id,auction_called_players.lot_id)
            END,
            active=1,
            called_at=CURRENT_TIMESTAMP,
            updated_at=CURRENT_TIMESTAMP
    """, (
        int(league_id),
        int(player_id),
        str(fonte),
        int(lot_id) if lot_id is not None else None,
        int(st.session_state.get("auth_user_id") or 0)
    ))


def contatore_chiamati_v147(league_id):
    league_id = int(league_id)
    assicura_schema_storico_asta_v147(league_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT
                (
                    SELECT COUNT(DISTINCT player_id)
                    FROM auction_called_players cp
                    WHERE cp.league_id=?
                      AND COALESCE(cp.active,1)=1
                      AND NOT EXISTS (
                          SELECT 1
                          FROM auction_history_exclusions hx
                          WHERE hx.league_id=cp.league_id
                            AND hx.player_id=cp.player_id
                      )
                ),
                (
                    SELECT COUNT(*)
                    FROM league_player_catalog
                    WHERE league_id=?
                )
        """, (league_id, league_id))
        r = cur.fetchone() or (0,0)
        chiamati = int(r[0] or 0)
        totale = int(r[1] or 0)
        percentuale = (
            round((chiamati / totale) * 100, 1)
            if totale > 0 else 0.0
        )
        return chiamati, totale, percentuale
    finally:
        _portal_close(conn)


def _storico_asta_db_v156(league_id):
    """V164: query storico minimale, senza scansione/window di auction_lots."""
    league_id = int(league_id)
    assicura_schema_storico_asta_v147(league_id)

    conn = _portal_raw_connection()
    try:
        return pd.read_sql_query("""
            SELECT
                cp.player_id AS "__PLAYER_ID",
                c.nome AS "NOME GIOCATORE",
                c.ruolo_mantra AS "RUOLO",
                c.squadra AS "SQUADRA",
                lp.prezzo_assegnazione AS "PREZZO",
                COALESCE(t.nome,'—') AS "ASSEGNATO A"
            FROM auction_called_players cp
            JOIN league_player_catalog c
              ON c.league_id=cp.league_id
             AND c.player_id=cp.player_id
            LEFT JOIN league_players lp
              ON lp.league_id=cp.league_id
             AND lp.player_id=cp.player_id
            LEFT JOIN teams t
              ON t.league_id=cp.league_id
             AND t.id=lp.assigned_team_id
            WHERE cp.league_id=?
              AND COALESCE(cp.active,1)=1
              AND NOT EXISTS (
                  SELECT 1
                  FROM auction_history_exclusions hx
                  WHERE hx.league_id=cp.league_id
                    AND hx.player_id=cp.player_id
              )
            ORDER BY cp.called_at DESC, cp.id DESC
        """, conn, params=(league_id,))
    finally:
        _portal_close(conn)

def _squadre_storico_db_v156(league_id):
    league_id = int(league_id)
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT id,nome
            FROM teams
            WHERE league_id=? AND is_active=1
            ORDER BY posizione,id
        """, (league_id,))
        rows = cur.fetchall() or []
        return [
            {"team_id": int(r[0]), "nome": str(r[1] or "")}
            for r in rows
        ]
    finally:
        _portal_close(conn)



def totale_giocatori_lega_fast_v164(league_id, ttl=300.0):
    """Totale listone quasi-statico: una query al massimo ogni 5 minuti/sessione."""
    league_id = int(league_id)
    key = f"_v164_total_catalog_{league_id}"
    now = time.monotonic()
    cached = st.session_state.get(key)
    if isinstance(cached, dict) and now - float(cached.get("ts", 0)) < float(ttl):
        return int(cached.get("value", 0))
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("SELECT COUNT(*) FROM league_player_catalog WHERE league_id=?", (league_id,))
        value = int((cur.fetchone() or (0,))[0] or 0)
    finally:
        _portal_close(conn)
    st.session_state[key] = {"ts": now, "value": value}
    return value


def storico_asta_v147(league_id, ttl=15.0):
    league_id = int(league_id)
    key = f"_v156_history_{league_id}"
    now = time.monotonic()
    cached = st.session_state.get(key)
    if isinstance(cached, dict) and now - float(cached.get("ts", 0)) < float(ttl):
        return cached["df"].copy()
    df = _storico_asta_db_v156(league_id)
    st.session_state[key] = {"ts": now, "df": df.copy()}
    return df


def squadre_storico_v147(league_id, ttl=300.0):
    league_id = int(league_id)
    key = f"_v156_history_teams_{league_id}"
    now = time.monotonic()
    cached = st.session_state.get(key)
    if isinstance(cached, dict) and now - float(cached.get("ts", 0)) < float(ttl):
        return list(cached["value"])
    value = _squadre_storico_db_v156(league_id)
    st.session_state[key] = {"ts": now, "value": list(value)}
    return value


def _ricalcola_budget_team_v147(cur, league_id, team_id):
    league_id = int(league_id)
    team_id = int(team_id)

    cur.execute("""
        SELECT
            COALESCE(tb.budget_impostato,r.budget_iniziale,500),
            COALESCE(r.soglia_budget,r.budget_iniziale,500),
            COALESCE(r.moltiplicatore_oltre_soglia,1),
            COALESCE((
                SELECT SUM(COALESCE(lp.prezzo_assegnazione,0))
                FROM league_players lp
                WHERE lp.league_id=?
                  AND lp.stato='ASSEGNATO'
                  AND lp.assigned_team_id=?
            ),0)
            +
            COALESCE((
                SELECT SUM(COALESCE(rc.costo,0))
                FROM auction_release_costs rc
                WHERE rc.league_id=?
                  AND rc.team_id=?
                  AND rc.active=1
            ),0)
        FROM league_rules r
        LEFT JOIN team_budgets tb
          ON tb.league_id=r.league_id
         AND tb.team_id=?
        WHERE r.league_id=?
        LIMIT 1
    """, (
        league_id,team_id,
        league_id,team_id,
        team_id,league_id
    ))
    r = cur.fetchone()
    if not r:
        return

    budget = float(r[0] or 0)
    soglia = float(r[1] or budget)
    moltiplicatore = max(1.0, float(r[2] or 1))
    valore = float(r[3] or 0)
    spesa = float(_spesa_effettiva_regole(
        valore, soglia, moltiplicatore
    ))

    cur.execute("""
        INSERT INTO team_budgets (
            league_id,team_id,budget_impostato,
            valore_acquisti,spesa_effettiva,updated_at
        )
        VALUES (?,?,?,?,?,CURRENT_TIMESTAMP)
        ON CONFLICT(league_id,team_id)
        DO UPDATE SET
            valore_acquisti=excluded.valore_acquisti,
            spesa_effettiva=excluded.spesa_effettiva,
            updated_at=CURRENT_TIMESTAMP
    """, (
        league_id,team_id,budget,valore,spesa
    ))



def modifica_assegnazione_storico_v147(
    league_id, player_id, nuovo_team_nome, nuovo_prezzo
):
    """
    Corregge squadra/prezzo dallo STORICO ASTA.
    Le viste ROSA e ROSE AVVERSARI si aggiornano automaticamente
    perché leggono dallo stesso league_players autorevole.
    """
    league_id = int(league_id)
    player_id = int(player_id)
    user_id = int(st.session_state.get("auth_user_id") or 0)
    team_nome = str(nuovo_team_nome or "—").strip()
    prezzo = (
        None
        if nuovo_prezzo is None or pd.isna(nuovo_prezzo)
        else float(nuovo_prezzo)
    )

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT COUNT(*)
            FROM league_members
            WHERE league_id=? AND user_id=? AND is_active=1
              AND (is_auctioneer=1 OR is_admin=1)
        """, (league_id,user_id))
        if int((cur.fetchone() or [0])[0] or 0) <= 0:
            raise PermissionError("Operazione riservata al Banditore/Admin.")

        cur.execute("""
            SELECT 1
            FROM auction_called_players
            WHERE league_id=? AND player_id=?
            LIMIT 1
        """, (league_id,player_id))
        if not cur.fetchone():
            raise ValueError("Giocatore non presente nello storico asta.")

        # Non correggere un lotto ancora aperto.
        cur.execute("""
            SELECT UPPER(COALESCE(stato,''))
            FROM auction_lots
            WHERE league_id=? AND player_id=?
            ORDER BY id DESC
            LIMIT 1
        """, (league_id,player_id))
        rlot = cur.fetchone()
        if rlot and str(rlot[0] or "") in ("OPEN","CLOSING"):
            raise ValueError(
                "Il lotto è ancora aperto: chiudilo prima di modificare lo storico."
            )

        cur.execute("""
            SELECT assigned_team_id,prezzo_assegnazione
            FROM league_players
            WHERE league_id=? AND player_id=?
            LIMIT 1
        """, (league_id,player_id))
        old = cur.fetchone()
        old_team_id = int(old[0]) if old and old[0] is not None else None
        old_prezzo = float(old[1]) if old and old[1] is not None else None

        new_team_id = None
        if team_nome not in ("", "—", "-", "NESSUNO"):
            cur.execute("""
                SELECT id
                FROM teams
                WHERE league_id=? AND is_active=1 AND nome=?
                LIMIT 1
            """, (league_id,team_nome))
            rt = cur.fetchone()
            if not rt:
                raise ValueError("Squadra selezionata non valida.")
            new_team_id = int(rt[0])

            if prezzo is None or prezzo < 0:
                raise ValueError("Inserisci un prezzo valido.")

            # Controlli essenziali sul nuovo destinatario.
            cur.execute("""
                SELECT
                    COALESCE(r.max_giocatori,30),
                    COALESCE(tb.budget_impostato,r.budget_iniziale,500),
                    COALESCE(r.soglia_budget,r.budget_iniziale,500),
                    COALESCE(r.moltiplicatore_oltre_soglia,1),
                    COALESCE((
                        SELECT COUNT(*)
                        FROM league_players lp
                        WHERE lp.league_id=t.league_id
                          AND lp.stato='ASSEGNATO'
                          AND lp.assigned_team_id=t.id
                          AND lp.player_id<>?
                    ),0),
                    COALESCE((
                        SELECT SUM(COALESCE(lp.prezzo_assegnazione,0))
                        FROM league_players lp
                        WHERE lp.league_id=t.league_id
                          AND lp.stato='ASSEGNATO'
                          AND lp.assigned_team_id=t.id
                          AND lp.player_id<>?
                    ),0)
                FROM teams t
                LEFT JOIN league_rules r ON r.league_id=t.league_id
                LEFT JOIN team_budgets tb
                  ON tb.league_id=t.league_id AND tb.team_id=t.id
                WHERE t.league_id=? AND t.id=?
                LIMIT 1
            """, (
                player_id,player_id,league_id,new_team_id
            ))
            vr = cur.fetchone()
            if not vr:
                raise ValueError("Squadra non valida.")
            max_giocatori = int(vr[0] or 30)
            budget = float(vr[1] or 0)
            soglia = float(vr[2] or budget)
            moltiplicatore = max(1.0,float(vr[3] or 1))
            altri = int(vr[4] or 0)
            valore_altri = float(vr[5] or 0)

            if altri >= max_giocatori:
                raise ValueError("La rosa della squadra selezionata è completa.")

            nuova_spesa = float(_spesa_effettiva_regole(
                valore_altri + prezzo,
                soglia,
                moltiplicatore
            ))
            if nuova_spesa > budget + 1e-9:
                raise ValueError("Budget insufficiente per la correzione.")

        # Una correzione manuale dello storico sostituisce qualunque
        # precedente stato SVINCOLATO del giocatore.
        cur.execute("""
            DELETE FROM auction_release_costs
            WHERE league_id=? AND player_id=?
        """, (league_id,player_id))

        # Rimuove eventuale roster precedente.
        cur.execute("""
            DELETE FROM rosters
            WHERE league_id=? AND player_id=?
        """, (league_id,player_id))

        if new_team_id is None:
            cur.execute("""
                INSERT INTO league_players (
                    league_id,player_id,stato,
                    assigned_team_id,prezzo_assegnazione,updated_at
                )
                VALUES (?,?,'DISPONIBILE',NULL,NULL,CURRENT_TIMESTAMP)
                ON CONFLICT(league_id,player_id)
                DO UPDATE SET
                    stato='DISPONIBILE',
                    assigned_team_id=NULL,
                    prezzo_assegnazione=NULL,
                    updated_at=CURRENT_TIMESTAMP
            """, (league_id,player_id))
        else:
            cur.execute("""
                INSERT INTO league_players (
                    league_id,player_id,stato,
                    assigned_team_id,prezzo_assegnazione,updated_at
                )
                VALUES (?,?,'ASSEGNATO',?,?,CURRENT_TIMESTAMP)
                ON CONFLICT(league_id,player_id)
                DO UPDATE SET
                    stato='ASSEGNATO',
                    assigned_team_id=excluded.assigned_team_id,
                    prezzo_assegnazione=excluded.prezzo_assegnazione,
                    updated_at=CURRENT_TIMESTAMP
            """, (
                league_id,player_id,new_team_id,prezzo
            ))

            cur.execute("""
                INSERT INTO rosters (
                    league_id,team_id,player_id,prezzo_acquisto,
                    fonte,assigned_at,updated_at
                )
                VALUES (?,?,?,?,'AUCTION_HISTORY_EDIT',
                        CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
                ON CONFLICT(league_id,team_id,player_id)
                DO UPDATE SET
                    prezzo_acquisto=excluded.prezzo_acquisto,
                    fonte='AUCTION_HISTORY_EDIT',
                    updated_at=CURRENT_TIMESTAMP
            """, (
                league_id,new_team_id,player_id,prezzo
            ))

        # Aggiorna l'ultimo lotto storico del giocatore.
        cur.execute("""
            SELECT id
            FROM auction_lots
            WHERE league_id=? AND player_id=?
            ORDER BY id DESC
            LIMIT 1
        """, (league_id,player_id))
        lr = cur.fetchone()
        if lr:
            latest_lot_id = int(lr[0])
            if new_team_id is None:
                cur.execute("""
                    UPDATE auction_lots
                    SET stato='CLOSED',
                        assigned_team_id=NULL,
                        final_price=NULL,
                        closed_at=COALESCE(closed_at,CURRENT_TIMESTAMP)
                    WHERE id=? AND league_id=?
                """, (latest_lot_id,league_id))
            else:
                cur.execute("""
                    UPDATE auction_lots
                    SET stato='ASSIGNED',
                        assigned_team_id=?,
                        final_price=?,
                        closed_at=COALESCE(closed_at,CURRENT_TIMESTAMP)
                    WHERE id=? AND league_id=?
                """, (
                    new_team_id,prezzo,latest_lot_id,league_id
                ))

        # Storico assegnazioni: chiude i record precedenti e crea la correzione.
        cur.execute("""
            UPDATE auction_assignment_history
            SET stato='CORRECTED',
                undone_by_user_id=?,
                undone_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND player_id=? AND stato='ACTIVE'
        """, (user_id,league_id,player_id))

        if new_team_id is not None:
            cur.execute("""
                INSERT INTO auction_assignment_history (
                    league_id,player_id,team_id,prezzo,stato,
                    assigned_by_user_id,assigned_at
                )
                VALUES (?,?,?,?,'ACTIVE',?,CURRENT_TIMESTAMP)
            """, (
                league_id,player_id,new_team_id,prezzo,user_id
            ))

        # Ricalcola budget delle squadre coinvolte.
        team_da_ricalcolare = {
            x for x in (old_team_id,new_team_id)
            if x is not None
        }
        for tid in team_da_ricalcolare:
            _ricalcola_budget_team_v147(cur,league_id,tid)

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,team_id,azione,
                entita,entita_id,dettagli_json,created_at
            )
            VALUES (?,?,?,'AUCTION_HISTORY_EDIT','PLAYER',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,user_id,new_team_id,str(player_id),
            json.dumps({
                "old_team_id": old_team_id,
                "old_price": old_prezzo,
                "new_team_id": new_team_id,
                "new_price": prezzo,
            }, ensure_ascii=False)
        ))

        conn.commit()
        return True
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)



def azione_storico_rosa_v149(league_id, player_id, azione):
    """
    SVINCOLA:
      rimuove dalla rosa e mantiene il costo sostenuto.

    ELIMINA:
      rimuove dalla rosa e restituisce integralmente il costo.
    """
    league_id = int(league_id)
    player_id = int(player_id)
    azione = str(azione or "").strip().upper()
    if azione not in ("SVINCOLA","ELIMINA"):
        raise ValueError("Azione non valida.")

    assicura_schema_movimenti_rosa_v149(league_id)

    user_id = int(st.session_state.get("auth_user_id") or 0)
    conn = _portal_raw_connection()
    cur = conn.cursor()

    try:
        # V163 - un solo round-trip remoto per autorizzazione + stato giocatore.
        cur.execute("""
            SELECT
                EXISTS(
                    SELECT 1
                    FROM league_members lm
                    WHERE lm.league_id=? AND lm.user_id=? AND lm.is_active=1
                      AND (lm.is_auctioneer=1 OR lm.is_admin=1)
                ) AS allowed,
                lp.assigned_team_id,
                lp.prezzo_assegnazione,
                COALESCE(t.nome,'')
            FROM league_players lp
            LEFT JOIN teams t
              ON t.league_id=lp.league_id
             AND t.id=lp.assigned_team_id
            WHERE lp.league_id=?
              AND lp.player_id=?
              AND lp.stato='ASSEGNATO'
            LIMIT 1
        """, (league_id,user_id,league_id,player_id))
        old = cur.fetchone()

        if not old:
            raise ValueError("Il giocatore non risulta attualmente assegnato.")
        if not bool(old[0]):
            raise PermissionError("Operazione riservata al Banditore/Admin.")

        team_id = int(old[1])
        prezzo = float(old[2] or 0)
        team_nome = str(old[3] or "")

        # Rimuove la proiezione rosa.
        cur.execute("""
            DELETE FROM rosters
            WHERE league_id=? AND player_id=?
        """, (league_id,player_id))

        # Il giocatore torna disponibile in entrambi i casi.
        cur.execute("""
            UPDATE league_players
            SET stato='DISPONIBILE',
                assigned_team_id=NULL,
                prezzo_assegnazione=NULL,
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND player_id=?
        """, (league_id,player_id))

        if azione == "SVINCOLA":
            # Il costo resta definitivamente a carico della vecchia squadra.
            cur.execute("""
                INSERT INTO auction_release_costs (
                    league_id,team_id,player_id,costo,active,
                    created_by_user_id,created_at,updated_at
                )
                VALUES (?,?,?,?,1,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
                ON CONFLICT(league_id,player_id)
                DO UPDATE SET
                    team_id=excluded.team_id,
                    costo=excluded.costo,
                    active=1,
                    created_by_user_id=excluded.created_by_user_id,
                    updated_at=CURRENT_TIMESTAMP
            """, (
                league_id,team_id,player_id,prezzo,user_id
            ))
        else:
            # ELIMINA = rimborso totale.
            cur.execute("""
                DELETE FROM auction_release_costs
                WHERE league_id=? AND player_id=?
            """, (league_id,player_id))

            # V189 - ELIMINA dallo Storico significa anche "nuovamente chiamabile".
            # Se il giocatore era stato skippato in precedenza, togliamo quel blocco.
            cur.execute("""
                SELECT COALESCE(skipped_players_json,'[]')
                FROM auction_mode_state
                WHERE league_id=?
                LIMIT 1
            """, (league_id,))
            _sr = cur.fetchone()
            try:
                _sk = {int(x) for x in json.loads(_sr[0] if _sr else '[]')}
            except Exception:
                _sk = set()
            if player_id in _sk:
                _sk.discard(player_id)
                cur.execute("""
                    UPDATE auction_mode_state
                    SET skipped_players_json=?,
                        updated_at=CURRENT_TIMESTAMP
                    WHERE league_id=?
                """, (json.dumps(sorted(_sk)), league_id))

        # Storico assegnazione non più attivo.
        cur.execute("""
            UPDATE auction_assignment_history
            SET stato=?,
                undone_by_user_id=?,
                undone_at=CURRENT_TIMESTAMP
            WHERE league_id=?
              AND player_id=?
              AND stato='ACTIVE'
        """, (
            "RELEASED" if azione=="SVINCOLA" else "DELETED",
            user_id,league_id,player_id
        ))

        # V163 - non tocchiamo più auction_lots né active della chiamata qui.
        # L'esclusione autorevole sottostante è sufficiente a rimuovere subito
        # il giocatore da tabella e counter; una nuova chiamata cancella
        # l'esclusione e lo rende nuovamente visibile. Due scritture remote in meno.

        # V162 - esclusione persistente e autorevole dallo Storico Asta.
        # Anche se in futuro viene rieseguito un backfill dei vecchi lotti,
        # tabella e counter continueranno a ignorare questo giocatore finche'
        # non viene chiamato nuovamente.
        cur.execute("""
            INSERT INTO auction_history_exclusions (
                league_id, player_id, reason, excluded_by_user_id, excluded_at
            )
            VALUES (?,?,?,?,CURRENT_TIMESTAMP)
            ON CONFLICT(league_id,player_id)
            DO UPDATE SET
                reason=excluded.reason,
                excluded_by_user_id=excluded.excluded_by_user_id,
                excluded_at=CURRENT_TIMESTAMP
        """, (
            league_id, player_id, azione, user_id
        ))

        _ricalcola_budget_team_v147(cur,league_id,team_id)

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,team_id,azione,
                entita,entita_id,dettagli_json,created_at
            )
            VALUES (?,?,?,?, 'PLAYER',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,user_id,team_id,
            "PLAYER_RELEASED" if azione=="SVINCOLA" else "PLAYER_DELETED",
            str(player_id),
            json.dumps({
                "team": team_nome,
                "prezzo": prezzo,
                "rimborso": 0 if azione=="SVINCOLA" else prezzo
            }, ensure_ascii=False)
        ))

        conn.commit()

        # V163 - aggiorna in RAM Storico e counter senza rileggerli dal DB.
        # Il database è già stato commit-tato; questa patch evita due round-trip
        # remoti subito dopo SVINCOLA/ELIMINA.
        _hk = f"_v156_history_{league_id}"
        _hc = st.session_state.get(_hk)
        if isinstance(_hc, dict) and isinstance(_hc.get("df"), pd.DataFrame):
            _hdf = _hc["df"].copy()
            if "__PLAYER_ID" in _hdf.columns:
                _hdf = _hdf[_hdf["__PLAYER_ID"] != int(player_id)].copy()
            st.session_state[_hk] = {"ts": time.monotonic(), "df": _hdf}

        _ck = f"_v156_counter_{league_id}"
        _cc = st.session_state.get(_ck)
        if isinstance(_cc, dict) and isinstance(_cc.get("value"), tuple):
            try:
                _ch, _tot, _pct = _cc["value"]
                _ch = max(0, int(_ch) - 1)
                _pct = round((_ch / int(_tot)) * 100, 1) if int(_tot) > 0 else 0.0
                st.session_state[_ck] = {
                    "ts": time.monotonic(),
                    "value": (_ch, int(_tot), _pct),
                }
            except Exception:
                st.session_state.pop(_ck, None)

        # In Gestione Asta il giocatore è nuovamente disponibile: invalida solo
        # lo snapshot idle, non lo Storico appena aggiornato localmente.
        st.session_state.pop(f"_v156_idle_{league_id}", None)

        return {
            "team": team_nome,
            "prezzo": prezzo,
            "azione": azione
        }

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)




@st.dialog("Conferma svincolo")
def conferma_svincolo_storico_v151(
    league_id,
    player_id,
    nome_giocatore,
    squadra_nome,
    prezzo
):
    prezzo = float(prezzo or 0)

    st.write(
        f'Vuoi svincolare **{nome_giocatore}** '
        f'dalla rosa di **{squadra_nome}**?'
    )

    st.warning(
        f"Il giocatore tornerà disponibile, ma i "
        f"**{formatta_crediti(prezzo)}** spesi "
        f"resteranno conteggiati alla squadra."
    )

    c1, c2 = st.columns(2)

    with c1:
        if st.button(
            "CONFERMA SVINCOLO",
            type="primary",
            use_container_width=True,
            key=f"v151_confirm_release_{league_id}_{player_id}"
        ):
            try:
                azione_storico_rosa_v149(
                    int(league_id),
                    int(player_id),
                    "SVINCOLA"
                )
                st.session_state["v151_storico_msg"] = (
                    f"{nome_giocatore} svincolato. "
                    "Il costo resta a carico della squadra."
                )
                st.session_state.pop("v151_storico_error", None)
                try:
                    st.rerun(scope="app")
                except TypeError:
                    st.rerun()
            except Exception as errore:
                st.error(str(errore))

    with c2:
        if st.button(
            "ANNULLA",
            use_container_width=True,
            key=f"v151_cancel_release_{league_id}_{player_id}"
        ):
            st.rerun()


