def render_storico_asta_v147():
    if st.session_state.get("ml_modalita_accesso") != "BANDITORE":
        st.error("Accedi come BANDITORE per visualizzare lo storico asta.")
        return

    league_id = int(st.session_state.get("ml_league_id"))
    assicura_schema_storico_asta_v147(league_id)


    _storico_ctrl1, _storico_ctrl2, _storico_ctrl3 = st.columns(3)
    with _storico_ctrl1:
        if st.button(
            "⟳ AGGIORNA",
            use_container_width=True,
            key=f"v152_refresh_storico_asta_{league_id}"
        ):
            invalida_cache_dati()
            invalida_cache_banditore_v156(league_id)
            st.rerun()

    with _storico_ctrl2:
        if st.button(
            "♻️ RESET SPESE",
            use_container_width=True,
            key=f"v154_reset_expenses_history_open_{league_id}",
            
        ):
            dialog_reset_spese_asta_v153(league_id)

    with _storico_ctrl3:
        if st.button(
            "⚠️ RESET ASSEGNAZIONI",
            use_container_width=True,
            key=f"v179_reset_assignments_history_open_{league_id}",
            
        ):
            dialog_reset_assegnazioni_v179(league_id)

    if st.session_state.get("v154_storico_reset_msg"):
        st.success(st.session_state.pop("v154_storico_reset_msg"))

    if st.session_state.get("v179_storico_reset_assignments_msg"):
        st.success(st.session_state.pop("v179_storico_reset_assignments_msg"))

    if st.session_state.get("v151_storico_msg"):
        st.success(
            st.session_state.pop("v151_storico_msg")
        )

    if st.session_state.get("v151_storico_error"):
        st.error(
            st.session_state.pop("v151_storico_error")
        )

    # V164 PERFORMANCE MAX: una sola lettura autorevole dello storico.
    # Il numero dei chiamati coincide con le righe visibili dello storico, quindi
    # non eseguiamo piu' una seconda COUNT remota ad ogni apertura pagina.
    try:
        storico = storico_asta_v147(league_id)
        teams = squadre_storico_v147(league_id)
        _chiamati = int(len(storico))
        _totale = totale_giocatori_lega_fast_v164(league_id)
        _pct = round((_chiamati / _totale) * 100, 1) if _totale > 0 else 0.0

        _cc1, _cc2 = st.columns([1.2, 3.8])
        with _cc1:
            st.metric("CHIAMATI / TOTALE", f"{_chiamati} / {_totale}")
        with _cc2:
            st.markdown(f"**Chiamata completa al {_pct:g}%**")
            st.progress(min(1.0, max(0.0, _pct / 100.0)))
    except Exception as errore:
        st.error("Impossibile caricare lo storico asta: " + str(errore))
        return

    if storico.empty:
        st.info("Nessun giocatore ancora chiamato.")
        return

    nomi_team = ["—"] + [x["nome"] for x in teams]

    # ------------------------------------------------------------
    # V150 - ricerca e filtri storico asta
    # ------------------------------------------------------------
    f1, f2, f3, f4 = st.columns([3.2, 1.8, 1.8, 1.4])

    with f1:
        ricerca = st.text_input(
            "🔎 Cerca giocatore",
            placeholder="Nome giocatore...",
            key=f"v150_hist_search_{league_id}"
        ).strip()

    squadre_reali = sorted(
        {
            str(x).strip()
            for x in storico["SQUADRA"].dropna().tolist()
            if str(x).strip()
        },
        key=str.casefold
    )

    ruoli_storico = sorted(
        {
            str(x).strip()
            for x in storico["RUOLO"].dropna().tolist()
            if str(x).strip()
        },
        key=str.casefold
    )

    with f2:
        filtro_assegnato = st.selectbox(
            "Assegnato a",
            ["TUTTE"] + nomi_team,
            key=f"v150_hist_filter_team_{league_id}"
        )

    with f3:
        filtro_squadra = st.selectbox(
            "Squadra Serie A",
            ["TUTTE"] + squadre_reali,
            key=f"v150_hist_filter_realteam_{league_id}"
        )

    with f4:
        filtro_ruolo = st.selectbox(
            "Ruolo",
            ["TUTTI"] + ruoli_storico,
            key=f"v150_hist_filter_role_{league_id}"
        )

    storico_filtrato = storico.copy()

    if ricerca:
        _q = ricerca.casefold()
        storico_filtrato = storico_filtrato[
            storico_filtrato["NOME GIOCATORE"]
            .fillna("")
            .astype(str)
            .str.casefold()
            .str.contains(_q, regex=False)
        ]

    if filtro_assegnato != "TUTTE":
        if filtro_assegnato == "—":
            storico_filtrato = storico_filtrato[
                storico_filtrato["ASSEGNATO A"]
                .fillna("—")
                .astype(str)
                .replace("", "—")
                == "—"
            ]
        else:
            storico_filtrato = storico_filtrato[
                storico_filtrato["ASSEGNATO A"]
                .fillna("")
                .astype(str)
                == filtro_assegnato
            ]

    if filtro_squadra != "TUTTE":
        storico_filtrato = storico_filtrato[
            storico_filtrato["SQUADRA"]
            .fillna("")
            .astype(str)
            == filtro_squadra
        ]

    if filtro_ruolo != "TUTTI":
        storico_filtrato = storico_filtrato[
            storico_filtrato["RUOLO"]
            .fillna("")
            .astype(str)
            == filtro_ruolo
        ]

    if storico_filtrato.empty:
        st.info("Nessun giocatore corrisponde ai filtri selezionati.")
        return

    # Paginazione applicata DOPO ricerca e filtri.
    page_size = 15
    totale_righe = len(storico_filtrato)
    totale_pagine = max(1, (totale_righe + page_size - 1) // page_size)

    if totale_pagine > 1:
        pagina = st.number_input(
            "Pagina storico",
            min_value=1,
            max_value=totale_pagine,
            value=1,
            step=1,
            key=f"v149_hist_page_{league_id}"
        )
    else:
        pagina = 1

    start_idx = (int(pagina)-1) * page_size
    end_idx = min(start_idx + page_size, totale_righe)
    pagina_df = storico_filtrato.iloc[start_idx:end_idx].copy()

    st.caption(
        f"Visualizzati {start_idx+1}-{end_idx} di {totale_righe} "
        f"giocatori trovati."
    )

    hdr = st.columns([3.1,1.2,1.8,1.1,2.0,0.75,0.8,0.8])
    titoli = [
        "NOME GIOCATORE","RUOLO","SQUADRA","PREZZO",
        "ASSEGNATO A","SALVA","SVINCOLA","ELIMINA"
    ]
    for col,titolo in zip(hdr,titoli):
        col.markdown(f"**{titolo}**")

    for _, r in pagina_df.iterrows():
        player_id = int(r["__PLAYER_ID"])
        nome = str(r["NOME GIOCATORE"] or "")
        ruolo = str(r["RUOLO"] or "")
        squadra_reale = str(r["SQUADRA"] or "")
        prezzo = None if pd.isna(r["PREZZO"]) else float(r["PREZZO"])
        team_corrente = (
            str(r["ASSEGNATO A"])
            if pd.notna(r["ASSEGNATO A"]) and str(r["ASSEGNATO A"]).strip()
            else "—"
        )
        if team_corrente not in nomi_team:
            team_corrente = "—"

        cols = st.columns([3.1,1.2,1.8,1.1,2.0,0.75,0.8,0.8],
                          vertical_alignment="center")

        cols[0].write(nome)
        cols[1].write(ruolo)
        cols[2].write(squadra_reale)

        prezzo_key = f"v149_hist_price_{league_id}_{player_id}"
        team_key = f"v149_hist_team_{league_id}_{player_id}"

        if prezzo_key not in st.session_state:
            st.session_state[prezzo_key] = float(prezzo or 0)
        if team_key not in st.session_state:
            st.session_state[team_key] = team_corrente

        with cols[3]:
            st.number_input(
                "Prezzo",
                min_value=0.0,
                step=1.0,
                key=prezzo_key,
                label_visibility="collapsed"
            )

        with cols[4]:
            st.selectbox(
                "Assegnato a",
                options=nomi_team,
                key=team_key,
                label_visibility="collapsed"
            )

        nuovo_prezzo = float(st.session_state.get(prezzo_key,0))
        nuovo_team = str(st.session_state.get(team_key,"—"))

        changed = (
            nuovo_team != team_corrente
            or abs(nuovo_prezzo - float(prezzo or 0)) > 0.0001
        )

        with cols[5]:
            if st.button(
                "✓",
                key=f"v149_save_{league_id}_{player_id}",
                
                disabled=not changed,
                use_container_width=True
            ):
                try:
                    modifica_assegnazione_storico_v147(
                        league_id,player_id,nuovo_team,nuovo_prezzo
                    )
                    st.success(f"Modificato {nome}.")
                    st.rerun()
                except Exception as errore:
                    st.error(f"{nome}: {errore}")

        assegnato = team_corrente != "—"

        with cols[6]:
            if st.button(
                "🔓",
                key=f"v151_release_{league_id}_{player_id}",
                
                disabled=not assegnato,
                use_container_width=True
            ):
                conferma_svincolo_storico_v151(
                    league_id,
                    player_id,
                    nome,
                    team_corrente,
                    float(prezzo or 0)
                )

        with cols[7]:
            if st.button(
                "🗑️",
                key=f"v151_delete_{league_id}_{player_id}",
                
                disabled=not assegnato,
                use_container_width=True
            ):
                conferma_elimina_storico_v151(
                    league_id,
                    player_id,
                    nome,
                    team_corrente,
                    float(prezzo or 0)
                )



def assicura_fastpath_asta_v293(league_id):
    """
    V293 - installazione una tantum dei trigger server-side per OPEN/ASSIGN.
    Il costo di setup viene pagato al caricamento della console Banditore,
    non al click di apertura/chiusura.
    """
    league_id=int(league_id)
    guard=f"_v293_fastpath_ready_{league_id}"
    if st.session_state.get(guard):
        return

    # Garantisce le tabelle usate dai trigger prima della loro creazione.
    assicura_schema_storico_asta_v147(league_id)
    assicura_schema_movimenti_rosa_v149(league_id)

    conn=_portal_raw_connection()
    cur=conn.cursor()
    try:
        cur.execute("""
            CREATE TRIGGER IF NOT EXISTS trg_v293_lot_open
            AFTER INSERT ON auction_lots
            WHEN UPPER(COALESCE(NEW.stato,''))='OPEN'
            BEGIN
                DELETE FROM auction_history_exclusions
                WHERE league_id=NEW.league_id AND player_id=NEW.player_id;

                INSERT INTO auction_called_players (
                    league_id,player_id,fonte,lot_id,
                    called_by_user_id,called_at,updated_at,active
                )
                VALUES (
                    NEW.league_id,NEW.player_id,'LOT',NEW.id,
                    NEW.opened_by_user_id,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1
                )
                ON CONFLICT(league_id,player_id)
                DO UPDATE SET
                    fonte='LOT',
                    lot_id=excluded.lot_id,
                    called_by_user_id=excluded.called_by_user_id,
                    active=1,
                    called_at=CURRENT_TIMESTAMP,
                    updated_at=CURRENT_TIMESTAMP;

                INSERT INTO auction_sessions (
                    league_id,stato,current_lot_id,started_by_user_id,
                    started_at,updated_at
                )
                VALUES (
                    NEW.league_id,'RUNNING',NEW.id,NEW.opened_by_user_id,
                    CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
                )
                ON CONFLICT(league_id) DO UPDATE SET
                    stato='RUNNING',
                    current_lot_id=excluded.current_lot_id,
                    started_by_user_id=excluded.started_by_user_id,
                    started_at=COALESCE(auction_sessions.started_at,CURRENT_TIMESTAMP),
                    updated_at=CURRENT_TIMESTAMP;

                INSERT INTO audit_log (
                    league_id,user_id,azione,entita,entita_id,dettagli_json,created_at
                )
                VALUES (
                    NEW.league_id,NEW.opened_by_user_id,'LOT_OPENED',
                    'AUCTION_LOT',CAST(NEW.id AS TEXT),
                    '{"player_id":'||CAST(NEW.player_id AS TEXT)||'}',
                    CURRENT_TIMESTAMP
                );
            END
        """)

        cur.execute("""
            CREATE TRIGGER IF NOT EXISTS trg_v293_lot_assigned
            AFTER UPDATE OF stato ON auction_lots
            WHEN UPPER(COALESCE(OLD.stato,''))='OPEN'
             AND UPPER(COALESCE(NEW.stato,''))='ASSIGNED'
            BEGIN
                INSERT INTO league_players (
                    league_id,player_id,stato,
                    assigned_team_id,prezzo_assegnazione,updated_at
                )
                VALUES (
                    NEW.league_id,NEW.player_id,'ASSEGNATO',
                    NEW.assigned_team_id,NEW.final_price,CURRENT_TIMESTAMP
                )
                ON CONFLICT(league_id,player_id)
                DO UPDATE SET
                    stato='ASSEGNATO',
                    assigned_team_id=excluded.assigned_team_id,
                    prezzo_assegnazione=excluded.prezzo_assegnazione,
                    updated_at=CURRENT_TIMESTAMP;

                INSERT INTO rosters (
                    league_id,team_id,player_id,prezzo_acquisto,
                    fonte,assigned_at,updated_at
                )
                VALUES (
                    NEW.league_id,NEW.assigned_team_id,NEW.player_id,NEW.final_price,
                    'AUCTION_FINAL',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
                )
                ON CONFLICT(league_id,team_id,player_id)
                DO UPDATE SET
                    prezzo_acquisto=excluded.prezzo_acquisto,
                    fonte='AUCTION_FINAL',
                    updated_at=CURRENT_TIMESTAMP;

                INSERT INTO team_budgets (
                    league_id,team_id,budget_impostato,
                    valore_acquisti,spesa_effettiva,updated_at
                )
                SELECT
                    NEW.league_id,
                    NEW.assigned_team_id,
                    COALESCE(tb.budget_impostato,r.budget_iniziale,500),
                    x.valore,
                    CASE
                        WHEN x.valore <= COALESCE(r.soglia_budget,r.budget_iniziale,500)
                        THEN x.valore
                        ELSE COALESCE(r.soglia_budget,r.budget_iniziale,500)
                             +(x.valore-COALESCE(r.soglia_budget,r.budget_iniziale,500))
                              *COALESCE(r.moltiplicatore_oltre_soglia,1)
                    END,
                    CURRENT_TIMESTAMP
                FROM league_rules r
                LEFT JOIN team_budgets tb
                  ON tb.league_id=r.league_id
                 AND tb.team_id=NEW.assigned_team_id
                CROSS JOIN (
                    SELECT
                        COALESCE((
                            SELECT SUM(COALESCE(prezzo_assegnazione,0))
                            FROM league_players
                            WHERE league_id=NEW.league_id
                              AND stato='ASSEGNATO'
                              AND assigned_team_id=NEW.assigned_team_id
                        ),0)
                        +
                        COALESCE((
                            SELECT SUM(COALESCE(costo,0))
                            FROM auction_release_costs
                            WHERE league_id=NEW.league_id
                              AND team_id=NEW.assigned_team_id
                              AND active=1
                        ),0) AS valore
                ) x
                WHERE r.league_id=NEW.league_id
                ON CONFLICT(league_id,team_id)
                DO UPDATE SET
                    valore_acquisti=excluded.valore_acquisti,
                    spesa_effettiva=excluded.spesa_effettiva,
                    updated_at=CURRENT_TIMESTAMP;

                INSERT INTO auction_assignment_history (
                    league_id,player_id,team_id,prezzo,stato,
                    assigned_by_user_id,assigned_at
                )
                VALUES (
                    NEW.league_id,NEW.player_id,NEW.assigned_team_id,
                    NEW.final_price,'ACTIVE',NEW.closing_by_user_id,CURRENT_TIMESTAMP
                );

                UPDATE auction_sessions
                SET current_lot_id=NULL,
                    stato='READY',
                    updated_at=CURRENT_TIMESTAMP
                WHERE league_id=NEW.league_id AND current_lot_id=NEW.id;

                INSERT INTO audit_log (
                    league_id,user_id,team_id,azione,
                    entita,entita_id,dettagli_json,created_at
                )
                VALUES (
                    NEW.league_id,NEW.closing_by_user_id,NEW.assigned_team_id,
                    'PLAYER_ASSIGNED','PLAYER',CAST(NEW.player_id AS TEXT),
                    '{"prezzo":'||CAST(NEW.final_price AS TEXT)
                    ||',"lot_id":'||CAST(NEW.id AS TEXT)
                    ||',"modalita":"FAST_CLOSE_V293"}',
                    CURRENT_TIMESTAMP
                );
            END
        """)
        conn.commit()
        st.session_state[guard]=True
    finally:
        _portal_close(conn)


def apri_lotto_banditore(league_id, player_id):
    """V293 - apertura lotto: 1 statement remoto + commit sul percorso OK."""
    league_id=int(league_id); player_id=int(player_id)
    user_id=int(st.session_state.get("auth_user_id") or 0)
    assicura_fastpath_asta_v293(league_id)

    conn=_portal_raw_connection(); cur=conn.cursor()
    try:
        cur.execute("""
            INSERT INTO auction_lots (
                league_id,player_id,stato,opened_by_user_id,opened_at,
                current_bid,current_team_id,bid_count,version,
                bid_deadline_ts,auto_assign_claimed
            )
            SELECT ?,?,'OPEN',?,CURRENT_TIMESTAMP,NULL,NULL,0,0,NULL,0
            WHERE EXISTS (
                SELECT 1 FROM league_members
                WHERE league_id=? AND user_id=? AND is_active=1
                  AND (is_auctioneer=1 OR is_admin=1)
            )
              AND EXISTS (
                SELECT 1 FROM league_players
                WHERE league_id=? AND player_id=? AND stato='DISPONIBILE'
            )
              AND NOT EXISTS (
                SELECT 1
                FROM auction_sessions s
                JOIN auction_lots l ON l.id=s.current_lot_id
                WHERE s.league_id=?
                  AND UPPER(COALESCE(l.stato,'')) IN ('OPEN','CLOSING')
            )
            RETURNING id
        """,(
            league_id,player_id,user_id,
            league_id,user_id,
            league_id,player_id,
            league_id
        ))
        row=cur.fetchone()
        if not row:
            # Diagnostica solo sul percorso di errore: non rallenta l'apertura normale.
            cur.execute("""
                SELECT
                    EXISTS(SELECT 1 FROM league_members
                           WHERE league_id=? AND user_id=? AND is_active=1
                             AND (is_auctioneer=1 OR is_admin=1)),
                    (SELECT UPPER(COALESCE(stato,'')) FROM league_players
                     WHERE league_id=? AND player_id=? LIMIT 1),
                    EXISTS(
                        SELECT 1 FROM auction_sessions s
                        JOIN auction_lots l ON l.id=s.current_lot_id
                        WHERE s.league_id=?
                          AND UPPER(COALESCE(l.stato,'')) IN ('OPEN','CLOSING')
                    )
            """,(league_id,user_id,league_id,player_id,league_id))
            chk=cur.fetchone() or (0,None,0)
            if not bool(chk[0]):
                raise PermissionError("Operazione riservata a Banditore o Admin.")
            if chk[1] is None:
                raise ValueError("Giocatore non presente nel listone della lega.")
            if str(chk[1]).upper()!="DISPONIBILE":
                raise ValueError("Il giocatore non è disponibile.")
            if bool(chk[2]):
                raise ValueError("Esiste già un lotto attivo. Devi completarlo prima di aprirne un altro.")
            raise RuntimeError("Impossibile creare il lotto.")

        lot_id=int(row[0])
        conn.commit()
        return lot_id
    except Exception:
        try: conn.rollback()
        except Exception: pass
        raise
    finally:
        _portal_close(conn)



def metti_lotto_in_chiusura_banditore(league_id, lot_id):
    """V125 - OPEN -> CLOSING ottimizzato."""
    league_id=int(league_id); lot_id=int(lot_id)
    user_id=int(st.session_state.get("auth_user_id") or 0)
    conn=_portal_raw_connection(); cur=conn.cursor()
    try:
        cur.execute("""
            UPDATE auction_lots
            SET stato='CLOSING',closing_by_user_id=?,closing_at=CURRENT_TIMESTAMP
            WHERE id=? AND league_id=? AND stato='OPEN'
              AND EXISTS (
                  SELECT 1 FROM league_members
                  WHERE league_id=? AND user_id=? AND is_active=1
                    AND (is_auctioneer=1 OR is_admin=1)
              )
            RETURNING id
        """,(user_id,lot_id,league_id,league_id,user_id))
        if not cur.fetchone():
            raise ValueError("Lotto non più OPEN oppure utente non autorizzato.")

        cur.execute("""
            UPDATE auction_sessions
            SET stato='CLOSING',updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND current_lot_id=?
        """,(league_id,lot_id))
        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,azione,entita,entita_id,dettagli_json,created_at
            )
            VALUES (?,?,'LOT_CLOSING','AUCTION_LOT',?,?,CURRENT_TIMESTAMP)
        """,(league_id,user_id,str(lot_id),
             json.dumps({"stato":"CLOSING"},ensure_ascii=False)))
        conn.commit(); return True
    except Exception:
        try: conn.rollback()
        except Exception: pass
        raise
    finally:
        _portal_close(conn)




def riapri_lotto_banditore(league_id, lot_id):
    """V125 - CLOSING -> OPEN ottimizzato."""
    league_id=int(league_id); lot_id=int(lot_id)
    user_id=int(st.session_state.get("auth_user_id") or 0)
    conn=_portal_raw_connection(); cur=conn.cursor()
    try:
        cur.execute("""
            UPDATE auction_lots
            SET stato='OPEN',closing_by_user_id=NULL,closing_at=NULL
            WHERE id=? AND league_id=? AND stato='CLOSING'
              AND EXISTS (
                  SELECT 1 FROM league_members
                  WHERE league_id=? AND user_id=? AND is_active=1
                    AND (is_auctioneer=1 OR is_admin=1)
              )
            RETURNING id
        """,(lot_id,league_id,league_id,user_id))
        if not cur.fetchone():
            raise ValueError("Lotto non in CLOSING oppure utente non autorizzato.")

        cur.execute("""
            UPDATE auction_sessions
            SET stato='RUNNING',updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND current_lot_id=?
        """,(league_id,lot_id))
        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,azione,entita,entita_id,dettagli_json,created_at
            )
            VALUES (?,?,'LOT_REOPENED','AUCTION_LOT',?,?,CURRENT_TIMESTAMP)
        """,(league_id,user_id,str(lot_id),
             json.dumps({"stato":"OPEN"},ensure_ascii=False)))
        conn.commit(); return True
    except Exception:
        try: conn.rollback()
        except Exception: pass
        raise
    finally:
        _portal_close(conn)




def chiudi_lotto_banditore(league_id, lot_id, motivo="CLOSED"):
    """V125 - chiusura lotto senza offerte ottimizzata."""
    league_id=int(league_id); lot_id=int(lot_id)
    user_id=int(st.session_state.get("auth_user_id") or 0)
    conn=_portal_raw_connection(); cur=conn.cursor()
    try:
        cur.execute("""
            UPDATE auction_lots
            SET stato=?,closed_at=CURRENT_TIMESTAMP
            WHERE id=? AND league_id=?
              AND stato IN ('OPEN','CLOSING')
              AND COALESCE(bid_count,0)=0
              AND EXISTS (
                  SELECT 1 FROM league_members
                  WHERE league_id=? AND user_id=? AND is_active=1
                    AND (is_auctioneer=1 OR is_admin=1)
              )
            RETURNING id
        """,(str(motivo),lot_id,league_id,league_id,user_id))
        if not cur.fetchone():
            raise ValueError(
                "Il lotto non può essere chiuso: potrebbe contenere offerte, "
                "essere già chiuso oppure l'utente non è autorizzato."
            )

        cur.execute("""
            UPDATE auction_sessions
            SET current_lot_id=NULL,stato='READY',updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND current_lot_id=?
        """,(league_id,lot_id))
        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,azione,entita,entita_id,dettagli_json,created_at
            )
            VALUES (?,?,'LOT_CLOSED','AUCTION_LOT',?,?,CURRENT_TIMESTAMP)
        """,(league_id,user_id,str(lot_id),
             json.dumps({"stato":str(motivo)},ensure_ascii=False)))
        conn.commit(); return True
    except Exception:
        try: conn.rollback()
        except Exception: pass
        raise
    finally:
        _portal_close(conn)




def sincronizza_workspace_team_da_normalizzato(league_id, team_id):
    """
    V108: riallinea il workspace compatibile della squadra con le tabelle
    normalizzate autorevoli (rosters / team_budgets).

    È best-effort: se il workspace non è ancora stato creato, il dato centrale
    resta comunque corretto e verrà sincronizzato quando il team aprirà l'app.
    """
    league_id=int(league_id)
    team_id=int(team_id)
    tab_team="giocatori_ml_l"+str(league_id)+"_t"+str(team_id)
    tab_conf="configurazione_app_ml_l"+str(league_id)+"_t"+str(team_id)

    conn=_portal_raw_connection()
    cur=conn.cursor()
    try:
        # Verifica esistenza tabella giocatori del workspace.
        cur.execute("""
            SELECT name
            FROM sqlite_master
            WHERE type='table' AND name=?
            LIMIT 1
        """,(tab_team,))
        if not cur.fetchone():
            return False

        # Il workspace è una proiezione: prima libera gli stati di acquisto
        # locali, poi riapplica la rosa normalizzata.
        try:
            cur.execute(
                f"""
                UPDATE {tab_team}
                SET stato='DISPONIBILE',
                    prezzo_acquisto=NULL
                WHERE UPPER(COALESCE(stato,''))='MIO'
                """
            )
        except Exception:
            pass

        cur.execute("""
            SELECT player_id, prezzo_acquisto
            FROM rosters
            WHERE league_id=? AND team_id=?
        """,(league_id,team_id))

        for player_id, prezzo in (cur.fetchall() or []):
            try:
                cur.execute(
                    f"""
                    UPDATE {tab_team}
                    SET stato='MIO',
                        prezzo_acquisto=?,
                        ultimo_aggiornamento=CURRENT_TIMESTAMP
                    WHERE id=?
                    """,
                    (float(prezzo or 0),int(player_id))
                )
            except Exception:
                pass

        # Sincronizza anche il budget locale se la tabella/configurazione
        # compatibile è già presente. Le colonne possono variare tra versioni,
        # quindi la scrittura resta volutamente best-effort.
        cur.execute("""
            SELECT
                COALESCE(b.budget_impostato,r.budget_iniziale,500),
                COALESCE(b.valore_acquisti,0),
                COALESCE(b.spesa_effettiva,0)
            FROM teams t
            LEFT JOIN league_rules r ON r.league_id=t.league_id
            LEFT JOIN team_budgets b
              ON b.league_id=t.league_id AND b.team_id=t.id
            WHERE t.league_id=? AND t.id=?
            LIMIT 1
        """,(league_id,team_id))
        rb=cur.fetchone()

        if rb:
            try:
                cur.execute("""
                    SELECT name
                    FROM sqlite_master
                    WHERE type='table' AND name=?
                    LIMIT 1
                """,(tab_conf,))
                if cur.fetchone():
                    cur.execute(f"PRAGMA table_info({tab_conf})")
                    cols={str(r[1]) for r in (cur.fetchall() or [])}

                    aggiornamenti=[]
                    valori=[]

                    for nome_col,valore in (
                        ("budget",float(rb[0] or 0)),
                        ("budget_impostato",float(rb[0] or 0)),
                        ("valore_acquisti",float(rb[1] or 0)),
                        ("spesa_effettiva",float(rb[2] or 0)),
                    ):
                        if nome_col in cols:
                            aggiornamenti.append(nome_col+"=?")
                            valori.append(valore)

                    if aggiornamenti:
                        cur.execute(
                            f"UPDATE {tab_conf} SET "+",".join(aggiornamenti),
                            tuple(valori)
                        )
            except Exception:
                pass

        conn.commit()
        return True
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        _portal_close(conn)


def sincronizza_workspace_corrente_team():
    league_id=st.session_state.get("ml_league_id")
    team_id=st.session_state.get("ml_team_id")
    if league_id is None or team_id is None:
        return False
    return sincronizza_workspace_team_da_normalizzato(
        int(league_id),int(team_id)
    )



def situazione_team_corrente_multilega(league_id, team_id):
    """
    V124 - situazione team live.
    Fonte autorevole: league_players, non rosters legacy/compatibility.
    """
    league_id = int(league_id)
    team_id = int(team_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT
                COALESCE(t.nome,''),
                COALESCE(b.budget_impostato,r.budget_iniziale,500),
                COALESCE(r.max_giocatori,30),
                COALESCE(r.soglia_budget,r.budget_iniziale,500),
                COALESCE(r.moltiplicatore_oltre_soglia,1),
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=t.id
                        THEN COALESCE(lp.prezzo_assegnazione,0)
                        ELSE 0
                    END
                ),0),
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=t.id
                        THEN 1 ELSE 0
                    END
                ),0)
            FROM teams t
            LEFT JOIN league_rules r
              ON r.league_id=t.league_id
            LEFT JOIN team_budgets b
              ON b.league_id=t.league_id
             AND b.team_id=t.id
            LEFT JOIN league_players lp
              ON lp.league_id=t.league_id
             AND lp.assigned_team_id=t.id
             AND lp.stato='ASSEGNATO'
            WHERE t.league_id=? AND t.id=? AND t.is_active=1
            GROUP BY
                t.id,t.nome,b.budget_impostato,
                r.budget_iniziale,r.max_giocatori,
                r.soglia_budget,r.moltiplicatore_oltre_soglia
            LIMIT 1
        """, (league_id, team_id))
        r = cur.fetchone()
        if not r:
            return None

        budget = float(r[1] or 0)
        max_giocatori = int(r[2] or 30)
        soglia = float(r[3] or budget)
        moltiplicatore = max(1.0, float(r[4] or 1))
        valore = float(r[5] or 0)
        giocatori = int(r[6] or 0)

        spesa = float(
            _spesa_effettiva_regole(
                valore,
                soglia,
                moltiplicatore
            )
        )

        return {
            "nome": str(r[0] or ""),
            "budget": budget,
            "valore_acquisti": valore,
            "spesa_effettiva": spesa,
            "residuo": round(budget - spesa, 2),
            "max_giocatori": max_giocatori,
            "giocatori": giocatori,
        }
    finally:
        _portal_close(conn)




def regole_bidding_multilega(league_id):
    """V124 - regole bidding complete in una singola lettura."""
    league_id = int(league_id)
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT
                COALESCE(incremento_minimo,1),
                COALESCE(max_giocatori,30),
                COALESCE(min_portieri,0),
                COALESCE(budget_iniziale,500),
                COALESCE(soglia_budget,budget_iniziale,500),
                COALESCE(moltiplicatore_oltre_soglia,1),
                COALESCE(tipo_asta,'CHIAMATA'),
                COALESCE(budget_illimitato,0),
                COALESCE(fair_play_finanziario,0)
            FROM league_rules
            WHERE league_id=?
            LIMIT 1
        """, (league_id,))
        r = cur.fetchone()

        if not r:
            return {
                "incremento": 1.0,
                "max_giocatori": 30,
                "min_portieri": 0,
                "budget": 500.0,
                "soglia": 500.0,
                "moltiplicatore": 1.0,
                "tipo_asta": "CHIAMATA",
            }

        raw_tipo = str(r[6] or "CHIAMATA").strip().upper()
        aliases = {
            "A CHIAMATA": "CHIAMATA",
            "CHIAMATA": "CHIAMATA",
            "ALFABETICO": "ALFABETICO",
            "RANDOM": "RANDOM",
            "CASUALE": "RANDOM",
            "DRAFT": "DRAFT",
        }

        return {
            "incremento": max(0.01, float(r[0] or 1)),
            "max_giocatori": int(r[1] or 30),
            "min_portieri": int(r[2] or 0),
            "budget": float(r[3] or 500),
            "soglia": float(r[4] or r[3] or 500),
            "moltiplicatore": max(1.0, float(r[5] or 1)),
            "tipo_asta": aliases.get(raw_tipo, raw_tipo),
        }
    finally:
        _portal_close(conn)




def stato_offerte_lotto_multilega(
    league_id,
    lot_id,
    limit=20,
    include_history=False
):
    """
    V124 - stato bidding leggero.
    Per il rendering standard legge solo il record autorevole auction_lots.
    Lo storico bids viene caricato solo su richiesta.
    """
    league_id = int(league_id)
    lot_id = int(lot_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT
                l.current_bid,
                l.current_team_id,
                COALESCE(t.nome,''),
                COALESCE(l.bid_count,0),
                COALESCE(l.version,0),
                l.stato
            FROM auction_lots l
            LEFT JOIN teams t
              ON t.id=l.current_team_id
             AND t.league_id=l.league_id
            WHERE l.league_id=? AND l.id=?
            LIMIT 1
        """, (league_id, lot_id))
        stato = cur.fetchone()

        migliore = None
        if stato and stato[0] is not None and stato[1] is not None:
            migliore = {
                "team_id": int(stato[1]),
                "team": str(stato[2] or ""),
                "amount": float(stato[0]),
                "version": int(stato[4] or 0),
            }

        bids = []
        if include_history:
            cur.execute("""
                SELECT
                    b.id,
                    b.team_id,
                    COALESCE(t.nome,''),
                    b.user_id,
                    COALESCE(u.username,''),
                    b.amount,
                    b.created_at
                FROM bids b
                LEFT JOIN teams t
                  ON t.id=b.team_id AND t.league_id=b.league_id
                LEFT JOIN users u ON u.id=b.user_id
                WHERE b.league_id=? AND b.lot_id=?
                ORDER BY b.id DESC
                LIMIT ?
            """, (league_id, lot_id, int(limit)))

            bids = [
                {
                    "bid_id": int(r[0]),
                    "team_id": int(r[1]),
                    "team": str(r[2] or ""),
                    "user_id": int(r[3]),
                    "username": str(r[4] or ""),
                    "amount": float(r[5] or 0),
                    "created_at": str(r[6] or ""),
                }
                for r in (cur.fetchall() or [])
            ]

        return {
            "best": migliore,
            "bids": bids,
            "count": int(stato[3] or 0) if stato else 0,
            "version": int(stato[4] or 0) if stato else 0,
            "stato": str(stato[5] or "") if stato else "",
        }
    finally:
        _portal_close(conn)




def _spesa_effettiva_regole(valore, soglia, moltiplicatore):
    valore = float(valore or 0)
    soglia = float(soglia or 0)
    moltiplicatore = max(1.0, float(moltiplicatore or 1))

    if valore <= soglia:
        return round(valore, 2)

    return round(
        soglia + (valore - soglia) * moltiplicatore,
        2
    )


def _plafond_nominale_fpf_v182(budget, soglia, moltiplicatore, fair_play, budget_illimitato):
    """Massimo totale di crediti nominali acquistabili rispettando budget + FPF."""
    if bool(budget_illimitato):
        return 1_000_000_000_000.0
    budget = max(0.0, float(budget or 0))
    if not bool(fair_play):
        return budget
    soglia = max(0.0, float(soglia or 0))
    moltiplicatore = max(1.0, float(moltiplicatore or 1))
    if budget <= soglia:
        return budget
    return soglia + (budget - soglia) / moltiplicatore


def calcola_vincoli_offerta_team_multilega(
    league_id,
    lot_id,
    team_id,
    user_id=None,
    _conn=None
):
    import math

    league_id = int(league_id)
    lot_id = int(lot_id)
    team_id = int(team_id)
    user_id = int(
        user_id if user_id is not None
        else (st.session_state.get("auth_user_id") or 0)
    )

    _own_conn = _conn is None
    conn = _conn if _conn is not None else _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT COUNT(*)
            FROM league_members
            WHERE league_id=? AND user_id=? AND team_id=?
              AND is_active=1 AND is_team_member=1
        """, (league_id, user_id, team_id))
        if int(cur.fetchone()[0] or 0) == 0:
            raise PermissionError(
                "L'utente non è autorizzato a offrire per questa squadra."
            )

        cur.execute("""
            SELECT
                s.current_lot_id,
                l.stato,
                l.player_id,
                l.current_bid,
                l.current_team_id
            FROM auction_sessions s
            LEFT JOIN auction_lots l ON l.id=s.current_lot_id
            WHERE s.league_id=?
            LIMIT 1
        """, (league_id,))
        rl = cur.fetchone()

        if (
            not rl
            or rl[0] is None
            or int(rl[0]) != lot_id
            or str(rl[1] or "").upper() != "OPEN"
        ):
            raise ValueError("Il lotto non è più aperto.")

        player_id = int(rl[2])
        best_before = float(rl[3] or 0)
        best_team_id = int(rl[4]) if rl[4] is not None else None

        cur.execute("""
            SELECT
                lp.stato,
                COALESCE(c.ruolo_classico,''),
                COALESCE(c.ruolo_mantra,'')
            FROM league_players lp
            LEFT JOIN league_player_catalog c
              ON c.league_id=lp.league_id
             AND c.player_id=lp.player_id
            WHERE lp.league_id=? AND lp.player_id=?
            LIMIT 1
        """, (league_id, player_id))
        rp = cur.fetchone()
        if not rp or str(rp[0] or "").upper() != "DISPONIBILE":
            raise ValueError("Il giocatore non è più disponibile.")

        ruolo_classico = str(rp[1] or "").strip().upper()
        ruolo_mantra = str(rp[2] or "").strip().upper()
        giocatore_portiere = (
            ruolo_classico == "P"
            or ruolo_mantra in ("P", "POR")
        )

        cur.execute("""
            SELECT
                COALESCE(incremento_minimo,1),
                COALESCE(tipo_incremento_asta,'FISSO'),
                COALESCE(incrementi_scalari_json,'[]'),
                COALESCE(max_giocatori,30),
                COALESCE(min_portieri,0),
                COALESCE(budget_iniziale,500),
                COALESCE(soglia_budget,budget_iniziale,500),
                COALESCE(moltiplicatore_oltre_soglia,1),
                COALESCE(tipo_asta,'CHIAMATA'),
                COALESCE(budget_illimitato,0),
                COALESCE(fair_play_finanziario,0)
            FROM league_rules
            WHERE league_id=?
            LIMIT 1
        """, (league_id,))
        rr = cur.fetchone()
        if not rr:
            raise ValueError("Regolamento della lega non trovato.")

        incremento_base = max(0.01, float(rr[0] or 1))
        tipo_incremento_asta = str(rr[1] or "FISSO").upper()
        incrementi_scalari_json = str(rr[2] or "[]")
        incremento = _incremento_corrente_v187(
            best_before, incremento_base, tipo_incremento_asta, incrementi_scalari_json
        )
        max_giocatori = int(rr[3] or 30)
        min_portieri = int(rr[4] or 0)
        budget_default = float(rr[5] or 500)
        soglia = float(rr[6] or budget_default)
        moltiplicatore = max(1.0, float(rr[7] or 1))
        tipo_asta = str(rr[8] or "").strip().upper()
        budget_illimitato = bool(int(rr[9] or 0))
        fair_play_finanziario = bool(int(rr[10] or 0))

        if tipo_asta == "DRAFT":
            raise ValueError("La modalità Draft non prevede offerte.")

        minimo = 1.0 if best_before <= 0 else round(best_before + incremento, 2)

        cur.execute("""
            SELECT
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=?
                        THEN 1 ELSE 0
                    END
                ),0),
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=?
                        THEN COALESCE(lp.prezzo_assegnazione,0)
                        ELSE 0
                    END
                ),0),
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=?
                         AND (
                            UPPER(COALESCE(c.ruolo_classico,''))='P'
                            OR UPPER(COALESCE(c.ruolo_mantra,'')) IN ('P','POR')
                         )
                        THEN 1 ELSE 0
                    END
                ),0)
            FROM league_players lp
            LEFT JOIN league_player_catalog c
              ON c.league_id=lp.league_id
             AND c.player_id=lp.player_id
            WHERE lp.league_id=?
        """, (team_id, team_id, team_id, league_id))
        rrosa = cur.fetchone() or (0,0,0)

        numero_rosa = int(rrosa[0] or 0)
        valore_acquisti = float(rrosa[1] or 0)
        portieri_attuali = int(rrosa[2] or 0)

        if numero_rosa >= max_giocatori:
            return {
                "can_bid": False,
                "motivo": "La rosa è già completa.",
                "player_id": player_id,
                "minimo": minimo,
                "massimo": 0.0,
                "best_before": best_before,
                "best_team_id": best_team_id,
                "portieri_attuali": portieri_attuali,
                "min_portieri": min_portieri,
                "riserva_minima": 0.0,
            }

        cur.execute("""
            SELECT COALESCE(budget_impostato,?)
            FROM team_budgets
            WHERE league_id=? AND team_id=?
            LIMIT 1
        """, (budget_default, league_id, team_id))
        rb = cur.fetchone()
        budget = float(rb[0] if rb else budget_default)

        numero_dopo = numero_rosa + 1
        slot_residui = max(0, max_giocatori - numero_dopo)
        portieri_dopo = portieri_attuali + (1 if giocatore_portiere else 0)
        portieri_mancanti_dopo = max(0, min_portieri - portieri_dopo)

        vincolo_portieri_ok = slot_residui >= portieri_mancanti_dopo

        riserva_minima = float(slot_residui)

        # V182 - plafond coerente con BUDGET LIMITATO/ILLIMITATO e F.P.F.
        plafond_nominale = _plafond_nominale_fpf_v182(
            budget, soglia, moltiplicatore,
            fair_play_finanziario, budget_illimitato
        )
        massimo = plafond_nominale - float(valore_acquisti) - riserva_minima
        massimo = float(max(0, math.floor(massimo + 1e-9)))

        can_bid = True
        motivo = ""

        if best_team_id is not None and best_team_id == team_id:
            can_bid = False
            motivo = "Sei già il miglior offerente."
        elif not vincolo_portieri_ok:
            can_bid = False
            motivo = (
                "Questa offerta renderebbe impossibile raggiungere "
                f"il numero minimo di portieri ({min_portieri})."
            )
        elif massimo + 1e-9 < minimo:
            can_bid = False
            motivo = (
                f"Non hai margine sufficiente per l'offerta minima "
                f"di {minimo:g} crediti."
            )

        return {
            "can_bid": can_bid,
            "motivo": motivo,
            "player_id": player_id,
            "incremento": incremento,
            "best_before": best_before,
            "best_team_id": best_team_id,
            "minimo": minimo,
            "massimo": massimo,
            "budget": budget,
            "numero_rosa": numero_rosa,
            "slot_residui": slot_residui,
            "riserva_minima": riserva_minima,
            "valore_acquisti": valore_acquisti,
            "soglia": soglia,
            "moltiplicatore": moltiplicatore,
            "budget_illimitato": budget_illimitato,
            "fair_play_finanziario": fair_play_finanziario,
            "min_portieri": min_portieri,
            "portieri_attuali": portieri_attuali,
            "portieri_dopo": portieri_dopo,
            "portieri_mancanti_dopo": portieri_mancanti_dopo,
            "giocatore_portiere": giocatore_portiere,
        }
    finally:
        if _own_conn:
            _portal_close(conn)



def calcola_vincoli_offerta_team_multilega_v239_fast(
    league_id, lot_id, team_id, user_id, _conn
):
    """V239 - validazione BID in un'unica lettura DB autorevole."""
    import math
    league_id, lot_id, team_id, user_id = map(
        int, (league_id, lot_id, team_id, user_id)
    )
    cur = _conn.cursor()
    cur.execute("""
        SELECT
            EXISTS(
                SELECT 1 FROM league_members m
                WHERE m.league_id=? AND m.user_id=? AND m.team_id=?
                  AND m.is_active=1 AND m.is_team_member=1
            ),
            s.current_lot_id,
            l.stato,l.player_id,l.current_bid,l.current_team_id,COALESCE(l.version,0),
            lp.stato,
            COALESCE(c.ruolo_classico,''),COALESCE(c.ruolo_mantra,''),
            COALESCE(r.incremento_minimo,1),
            COALESCE(r.tipo_incremento_asta,'FISSO'),
            COALESCE(r.incrementi_scalari_json,'[]'),
            COALESCE(r.max_giocatori,30),COALESCE(r.min_portieri,0),
            COALESCE(r.budget_iniziale,500),
            COALESCE(r.soglia_budget,r.budget_iniziale,500),
            COALESCE(r.moltiplicatore_oltre_soglia,1),
            COALESCE(r.tipo_asta,'CHIAMATA'),
            COALESCE(r.budget_illimitato,0),
            COALESCE(r.fair_play_finanziario,0),
            COALESCE(tb.budget_impostato,r.budget_iniziale,500),
            (SELECT COUNT(*) FROM league_players x
             WHERE x.league_id=? AND x.stato='ASSEGNATO'
               AND x.assigned_team_id=?),
            (SELECT COALESCE(SUM(COALESCE(x.prezzo_assegnazione,0)),0)
             FROM league_players x
             WHERE x.league_id=? AND x.stato='ASSEGNATO'
               AND x.assigned_team_id=?),
            (SELECT COUNT(*)
             FROM league_players x
             LEFT JOIN league_player_catalog xc
               ON xc.league_id=x.league_id AND xc.player_id=x.player_id
             WHERE x.league_id=? AND x.stato='ASSEGNATO'
               AND x.assigned_team_id=?
               AND (
                    UPPER(COALESCE(xc.ruolo_classico,''))='P'
                    OR UPPER(COALESCE(xc.ruolo_mantra,'')) IN ('P','POR')
               ))
        FROM auction_sessions s
        JOIN auction_lots l
          ON l.league_id=s.league_id AND l.id=s.current_lot_id
        JOIN league_players lp
          ON lp.league_id=l.league_id AND lp.player_id=l.player_id
        LEFT JOIN league_player_catalog c
          ON c.league_id=l.league_id AND c.player_id=l.player_id
        JOIN league_rules r ON r.league_id=l.league_id
        LEFT JOIN team_budgets tb
          ON tb.league_id=l.league_id AND tb.team_id=?
        WHERE s.league_id=? AND l.id=?
        LIMIT 1
    """, (
        league_id,user_id,team_id,
        league_id,team_id,
        league_id,team_id,
        league_id,team_id,
        team_id,league_id,lot_id
    ))
    row=cur.fetchone()
    if not row:
        raise ValueError("Il lotto non è più aperto.")
    if not int(row[0] or 0):
        raise PermissionError("L'utente non è autorizzato a offrire per questa squadra.")
    if row[1] is None or int(row[1]) != lot_id or str(row[2] or "").upper()!="OPEN":
        raise ValueError("Il lotto non è più aperto.")
    if str(row[7] or "").upper()!="DISPONIBILE":
        raise ValueError("Il giocatore non è più disponibile.")

    player_id=int(row[3]); best_before=float(row[4] or 0)
    best_team_id=int(row[5]) if row[5] is not None else None
    version=int(row[6] or 0)
    ruolo_classico=str(row[8] or "").strip().upper()
    ruolo_mantra=str(row[9] or "").strip().upper()
    giocatore_portiere=ruolo_classico=="P" or ruolo_mantra in ("P","POR")
    incremento_base=max(.01,float(row[10] or 1))
    tipo_incremento=str(row[11] or "FISSO").upper()
    incrementi_json=str(row[12] or "[]")
    incremento=_incremento_corrente_v187(
        best_before,incremento_base,tipo_incremento,incrementi_json
    )
    max_giocatori=int(row[13] or 30); min_portieri=int(row[14] or 0)
    budget_default=float(row[15] or 500); soglia=float(row[16] or budget_default)
    moltiplicatore=max(1.0,float(row[17] or 1))
    if str(row[18] or "").strip().upper()=="DRAFT":
        raise ValueError("La modalità Draft non prevede offerte.")
    budget_illimitato=bool(int(row[19] or 0))
    fair_play_finanziario=bool(int(row[20] or 0))
    budget=float(row[21] if row[21] is not None else budget_default)
    numero_rosa=int(row[22] or 0); valore_acquisti=float(row[23] or 0)
    portieri_attuali=int(row[24] or 0)
    minimo=1.0 if best_before<=0 else round(best_before+incremento,2)

    if numero_rosa>=max_giocatori:
        return {"can_bid":False,"motivo":"La rosa è già completa.",
                "player_id":player_id,"minimo":minimo,"massimo":0.0,
                "best_before":best_before,"best_team_id":best_team_id,
                "version":version,"riserva_minima":0.0,
                "portieri_attuali":portieri_attuali,"min_portieri":min_portieri}

    slot_residui=max(0,max_giocatori-(numero_rosa+1))
    portieri_dopo=portieri_attuali+(1 if giocatore_portiere else 0)
    portieri_mancanti_dopo=max(0,min_portieri-portieri_dopo)
    riserva_minima=float(slot_residui)
    plafond=_plafond_nominale_fpf_v182(
        budget,soglia,moltiplicatore,fair_play_finanziario,budget_illimitato
    )
    massimo=float(max(0,math.floor(plafond-valore_acquisti-riserva_minima+1e-9)))
    can_bid=True; motivo=""
    if best_team_id==team_id:
        can_bid=False; motivo="Sei già il miglior offerente."
    elif slot_residui<portieri_mancanti_dopo:
        can_bid=False
        motivo=f"Questa offerta renderebbe impossibile raggiungere il numero minimo di portieri ({min_portieri})."
    elif massimo+1e-9<minimo:
        can_bid=False
        motivo=f"Non hai margine sufficiente per l'offerta minima di {minimo:g} crediti."

    return {
        "can_bid":can_bid,"motivo":motivo,"player_id":player_id,
        "incremento":incremento,"best_before":best_before,
        "best_team_id":best_team_id,"version":version,
        "minimo":minimo,"massimo":massimo,"budget":budget,
        "numero_rosa":numero_rosa,"slot_residui":slot_residui,
        "riserva_minima":riserva_minima,"valore_acquisti":valore_acquisti,
        "soglia":soglia,"moltiplicatore":moltiplicatore,
        "budget_illimitato":budget_illimitato,
        "fair_play_finanziario":fair_play_finanziario,
        "min_portieri":min_portieri,"portieri_attuali":portieri_attuali,
        "portieri_dopo":portieri_dopo,
        "portieri_mancanti_dopo":portieri_mancanti_dopo,
        "giocatore_portiere":giocatore_portiere,
    }


def verifica_offerta_team_multilega(
    league_id,
    lot_id,
    team_id,
    amount,
    user_id=None,
    _conn=None
):
    amount = round(float(amount), 2)

    if amount <= 0:
        raise ValueError("L'offerta deve essere superiore a zero.")

    info = calcola_vincoli_offerta_team_multilega(
        league_id, lot_id, team_id, user_id, _conn=_conn
    )

    if not info.get("can_bid", False):
        raise ValueError(
            info.get("motivo")
            or "Non puoi effettuare questa offerta."
        )

    if amount + 1e-9 < float(info["minimo"]):
        raise ValueError(
            f"Offerta troppo bassa. Offerta minima: "
            f"{float(info['minimo']):g} crediti."
        )

    if amount > float(info["massimo"]) + 1e-9:
        raise ValueError(
            f"Offerta troppo alta per il budget disponibile. "
            f"Offerta massima: {float(info['massimo']):g} crediti."
        )

    valore_con_offerta = round(
        float(info["valore_acquisti"]) + amount, 2
    )
    valore_con_riserva = round(
        valore_con_offerta + float(info["riserva_minima"]), 2
    )
    # V182 - il limite reale considera anche l'eventuale Fair Play Finanziario.
    spesa_con_riserva = _spesa_effettiva_regole(
        valore_con_riserva,
        info.get("soglia", info["budget"]),
        info.get("moltiplicatore", 1)
    ) if info.get("fair_play_finanziario") else valore_con_riserva

    if (not info.get("budget_illimitato")) and spesa_con_riserva > float(info["budget"]) + 1e-9:
        raise ValueError(
            "Budget insufficiente considerando la riserva minima "
            "e le regole del Fair Play Finanziario."
        )

    return {
        **info,
        "valore_con_offerta": valore_con_offerta,
        "spesa_con_riserva": spesa_con_riserva,
    }



def inserisci_offerta_team_multilega(league_id, lot_id, team_id, amount):
    """
    V113 - Bidding atomico con optimistic locking.

    Il record auction_lots è la fonte autorevole:
    current_bid + current_team_id + version.
    Due offerte concorrenti non possono entrambe vincere la stessa versione.
    """
    league_id = int(league_id)
    lot_id = int(lot_id)
    team_id = int(team_id)
    amount = round(float(amount), 2)

    assicura_schema_timer_v129(league_id)
    user_id = int(st.session_state.get("auth_user_id") or 0)

    # V181 - una sola connessione remota per validazione + scrittura del bid.
    # Evita un secondo handshake/checkout DB a ogni click di offerta.
    conn = _portal_raw_connection()
    cur = conn.cursor()

    try:
        # V239 - una sola lettura DB per TUTTI i vincoli del bid.
        # La versione letta viene poi protetta dal CAS atomico sottostante.
        info = calcola_vincoli_offerta_team_multilega_v239_fast(
            league_id, lot_id, team_id, user_id, conn
        )
        if not info.get("can_bid", False):
            raise ValueError(info.get("motivo") or "Non puoi effettuare questa offerta.")
        if amount + 1e-9 < float(info["minimo"]):
            raise ValueError(f"Offerta troppo bassa. Offerta minima: {float(info['minimo']):g} crediti.")
        if amount > float(info["massimo"]) + 1e-9:
            raise ValueError(f"Offerta troppo alta. Offerta massima: {float(info['massimo']):g} crediti.")

        valore_con_offerta=round(float(info["valore_acquisti"])+amount,2)
        valore_con_riserva=round(valore_con_offerta+float(info["riserva_minima"]),2)
        spesa_con_riserva=(
            _spesa_effettiva_regole(
                valore_con_riserva,info["soglia"],info["moltiplicatore"]
            ) if info.get("fair_play_finanziario") else valore_con_riserva
        )
        if (not info.get("budget_illimitato")) and spesa_con_riserva > float(info["budget"])+1e-9:
            raise ValueError("Budget insufficiente considerando la riserva minima e le regole del Fair Play Finanziario.")

        current_bid=float(info["best_before"] or 0)
        version=int(info["version"])

        # CAS: aggiorna solo se la versione letta è ancora quella corrente.
        cur.execute("""
            UPDATE auction_lots
            SET current_bid=?,
                current_team_id=?,
                bid_count=COALESCE(bid_count,0)+1,
                version=COALESCE(version,0)+1
            WHERE id=?
              AND league_id=?
              AND stato='OPEN'
              AND COALESCE(version,0)=?
              AND EXISTS (
                    SELECT 1 FROM auction_sessions s
                    WHERE s.league_id=? AND s.current_lot_id=?
                  )
              AND (
                    current_bid IS NULL
                    OR ? > current_bid
                  )
            RETURNING current_bid,current_team_id,COALESCE(version,0),stato
        """, (
            amount,
            team_id,
            lot_id,
            league_id,
            version,
            league_id,
            lot_id,
            amount
        ))
        check = cur.fetchone()

        if (
            not check
            or str(check[3] or "").upper() != "OPEN"
            or check[0] is None
            or int(check[1] or 0) != team_id
            or abs(float(check[0]) - amount) > 0.0001
            or int(check[2] or 0) != version + 1
        ):
            raise ValueError(
                "Offerta non accettata: nel frattempo è stata registrata "
                "un'offerta uguale o superiore. Inserisci un importo più alto e riprova."
            )

        # Solo dopo aver vinto il CAS viene registrato lo storico del bid.
        cur.execute("""
            INSERT INTO bids (
                league_id,lot_id,team_id,user_id,amount,created_at
            )
            VALUES (?,?,?,?,?,CURRENT_TIMESTAMP)
        """, (league_id, lot_id, team_id, user_id, amount))

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,team_id,azione,entita,entita_id,
                dettagli_json,created_at
            )
            VALUES (?,?,?,'BID_PLACED','AUCTION_LOT',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            user_id,
            team_id,
            str(lot_id),
            json.dumps({
                "amount": amount,
                "player_id": info["player_id"],
                "previous_bid": current_bid,
                "version_before": version,
                "version_after": version + 1,
                "riserva_minima": info["riserva_minima"],
            }, ensure_ascii=False)
        ))

        conn.commit()

        return {
            **info,
            "amount": amount,
            "version": version + 1,
        }

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)



def migliore_offerta_lotto_multilega(league_id, lot_id):
    stato = stato_offerte_lotto_multilega(league_id, lot_id, 1)
    return stato.get("best")




def chiamata_pendente_multilega(league_id):
    league_id = int(league_id)
    inizializza_listone_lega_asta(league_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT
                c.id,
                c.team_id,
                COALESCE(t.nome,''),
                c.player_id,
                COALESCE(g.nome,''),
                COALESCE(g.squadra,''),
                COALESCE(g.ruolo_mantra,''),
                c.tipo_asta,
                c.stato,
                c.created_at
            FROM auction_calls c
            LEFT JOIN teams t
              ON t.id=c.team_id AND t.league_id=c.league_id
            LEFT JOIN league_player_catalog g ON g.player_id=c.player_id AND g.league_id=c.league_id
            WHERE c.league_id=? AND c.stato='PENDING'
            ORDER BY c.id
            LIMIT 1
        """, (league_id,))
        r = cur.fetchone()

        if not r:
            return None

        return {
            "call_id": int(r[0]),
            "team_id": int(r[1]),
            "team": str(r[2] or ""),
            "player_id": int(r[3]),
            "player": str(r[4] or ""),
            "squadra_reale": str(r[5] or ""),
            "ruolo_mantra": str(r[6] or ""),
            "tipo_asta": str(r[7] or "").upper(),
            "stato": str(r[8] or ""),
            "created_at": str(r[9] or ""),
        }
    finally:
        _portal_close(conn)


def invia_chiamata_team_multilega(league_id, team_id, player_id):
    """
    CHIAMATA / DRAFT:
    la squadra di turno seleziona il giocatore.
    Il Banditore non sceglie il giocatore al posto della squadra.
    """
    league_id = int(league_id)
    team_id = int(team_id)
    player_id = int(player_id)
    user_id = int(st.session_state.get("auth_user_id") or 0)

    tipo_asta = tipo_asta_lega_multilega(league_id)
    if tipo_asta not in ("CHIAMATA", "DRAFT"):
        raise ValueError(
            "La selezione da parte della squadra è disponibile solo "
            "in modalità A chiamata o Draft."
        )

    turno = turno_squadra_multilega(league_id, tipo_asta)
    if not turno or int(turno["team_id"]) != team_id:
        raise PermissionError("Non è il turno di questa squadra.")

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT COUNT(*)
            FROM league_members
            WHERE league_id=? AND team_id=? AND user_id=?
              AND is_active=1 AND is_team_member=1
        """, (league_id, team_id, user_id))
        if int(cur.fetchone()[0] or 0) == 0:
            raise PermissionError(
                "L'utente non è autorizzato a selezionare per questa squadra."
            )

        cur.execute("""
            SELECT current_lot_id
            FROM auction_sessions
            WHERE league_id=?
            LIMIT 1
        """, (league_id,))
        rs = cur.fetchone()
        if rs and rs[0] is not None:
            raise ValueError(
                "Esiste ancora un lotto attivo. Attendi la conclusione."
            )

        cur.execute("""
            SELECT COUNT(*)
            FROM auction_calls
            WHERE league_id=? AND stato='PENDING'
        """, (league_id,))
        if int(cur.fetchone()[0] or 0) > 0:
            raise ValueError(
                "Esiste già una chiamata in attesa di gestione dal Banditore."
            )

        cur.execute("""
            SELECT stato
            FROM league_players
            WHERE league_id=? AND player_id=?
            LIMIT 1
        """, (league_id, player_id))
        rp = cur.fetchone()
        if not rp or str(rp[0] or "").upper() != "DISPONIBILE":
            raise ValueError("Il giocatore non è più disponibile.")

        cur.execute("""
            INSERT INTO auction_calls (
                league_id,team_id,player_id,tipo_asta,stato,
                created_by_user_id,created_at
            )
            VALUES (?,?,?,?, 'PENDING', ?, CURRENT_TIMESTAMP)
        """, (
            league_id, team_id, player_id, tipo_asta, user_id
        ))

        cur.execute("SELECT last_insert_rowid()")
        rid = cur.fetchone()
        call_id = int(rid[0]) if rid and rid[0] is not None else 0

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,team_id,azione,entita,entita_id,
                dettagli_json,created_at
            )
            VALUES (?,?,?,'PLAYER_CALLED','AUCTION_CALL',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            user_id,
            team_id,
            str(call_id),
            json.dumps({
                "player_id": player_id,
                "tipo_asta": tipo_asta,
            }, ensure_ascii=False)
        ))

        conn.commit()
        return call_id

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)


def gestisci_chiamata_banditore_multilega(league_id, call_id):
    """
    CHIAMATA: apre il lotto sul giocatore scelto dalla squadra di turno.
    DRAFT: assegna direttamente il giocatore alla squadra di turno.
    """
    league_id = int(league_id)
    call_id = int(call_id)
    user_id = int(st.session_state.get("auth_user_id") or 0)

    call = chiamata_pendente_multilega(league_id)
    if not call or int(call["call_id"]) != call_id:
        raise ValueError("La chiamata non è più disponibile.")

    tipo_asta = str(call["tipo_asta"]).upper()

    if tipo_asta == "CHIAMATA":
        lot_id = apri_lotto_banditore(
            league_id,
            call["player_id"]
        )

        conn = _portal_raw_connection()
        cur = conn.cursor()
        try:
            cur.execute("""
                UPDATE auction_calls
                SET stato='OPENED',
                    handled_by_user_id=?,
                    handled_at=CURRENT_TIMESTAMP
                WHERE id=? AND league_id=? AND stato='PENDING'
            """, (user_id, call_id, league_id))
            conn.commit()
        finally:
            _portal_close(conn)

        return {
            "azione": "OPENED",
            "lot_id": lot_id,
            **call
        }

    if tipo_asta == "DRAFT":
        # Il giocatore è stato chiamato anche se il Draft lo assegna direttamente.
        assicura_schema_storico_asta_v147(league_id)
        _conn_call = _portal_raw_connection()
        _cur_call = _conn_call.cursor()
        try:
            registra_giocatore_chiamato_v147(
                _cur_call, league_id, call["player_id"], "DRAFT", None
            )
            _conn_call.commit()
        finally:
            _portal_close(_conn_call)

        risultato = assegna_giocatore_banditore(
            league_id,
            call["player_id"],
            call["team_id"],
            0.0
        )

        avanza_turno_squadra_multilega(
            league_id,
            "DRAFT"
        )

        conn = _portal_raw_connection()
        cur = conn.cursor()
        try:
            cur.execute("""
                UPDATE auction_calls
                SET stato='ASSIGNED',
                    handled_by_user_id=?,
                    handled_at=CURRENT_TIMESTAMP
                WHERE id=? AND league_id=? AND stato='PENDING'
            """, (user_id, call_id, league_id))
            conn.commit()
        finally:
            _portal_close(conn)

        return {
            "azione": "ASSIGNED",
            "risultato": risultato,
            **call
        }

    raise ValueError("Modalità asta non compatibile con la chiamata.")




def rosa_normalizzata_team_multilega(league_id, team_id):
    """
    Costruisce la rosa del team usando esclusivamente le tabelle normalizzate
    autorevoli della lega.
    """
    league_id = int(league_id)
    team_id = int(team_id)

    conn = _portal_raw_connection()
    try:
        df = pd.read_sql_query("""
            SELECT
                c.player_id AS Id,
                c.ruolo_classico AS R,
                c.ruolo_mantra AS RM,
                c.nome AS Nome,
                c.squadra AS Squadra,
                c.quotazione_attuale AS "Qt.A",
                c.quotazione_iniziale AS "Qt.I",
                c.differenza AS "Diff.",
                c.quotazione_attuale_mantra AS "Qt.A M",
                c.quotazione_iniziale_mantra AS "Qt.I M",
                c.differenza_mantra AS "Diff.M",
                c.fvm AS FVM,
                c.fvm_mantra AS "FVM M",
                'MIO' AS Stato,
                ro.prezzo_acquisto AS Prezzo
            FROM rosters ro
            JOIN league_player_catalog c
              ON c.league_id=ro.league_id
             AND c.player_id=ro.player_id
            WHERE ro.league_id=? AND ro.team_id=?
            ORDER BY c.nome
        """, conn, params=(league_id, team_id))
        return df
    finally:
        _portal_close(conn)


def max_giocatori_lega_multilega(league_id):
    league_id = int(league_id)
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT COALESCE(max_giocatori,30)
            FROM league_rules
            WHERE league_id=?
            LIMIT 1
        """, (league_id,))
        r = cur.fetchone()
        return int(r[0] or 30) if r else 30
    finally:
        _portal_close(conn)


def aggiorna_iqr_team_multilega(league_id, team_id, salva_snapshot=False):
    """V121: calcola IQR senza scritture DB durante il rendering."""
    league_id=int(league_id); team_id=int(team_id)
    df_rosa=rosa_normalizzata_team_multilega(league_id,team_id)
    max_giocatori=max_giocatori_lega_multilega(league_id)
    valore=float(calcola_iqr(df_rosa,None,max_giocatori=max_giocatori))

    if salva_snapshot:
        conn=_portal_raw_connection(); cur=conn.cursor()
        try:
            cur.execute("""
                INSERT INTO iqr_profiles (
                    league_id,team_id,iqr_corrente,max_giocatori,
                    giocatori_rosa,updated_at
                ) VALUES (?,?,?,?,?,CURRENT_TIMESTAMP)
                ON CONFLICT(league_id,team_id) DO UPDATE SET
                    iqr_corrente=excluded.iqr_corrente,
                    max_giocatori=excluded.max_giocatori,
                    giocatori_rosa=excluded.giocatori_rosa,
                    updated_at=CURRENT_TIMESTAMP
            """,(league_id,team_id,valore,max_giocatori,len(df_rosa)))
            conn.commit()
        finally: _portal_close(conn)

    return {"iqr":valore,"max_giocatori":max_giocatori,
            "giocatori":len(df_rosa),"df_rosa":df_rosa}


def valuta_iqr_giocatore_team_multilega(
    league_id,team_id,player_id,base_iqr=None,salva_valutazione=False
):
    """V121: valutazione IQR read-only e riuso del calcolo rosa corrente."""
    league_id=int(league_id); team_id=int(team_id); player_id=int(player_id)
    base=base_iqr if isinstance(base_iqr,dict) and "df_rosa" in base_iqr else \
        aggiorna_iqr_team_multilega(league_id,team_id,salva_snapshot=False)
    df_rosa=base["df_rosa"].copy()
    max_giocatori=int(base["max_giocatori"])

    conn=_portal_raw_connection(); cur=conn.cursor()
    try:
        cur.execute("""
            SELECT player_id,ruolo_classico,ruolo_mantra,nome,squadra,
                   quotazione_attuale,quotazione_iniziale,differenza,
                   quotazione_attuale_mantra,quotazione_iniziale_mantra,
                   differenza_mantra,fvm,fvm_mantra
            FROM league_player_catalog
            WHERE league_id=? AND player_id=? LIMIT 1
        """,(league_id,player_id))
        r=cur.fetchone()
        if not r: raise ValueError("Giocatore non presente nel listone della lega.")

        nuova=pd.DataFrame([{
            "Id":int(r[0]),"R":str(r[1] or ""),"RM":str(r[2] or ""),
            "Nome":str(r[3] or ""),"Squadra":str(r[4] or ""),
            "Qt.A":r[5],"Qt.I":r[6],"Diff.":r[7],"Qt.A M":r[8],
            "Qt.I M":r[9],"Diff.M":r[10],"FVM":r[11],"FVM M":r[12],
            "Stato":"MIO","Prezzo":None
        }])
        presente=("Id" in df_rosa.columns and
            (pd.to_numeric(df_rosa["Id"],errors="coerce").fillna(-1).astype(int)==player_id).any())
        iqr_dopo=float(base["iqr"]) if presente else float(
            calcola_iqr(pd.concat([df_rosa,nuova],ignore_index=True),None,max_giocatori=max_giocatori)
        )
        iqr_prima=float(base["iqr"]); delta=round(iqr_dopo-iqr_prima,1)

        if salva_valutazione:
            cur.execute("""
                INSERT INTO player_evaluations (
                    league_id,team_id,player_id,iqr_prima,iqr_dopo,delta_iqr,updated_at
                ) VALUES (?,?,?,?,?,?,CURRENT_TIMESTAMP)
                ON CONFLICT(league_id,team_id,player_id) DO UPDATE SET
                    iqr_prima=excluded.iqr_prima,iqr_dopo=excluded.iqr_dopo,
                    delta_iqr=excluded.delta_iqr,updated_at=CURRENT_TIMESTAMP
            """,(league_id,team_id,player_id,iqr_prima,iqr_dopo,delta))
            conn.commit()

        return {"iqr_prima":iqr_prima,"iqr_dopo":iqr_dopo,"delta":delta,
                "descrizione_prima":descrizione_iqr(iqr_prima),
                "descrizione_dopo":descrizione_iqr(iqr_dopo)}
    finally: _portal_close(conn)



def assicura_workspace_console_team_multilega(league_id,team_id,forza=False):
    """V121: sync compatibility una sola volta per sessione/team."""
    league_id=int(league_id); team_id=int(team_id)
    key=f"_ml37_console_workspace_ready_{league_id}_{team_id}"
    if not forza and st.session_state.get(key): return
    sincronizza_listone_lega_nel_workspace(league_id,team_id)
    sincronizza_workspace_team_da_normalizzato(league_id,team_id)
    st.session_state[key]=True



def render_console_asta_team():
    if "TEAM" not in RUOLI_ATTIVI:
        st.error("Questa sezione è disponibile solo per una squadra della lega.")
        return

    league_id = int(st.session_state.get("ml_league_id"))
    team_id = st.session_state.get("ml_team_id")

    if team_id is None:
        st.warning("Nessuna squadra associata all'accesso corrente.")
        return

    team_id = int(team_id)

    st.subheader("📡 Console Asta")
    st.caption(
        "Lo stato dell'asta viene aggiornato quando entri nella sezione "
        "o quando premi «AGGIORNA ORA». Le offerte simultanee sono "
        "validate atomicamente dal server."
    )

    if st.session_state.get("team_bid_msg"):
        st.success(st.session_state.pop("team_bid_msg"))

    _console_perf_start=time.perf_counter()
    _console_perf={}
    try:
        _t0=time.perf_counter()
        assicura_workspace_console_team_multilega(league_id,team_id)
        _console_perf["Sync workspace"]=time.perf_counter()-_t0

        _t0=time.perf_counter()
        lotto=lotto_corrente_multilega(league_id)
        _console_perf["Lotto"]=time.perf_counter()-_t0

        _t0=time.perf_counter()
        team=situazione_team_corrente_multilega(league_id,team_id)
        _console_perf["Team"]=time.perf_counter()-_t0

        _t0=time.perf_counter()
        regole=regole_bidding_multilega(league_id)
        tipo_asta=str(regole.get("tipo_asta") or "CHIAMATA").upper()
        _console_perf["Regole"]=time.perf_counter()-_t0

        _t0=time.perf_counter()
        turno_corrente=(
            turno_squadra_multilega(league_id,tipo_asta)
            if tipo_asta in ("CHIAMATA","DRAFT") else None
        )
        _console_perf["Turno"]=time.perf_counter()-_t0
    except Exception as errore:
        st.error("Impossibile leggere lo stato dell'asta: " + str(errore))
        return

    if team:
        try:
            _t0=time.perf_counter()
            _iqr_team=aggiorna_iqr_team_multilega(
                league_id,team_id,salva_snapshot=False
            )
            _iqr_corrente=float(_iqr_team["iqr"])
            _console_perf["IQR team"]=time.perf_counter()-_t0
        except Exception:
            _iqr_corrente = 0.0

        c1, c2, c3, c4, c5 = st.columns(5)
        c1.metric("Budget", f'{team["budget"]:g}')
        c2.metric("Spesa effettiva", f'{team["spesa_effettiva"]:g}')
        c3.metric("Residuo", f'{team["residuo"]:g}')
        c4.metric("Rosa", f'{team["giocatori"]}/{team["max_giocatori"]}')
        c5.metric("IQR", f'{_iqr_corrente:.1f}%')

    render_info_modalita_asta(tipo_asta, turno_corrente)

    if tipo_asta == "DRAFT":
        st.warning(
            "In modalità Draft non sono previste offerte: "
            "il Banditore assegna direttamente il giocatore alla squadra di turno."
        )

    st.markdown("---")

    if lotto is None:
        if tipo_asta in ("CHIAMATA","DRAFT"):
            pending_call = chiamata_pendente_multilega(league_id)

            if pending_call is not None:
                if int(pending_call["team_id"]) == team_id:
                    st.success(
                        f'📣 Hai selezionato **{pending_call["player"]}** · '
                        "in attesa del Banditore."
                    )
                else:
                    st.info(
                        f'⏳ In attesa della selezione/gestione della squadra '
                        f'**{pending_call["team"]}**.'
                    )

            elif turno_corrente and int(turno_corrente["team_id"]) == team_id:
                st.success("🎯 È il tuo turno di selezione.")

                try:
                    _disponibili_call = [
                        x for x in elenco_giocatori_asta_multilega(league_id)
                        if str(x["stato"]).upper() == "DISPONIBILE"
                    ]
                except Exception as errore:
                    _disponibili_call = []
                    st.error("Impossibile leggere i giocatori disponibili: " + str(errore))

                _q_call = st.text_input(
                    "Cerca il giocatore da chiamare",
                    placeholder="Nome, squadra o ruolo...",
                    key=f"team_call_search_{league_id}_{team_id}_{tipo_asta}"
                ).strip().lower()

                if _q_call:
                    _filtrati_call = [
                        x for x in _disponibili_call
                        if _q_call in str(x["nome"]).lower()
                        or _q_call in str(x["squadra"]).lower()
                        or _q_call in str(x["ruolo_mantra"]).lower()
                    ]
                else:
                    _filtrati_call = _disponibili_call[:200]

                if _filtrati_call:
                    _op_call = {
                        f'{x["nome"]} · {x["squadra"]} · {x["ruolo_mantra"]} '
                        f'· FVM {x["fvm"]:g}': x
                        for x in _filtrati_call
                    }

                    _sel_call = st.selectbox(
                        "Giocatore",
                        list(_op_call.keys()),
                        key=f"team_call_player_{league_id}_{team_id}_{tipo_asta}"
                    )
                    _g_call = _op_call[_sel_call]

                    _label = (
                        "📣 CHIAMA GIOCATORE"
                        if tipo_asta == "CHIAMATA"
                        else "🧩 SELEZIONA PER IL DRAFT"
                    )

                    if st.button(
                        _label,
                        type="primary",
                        use_container_width=True,
                        key=f"team_call_submit_{league_id}_{team_id}_{tipo_asta}"
                    ):
                        try:
                            invia_chiamata_team_multilega(
                                league_id,
                                team_id,
                                _g_call["player_id"]
                            )
                            st.session_state["team_bid_msg"] = (
                                f'{_g_call["nome"]} selezionato. '
                                "Attendi il Banditore."
                            )
                            st.rerun()
                        except Exception as errore:
                            st.error(str(errore))
                else:
                    st.info("Nessun giocatore disponibile corrisponde alla ricerca.")
            else:
                _nome_turno = (
                    turno_corrente["nome"]
                    if turno_corrente else "un'altra squadra"
                )
                st.info(
                    f"⏳ Non è il tuo turno. Sta selezionando **{_nome_turno}**."
                )
        else:
            st.info(
                "⏳ Nessun giocatore è attualmente all'asta. "
                "Attendi che il Banditore apra il prossimo lotto."
            )
    else:
        stato_bids = stato_offerte_lotto_multilega(
            league_id,
            lotto["lot_id"],
            20,
            include_history=False
        )
        best = stato_bids["best"]
        incremento = float(regole["incremento"])
        offerta_minima = (
            1.0
            if best is None
            else round(float(best["amount"]) + incremento, 2)
        )

        try:
            vincoli_offerta = calcola_vincoli_offerta_team_multilega(
                league_id,
                lotto["lot_id"],
                team_id
            )
        except Exception as errore:
            vincoli_offerta = {
                "can_bid": False,
                "motivo": str(errore),
                "minimo": offerta_minima,
                "massimo": 0.0,
                "riserva_minima": 0.0,
                "portieri_attuali": 0,
                "min_portieri": 0,
            }

        lotto_stato = str(lotto.get("stato","")).upper()

        if lotto_stato == "OPEN":
            st.success("🟢 LOTTO APERTO")
        elif lotto_stato == "CLOSING":
            st.warning("🟠 OFFERTE CHIUSE · ASSEGNAZIONE IN CORSO")
        else:
            st.info(f"Stato lotto: {lotto_stato}")

        st.markdown(
            f"""
            <div style="
                background:#071a2f;
                border:2px solid #f5b51b;
                border-radius:16px;
                padding:22px 24px;
                margin:8px 0 14px 0;
                color:white;
            ">
                <div style="font-size:30px;font-weight:950;">
                    {html.escape(lotto["nome"])}
                </div>
                <div style="font-size:17px;color:#dbeafe;margin-top:6px;">
                    {html.escape(lotto["squadra"])}
                    &nbsp;·&nbsp;
                    {html.escape(lotto["ruolo_mantra"])}
                </div>
                <div style="display:flex;gap:28px;margin-top:16px;">
                    <div>
                        <span style="color:#94a3b8;">FVM M</span><br>
                        <strong style="font-size:22px;color:#f5b51b;">
                            {lotto["fvm"]:g}
                        </strong>
                    </div>
                    <div>
                        <span style="color:#94a3b8;">Quotazione</span><br>
                        <strong style="font-size:22px;color:white;">
                            {lotto["quotazione"]:g}
                        </strong>
                    </div>
                </div>
            </div>
            """,
            unsafe_allow_html=True
        )

        try:
            _t0=time.perf_counter()
            _iqr_lotto=valuta_iqr_giocatore_team_multilega(
                league_id,team_id,lotto["player_id"],
                base_iqr=(_iqr_team if "_iqr_team" in locals() else None),
                salva_valutazione=False
            )
            _console_perf["IQR giocatore"]=time.perf_counter()-_t0

            _delta_iqr = float(_iqr_lotto["delta"])
            _segno_iqr = "+" if _delta_iqr > 0 else ""

            _ic1, _ic2, _ic3 = st.columns(3)
            _ic1.metric(
                "IQR attuale",
                f'{float(_iqr_lotto["iqr_prima"]):.1f}%'
            )
            _ic2.metric(
                "IQR con giocatore",
                f'{float(_iqr_lotto["iqr_dopo"]):.1f}%',
                delta=f'{_segno_iqr}{_delta_iqr:.1f}'
            )
            _ic3.metric(
                "Impatto IQR",
                f'{_segno_iqr}{_delta_iqr:.1f}'
            )

            st.caption(
                "Valutazione personalizzata sulla tua rosa: "
                f'**{_iqr_lotto["descrizione_prima"]}** → '
                f'**{_iqr_lotto["descrizione_dopo"]}**'
            )
        except Exception as errore:
            st.caption(
                "IQR personalizzato non disponibile: " + str(errore)
            )

        if best is None:
            st.info(
                f"Nessuna offerta. Offerta iniziale minima: "
                f"**{offerta_minima:g}** crediti."
            )
        else:
            best_mia = int(best["team_id"]) == team_id
            if best_mia:
                st.success(
                    f'🏆 Sei il miglior offerente: **{best["amount"]:g}** crediti.'
                )
            else:
                st.warning(
                    f'Migliore offerta: **{best["amount"]:g}** crediti · '
                    f'**{best["team"]}**'
                )

        _vc1, _vc2, _vc3 = st.columns(3)
        _vc1.metric(
            "Offerta minima",
            f'{float(vincoli_offerta.get("minimo",offerta_minima)):g}'
        )
        _vc2.metric(
            "Offerta massima",
            f'{float(vincoli_offerta.get("massimo",0)):g}'
        )
        _vc3.metric(
            "Riserva rosa",
            f'{float(vincoli_offerta.get("riserva_minima",0)):g}'
        )

        st.caption(
            f'Incremento minimo: {incremento:g} crediti · '
            f'Portieri: {int(vincoli_offerta.get("portieri_attuali",0))}/'
            f'{int(vincoli_offerta.get("min_portieri",0))}'
        )

        if (
            lotto_stato == "OPEN"
            and tipo_asta != "DRAFT"
            and not vincoli_offerta.get("can_bid", False)
        ):
            st.warning(
                "⛔ " + str(
                    vincoli_offerta.get("motivo")
                    or "Non puoi effettuare offerte su questo lotto."
                )
            )

        if lotto_stato == "CLOSING":
            if best is None:
                st.info("Le offerte sono chiuse. Nessuna offerta registrata.")
            elif int(best["team_id"]) == team_id:
                st.success(
                    f'🔒 Offerte chiuse: sei in testa a **{best["amount"]:g}** crediti.'
                )
            else:
                st.warning(
                    f'🔒 Offerte chiuse: miglior offerta **{best["amount"]:g}** · '
                    f'**{best["team"]}**'
                )

        if tipo_asta == "DRAFT":
            st.info("Il Draft non utilizza il sistema di bidding.")
        elif lotto_stato != "OPEN":
            st.caption(
                "Nuove offerte non consentite: il Banditore ha chiuso il bidding."
            )
        elif not vincoli_offerta.get("can_bid", False):
            st.caption("Offerta non disponibile per i vincoli correnti.")
        else:
            _min_ui = float(
                vincoli_offerta.get("minimo", offerta_minima)
            )
            _max_ui = float(
                vincoli_offerta.get("massimo", _min_ui)
            )

            st.markdown("#### Fai la tua offerta")

            _qb1, _qb2, _qb3 = st.columns(3)

            _quick_values = [
                ("OFFERTA MINIMA", _min_ui),
                ("+5", min(_max_ui, _min_ui + 5)),
                ("+10", min(_max_ui, _min_ui + 10)),
            ]

            for _col, (_label_q, _value_q) in zip(
                (_qb1, _qb2, _qb3),
                _quick_values
            ):
                with _col:
                    _disabled_q = (
                        _value_q < _min_ui - 1e-9
                        or _value_q > _max_ui + 1e-9
                    )
                    if st.button(
                        f"{_label_q} · {_value_q:g}",
                        type=("primary" if _label_q == "OFFERTA MINIMA" else "secondary"),
                        use_container_width=True,
                        disabled=_disabled_q,
                        key=f"team_bid_quick_{lotto['lot_id']}_{_label_q}"
                    ):
                        try:
                            inserisci_offerta_team_multilega(
                                league_id,
                                lotto["lot_id"],
                                team_id,
                                float(_value_q)
                            )
                            st.session_state["team_bid_msg"] = (
                                f"Offerta di {float(_value_q):g} crediti registrata."
                            )
                            st.rerun()
                        except Exception as errore:
                            st.error(str(errore))

            offerta_diretta = st.number_input(
                "Offerta personalizzata",
                min_value=_min_ui,
                max_value=max(_min_ui, _max_ui),
                value=_min_ui,
                step=float(incremento),
                key=f"team_bid_direct_value_{lotto['lot_id']}"
            )

            if st.button(
                "💰 INVIA OFFERTA PERSONALIZZATA",
                use_container_width=True,
                key=f"team_bid_direct_{lotto['lot_id']}"
            ):
                try:
                    inserisci_offerta_team_multilega(
                        league_id,
                        lotto["lot_id"],
                        team_id,
                        float(offerta_diretta)
                    )
                    st.session_state["team_bid_msg"] = (
                        f"Offerta di {float(offerta_diretta):g} crediti registrata."
                    )
                    st.rerun()
                except Exception as errore:
                    st.error(str(errore))

        _history_key = f"team_bid_history_{league_id}_{lotto['lot_id']}"
        if st.button(
            "📜 MOSTRA / NASCONDI ULTIME OFFERTE",
            use_container_width=True,
            key=f"team_bid_history_toggle_{league_id}_{lotto['lot_id']}"
        ):
            st.session_state[_history_key] = not bool(
                st.session_state.get(_history_key, False)
            )

        if st.session_state.get(_history_key, False):
            try:
                _storico_bids = stato_offerte_lotto_multilega(
                    league_id,
                    lotto["lot_id"],
                    20,
                    include_history=True
                )["bids"]
            except Exception as errore:
                _storico_bids = []
                st.warning("Impossibile leggere lo storico offerte: " + str(errore))

            if not _storico_bids:
                st.caption("Nessuna offerta registrata.")
            else:
                st.dataframe(
                    pd.DataFrame([
                        {
                            "Squadra": b["team"],
                            "Offerta": b["amount"],
                            "Data": b["created_at"],
                        }
                        for b in _storico_bids
                    ]),
                    use_container_width=True,
                    hide_index=True
                )

    if st.button(
        "⟳ AGGIORNA ORA",
        use_container_width=True,
        key="team_auction_refresh"
    ):
        st.session_state.pop(
            f"_ml37_console_workspace_ready_{league_id}_{team_id}",None
        )
        st.rerun()

    _console_perf["Totale"]=time.perf_counter()-_console_perf_start
    if "ADMIN" in RUOLI_ATTIVI and _console_perf["Totale"] >= 1.0:
        with st.expander("⏱ Diagnostica prestazioni Console Asta",expanded=False):
            st.dataframe(
                pd.DataFrame([
                    {"Fase":k,"Secondi":round(float(v),3)}
                    for k,v in _console_perf.items()
                ]),
                use_container_width=True,hide_index=True
            )




def elenco_giocatori_asta_multilega(league_id):
    league_id=int(league_id)
    inizializza_listone_lega_asta(league_id)
    conn=_portal_raw_connection()
    cur=conn.cursor()
    try:
        cur.execute("""
            SELECT
                g.player_id,
                COALESCE(g.nome,''),
                COALESCE(g.squadra,''),
                COALESCE(g.ruolo_mantra,''),
                COALESCE(g.fvm_mantra,g.fvm,0),
                COALESCE(lp.stato,'DISPONIBILE'),
                lp.assigned_team_id,
                lp.prezzo_assegnazione
            FROM league_player_catalog g
            JOIN league_players lp
              ON lp.player_id=g.player_id
             AND lp.league_id=g.league_id
            WHERE g.league_id=?
            ORDER BY g.nome COLLATE NOCASE
        """,(league_id,))
        return [
            {
                "player_id":int(r[0]),
                "nome":str(r[1]),
                "squadra":str(r[2]),
                "ruolo_mantra":str(r[3]),
                "fvm":float(r[4] or 0),
                "stato":str(r[5] or "DISPONIBILE"),
                "assigned_team_id":int(r[6]) if r[6] is not None else None,
                "prezzo":float(r[7]) if r[7] is not None else None,
            }
            for r in (cur.fetchall() or [])
        ]
    finally:
        _portal_close(conn)


def riepilogo_team_asta_multilega(league_id):
    """
    V123 - riepilogo squadre autorevole.

    Usa league_players per conteggio giocatori/prezzi assegnati.
    Non usa rosters, che può contenere righe legacy/importate non coerenti
    con lo stato live dell'asta.
    """
    league_id = int(league_id)
    inizializza_listone_lega_asta(league_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT
                COALESCE(soglia_budget,budget_iniziale,500),
                COALESCE(moltiplicatore_oltre_soglia,1)
            FROM league_rules
            WHERE league_id=?
            LIMIT 1
        """, (league_id,))
        _rr = cur.fetchone() or (500,1)
        _soglia = float(_rr[0] or 500)
        _moltiplicatore = max(1.0, float(_rr[1] or 1))

        cur.execute("""
            SELECT
                t.id,
                t.nome,
                COALESCE(b.budget_impostato,r.budget_iniziale,500),
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=t.id
                        THEN COALESCE(lp.prezzo_assegnazione,0)
                        ELSE 0
                    END
                ),0),
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=t.id
                        THEN 1 ELSE 0
                    END
                ),0),
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=t.id
                         AND (
                            UPPER(COALESCE(g.ruolo_classico,''))='P'
                            OR UPPER(COALESCE(g.ruolo_mantra,'')) IN ('P','POR')
                         )
                        THEN 1 ELSE 0
                    END
                ),0)
            FROM teams t
            LEFT JOIN league_rules r
              ON r.league_id=t.league_id
            LEFT JOIN team_budgets b
              ON b.league_id=t.league_id
             AND b.team_id=t.id
            LEFT JOIN league_players lp
              ON lp.league_id=t.league_id
             AND lp.assigned_team_id=t.id
             AND lp.stato='ASSEGNATO'
            LEFT JOIN league_player_catalog g
              ON g.league_id=lp.league_id
             AND g.player_id=lp.player_id
            WHERE t.league_id=? AND t.is_active=1
            GROUP BY
                t.id,t.nome,t.posizione,
                b.budget_impostato,r.budget_iniziale
            ORDER BY t.posizione,t.id
        """, (league_id,))

        result = []
        for r in (cur.fetchall() or []):
            valore = float(r[3] or 0)
            result.append({
                "team_id": int(r[0]),
                "nome": str(r[1]),
                "budget": float(r[2] or 0),
                "valore_acquisti": valore,
                "spesa_effettiva": float(
                    _spesa_effettiva_regole(
                        valore,
                        _soglia,
                        _moltiplicatore
                    )
                ),
                "giocatori": int(r[4] or 0),
                "portieri": int(r[5] or 0),
            })
        return result
    finally:
        _portal_close(conn)




def assegna_giocatore_banditore(league_id, player_id, team_id, prezzo):
    """
    Assegnazione server-side autorevole:
    - verifica ruolo Banditore/Admin
    - verifica giocatore disponibile
    - verifica squadra attiva e capienza rosa
    - verifica budget effettivo
    - aggiorna league_players, rosters, team_budgets e audit
    - sincronizza anche il workspace operativo della squadra target
    """
    league_id=int(league_id)
    player_id=int(player_id)
    team_id=int(team_id)
    prezzo=float(prezzo)

    if prezzo < 0:
        raise ValueError("Il prezzo non può essere negativo.")

    user_id=int(st.session_state.get("auth_user_id") or 0)
    conn=_portal_raw_connection()
    cur=conn.cursor()

    try:
        cur.execute("""
            SELECT COUNT(*)
            FROM league_members
            WHERE league_id=? AND user_id=? AND is_active=1
              AND (is_auctioneer=1 OR is_admin=1)
        """,(league_id,user_id))
        if int(cur.fetchone()[0] or 0)==0:
            raise PermissionError("Operazione riservata a Banditore o Admin.")

        cur.execute("""
            SELECT stato,assigned_team_id
            FROM league_players
            WHERE league_id=? AND player_id=?
            LIMIT 1
        """,(league_id,player_id))
        rp=cur.fetchone()
        if not rp:
            raise ValueError("Giocatore non presente nel listone della lega.")
        if str(rp[0] or "").upper()!="DISPONIBILE":
            raise ValueError("Il giocatore non è più disponibile.")

        cur.execute("""
            SELECT nome FROM teams
            WHERE league_id=? AND id=? AND is_active=1
            LIMIT 1
        """,(league_id,team_id))
        rt=cur.fetchone()
        if not rt:
            raise ValueError("Squadra non valida.")
        nome_team=str(rt[0])

        # V108: se l'assegnazione riguarda il lotto corrente e sono presenti
        # offerte, il server accetta esclusivamente il miglior offerente e
        # il relativo importo. Non è più soltanto un vincolo dell'interfaccia.
        cur.execute("""
            SELECT s.current_lot_id,l.stato,l.player_id
            FROM auction_sessions s
            LEFT JOIN auction_lots l ON l.id=s.current_lot_id
            WHERE s.league_id=?
            LIMIT 1
        """,(league_id,))
        _lot_auth=cur.fetchone()

        if (
            _lot_auth
            and _lot_auth[0] is not None
            and _lot_auth[2] is not None
            and int(_lot_auth[2])==player_id
        ):
            _lot_auth_id=int(_lot_auth[0])
            _lot_auth_state=str(_lot_auth[1] or "").upper()

            cur.execute("""
                SELECT current_team_id,current_bid
                FROM auction_lots
                WHERE league_id=? AND id=?
                LIMIT 1
            """,(league_id,_lot_auth_id))
            _best_auth=cur.fetchone()

            if _best_auth:
                if _lot_auth_state!="CLOSING":
                    raise ValueError(
                        "Prima dell'assegnazione devi chiudere le offerte."
                    )

                if (
                    int(_best_auth[0])!=team_id
                    or abs(float(_best_auth[1] or 0)-prezzo)>0.0001
                ):
                    raise ValueError(
                        "Assegnazione rifiutata: squadra o prezzo non coincidono "
                        "con la migliore offerta registrata."
                    )

        cur.execute("""
            SELECT
                COALESCE(max_giocatori,30),
                COALESCE(budget_iniziale,500),
                COALESCE(soglia_budget,500),
                COALESCE(moltiplicatore_oltre_soglia,1)
            FROM league_rules
            WHERE league_id=?
            LIMIT 1
        """,(league_id,))
        rr=cur.fetchone()
        if not rr:
            raise ValueError("Regolamento della lega non trovato.")

        max_giocatori=int(rr[0] or 30)
        budget_default=float(rr[1] or 500)
        soglia=float(rr[2] or budget_default)
        moltiplicatore=max(1,float(rr[3] or 1))

        cur.execute("""
            SELECT COALESCE(min_portieri,0)
            FROM league_rules
            WHERE league_id=?
            LIMIT 1
        """,(league_id,))
        _r_min_p=cur.fetchone()
        _min_portieri=int(_r_min_p[0] or 0) if _r_min_p else 0

        cur.execute("""
            SELECT
                COALESCE(SUM(
                    CASE
                        WHEN stato='ASSEGNATO' AND assigned_team_id=?
                        THEN 1 ELSE 0
                    END
                ),0),
                COALESCE(SUM(
                    CASE
                        WHEN stato='ASSEGNATO' AND assigned_team_id=?
                        THEN COALESCE(prezzo_assegnazione,0)
                        ELSE 0
                    END
                ),0)
            FROM league_players
            WHERE league_id=?
        """,(team_id,team_id,league_id))
        roster_count,valore_attuale=cur.fetchone()
        roster_count=int(roster_count or 0)
        valore_attuale=float(valore_attuale or 0)

        if roster_count >= max_giocatori:
            raise ValueError("La rosa della squadra è già completa.")

        cur.execute("""
            SELECT
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=?
                         AND (
                            UPPER(COALESCE(c.ruolo_classico,''))='P'
                            OR UPPER(COALESCE(c.ruolo_mantra,'')) IN ('P','POR')
                         )
                        THEN 1 ELSE 0
                    END
                ),0)
            FROM league_players lp
            LEFT JOIN league_player_catalog c
              ON c.league_id=lp.league_id
             AND c.player_id=lp.player_id
            WHERE lp.league_id=?
        """,(team_id,league_id))
        _r_portieri=cur.fetchone()
        _portieri_attuali=int(_r_portieri[0] or 0) if _r_portieri else 0

        cur.execute("""
            SELECT COALESCE(ruolo_classico,''),COALESCE(ruolo_mantra,'')
            FROM league_player_catalog
            WHERE league_id=? AND player_id=?
            LIMIT 1
        """,(league_id,player_id))
        _r_ruolo=cur.fetchone()

        _is_portiere=bool(
            _r_ruolo
            and (
                str(_r_ruolo[0] or "").strip().upper()=="P"
                or str(_r_ruolo[1] or "").strip().upper() in ("P","POR")
            )
        )

        _slot_dopo=max(0,max_giocatori-(roster_count+1))
        _portieri_dopo=_portieri_attuali+(1 if _is_portiere else 0)
        _portieri_mancanti=max(0,_min_portieri-_portieri_dopo)

        if _slot_dopo < _portieri_mancanti:
            raise ValueError(
                "Assegnazione non consentita: non resterebbero abbastanza "
                "slot per raggiungere il numero minimo di portieri."
            )

        cur.execute("""
            SELECT COALESCE(budget_impostato,?)
            FROM team_budgets
            WHERE league_id=? AND team_id=?
            LIMIT 1
        """,(budget_default,league_id,team_id))
        rb=cur.fetchone()
        budget=float(rb[0] if rb else budget_default)

        nuovo_valore=round(valore_attuale+prezzo,2)
        if nuovo_valore <= soglia:
            nuova_spesa=nuovo_valore
        else:
            nuova_spesa=round(soglia+(nuovo_valore-soglia)*moltiplicatore,2)

        if nuova_spesa > budget + 1e-9:
            raise ValueError(
                "Budget insufficiente: la spesa effettiva diventerebbe "
                + f"{nuova_spesa:.2f} su {budget:.2f} crediti."
            )

        cur.execute("""
            UPDATE league_players
            SET stato='ASSEGNATO',
                assigned_team_id=?,
                prezzo_assegnazione=?,
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND player_id=? AND stato='DISPONIBILE'
        """,(team_id,prezzo,league_id,player_id))

        if cur.rowcount==0:
            raise ValueError("Il giocatore è stato appena assegnato da un'altra operazione.")

        cur.execute("""
            INSERT INTO rosters (
                league_id,team_id,player_id,prezzo_acquisto,fonte,assigned_at,updated_at
            )
            VALUES (?,?,?,?,'AUCTIONEER',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
            ON CONFLICT(league_id,team_id,player_id)
            DO UPDATE SET
                prezzo_acquisto=excluded.prezzo_acquisto,
                fonte='AUCTIONEER',
                updated_at=CURRENT_TIMESTAMP
        """,(league_id,team_id,player_id,prezzo))

        cur.execute("""
            INSERT INTO team_budgets (
                league_id,team_id,budget_impostato,valore_acquisti,spesa_effettiva,updated_at
            )
            VALUES (?,?,?,?,?,CURRENT_TIMESTAMP)
            ON CONFLICT(league_id,team_id)
            DO UPDATE SET
                valore_acquisti=excluded.valore_acquisti,
                spesa_effettiva=excluded.spesa_effettiva,
                updated_at=CURRENT_TIMESTAMP
        """,(league_id,team_id,budget,nuovo_valore,nuova_spesa))

        cur.execute("""
            INSERT INTO auction_assignment_history (
                league_id,player_id,team_id,prezzo,stato,
                assigned_by_user_id,assigned_at
            )
            VALUES (?,?,?,?,'ACTIVE',?,CURRENT_TIMESTAMP)
        """,(league_id,player_id,team_id,prezzo,user_id))

        cur.execute("SELECT last_insert_rowid()")
        _hist_row=cur.fetchone()
        history_id=int(_hist_row[0]) if _hist_row and _hist_row[0] is not None else 0

        # Sincronizza il workspace fisico della squadra target.
        tab_team="giocatori_ml_l"+str(league_id)+"_t"+str(team_id)
        try:
            cur.execute(
                f"""UPDATE {tab_team}
                    SET stato='MIO',
                        prezzo_acquisto=?,
                        ultimo_aggiornamento=CURRENT_TIMESTAMP
                    WHERE id=?""",
                (prezzo,player_id)
            )
        except Exception:
            # Se il team non ha mai aperto l'app, il suo workspace può
            # non esistere ancora: rosters resta comunque autorevole.
            pass

        # Se il giocatore assegnato è quello del lotto corrente,
        # il lotto viene chiuso nella stessa transazione.
        cur.execute("""
            SELECT s.current_lot_id,l.player_id
            FROM auction_sessions s
            LEFT JOIN auction_lots l ON l.id=s.current_lot_id
            WHERE s.league_id=?
            LIMIT 1
        """, (league_id,))
        _lot_current = cur.fetchone()

        if (
            _lot_current
            and _lot_current[0] is not None
            and _lot_current[1] is not None
            and int(_lot_current[1]) == player_id
        ):
            _lot_id = int(_lot_current[0])

            cur.execute("""
                UPDATE auction_lots
                SET stato='ASSIGNED',
                    assigned_team_id=?,
                    final_price=?,
                    closed_at=CURRENT_TIMESTAMP
                WHERE id=? AND league_id=? AND stato IN ('OPEN','CLOSING')
            """, (team_id, prezzo, _lot_id, league_id))

            cur.execute("""
                UPDATE auction_sessions
                SET current_lot_id=NULL,
                    stato='READY',
                    updated_at=CURRENT_TIMESTAMP
                WHERE league_id=? AND current_lot_id=?
            """, (league_id, _lot_id))

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,team_id,azione,entita,entita_id,dettagli_json,created_at
            )
            VALUES (?,?,?,'PLAYER_ASSIGNED','PLAYER',?,?,CURRENT_TIMESTAMP)
        """,(
            league_id,user_id,team_id,str(player_id),
            json.dumps({
                "prezzo":prezzo,
                "team":nome_team,
                "history_id":history_id,
                "valore_acquisti":nuovo_valore,
                "spesa_effettiva":nuova_spesa
            },ensure_ascii=False)
        ))

        conn.commit()
        return {
            "team":nome_team,
            "valore_acquisti":nuovo_valore,
            "spesa_effettiva":nuova_spesa,
            "budget":budget
        }

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)



def ultime_assegnazioni_banditore(league_id, limit=15):
    league_id=int(league_id)
    inizializza_listone_lega_asta(league_id)
    conn=_portal_raw_connection()
    cur=conn.cursor()
    try:
        cur.execute("""
            SELECT
                h.id,
                h.player_id,
                COALESCE(g.nome,''),
                COALESCE(g.squadra,''),
                COALESCE(g.ruolo_mantra,''),
                h.team_id,
                COALESCE(t.nome,''),
                h.prezzo,
                h.stato,
                COALESCE(u.username,''),
                h.assigned_at,
                COALESCE(uu.username,''),
                h.undone_at
            FROM auction_assignment_history h
            LEFT JOIN league_player_catalog g ON g.player_id=h.player_id AND g.league_id=h.league_id
            LEFT JOIN teams t ON t.id=h.team_id AND t.league_id=h.league_id
            LEFT JOIN users u ON u.id=h.assigned_by_user_id
            LEFT JOIN users uu ON uu.id=h.undone_by_user_id
            WHERE h.league_id=?
            ORDER BY h.id DESC
            LIMIT ?
        """,(league_id,int(limit)))
        return [
            {
                "history_id":int(r[0]),
                "player_id":int(r[1]),
                "giocatore":str(r[2]),
                "squadra_reale":str(r[3]),
                "ruolo":str(r[4]),
                "team_id":int(r[5]),
                "team":str(r[6]),
                "prezzo":float(r[7] or 0),
                "stato":str(r[8] or ""),
                "assegnato_da":str(r[9] or ""),
                "assegnato_il":str(r[10] or ""),
                "annullato_da":str(r[11] or ""),
                "annullato_il":str(r[12] or ""),
            }
            for r in (cur.fetchall() or [])
        ]
    finally:
        _portal_close(conn)


def annulla_assegnazione_banditore(league_id, history_id):
    """
    Annulla una singola assegnazione ancora ACTIVE.

    L'annullamento è consentito solo se il giocatore risulta ancora assegnato
    alla stessa squadra e allo stesso prezzo. In questo modo non si può
    annullare una vecchia assegnazione dopo successive modifiche.
    """
    league_id=int(league_id)
    history_id=int(history_id)
    user_id=int(st.session_state.get("auth_user_id") or 0)

    conn=_portal_raw_connection()
    cur=conn.cursor()
    try:
        cur.execute("""
            SELECT COUNT(*)
            FROM league_members
            WHERE league_id=? AND user_id=? AND is_active=1
              AND (is_auctioneer=1 OR is_admin=1)
        """,(league_id,user_id))
        if int(cur.fetchone()[0] or 0)==0:
            raise PermissionError("Operazione riservata a Banditore o Admin.")

        cur.execute("""
            SELECT player_id,team_id,prezzo,stato
            FROM auction_assignment_history
            WHERE id=? AND league_id=?
            LIMIT 1
        """,(history_id,league_id))
        rh=cur.fetchone()
        if not rh:
            raise ValueError("Assegnazione non trovata.")

        player_id=int(rh[0]); team_id=int(rh[1]); prezzo=float(rh[2] or 0)
        if str(rh[3] or "").upper()!="ACTIVE":
            raise ValueError("Questa assegnazione è già stata annullata.")

        cur.execute("""
            SELECT stato,assigned_team_id,prezzo_assegnazione
            FROM league_players
            WHERE league_id=? AND player_id=?
            LIMIT 1
        """,(league_id,player_id))
        rp=cur.fetchone()
        if not rp:
            raise ValueError("Stato del giocatore non trovato.")

        stato=str(rp[0] or "").upper()
        team_corrente=int(rp[1]) if rp[1] is not None else None
        prezzo_corrente=float(rp[2] or 0) if rp[2] is not None else None

        if stato!="ASSEGNATO" or team_corrente!=team_id:
            raise ValueError(
                "L'assegnazione non è più quella corrente: annullamento bloccato."
            )
        if prezzo_corrente is None or abs(prezzo_corrente-prezzo)>0.0001:
            raise ValueError(
                "Il prezzo corrente non coincide con l'assegnazione da annullare."
            )

        cur.execute("""
            DELETE FROM rosters
            WHERE league_id=? AND team_id=? AND player_id=?
        """,(league_id,team_id,player_id))

        cur.execute("""
            UPDATE league_players
            SET stato='DISPONIBILE',
                assigned_team_id=NULL,
                prezzo_assegnazione=NULL,
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND player_id=?
        """,(league_id,player_id))

        # Ricalcolo autorevole del valore acquisti della squadra
        cur.execute("""
            SELECT
                COALESCE(SUM(prezzo_acquisto),0)
            FROM rosters
            WHERE league_id=? AND team_id=?
        """,(league_id,team_id))
        valore=float(cur.fetchone()[0] or 0)

        cur.execute("""
            SELECT
                COALESCE(budget_iniziale,500),
                COALESCE(soglia_budget,500),
                COALESCE(moltiplicatore_oltre_soglia,1)
            FROM league_rules
            WHERE league_id=?
            LIMIT 1
        """,(league_id,))
        rr=cur.fetchone()
        budget_default=float(rr[0] or 500) if rr else 500.0
        soglia=float(rr[1] or budget_default) if rr else budget_default
        moltiplicatore=max(1,float(rr[2] or 1)) if rr else 1.0

        if valore <= soglia:
            spesa=round(valore,2)
        else:
            spesa=round(soglia+(valore-soglia)*moltiplicatore,2)

        cur.execute("""
            SELECT budget_impostato
            FROM team_budgets
            WHERE league_id=? AND team_id=?
            LIMIT 1
        """,(league_id,team_id))
        rb=cur.fetchone()
        budget=float(rb[0]) if rb and rb[0] is not None else budget_default

        cur.execute("""
            INSERT INTO team_budgets (
                league_id,team_id,budget_impostato,valore_acquisti,
                spesa_effettiva,updated_at
            )
            VALUES (?,?,?,?,?,CURRENT_TIMESTAMP)
            ON CONFLICT(league_id,team_id)
            DO UPDATE SET
                valore_acquisti=excluded.valore_acquisti,
                spesa_effettiva=excluded.spesa_effettiva,
                updated_at=CURRENT_TIMESTAMP
        """,(league_id,team_id,budget,valore,spesa))

        # Sincronizza anche il workspace della squadra, se già esistente.
        tab_team="giocatori_ml_l"+str(league_id)+"_t"+str(team_id)
        try:
            cur.execute(
                f"""UPDATE {tab_team}
                    SET stato='DISPONIBILE',
                        prezzo_acquisto=NULL,
                        ultimo_aggiornamento=CURRENT_TIMESTAMP
                    WHERE id=?""",
                (player_id,)
            )
        except Exception:
            pass

        cur.execute("""
            UPDATE auction_assignment_history
            SET stato='UNDONE',
                undone_by_user_id=?,
                undone_at=CURRENT_TIMESTAMP
            WHERE id=? AND league_id=? AND stato='ACTIVE'
        """,(user_id,history_id,league_id))

        if cur.rowcount==0:
            raise ValueError("L'assegnazione è già stata annullata.")

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,team_id,azione,entita,entita_id,
                dettagli_json,created_at
            )
            VALUES (?,?,?,'PLAYER_ASSIGNMENT_UNDONE','PLAYER',?,?,CURRENT_TIMESTAMP)
        """,(
            league_id,user_id,team_id,str(player_id),
            json.dumps({
                "history_id":history_id,
                "prezzo_annullato":prezzo,
                "valore_acquisti_dopo":valore,
                "spesa_effettiva_dopo":spesa
            },ensure_ascii=False)
        ))

        conn.commit()
        return {
            "player_id":player_id,
            "team_id":team_id,
            "prezzo":prezzo,
            "valore_acquisti":valore,
            "spesa_effettiva":spesa
        }

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)



# ============================================================
# V153 - RESET SPESE + UNDO GESTIONE ASTA
# ============================================================

def reset_spese_squadra_asta_v153(league_id, team_id):
    """
    Azzera integralmente la spesa d'asta della squadra senza cancellare la rosa.

    - i giocatori attualmente assegnati restano in rosa ma con costo corrente 0;
    - i costi degli svincoli vengono disattivati;
    - il budget torna integralmente disponibile;
    - lo storico ACTIVE viene riallineato a prezzo 0 per mantenere coerente l'UNDO;
    - l'operazione viene registrata nell'audit log.
    """
    league_id = int(league_id)
    team_id = int(team_id)
    user_id = int(st.session_state.get("auth_user_id") or 0)

    assicura_schema_storico_asta_v147(league_id)
    conn = _portal_raw_connection()
    cur = conn.cursor()

    try:
        # V163 - autorizzazione, squadra e fotografia pre-reset in un'unica query.
        cur.execute("""
            SELECT
                EXISTS(
                    SELECT 1 FROM league_members lm
                    WHERE lm.league_id=? AND lm.user_id=? AND lm.is_active=1
                      AND (lm.is_auctioneer=1 OR lm.is_admin=1)
                ),
                t.nome,
                COALESCE((
                    SELECT COUNT(*) FROM league_players lp
                    WHERE lp.league_id=? AND lp.assigned_team_id=?
                      AND lp.stato='ASSEGNATO'
                ),0),
                COALESCE((
                    SELECT SUM(COALESCE(lp.prezzo_assegnazione,0))
                    FROM league_players lp
                    WHERE lp.league_id=? AND lp.assigned_team_id=?
                      AND lp.stato='ASSEGNATO'
                ),0),
                COALESCE((
                    SELECT SUM(COALESCE(rc.costo,0))
                    FROM auction_release_costs rc
                    WHERE rc.league_id=? AND rc.team_id=? AND rc.active=1
                ),0),
                COALESCE((
                    SELECT COUNT(*) FROM auction_release_costs rc
                    WHERE rc.league_id=? AND rc.team_id=? AND rc.active=1
                ),0)
            FROM teams t
            WHERE t.league_id=? AND t.id=? AND t.is_active=1
            LIMIT 1
        """, (
            league_id,user_id,
            league_id,team_id,
            league_id,team_id,
            league_id,team_id,
            league_id,team_id,
            league_id,team_id
        ))
        pre = cur.fetchone()
        if not pre:
            raise ValueError("Squadra non valida o non attiva.")
        if not bool(pre[0]):
            raise PermissionError("Operazione riservata al Banditore/Admin.")

        team_nome = str(pre[1] or "")
        giocatori_attivi = int(pre[2] or 0)
        valore_attivi_prima = float(pre[3] or 0)
        costo_svincoli_prima = float(pre[4] or 0)
        svincoli_attivi = int(pre[5] or 0)

        # I giocatori restano assegnati ma non generano più spesa.
        cur.execute("""
            UPDATE league_players
            SET prezzo_assegnazione=0,
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=?
              AND assigned_team_id=?
              AND stato='ASSEGNATO'
        """, (league_id, team_id))

        # V163 - rosters è una proiezione legacy: la Rosa legge league_players.
        # Evitiamo una scrittura remota non necessaria nel percorso critico.

        # Gli svincoli pregressi non devono più consumare crediti.
        cur.execute("""
            UPDATE auction_release_costs
            SET active=0,
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND team_id=? AND active=1
        """, (league_id, team_id))

        # Mantiene annullabili le assegnazioni correnti dopo il reset.
        cur.execute("""
            UPDATE auction_assignment_history
            SET prezzo=0
            WHERE league_id=?
              AND team_id=?
              AND stato='ACTIVE'
        """, (league_id, team_id))

        # V163 - nessun update del workspace legacy nel percorso critico.
        # Tutte le viste correnti derivano dallo stato centrale league_players.

        _ricalcola_budget_team_v147(cur, league_id, team_id)

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,team_id,azione,
                entita,entita_id,dettagli_json,created_at
            )
            VALUES (?,?,?,'AUCTION_EXPENSES_RESET','TEAM',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            user_id,
            team_id,
            str(team_id),
            json.dumps({
                "team": team_nome,
                "giocatori_attivi": giocatori_attivi,
                "valore_attivi_prima": valore_attivi_prima,
                "svincoli_attivi": svincoli_attivi,
                "costo_svincoli_prima": costo_svincoli_prima,
                "crediti_riassegnati": round(
                    valore_attivi_prima + costo_svincoli_prima, 2
                ),
                "valore_acquisti_dopo": 0,
                "spesa_effettiva_dopo": 0,
            }, ensure_ascii=False)
        ))

        conn.commit()
        return {
            "team_id": team_id,
            "team": team_nome,
            "giocatori_attivi": giocatori_attivi,
            "valore_attivi_prima": valore_attivi_prima,
            "costo_svincoli_prima": costo_svincoli_prima,
            "crediti_riassegnati": round(
                valore_attivi_prima + costo_svincoli_prima, 2
            ),
        }

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)


def reset_assegnazioni_asta_v179(league_id):
    """V180 - Reset globale dell'asta: assegnazioni e storico chiamate tornano a zero."""
    league_id = int(league_id)
    user_id = int(st.session_state.get("auth_user_id") or 0)
    assicura_schema_storico_asta_v147(league_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT EXISTS(
                SELECT 1 FROM league_members lm
                WHERE lm.league_id=? AND lm.user_id=? AND lm.is_active=1
                  AND (lm.is_auctioneer=1 OR lm.is_admin=1)
            )
        """, (league_id, user_id))
        allowed = bool((cur.fetchone() or (0,))[0])
        if not allowed:
            raise PermissionError("Operazione riservata al Banditore/Admin.")

        cur.execute("""
            SELECT COUNT(*), COALESCE(SUM(COALESCE(prezzo_assegnazione,0)),0)
            FROM league_players
            WHERE league_id=? AND stato='ASSEGNATO'
        """, (league_id,))
        r = cur.fetchone() or (0, 0)
        numero_assegnazioni = int(r[0] or 0)
        valore_assegnazioni = float(r[1] or 0)

        # Tutti i giocatori assegnati tornano disponibili.
        cur.execute("""
            UPDATE league_players
            SET stato='DISPONIBILE', assigned_team_id=NULL,
                prezzo_assegnazione=NULL, updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND stato='ASSEGNATO'
        """, (league_id,))

        # Pulisce la proiezione rosa legacy.
        cur.execute("DELETE FROM rosters WHERE league_id=?", (league_id,))

        # Nessun costo di svincolo deve sopravvivere a un reset globale.
        cur.execute("""
            UPDATE auction_release_costs
            SET active=0, updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND active=1
        """, (league_id,))

        # Le vecchie assegnazioni non sono più annullabili come ACTIVE.
        cur.execute("""
            UPDATE auction_assignment_history
            SET stato='RESET', undone_by_user_id=?, undone_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND stato='ACTIVE'
        """, (user_id, league_id))

        # I lotti restano nello storico delle chiamate, ma non risultano assegnati.
        cur.execute("""
            UPDATE auction_lots
            SET stato='CLOSED', assigned_team_id=NULL, final_price=NULL,
                closed_at=COALESCE(closed_at,CURRENT_TIMESTAMP)
            WHERE league_id=? AND stato='ASSIGNED'
        """, (league_id,))

        # V180 - RESET ASSEGNAZIONI deve riportare anche lo STORICO ASTA a zero.
        # Non cancelliamo fisicamente auction_called_players: li rendiamo inattivi.
        # In questo modo il backfill idempotente dei vecchi lotti non può farli
        # ricomparire al successivo riavvio, mentre una nuova chiamata li riattiva.
        cur.execute("""
            UPDATE auction_called_players
            SET active=0, updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND COALESCE(active,1)=1
        """, (league_id,))

        # Azzera anche la memoria dei giocatori saltati/chiamati dalla modalità
        # RANDOM/ALFABETICO, così il nuovo ciclo d'asta riparte davvero da zero.
        try:
            cur.execute("""
                UPDATE auction_mode_state
                SET skipped_players_json='[]', updated_at=CURRENT_TIMESTAMP
                WHERE league_id=?
            """, (league_id,))
        except Exception:
            pass

        # Nessuna vecchia esclusione deve interferire con il nuovo ciclo d'asta.
        cur.execute("DELETE FROM auction_history_exclusions WHERE league_id=?", (league_id,))

        # V181 - dopo un reset globale non serve ricalcolare una squadra alla volta:
        # tutte le rose sono vuote, quindi valore acquisti e spesa sono entrambi zero.
        cur.execute("""
            UPDATE team_budgets
            SET valore_acquisti=0,
                spesa_effettiva=0,
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=?
        """, (league_id,))
        cur.execute(
            "SELECT COUNT(*) FROM teams WHERE league_id=? AND is_active=1",
            (league_id,)
        )
        squadre_ricalcolate = int((cur.fetchone() or (0,))[0] or 0)

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,team_id,azione,entita,entita_id,dettagli_json,created_at
            ) VALUES (?,?,NULL,'AUCTION_ASSIGNMENTS_RESET','LEAGUE',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id, user_id, str(league_id),
            json.dumps({
                "assegnazioni_resettate": numero_assegnazioni,
                "valore_assegnazioni": valore_assegnazioni,
                "storico_chiamate_azzerato": True,
                "squadre_ricalcolate": squadre_ricalcolate
            }, ensure_ascii=False)
        ))
        conn.commit()
        return {
            "assegnazioni_resettate": numero_assegnazioni,
            "valore_assegnazioni": valore_assegnazioni,
        }
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)


