@st.dialog("Reset spese squadra")
def dialog_reset_spese_asta_v153(league_id):
    league_id = int(league_id)
    teams = squadre_storico_v147(league_id)

    if not teams:
        st.info("Nessuna squadra attiva disponibile.")
        return

    st.warning(
        "Il reset restituisce alla squadra tutti i crediti spesi, "
        "compresi i costi derivanti dagli svincoli. "
        "La rosa NON viene cancellata: i giocatori già assegnati restano in squadra."
    )

    _nomi = [x["nome"] for x in teams]
    _by_name = {x["nome"]: int(x["team_id"]) for x in teams}

    scelta = st.selectbox(
        "Per quale squadra vuoi resettare le spese?",
        ["— Seleziona una squadra —"] + _nomi,
        index=0,
        key=f"v153_reset_expenses_team_{league_id}"
    )

    if scelta == "— Seleziona una squadra —":
        st.info("Seleziona la squadra da resettare. Nessuna operazione verrà eseguita senza conferma.")
        return

    team_id = _by_name[scelta]

    # Mostra l'impatto prima della conferma.
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT
                COALESCE(SUM(CASE WHEN lp.stato='ASSEGNATO' AND lp.assigned_team_id=?
                                  THEN COALESCE(lp.prezzo_assegnazione,0) ELSE 0 END),0),
                COALESCE((SELECT SUM(COALESCE(rc.costo,0))
                          FROM auction_release_costs rc
                          WHERE rc.league_id=? AND rc.team_id=? AND rc.active=1),0)
            FROM league_players lp
            WHERE lp.league_id=?
        """, (team_id, league_id, team_id, league_id))
        imp = cur.fetchone() or (0, 0)
        _attivi = float(imp[0] or 0)
        _svincoli = float(imp[1] or 0)
    finally:
        _portal_close(conn)

    st.info(
        f"**{scelta}** · spesa giocatori: {formatta_crediti(_attivi)} · "
        f"costi svincoli: {formatta_crediti(_svincoli)} · "
        f"crediti da riassegnare: **{formatta_crediti(_attivi + _svincoli)}**"
    )

    conferma = st.checkbox(
        f"Confermo di voler resettare le spese della squadra {scelta}",
        key=f"v153_reset_expenses_confirm_{league_id}_{team_id}"
    )

    c1, c2 = st.columns(2)
    with c1:
        if st.button(
            "✅ CONFERMA RESET",
            type="primary",
            use_container_width=True,
            disabled=not conferma,
            key=f"v153_reset_expenses_execute_{league_id}_{team_id}"
        ):
            try:
                esito = reset_spese_squadra_asta_v153(league_id, team_id)
                # V163 - aggiorna direttamente la tabella Storico già in RAM:
                # i giocatori restano assegnati, ma il prezzo diventa 0.
                _hk = f"_v156_history_{league_id}"
                _hc = st.session_state.get(_hk)
                if isinstance(_hc, dict) and isinstance(_hc.get("df"), pd.DataFrame):
                    _hdf = _hc["df"].copy()
                    if "ASSEGNATO A" in _hdf.columns and "PREZZO" in _hdf.columns:
                        _hdf.loc[
                            _hdf["ASSEGNATO A"].fillna("").astype(str) == str(esito["team"]),
                            "PREZZO"
                        ] = 0.0
                    st.session_state[_hk] = {"ts": time.monotonic(), "df": _hdf}

                st.session_state.pop("_ultime_operazioni_sessione", None)
                st.session_state.pop("_costi_svincoli_sessione", None)
                st.session_state["v154_storico_reset_msg"] = (
                    f'♻️ Spese di {esito["team"]} azzerate. '
                    f'Riassegnati {formatta_crediti(esito["crediti_riassegnati"])} crediti.'
                )
                st.rerun()
            except Exception as errore:
                st.error(str(errore))

    with c2:
        if st.button(
            "ANNULLA",
            use_container_width=True,
            key=f"v153_reset_expenses_cancel_{league_id}"
        ):
            st.rerun()


@st.dialog("Undo ultime operazioni asta")
def dialog_undo_asta_v153(league_id):
    league_id = int(league_id)
    operazioni = ultime_assegnazioni_banditore(league_id, limit=10)

    st.caption(
        "Sono mostrate le ultime 10 aggiudicazioni registrate. "
        "È annullabile solo un'assegnazione ancora attiva e coerente con la rosa corrente."
    )

    if not operazioni:
        st.info("Non ci sono operazioni d'asta da annullare.")
        return

    opzioni = []
    mapping = {}
    for idx, op in enumerate(operazioni, start=1):
        stato = str(op.get("stato") or "").upper()
        label = (
            f'{idx}. {op["giocatore"]} → {op["team"]} · '
            f'{formatta_crediti(op["prezzo"])} cr · {stato}'
        )
        opzioni.append(label)
        mapping[label] = op

    scelta = st.selectbox(
        "Operazione da annullare",
        opzioni,
        key=f"v153_undo_auction_select_{league_id}"
    )
    op = mapping[scelta]
    annullabile = str(op.get("stato") or "").upper() == "ACTIVE"

    if annullabile:
        st.warning(
            f'Annullando questa operazione **{op["giocatore"]}** tornerà disponibile '
            f'e i {formatta_crediti(op["prezzo"])} crediti verranno restituiti a '
            f'**{op["team"]}**.'
        )
    else:
        st.info(
            "Questa operazione non è più attiva ed è mostrata solo per completezza storica."
        )

    conferma = st.checkbox(
        "Confermo l'annullamento dell'operazione selezionata",
        disabled=not annullabile,
        key=f'v153_undo_confirm_{league_id}_{op["history_id"]}'
    )

    c1, c2 = st.columns(2)
    with c1:
        if st.button(
            "↩️ CONFERMA UNDO",
            type="primary",
            use_container_width=True,
            disabled=(not annullabile or not conferma),
            key=f'v153_undo_execute_{league_id}_{op["history_id"]}'
        ):
            try:
                annulla_assegnazione_banditore(
                    league_id,
                    int(op["history_id"])
                )
                invalida_cache_dati()
                st.session_state.pop("_titolarita_cache", None)
                st.session_state.pop("_formazioni_tipo_fast_cache", None)
                st.session_state["auctioneer_msg"] = (
                    f'↩️ Annullata assegnazione di {op["giocatore"]} a {op["team"]}.'
                )
                st.rerun()
            except Exception as errore:
                st.error(str(errore))

    with c2:
        if st.button(
            "CHIUDI",
            use_container_width=True,
            key=f"v153_undo_close_{league_id}"
        ):
            st.rerun()


def audit_asta_multilega(league_id, limit=100):
    league_id=int(league_id)
    conn=_portal_raw_connection()
    cur=conn.cursor()
    try:
        cur.execute("""
            SELECT
                a.id,
                a.azione,
                COALESCE(u.username,''),
                COALESCE(t.nome,''),
                a.entita_id,
                COALESCE(a.dettagli_json,''),
                a.created_at
            FROM audit_log a
            LEFT JOIN users u ON u.id=a.user_id
            LEFT JOIN teams t
              ON t.id=a.team_id AND t.league_id=a.league_id
            WHERE a.league_id=?
              AND a.azione IN (
                'PLAYER_ASSIGNED',
                'PLAYER_ASSIGNMENT_UNDONE',
                'BID_PLACED',
                'LOT_CLOSING',
                'LOT_REOPENED',
                'PLAYER_CALLED'
              )
            ORDER BY a.id DESC
            LIMIT ?
        """,(league_id,int(limit)))
        return [
            {
                "id":int(r[0]),
                "azione":str(r[1]),
                "utente":str(r[2]),
                "squadra":str(r[3]),
                "player_id":str(r[4] or ""),
                "dettagli":str(r[5] or ""),
                "data":str(r[6] or "")
            }
            for r in (cur.fetchall() or [])
        ]
    finally:
        _portal_close(conn)



def tipo_asta_lega_multilega(league_id):
    league_id = int(league_id)
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT COALESCE(tipo_asta,'CHIAMATA')
            FROM league_rules
            WHERE league_id=?
            LIMIT 1
        """, (league_id,))
        r = cur.fetchone()
        valore = str(r[0] if r and r[0] is not None else "CHIAMATA").strip().upper()

        aliases = {
            "A CHIAMATA": "CHIAMATA",
            "CHIAMATA": "CHIAMATA",
            "ALFABETICO": "ALFABETICO",
            "RANDOM": "RANDOM",
            "CASUALE": "RANDOM",
            "DRAFT": "DRAFT",
        }
        return aliases.get(valore, valore)
    finally:
        _portal_close(conn)


def inizializza_stato_modalita_asta(league_id):
    """
    Stato persistente minimo necessario per RANDOM / ALFABETICO / CHIAMATA / DRAFT.

    V164 PERFORMANCE MAX: la migrazione DDL viene eseguita una sola volta per
    sessione/lega. Prima questa funzione faceva CREATE + ALTER + INSERT + COMMIT
    ad ogni apertura/rerender di Gestione Asta quando non c'era un lotto attivo.
    Su DB cloud era uno dei costi piu' alti dell'interfaccia Banditore.
    """
    league_id = int(league_id)
    _guard = f"_v164_auction_mode_schema_ready_{league_id}"
    if st.session_state.get(_guard):
        return

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            CREATE TABLE IF NOT EXISTS auction_mode_state (
                league_id INTEGER PRIMARY KEY,
                random_queue_json TEXT,
                random_index INTEGER NOT NULL DEFAULT 0,
                alpha_index INTEGER NOT NULL DEFAULT 0,
                call_turn_index INTEGER NOT NULL DEFAULT 0,
                draft_turn_index INTEGER NOT NULL DEFAULT 0,
                skipped_players_json TEXT,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)

        try:
            cur.execute("""
                ALTER TABLE auction_mode_state
                ADD COLUMN skipped_players_json TEXT
            """)
        except Exception:
            pass

        cur.execute("""
            INSERT INTO auction_mode_state (
                league_id, random_queue_json, random_index, alpha_index,
                call_turn_index, draft_turn_index, skipped_players_json, updated_at
            )
            VALUES (?, NULL, 0, 0, 0, 0, NULL, CURRENT_TIMESTAMP)
            ON CONFLICT(league_id) DO NOTHING
        """, (league_id,))
        conn.commit()
        st.session_state[_guard] = True
    finally:
        _portal_close(conn)


def prepara_coda_random_multilega(league_id, disponibili):
    """
    Crea una coda random persistente una sola volta per la lega.
    I giocatori già non disponibili vengono saltati in fase di lettura.
    """
    import random

    league_id = int(league_id)
    inizializza_stato_modalita_asta(league_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT random_queue_json, random_index
            FROM auction_mode_state
            WHERE league_id=?
            LIMIT 1
        """, (league_id,))
        r = cur.fetchone()

        queue = []
        idx = 0

        if r and r[0]:
            try:
                queue = [int(x) for x in json.loads(str(r[0]))]
            except Exception:
                queue = []
            idx = int(r[1] or 0)

        if not queue:
            queue = [int(g["player_id"]) for g in disponibili]
            random.shuffle(queue)
            idx = 0
            cur.execute("""
                UPDATE auction_mode_state
                SET random_queue_json=?,
                    random_index=0,
                    updated_at=CURRENT_TIMESTAMP
                WHERE league_id=?
            """, (json.dumps(queue), league_id))
            conn.commit()

        return queue, idx
    finally:
        _portal_close(conn)



def giocatori_saltati_modalita_multilega(league_id):
    league_id = int(league_id)
    inizializza_stato_modalita_asta(league_id)
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT skipped_players_json
            FROM auction_mode_state
            WHERE league_id=?
            LIMIT 1
        """, (league_id,))
        r = cur.fetchone()
        if not r or not r[0]:
            return set()
        try:
            return {int(x) for x in json.loads(str(r[0]))}
        except Exception:
            return set()
    finally:
        _portal_close(conn)


def salta_giocatore_modalita_multilega(league_id, player_id):
    league_id = int(league_id)
    player_id = int(player_id)
    saltati = giocatori_saltati_modalita_multilega(league_id)
    saltati.add(player_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            UPDATE auction_mode_state
            SET skipped_players_json=?,
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=?
        """, (json.dumps(sorted(saltati)), league_id))
        conn.commit()
    finally:
        _portal_close(conn)



def prossimo_giocatore_automatico_multilega(league_id, disponibili, tipo_asta):
    """
    Restituisce il prossimo giocatore per modalità sequenziali:
    - RANDOM: coda casuale persistente
    - ALFABETICO: A→Z
    """
    league_id = int(league_id)
    tipo_asta = str(tipo_asta).upper()

    if not disponibili:
        return None

    saltati = giocatori_saltati_modalita_multilega(league_id)
    candidati = [
        g for g in disponibili
        if int(g.get("player_id",0)) not in saltati
    ]

    # Terminata la prima passata, i saltati restano disponibili per eventuali
    # cicli successivi, ma non vengono riproposti nella stessa scansione.
    if not candidati:
        return None

    if tipo_asta == "ALFABETICO":
        return sorted(
            candidati,
            key=lambda g: (
                str(g.get("nome","")).casefold(),
                int(g.get("player_id",0))
            )
        )[0]

    if tipo_asta == "RANDOM":
        queue, _ = prepara_coda_random_multilega(league_id, candidati)
        disp_map = {int(g["player_id"]): g for g in candidati}
        for player_id in queue:
            if int(player_id) in disp_map:
                return disp_map[int(player_id)]

        # Se il listone è cambiato dopo la creazione della coda, aggiunge
        # gli eventuali nuovi disponibili in fondo in ordine casuale.
        import random
        mancanti = [pid for pid in disp_map if pid not in set(queue)]
        random.shuffle(mancanti)
        if mancanti:
            nuova = queue + mancanti
            conn = _portal_raw_connection()
            cur = conn.cursor()
            try:
                cur.execute("""
                    UPDATE auction_mode_state
                    SET random_queue_json=?,
                        updated_at=CURRENT_TIMESTAMP
                    WHERE league_id=?
                """, (json.dumps(nuova), league_id))
                conn.commit()
            finally:
                _portal_close(conn)
            return disp_map[mancanti[0]]

    return None


def turno_squadra_multilega(league_id, tipo_asta):
    """
    Squadra di turno per CHIAMATA e DRAFT.
    L'ordine segue teams.posizione; se assente, l'id.
    """
    league_id = int(league_id)
    tipo_asta = str(tipo_asta).upper()
    inizializza_stato_modalita_asta(league_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT id, nome
            FROM teams
            WHERE league_id=? AND is_active=1
            ORDER BY posizione, id
        """, (league_id,))
        teams = cur.fetchall() or []
        if not teams:
            return None

        campo = "draft_turn_index" if tipo_asta == "DRAFT" else "call_turn_index"
        cur.execute(
            f"SELECT {campo} FROM auction_mode_state WHERE league_id=? LIMIT 1",
            (league_id,)
        )
        r = cur.fetchone()
        idx = int(r[0] or 0) if r else 0
        idx = idx % len(teams)

        return {
            "team_id": int(teams[idx][0]),
            "nome": str(teams[idx][1]),
            "index": idx,
            "totale": len(teams),
        }
    finally:
        _portal_close(conn)


def avanza_turno_squadra_multilega(league_id, tipo_asta):
    league_id = int(league_id)
    tipo_asta = str(tipo_asta).upper()
    campo = "draft_turn_index" if tipo_asta == "DRAFT" else "call_turn_index"

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            UPDATE auction_mode_state
            SET {campo}={campo}+1,
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=?
            """,
            (league_id,)
        )
        conn.commit()
    finally:
        _portal_close(conn)


def render_info_modalita_asta(tipo_asta, turno=None):
    tipo_asta = str(tipo_asta).upper()

    if tipo_asta == "RANDOM":
        st.info(
            "🎲 **Asta Random** — viene mostrato un solo giocatore alla volta. "
            "Il successivo viene determinato e rivelato soltanto dopo assegnazione "
            "oppure dopo chiusura del lotto senza offerte."
        )
    elif tipo_asta == "ALFABETICO":
        st.info(
            "🔤 **Asta Alfabetica** — viene mostrato un solo giocatore alla volta. "
            "Il successivo compare soltanto dopo assegnazione oppure dopo chiusura "
            "del lotto senza offerte."
        )
    elif tipo_asta == "CHIAMATA":
        testo_turno = (
            f" Squadra di turno: **{turno['nome']}**."
            if turno else ""
        )
        st.info(
            "📣 **Asta a chiamata** — ogni squadra seleziona un giocatore a turno "
            "e l'asta si svolge solo sulla chiamata corrente. Nessuna chiamata "
            "successiva viene mostrata prima della chiusura." + testo_turno
        )
    elif tipo_asta == "DRAFT":
        testo_turno = (
            f" Squadra di turno: **{turno['nome']}**."
            if turno else ""
        )
        st.info(
            "🧩 **Draft** — ordine di selezione prestabilito tra le squadre. "
            "Si gestisce una sola selezione alla volta e il giocatore chiamato "
            "viene assegnato direttamente, senza bidding." + testo_turno
        )




def snapshot_banditore_multilega(league_id):
    """V118 - snapshot compatto del Banditore con una sola connessione remota."""
    league_id = int(league_id)
    inizializza_listone_lega_asta(league_id)

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT
                COALESCE(tipo_asta,'CHIAMATA'),
                COALESCE(incremento_minimo,1),
                COALESCE(max_giocatori,30),
                COALESCE(min_portieri,0),
                COALESCE(budget_iniziale,500),
                COALESCE(soglia_budget,budget_iniziale,500),
                COALESCE(moltiplicatore_oltre_soglia,1)
            FROM league_rules
            WHERE league_id=?
            LIMIT 1
        """, (league_id,))
        rr = cur.fetchone() or ("CHIAMATA",1,30,0,500,500,1)

        raw_tipo = str(rr[0] or "CHIAMATA").strip().upper()
        aliases = {
            "A CHIAMATA":"CHIAMATA",
            "CHIAMATA":"CHIAMATA",
            "ALFABETICO":"ALFABETICO",
            "RANDOM":"RANDOM",
            "CASUALE":"RANDOM",
            "DRAFT":"DRAFT",
        }
        tipo_asta = aliases.get(raw_tipo, raw_tipo)

        cur.execute("""
            SELECT
                SUM(CASE WHEN stato='DISPONIBILE' THEN 1 ELSE 0 END),
                SUM(CASE WHEN stato='ASSEGNATO' THEN 1 ELSE 0 END)
            FROM league_players
            WHERE league_id=?
        """, (league_id,))
        rc = cur.fetchone() or (0,0)
        disponibili_count = int(rc[0] or 0)
        assegnati_count = int(rc[1] or 0)

        # V123: fonte autorevole = league_players.
        # La tabella rosters può contenere righe legacy/importate e quindi
        # non deve essere usata per il riepilogo live del Banditore.
        cur.execute("""
            SELECT
                t.id,
                t.nome,
                COALESCE(b.budget_impostato,r.budget_iniziale,500),
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=t.id
                        THEN COALESCE(lp.prezzo_assegnazione,0)
                        ELSE 0
                    END
                ),0) AS valore_acquisti_reale,
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=t.id
                        THEN 1 ELSE 0
                    END
                ),0) AS giocatori_reali,
                COALESCE(SUM(
                    CASE
                        WHEN lp.stato='ASSEGNATO'
                         AND lp.assigned_team_id=t.id
                         AND (
                            UPPER(COALESCE(g.ruolo_classico,''))='P'
                            OR UPPER(COALESCE(g.ruolo_mantra,'')) IN ('P','POR')
                         )
                        THEN 1 ELSE 0
                    END
                ),0) AS portieri_reali
            FROM teams t
            LEFT JOIN league_rules r
              ON r.league_id=t.league_id
            LEFT JOIN team_budgets b
              ON b.league_id=t.league_id
             AND b.team_id=t.id
            LEFT JOIN league_players lp
              ON lp.league_id=t.league_id
             AND lp.assigned_team_id=t.id
             AND lp.stato='ASSEGNATO'
            LEFT JOIN league_player_catalog g
              ON g.league_id=lp.league_id
             AND g.player_id=lp.player_id
            WHERE t.league_id=? AND t.is_active=1
            GROUP BY
                t.id,t.nome,t.posizione,
                b.budget_impostato,r.budget_iniziale
            ORDER BY t.posizione,t.id
        """, (league_id,))

        _soglia = float(rr[5] or rr[4] or 500)
        _moltiplicatore = max(1.0, float(rr[6] or 1))

        teams = []
        for _r in (cur.fetchall() or []):
            _valore = float(_r[3] or 0)
            _spesa = _spesa_effettiva_regole(
                _valore,
                _soglia,
                _moltiplicatore
            )
            teams.append({
                "team_id": int(_r[0]),
                "nome": str(_r[1]),
                "budget": float(_r[2] or 0),
                "valore_acquisti": _valore,
                "spesa_effettiva": float(_spesa),
                "giocatori": int(_r[4] or 0),
                "portieri": int(_r[5] or 0),
            })

        cur.execute("""
            SELECT
                l.id,l.player_id,l.stato,l.opened_at,
                COALESCE(g.nome,''),
                COALESCE(g.squadra,''),
                COALESCE(g.ruolo_mantra,''),
                COALESCE(g.fvm_mantra,g.fvm,0),
                COALESCE(g.quotazione_attuale_mantra,g.quotazione_attuale,0),
                l.closing_at,l.current_bid,l.current_team_id,
                COALESCE(l.bid_count,0),COALESCE(l.version,0),
                l.bid_deadline_ts
            FROM auction_sessions s
            LEFT JOIN auction_lots l ON l.id=s.current_lot_id
            LEFT JOIN league_player_catalog g
              ON g.player_id=l.player_id AND g.league_id=s.league_id
            WHERE s.league_id=?
            LIMIT 1
        """, (league_id,))
        rl = cur.fetchone()

        lotto = None
        if rl and rl[0] is not None:
            lotto = {
                "lot_id":int(rl[0]),
                "player_id":int(rl[1]),
                "stato":str(rl[2] or ""),
                "opened_at":str(rl[3] or ""),
                "nome":str(rl[4] or ""),
                "squadra":str(rl[5] or ""),
                "ruolo_mantra":str(rl[6] or ""),
                "fvm":float(rl[7] or 0),
                "quotazione":float(rl[8] or 0),
                "closing_at":str(rl[9] or ""),
                "current_bid":float(rl[10]) if rl[10] is not None else None,
                "current_team_id":int(rl[11]) if rl[11] is not None else None,
                "bid_count":int(rl[12] or 0),
                "version":int(rl[13] or 0),
                "bid_deadline_ts":float(rl[14]) if rl[14] is not None else None,
            }

        turno = None
        if tipo_asta in ("CHIAMATA","DRAFT") and teams:
            campo = "draft_turn_index" if tipo_asta=="DRAFT" else "call_turn_index"
            try:
                cur.execute(
                    f"SELECT {campo} FROM auction_mode_state WHERE league_id=? LIMIT 1",
                    (league_id,)
                )
                rt = cur.fetchone()
                idx = int(rt[0] or 0) if rt else 0
            except Exception:
                idx = 0

            idx = idx % len(teams)
            turno = {
                "team_id":int(teams[idx]["team_id"]),
                "nome":str(teams[idx]["nome"]),
                "index":idx,
                "totale":len(teams),
            }

        disponibili = []
        if lotto is None and tipo_asta in ("RANDOM","ALFABETICO"):
            cur.execute("""
                SELECT
                    g.player_id,
                    COALESCE(g.nome,''),
                    COALESCE(g.squadra,''),
                    COALESCE(g.ruolo_mantra,''),
                    COALESCE(g.fvm_mantra,g.fvm,0)
                FROM league_player_catalog g
                JOIN league_players lp
                  ON lp.player_id=g.player_id
                 AND lp.league_id=g.league_id
                WHERE g.league_id=?
                  AND lp.stato='DISPONIBILE'
                ORDER BY g.nome COLLATE NOCASE
            """, (league_id,))
            disponibili = [
                {
                    "player_id":int(r[0]),
                    "nome":str(r[1]),
                    "squadra":str(r[2]),
                    "ruolo_mantra":str(r[3]),
                    "fvm":float(r[4] or 0),
                    "stato":"DISPONIBILE",
                    "assigned_team_id":None,
                    "prezzo":None,
                }
                for r in (cur.fetchall() or [])
            ]

        return {
            "tipo_asta":tipo_asta,
            "disponibili_count":disponibili_count,
            "assegnati_count":assegnati_count,
            "disponibili":disponibili,
            "teams":teams,
            "lotto":lotto,
            "turno":turno,
        }
    finally:
        _portal_close(conn)






def snapshot_banditore_live_v133(league_id):
    """V282 - snapshot Banditore in UNA sola query: lotto + ultime 2 offerte."""
    league_id = int(league_id)
    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            WITH current_lot AS (
                SELECT
                    l.id, l.player_id, l.stato, l.current_bid, l.current_team_id,
                    COALESCE(l.bid_count,0) AS bid_count,
                    COALESCE(l.version,0) AS version,
                    COALESCE(pc.nome,'') AS nome,
                    COALESCE(pc.squadra,'') AS squadra,
                    COALESCE(pc.ruolo_mantra,'') AS ruolo_mantra,
                    COALESCE(t.nome,'') AS current_team
                FROM auction_sessions s
                JOIN auction_lots l
                  ON l.id=s.current_lot_id AND l.league_id=s.league_id
                JOIN league_player_catalog pc
                  ON pc.league_id=l.league_id AND pc.player_id=l.player_id
                LEFT JOIN teams t
                  ON t.id=l.current_team_id AND t.league_id=l.league_id
                WHERE s.league_id=? AND l.stato IN ('OPEN','CLOSING')
                LIMIT 1
            ),
            last_bids AS (
                SELECT b.team_id,b.amount,b.created_at
                FROM bids b
                JOIN current_lot cl ON cl.id=b.lot_id
                WHERE b.league_id=?
                ORDER BY b.id DESC
                LIMIT 2
            )
            SELECT
                cl.id,cl.player_id,cl.stato,cl.current_bid,cl.current_team_id,
                cl.bid_count,cl.version,cl.nome,cl.squadra,cl.ruolo_mantra,
                cl.current_team,
                COALESCE(bt.nome,''),lb.amount,lb.created_at
            FROM current_lot cl
            LEFT JOIN last_bids lb ON 1=1
            LEFT JOIN teams bt
              ON bt.id=lb.team_id AND bt.league_id=?
            ORDER BY lb.created_at DESC
        """, (league_id, league_id, league_id))
        rows = cur.fetchall() or []
        if not rows:
            return None

        r = rows[0]
        offerte = []
        for br in rows:
            if br[12] is not None:
                offerte.append({
                    "Squadra": str(br[11] or ""),
                    "Offerta": float(br[12] or 0),
                    "Orario": str(br[13] or ""),
                })

        return {
            "lot_id": int(r[0]),
            "player_id": int(r[1]),
            "stato": str(r[2] or "").upper(),
            "current_bid": float(r[3]) if r[3] is not None else None,
            "current_team_id": int(r[4]) if r[4] is not None else None,
            "current_team": str(r[10] or ""),
            "bid_count": int(r[5] or 0),
            "version": int(r[6] or 0),
            "nome": str(r[7] or ""),
            "squadra": str(r[8] or ""),
            "ruolo_mantra": str(r[9] or ""),
            "offerte": offerte[:2],
        }
    finally:
        _portal_close(conn)

def snapshot_lotto_live_v132(league_id, team_id=None):
    """
    V181 - snapshot LIVE ottimizzato: statistiche rosa calcolate solo
    per la squadra collegata, non per tutte le squadre a ogni refresh.

    Una sola query remota restituisce:
    - lotto e giocatore corrente;
    - miglior offerta;
    - ultima/massima offerta di ogni squadra;
    - per la squadra corrente: budget/rosa e limiti di offerta.

    Durante un lotto OPEN questa è la sola query periodica del fragment.
    """
    league_id = int(league_id)
    team_id = int(team_id) if team_id is not None else None

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        cur.execute("""
            WITH current_lot AS (
                SELECT
                    l.id AS lot_id,
                    l.player_id,
                    l.stato,
                    l.current_bid,
                    l.current_team_id,
                    COALESCE(l.bid_count,0) AS bid_count,
                    COALESCE(l.version,0) AS version
                FROM auction_sessions s
                JOIN auction_lots l
                  ON l.id=s.current_lot_id
                 AND l.league_id=s.league_id
                WHERE s.league_id=?
                  AND l.stato IN ('OPEN','CLOSING')
                LIMIT 1
            ),
            roster_stats AS (
                SELECT
                    t.id AS team_id,
                    COALESCE(tb.budget_impostato,lr.budget_iniziale,500) AS budget,
                    COALESCE(SUM(CASE WHEN lp.stato='ASSEGNATO'
                                      AND lp.assigned_team_id=t.id
                                     THEN COALESCE(lp.prezzo_assegnazione,0) ELSE 0 END),0) AS valore_acquisti,
                    COALESCE(SUM(CASE WHEN lp.stato='ASSEGNATO'
                                      AND lp.assigned_team_id=t.id
                                     THEN 1 ELSE 0 END),0) AS numero_rosa,
                    COALESCE(SUM(CASE WHEN lp.stato='ASSEGNATO'
                                      AND lp.assigned_team_id=t.id
                                      AND (UPPER(COALESCE(pc2.ruolo_classico,''))='P'
                                           OR UPPER(COALESCE(pc2.ruolo_mantra,'')) IN ('P','POR'))
                                     THEN 1 ELSE 0 END),0) AS portieri
                FROM teams t
                LEFT JOIN league_rules lr ON lr.league_id=t.league_id
                LEFT JOIN team_budgets tb ON tb.league_id=t.league_id AND tb.team_id=t.id
                LEFT JOIN league_players lp
                  ON lp.league_id=t.league_id AND lp.assigned_team_id=t.id AND lp.stato='ASSEGNATO'
                LEFT JOIN league_player_catalog pc2
                  ON pc2.league_id=lp.league_id AND pc2.player_id=lp.player_id
                WHERE t.league_id=? AND t.is_active=1 AND t.id=?
                GROUP BY t.id,tb.budget_impostato,lr.budget_iniziale
            )
            SELECT
                cl.lot_id, cl.player_id, cl.stato, cl.current_bid,
                cl.current_team_id, cl.bid_count, cl.version,
                COALESCE(pc.nome,''), COALESCE(pc.squadra,''),
                COALESCE(pc.ruolo_classico,''), COALESCE(pc.ruolo_mantra,''),
                COALESCE(pc.fvm_mantra,pc.fvm,0),
                COALESCE(pc.quotazione_attuale_mantra,pc.quotazione_attuale,0),
                t.id, COALESCE(t.nome,''),
                (SELECT MAX(b.amount) FROM bids b
                 WHERE b.league_id=? AND b.lot_id=cl.lot_id AND b.team_id=t.id),
                COALESCE(lr.incremento_minimo,1),
                COALESCE(lr.tipo_incremento_asta,'FISSO'),
                COALESCE(lr.incrementi_scalari_json,'[]'),
                COALESCE(lr.max_giocatori,30), COALESCE(lr.min_portieri,0),
                COALESCE(lr.budget_iniziale,500),
                COALESCE(lr.soglia_budget,lr.budget_iniziale,500),
                COALESCE(lr.moltiplicatore_oltre_soglia,1),
                COALESCE(lr.budget_illimitato,0),
                COALESCE(lr.fair_play_finanziario,0),
                COALESCE(rs.budget,lr.budget_iniziale,500),
                COALESCE(rs.valore_acquisti,0), COALESCE(rs.numero_rosa,0),
                COALESCE(rs.portieri,0)
            FROM current_lot cl
            JOIN league_player_catalog pc
              ON pc.league_id=? AND pc.player_id=cl.player_id
            JOIN teams t
              ON t.league_id=? AND t.is_active=1 AND t.id=?
            LEFT JOIN league_rules lr ON lr.league_id=?
            LEFT JOIN roster_stats rs ON rs.team_id=t.id
            LIMIT 1
        """, (
            league_id,
            league_id, team_id,
            league_id,
            league_id,
            league_id, team_id,
            league_id
        ))
        rows = cur.fetchall() or []
        if not rows:
            return None

        r0 = rows[0]
        current_team_id = int(r0[4]) if r0[4] is not None else None

        offerte = []
        current_team_name = ""
        team_row = None

        for r in rows:
            tid = int(r[13])
            nome_team = str(r[14] or "")
            amount = float(r[15]) if r[15] is not None else None
            offerte.append({
                "team_id": tid,
                "Squadra": nome_team,
                "Offerta": amount,
                "Migliore": (
                    "🏆" if current_team_id is not None
                    and tid == current_team_id else ""
                ),
            })
            if current_team_id is not None and tid == current_team_id:
                current_team_name = nome_team
            if team_id is not None and tid == team_id:
                team_row = r

        out = {
            "lot_id": int(r0[0]),
            "player_id": int(r0[1]),
            "stato": str(r0[2] or "").upper(),
            "current_bid": float(r0[3]) if r0[3] is not None else None,
            "current_team_id": current_team_id,
            "current_team": current_team_name,
            "bid_count": int(r0[5] or 0),
            "version": int(r0[6] or 0),

            "nome": str(r0[7] or ""),
            "squadra": str(r0[8] or ""),
            "ruolo_classico": str(r0[9] or ""),
            "ruolo_mantra": str(r0[10] or ""),
            "fvm": float(r0[11] or 0),
            "quotazione": float(r0[12] or 0),
            "offerte": offerte,
        }

        if team_row is not None:
            incremento = _incremento_corrente_v187(
                out["current_bid"], float(team_row[16] or 1), team_row[17], team_row[18]
            )
            max_giocatori = int(team_row[19] or 30)
            min_portieri = int(team_row[20] or 0)
            budget_default = float(team_row[21] or 500)
            soglia = float(team_row[22] or budget_default)
            moltiplicatore = max(1.0, float(team_row[23] or 1))
            budget_illimitato = bool(int(team_row[24] or 0))
            fair_play_finanziario = bool(int(team_row[25] or 0))
            budget = float(team_row[26] or budget_default)
            valore = float(team_row[27] or 0)
            numero_rosa = int(team_row[28] or 0)
            portieri = int(team_row[29] or 0)

            minimo = (
                1.0
                if out["current_bid"] is None
                else round(out["current_bid"] + incremento, 2)
            )

            is_portiere = (
                out["ruolo_classico"].strip().upper() == "P"
                or out["ruolo_mantra"].strip().upper() in ("P","POR")
            )
            slot_dopo = max(0, max_giocatori - (numero_rosa + 1))
            portieri_dopo = portieri + (1 if is_portiere else 0)
            portieri_mancanti = max(0, min_portieri - portieri_dopo)

            # Conserva almeno 1 credito per ogni slot successivo.
            riserva = float(slot_dopo)

            # V182 - budget illimitato e F.P.F. applicati anche allo snapshot live.
            plafond_nominale = _plafond_nominale_fpf_v182(
                budget, soglia, moltiplicatore,
                fair_play_finanziario, budget_illimitato
            )
            massimo = float(max(
                0,
                math.floor(plafond_nominale - float(valore) - riserva + 1e-9)
            ))

            spesa = float(
                _spesa_effettiva_regole(valore, soglia, moltiplicatore)
                if fair_play_finanziario else valore
            )

            can_bid = True
            motivo = ""

            if out["stato"] != "OPEN":
                can_bid = False
                motivo = "Le offerte sono chiuse."
            elif out["current_team_id"] == team_id:
                can_bid = False
                motivo = "Sei già il miglior offerente."
            elif numero_rosa >= max_giocatori:
                can_bid = False
                motivo = "La rosa è già completa."
            elif slot_dopo < portieri_mancanti:
                can_bid = False
                motivo = (
                    "L'acquisto non lascerebbe abbastanza slot "
                    "per raggiungere il minimo di portieri."
                )
            elif massimo + 1e-9 < minimo:
                can_bid = False
                motivo = "Budget disponibile insufficiente per rilanciare."

            out["team"] = {
                "team_id": team_id,
                "budget": budget,
                "valore_acquisti": valore,
                "spesa_effettiva": spesa,
                "residuo": round(budget - spesa, 2),
                "numero_rosa": numero_rosa,
                "max_giocatori": max_giocatori,
                "portieri": portieri,
                "min_portieri": min_portieri,
                "incremento": incremento,
                "offerta_minima": minimo,
                "offerta_massima": massimo,
                "can_bid": can_bid,
                "motivo": motivo,
            }

        return out
    finally:
        _portal_close(conn)


def _tabella_offerte_live_v132(stato):
    righe = []
    for x in stato.get("offerte", []):
        righe.append({
            "Squadra": x["Squadra"],
            "Offerta": (
                x["Offerta"]
                if x["Offerta"] is not None
                else "—"
            ),
            "": x["Migliore"],
        })
    return pd.DataFrame(righe)



def chiudi_e_assegna_migliore_v133(league_id, lot_id):
    """
    V133 - chiusura e assegnazione ottimizzata in una sola connessione.

    Il bid è già stato validato server-side quando è stato accettato.
    Qui ricontrolliamo solo i vincoli essenziali prima della scrittura finale.
    """
    league_id = int(league_id)
    lot_id = int(lot_id)
    user_id = int(st.session_state.get("auth_user_id") or 0)

    conn = _portal_raw_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            UPDATE auction_lots
            SET stato='CLOSING',
                closing_by_user_id=?,
                closing_at=CURRENT_TIMESTAMP
            WHERE id=? AND league_id=?
              AND stato='OPEN'
              AND current_team_id IS NOT NULL
              AND current_bid IS NOT NULL
              AND EXISTS (
                  SELECT 1
                  FROM league_members
                  WHERE league_id=?
                    AND user_id=?
                    AND is_active=1
                    AND (is_auctioneer=1 OR is_admin=1)
              )
            RETURNING player_id,current_team_id,current_bid
        """, (
            user_id,
            lot_id,
            league_id,
            league_id,
            user_id
        ))
        claim = cur.fetchone()
        if not claim:
            raise ValueError(
                "Il lotto non è più aperto oppure non contiene offerte."
            )

        player_id = int(claim[0])
        team_id = int(claim[1])
        prezzo = float(claim[2])

        cur.execute("""
            SELECT
                COALESCE(t.nome,''),
                COALESCE(r.max_giocatori,30),
                COALESCE(r.min_portieri,0),
                COALESCE(tb.budget_impostato,r.budget_iniziale,500),
                COALESCE(r.soglia_budget,r.budget_iniziale,500),
                COALESCE(r.moltiplicatore_oltre_soglia,1),
                COALESCE(pc.ruolo_classico,''),
                COALESCE(pc.ruolo_mantra,''),
                COALESCE((
                    SELECT COUNT(*)
                    FROM league_players lp
                    WHERE lp.league_id=?
                      AND lp.stato='ASSEGNATO'
                      AND lp.assigned_team_id=?
                ),0),
                COALESCE((
                    SELECT SUM(COALESCE(lp.prezzo_assegnazione,0))
                    FROM league_players lp
                    WHERE lp.league_id=?
                      AND lp.stato='ASSEGNATO'
                      AND lp.assigned_team_id=?
                ),0),
                COALESCE((
                    SELECT COUNT(*)
                    FROM league_players lp
                    LEFT JOIN league_player_catalog p2
                      ON p2.league_id=lp.league_id
                     AND p2.player_id=lp.player_id
                    WHERE lp.league_id=?
                      AND lp.stato='ASSEGNATO'
                      AND lp.assigned_team_id=?
                      AND (
                          UPPER(COALESCE(p2.ruolo_classico,''))='P'
                          OR UPPER(COALESCE(p2.ruolo_mantra,'')) IN ('P','POR')
                      )
                ),0)
            FROM teams t
            LEFT JOIN league_rules r
              ON r.league_id=t.league_id
            LEFT JOIN team_budgets tb
              ON tb.league_id=t.league_id
             AND tb.team_id=t.id
            LEFT JOIN league_player_catalog pc
              ON pc.league_id=t.league_id
             AND pc.player_id=?
            WHERE t.league_id=?
              AND t.id=?
              AND t.is_active=1
            LIMIT 1
        """, (
            league_id, team_id,
            league_id, team_id,
            league_id, team_id,
            player_id,
            league_id, team_id
        ))

        r = cur.fetchone()
        if not r:
            raise ValueError("Squadra vincitrice non valida.")

        nome_team = str(r[0] or "")
        max_giocatori = int(r[1] or 30)
        min_portieri = int(r[2] or 0)
        budget = float(r[3] or 0)
        soglia = float(r[4] or budget)
        moltiplicatore = max(1.0, float(r[5] or 1))
        ruolo_classico = str(r[6] or "").strip().upper()
        ruolo_mantra = str(r[7] or "").strip().upper()
        roster_count = int(r[8] or 0)
        valore_attuale = float(r[9] or 0)
        portieri_attuali = int(r[10] or 0)

        if roster_count >= max_giocatori:
            raise ValueError("La rosa della squadra è già completa.")

        is_portiere = (
            ruolo_classico == "P"
            or ruolo_mantra in ("P","POR")
        )

        slot_dopo = max(0, max_giocatori - (roster_count + 1))
        portieri_dopo = portieri_attuali + (1 if is_portiere else 0)
        portieri_mancanti = max(0, min_portieri - portieri_dopo)

        if slot_dopo < portieri_mancanti:
            raise ValueError(
                "Assegnazione non consentita: vincolo minimo portieri."
            )

        nuovo_valore = round(valore_attuale + prezzo, 2)
        nuova_spesa = float(
            _spesa_effettiva_regole(
                nuovo_valore,
                soglia,
                moltiplicatore
            )
        )

        if nuova_spesa > budget + 1e-9:
            raise ValueError("Budget insufficiente per l'assegnazione.")

        cur.execute("""
            UPDATE league_players
            SET stato='ASSEGNATO',
                assigned_team_id=?,
                prezzo_assegnazione=?,
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=?
              AND player_id=?
              AND stato='DISPONIBILE'
            RETURNING player_id
        """, (
            team_id,
            prezzo,
            league_id,
            player_id
        ))
        if not cur.fetchone():
            raise ValueError("Giocatore non più disponibile.")

        cur.execute("""
            INSERT INTO rosters (
                league_id,team_id,player_id,prezzo_acquisto,
                fonte,assigned_at,updated_at
            )
            VALUES (?,?,?,?,'AUCTIONEER',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
            ON CONFLICT(league_id,team_id,player_id)
            DO UPDATE SET
                prezzo_acquisto=excluded.prezzo_acquisto,
                fonte='AUCTIONEER',
                updated_at=CURRENT_TIMESTAMP
        """, (
            league_id,
            team_id,
            player_id,
            prezzo
        ))

        cur.execute("""
            INSERT INTO team_budgets (
                league_id,team_id,budget_impostato,
                valore_acquisti,spesa_effettiva,updated_at
            )
            VALUES (?,?,?,?,?,CURRENT_TIMESTAMP)
            ON CONFLICT(league_id,team_id)
            DO UPDATE SET
                valore_acquisti=excluded.valore_acquisti,
                spesa_effettiva=excluded.spesa_effettiva,
                updated_at=CURRENT_TIMESTAMP
        """, (
            league_id,
            team_id,
            budget,
            nuovo_valore,
            nuova_spesa
        ))

        cur.execute("""
            INSERT INTO auction_assignment_history (
                league_id,player_id,team_id,prezzo,stato,
                assigned_by_user_id,assigned_at
            )
            VALUES (?,?,?,?,'ACTIVE',?,CURRENT_TIMESTAMP)
            RETURNING id
        """, (
            league_id,
            player_id,
            team_id,
            prezzo,
            user_id
        ))
        hrow = cur.fetchone()
        history_id = int(hrow[0]) if hrow else 0

        cur.execute("""
            UPDATE auction_lots
            SET stato='ASSIGNED',
                assigned_team_id=?,
                final_price=?,
                closed_at=CURRENT_TIMESTAMP
            WHERE id=? AND league_id=? AND stato='CLOSING'
        """, (
            team_id,
            prezzo,
            lot_id,
            league_id
        ))

        cur.execute("""
            UPDATE auction_sessions
            SET current_lot_id=NULL,
                stato='READY',
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND current_lot_id=?
        """, (
            league_id,
            lot_id
        ))

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,team_id,azione,
                entita,entita_id,dettagli_json,created_at
            )
            VALUES (?,?,?,'PLAYER_ASSIGNED','PLAYER',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            user_id,
            team_id,
            str(player_id),
            json.dumps({
                "prezzo": prezzo,
                "team": nome_team,
                "history_id": history_id,
                "lot_id": lot_id,
                "valore_acquisti": nuovo_valore,
                "spesa_effettiva": nuova_spesa,
            }, ensure_ascii=False)
        ))

        # Best-effort compatibility sync in SAME connection.
        tab_team = f"giocatori_ml_l{league_id}_t{team_id}"
        try:
            cur.execute(
                f"""
                UPDATE {tab_team}
                SET stato='MIO',
                    prezzo_acquisto=?,
                    ultimo_aggiornamento=CURRENT_TIMESTAMP
                WHERE id=?
                """,
                (prezzo, player_id)
            )
        except Exception:
            pass

        conn.commit()

        return {
            "team": nome_team,
            "team_id": team_id,
            "player_id": player_id,
            "prezzo": prezzo,
            "valore_acquisti": nuovo_valore,
            "spesa_effettiva": nuova_spesa,
        }

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise

    finally:
        _portal_close(conn)


def chiudi_lotto_vuoto_v133(league_id, lot_id, player_id):
    """
    V133 - chiusura lotto senza offerte in una sola connessione.
    """
    league_id = int(league_id)
    lot_id = int(lot_id)
    player_id = int(player_id)
    user_id = int(st.session_state.get("auth_user_id") or 0)

    conn = _portal_raw_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            UPDATE auction_lots
            SET stato='CLOSED',
                closed_at=CURRENT_TIMESTAMP
            WHERE id=? AND league_id=?
              AND stato='OPEN'
              AND COALESCE(bid_count,0)=0
              AND EXISTS (
                  SELECT 1
                  FROM league_members
                  WHERE league_id=?
                    AND user_id=?
                    AND is_active=1
                    AND (is_auctioneer=1 OR is_admin=1)
              )
            RETURNING id
        """, (
            lot_id,
            league_id,
            league_id,
            user_id
        ))
        if not cur.fetchone():
            raise ValueError(
                "Il lotto non è più aperto o contiene offerte."
            )

        cur.execute("""
            SELECT COALESCE(tipo_asta,'CHIAMATA')
            FROM league_rules
            WHERE league_id=?
            LIMIT 1
        """, (league_id,))
        rr = cur.fetchone()
        tipo = str(rr[0] if rr else "CHIAMATA").strip().upper()
        if tipo == "A CHIAMATA":
            tipo = "CHIAMATA"

        cur.execute("""
            UPDATE auction_sessions
            SET current_lot_id=NULL,
                stato='READY',
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=? AND current_lot_id=?
        """, (
            league_id,
            lot_id
        ))

        if tipo == "CHIAMATA":
            cur.execute("""
                UPDATE auction_mode_state
                SET call_turn_index=call_turn_index+1,
                    updated_at=CURRENT_TIMESTAMP
                WHERE league_id=?
            """, (league_id,))

        elif tipo in ("RANDOM","ALFABETICO"):
            cur.execute("""
                SELECT COALESCE(skipped_players_json,'[]')
                FROM auction_mode_state
                WHERE league_id=?
                LIMIT 1
            """, (league_id,))
            rs = cur.fetchone()
            try:
                skipped = {
                    int(x)
                    for x in json.loads(rs[0] if rs else "[]")
                }
            except Exception:
                skipped = set()
            skipped.add(player_id)

            cur.execute("""
                UPDATE auction_mode_state
                SET skipped_players_json=?,
                    updated_at=CURRENT_TIMESTAMP
                WHERE league_id=?
            """, (
                json.dumps(sorted(skipped)),
                league_id
            ))

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,azione,entita,entita_id,
                dettagli_json,created_at
            )
            VALUES (?,?,'LOT_CLOSED','AUCTION_LOT',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            user_id,
            str(lot_id),
            json.dumps({
                "stato": "CLOSED",
                "player_id": player_id,
            }, ensure_ascii=False)
        ))

        conn.commit()
        return True

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)


@st.cache_resource
def _auction_live_bus_v291():
    """V291 - bus RAM condiviso tra sessioni Streamlit; nessun accesso DB."""
    return {}


def pubblica_evento_asta_v291(league_id,lot_id,stato):
    """Pubblica una transizione asta per le altre sessioni collegate."""
    _auction_live_bus_v291()[int(league_id)] = {
        "lot_id": int(lot_id),
        "stato": str(stato or "").upper(),
        "seq": time.time_ns(),
    }


def leggi_evento_asta_v291(league_id):
    return _auction_live_bus_v291().get(int(league_id))


@st.fragment(run_every="1s")
def watcher_apertura_squadra_v292(league_id,last_seq=0):
    """V292 - ATTESA→OPEN via bus RAM condiviso; zero query periodiche."""
    evento=leggi_evento_asta_v291(league_id)
    if (
        isinstance(evento,dict)
        and str(evento.get("stato") or "").upper()=="OPEN"
        and int(evento.get("seq") or 0)>int(last_seq or 0)
    ):
        st.session_state[f"_v292_seen_open_{int(league_id)}"]=int(evento["seq"])
        st.rerun(scope="app")


@st.fragment(run_every="1s")
def watcher_chiusura_squadra_v291(league_id,lot_id):
    """
    V291 - watcher solo RAM: nessuna query e nessuna connessione Turso.
    Se il Banditore ha chiuso il lotto visualizzato, ricostruisce la pagina
    SQUADRA che troverà auction_sessions senza current_lot_id e mostrerà ATTESA.
    """
    evento=leggi_evento_asta_v291(league_id)
    if (
        isinstance(evento,dict)
        and int(evento.get("lot_id") or 0)==int(lot_id)
        and str(evento.get("stato") or "").upper() in ("ASSIGNED","CLOSED","IDLE")
    ):
        st.rerun(scope="app")


def callback_apri_lotto_v133(league_id, player_id, nome, squadra_reale='', ruolo_mantra=''):
    try:
        _v276_lot_id = apri_lotto_banditore(
            int(league_id),
            int(player_id)
        )
        # V276 - hint locale per la transizione immediata del Banditore.
        st.session_state[f"_v276_open_hint_{int(league_id)}"] = {
            "lot_id": int(_v276_lot_id),
            "player_id": int(player_id),
            "nome": str(nome),
            "squadra": str(squadra_reale or ""),
            "ruolo_mantra": str(ruolo_mantra or ""),
        }
        # V292 - comunica il nuovo lotto OPEN a tutte le SQUADRE.
        pubblica_evento_asta_v291(league_id,_v276_lot_id,"OPEN")
        invalida_cache_banditore_v156(league_id)
        st.session_state["auctioneer_msg"] = (
            f"Asta aperta su {nome}."
        )
        st.session_state.pop("auctioneer_error", None)
    except Exception as errore:
        st.session_state["auctioneer_error"] = str(errore)


def callback_chiudi_vuoto_v133(
    league_id,
    lot_id,
    player_id,
    nome
):
    try:
        chiudi_lotto_vuoto_v133(
            int(league_id),
            int(lot_id),
            int(player_id)
        )
        invalida_cache_banditore_v156(league_id)
        st.session_state["auctioneer_msg"] = (
            f"Lotto di {nome} chiuso senza assegnazione."
        )
        # V291 - anche un lotto vuoto deve sparire automaticamente dalle SQUADRE.
        pubblica_evento_asta_v291(league_id,lot_id,"CLOSED")
        st.session_state.pop("auctioneer_error", None)

        # V270 - anche la chiusura senza assegnazione torna alla console IDLE.
        st.rerun(scope="app")
    except Exception as errore:
        st.session_state["auctioneer_error"] = str(errore)



def assegna_lotto_migliore_v146(league_id, lot_id):
    """
    V146 - assegnazione definitiva e autorevole.

    Alla conferma del Banditore:
      1. congela il lotto;
      2. usa current_team_id/current_bid come vincitore/prezzo;
      3. aggiorna league_players;
      4. aggiorna rosters e team_budgets;
      5. chiude lotto/sessione;
      6. sincronizza, se esiste, il workspace compatibilità del vincitore;
      7. scrive audit/storico.

    Tutto il nucleo autorevole avviene in una sola transazione DB.
    """
    league_id = int(league_id)
    lot_id = int(lot_id)
    user_id = int(st.session_state.get("auth_user_id") or 0)

    conn = _portal_raw_connection()
    cur = conn.cursor()

    try:
        # Permesso server-side.
        cur.execute("""
            SELECT COUNT(*)
            FROM league_members
            WHERE league_id=?
              AND user_id=?
              AND is_active=1
              AND (is_auctioneer=1 OR is_admin=1)
        """, (league_id, user_id))
        if int((cur.fetchone() or [0])[0] or 0) <= 0:
            raise PermissionError("Operazione riservata al Banditore/Admin.")

        # Snapshot lotto prima del claim.
        cur.execute("""
            SELECT
                player_id,
                current_team_id,
                current_bid,
                stato,
                COALESCE(version,0)
            FROM auction_lots
            WHERE id=? AND league_id=?
            LIMIT 1
        """, (lot_id, league_id))
        lot = cur.fetchone()

        if not lot:
            raise ValueError("Lotto non trovato.")

        player_id = int(lot[0])
        team_id = int(lot[1]) if lot[1] is not None else None
        prezzo = float(lot[2]) if lot[2] is not None else None
        stato_lotto = str(lot[3] or "").upper()
        versione = int(lot[4] or 0)

        if stato_lotto != "OPEN":
            raise ValueError("Il lotto non è più aperto.")
        if team_id is None or prezzo is None:
            raise ValueError(
                "La squadra aggiudicataria deve inserire "
                "l'offerta conclusiva nell'app prima della conferma."
            )

        # Claim atomico del lotto. Niente RETURNING: massima compatibilità Turso.
        cur.execute("""
            UPDATE auction_lots
            SET stato='CLOSING',
                closing_by_user_id=?,
                closing_at=CURRENT_TIMESTAMP,
                version=COALESCE(version,0)+1
            WHERE id=?
              AND league_id=?
              AND stato='OPEN'
              AND COALESCE(version,0)=?
              AND current_team_id=?
              AND ABS(current_bid-?)<0.0001
        """, (
            user_id,
            lot_id,
            league_id,
            versione,
            team_id,
            prezzo
        ))

        cur.execute("""
            SELECT stato,current_team_id,current_bid
            FROM auction_lots
            WHERE id=? AND league_id=?
            LIMIT 1
        """, (lot_id, league_id))
        claimed = cur.fetchone()

        if (
            not claimed
            or str(claimed[0] or "").upper() != "CLOSING"
            or int(claimed[1] or 0) != team_id
            or abs(float(claimed[2] or 0) - prezzo) > 0.0001
        ):
            raise ValueError(
                "Il lotto è cambiato nel frattempo. "
                "Aggiorna le offerte e riprova."
            )

        # Team, regole e giocatore.
        cur.execute("""
            SELECT
                COALESCE(t.nome,''),
                COALESCE(r.max_giocatori,30),
                COALESCE(r.min_portieri,0),
                COALESCE(tb.budget_impostato,r.budget_iniziale,500),
                COALESCE(r.soglia_budget,r.budget_iniziale,500),
                COALESCE(r.moltiplicatore_oltre_soglia,1),
                COALESCE(pc.ruolo_classico,''),
                COALESCE(pc.ruolo_mantra,'')
            FROM teams t
            LEFT JOIN league_rules r
              ON r.league_id=t.league_id
            LEFT JOIN team_budgets tb
              ON tb.league_id=t.league_id
             AND tb.team_id=t.id
            LEFT JOIN league_player_catalog pc
              ON pc.league_id=t.league_id
             AND pc.player_id=?
            WHERE t.league_id=?
              AND t.id=?
              AND t.is_active=1
            LIMIT 1
        """, (player_id, league_id, team_id))
        info = cur.fetchone()

        if not info:
            raise ValueError("Squadra vincitrice non valida.")

        nome_team = str(info[0] or "")
        max_giocatori = int(info[1] or 30)
        min_portieri = int(info[2] or 0)
        budget = float(info[3] or 0)
        soglia = float(info[4] or budget)
        moltiplicatore = max(1.0, float(info[5] or 1))
        ruolo_classico = str(info[6] or "").strip().upper()
        ruolo_mantra = str(info[7] or "").strip().upper()

        # Non consente una seconda assegnazione dello stesso giocatore.
        cur.execute("""
            SELECT stato,assigned_team_id
            FROM league_players
            WHERE league_id=? AND player_id=?
            LIMIT 1
        """, (league_id, player_id))
        lp_old = cur.fetchone()

        if (
            lp_old
            and str(lp_old[0] or "").upper() == "ASSEGNATO"
            and lp_old[1] is not None
        ):
            raise ValueError("Il giocatore risulta già assegnato.")

        # Statistiche attuali della rosa del vincitore.
        cur.execute("""
            SELECT
                COUNT(*),
                COALESCE(SUM(COALESCE(lp.prezzo_assegnazione,0)),0),
                COALESCE(SUM(
                    CASE WHEN (
                        UPPER(COALESCE(pc.ruolo_classico,''))='P'
                        OR UPPER(COALESCE(pc.ruolo_mantra,'')) IN ('P','POR')
                    ) THEN 1 ELSE 0 END
                ),0)
            FROM league_players lp
            LEFT JOIN league_player_catalog pc
              ON pc.league_id=lp.league_id
             AND pc.player_id=lp.player_id
            WHERE lp.league_id=?
              AND lp.stato='ASSEGNATO'
              AND lp.assigned_team_id=?
        """, (league_id, team_id))
        stats = cur.fetchone() or (0,0,0)

        roster_count = int(stats[0] or 0)
        valore_attuale = float(stats[1] or 0)
        portieri_attuali = int(stats[2] or 0)

        if roster_count >= max_giocatori:
            raise ValueError("La rosa della squadra vincitrice è già completa.")

        is_portiere = (
            ruolo_classico == "P"
            or ruolo_mantra in ("P","POR")
        )
        slot_dopo = max(0, max_giocatori - (roster_count + 1))
        portieri_dopo = portieri_attuali + (1 if is_portiere else 0)
        portieri_mancanti = max(0, min_portieri - portieri_dopo)

        if slot_dopo < portieri_mancanti:
            raise ValueError("Vincolo minimo portieri non rispettabile.")

        nuovo_valore = round(valore_attuale + prezzo, 2)
        nuova_spesa = float(
            _spesa_effettiva_regole(
                nuovo_valore,
                soglia,
                moltiplicatore
            )
        )
        if nuova_spesa > budget + 1e-9:
            raise ValueError(
                f"Budget insufficiente: {nuova_spesa:.2f} su {budget:.2f}."
            )

        # Stato autorevole: UPSERT. Questo copre anche cataloghi/leghe
        # dove league_players non era stato inizializzato perfettamente.
        cur.execute("""
            INSERT INTO league_players (
                league_id,
                player_id,
                stato,
                assigned_team_id,
                prezzo_assegnazione,
                updated_at
            )
            VALUES (?,?,'ASSEGNATO',?,?,CURRENT_TIMESTAMP)
            ON CONFLICT(league_id,player_id)
            DO UPDATE SET
                stato='ASSEGNATO',
                assigned_team_id=excluded.assigned_team_id,
                prezzo_assegnazione=excluded.prezzo_assegnazione,
                updated_at=CURRENT_TIMESTAMP
        """, (
            league_id,
            player_id,
            team_id,
            prezzo
        ))

        # Rosa normalizzata.
        cur.execute("""
            INSERT INTO rosters (
                league_id,team_id,player_id,prezzo_acquisto,
                fonte,assigned_at,updated_at
            )
            VALUES (?,?,?,?,'AUCTION_FINAL',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
            ON CONFLICT(league_id,team_id,player_id)
            DO UPDATE SET
                prezzo_acquisto=excluded.prezzo_acquisto,
                fonte='AUCTION_FINAL',
                updated_at=CURRENT_TIMESTAMP
        """, (
            league_id,
            team_id,
            player_id,
            prezzo
        ))

        # Budget normalizzato.
        cur.execute("""
            INSERT INTO team_budgets (
                league_id,team_id,budget_impostato,
                valore_acquisti,spesa_effettiva,updated_at
            )
            VALUES (?,?,?,?,?,CURRENT_TIMESTAMP)
            ON CONFLICT(league_id,team_id)
            DO UPDATE SET
                valore_acquisti=excluded.valore_acquisti,
                spesa_effettiva=excluded.spesa_effettiva,
                updated_at=CURRENT_TIMESTAMP
        """, (
            league_id,
            team_id,
            budget,
            nuovo_valore,
            nuova_spesa
        ))

        # Storico.
        cur.execute("""
            INSERT INTO auction_assignment_history (
                league_id,player_id,team_id,prezzo,stato,
                assigned_by_user_id,assigned_at
            )
            VALUES (?,?,?,?,'ACTIVE',?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            player_id,
            team_id,
            prezzo,
            user_id
        ))

        # Chiude il lotto.
        cur.execute("""
            UPDATE auction_lots
            SET stato='ASSIGNED',
                assigned_team_id=?,
                final_price=?,
                closed_at=CURRENT_TIMESTAMP
            WHERE id=? AND league_id=? AND stato='CLOSING'
        """, (
            team_id,
            prezzo,
            lot_id,
            league_id
        ))

        # Libera la sessione asta.
        cur.execute("""
            UPDATE auction_sessions
            SET current_lot_id=NULL,
                stato='READY',
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=?
              AND current_lot_id=?
        """, (
            league_id,
            lot_id
        ))

        # Compatibilità ROSA legacy: aggiorna la tabella corretta del vincitore.
        tabelle_compat = []
        nome_upper = nome_team.strip().upper()

        if nome_upper == "IBBINI IDIOTA":
            tabelle_compat.append("giocatori")
        elif nome_upper == "GOSTOBAR":
            tabelle_compat.append("giocatori_gostobar")

        # Workspace multilega moderno, se già creato.
        tabelle_compat.append(
            f"giocatori_ml_l{league_id}_t{team_id}"
        )

        for tab_team in dict.fromkeys(tabelle_compat):
            try:
                cur.execute(
                    f"""
                    UPDATE {tab_team}
                    SET stato='MIO',
                        prezzo_acquisto=?,
                        ultimo_aggiornamento=CURRENT_TIMESTAMP
                    WHERE id=?
                    """,
                    (prezzo, player_id)
                )
            except Exception:
                # Il workspace può non esistere ancora; la fonte autorevole
                # resta league_players e la ROSA V146 la legge da lì.
                pass

        # Audit.
        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,team_id,azione,
                entita,entita_id,dettagli_json,created_at
            )
            VALUES (?,?,?,'PLAYER_ASSIGNED','PLAYER',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            user_id,
            team_id,
            str(player_id),
            json.dumps({
                "prezzo": prezzo,
                "team": nome_team,
                "lot_id": lot_id,
                "modalita": "ASTA_MISTA_V146"
            }, ensure_ascii=False)
        ))

        conn.commit()

        return {
            "player_id": player_id,
            "team_id": team_id,
            "team": nome_team,
            "prezzo": prezzo
        }

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise

    finally:
        _portal_close(conn)



def prossimo_giocatore_senza_lotto_v135(
    league_id, player_id, tipo_asta, call_id=None
):
    """Salta un giocatore senza creare o chiudere un lotto."""
    league_id = int(league_id)
    player_id = int(player_id)
    tipo_asta = str(tipo_asta or "").strip().upper()
    if tipo_asta == "A CHIAMATA":
        tipo_asta = "CHIAMATA"

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        # V196 FAST SKIP: un solo UPSERT, senza la DELETE accessoria usata
        # per le vere chiamate/lotti.
        cur.execute("""
            INSERT INTO auction_called_players (
                league_id,player_id,fonte,lot_id,
                called_by_user_id,called_at,updated_at,active
            )
            VALUES (?,?,'SKIPPED',NULL,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1)
            ON CONFLICT(league_id,player_id)
            DO UPDATE SET
                fonte='SKIPPED',
                lot_id=NULL,
                active=1,
                called_by_user_id=excluded.called_by_user_id,
                called_at=CURRENT_TIMESTAMP,
                updated_at=CURRENT_TIMESTAMP
        """, (
            league_id, player_id,
            int(st.session_state.get("auth_user_id") or 0)
        ))

        if tipo_asta in ("RANDOM","ALFABETICO"):
            cur.execute("""
                SELECT COALESCE(skipped_players_json,'[]')
                FROM auction_mode_state
                WHERE league_id=? LIMIT 1
            """, (league_id,))
            r = cur.fetchone()
            try:
                skipped = {int(x) for x in json.loads(r[0] if r else "[]")}
            except Exception:
                skipped = set()
            skipped.add(player_id)

            cur.execute("""
                INSERT INTO auction_mode_state (
                    league_id,skipped_players_json,updated_at
                )
                VALUES (?,?,CURRENT_TIMESTAMP)
                ON CONFLICT(league_id)
                DO UPDATE SET
                    skipped_players_json=excluded.skipped_players_json,
                    updated_at=CURRENT_TIMESTAMP
            """, (league_id, json.dumps(sorted(skipped))))

        elif tipo_asta == "CHIAMATA":
            if call_id is not None:
                cur.execute("""
                    UPDATE auction_calls
                    SET stato='SKIPPED',
                        handled_by_user_id=?,
                        handled_at=CURRENT_TIMESTAMP
                    WHERE id=? AND league_id=? AND stato='PENDING'
                """, (
                    int(st.session_state.get("auth_user_id") or 0),
                    int(call_id), league_id
                ))
            cur.execute("""
                UPDATE auction_mode_state
                SET call_turn_index=call_turn_index+1,
                    updated_at=CURRENT_TIMESTAMP
                WHERE league_id=?
            """, (league_id,))
        else:
            raise ValueError(
                "PROSSIMO GIOCATORE non previsto per questa modalità."
            )

        conn.commit()
        return True
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)



def giocatore_precedente_skippato_v189(league_id, tipo_asta):
    """
    Ripristina l'ultimo giocatore saltato con PROSSIMO GIOCATORE senza apertura lotto.
    Un giocatore che ha avuto un lotto non è ripristinabile da qui.
    """
    league_id = int(league_id)
    tipo_asta = str(tipo_asta or "").strip().upper()
    if tipo_asta not in ("RANDOM", "ALFABETICO"):
        raise ValueError("GIOCATORE PRECEDENTE è disponibile solo nelle modalità RANDOM/ALFABETICO.")

    conn = _portal_raw_connection()
    cur = conn.cursor()
    try:
        # V194 - conta lo stato CORRENTE dello skip, non eventuali vecchi lotti storici.
        # Se viene aperta una nuova asta sul giocatore, registra_giocatore_chiamato_v147
        # sovrascrive fonte=LOT e lot_id: da quel momento non è più richiamabile qui.
        cur.execute("""
            SELECT cp.player_id, COALESCE(g.nome,'')
            FROM auction_called_players cp
            JOIN league_players lp
              ON lp.league_id=cp.league_id
             AND lp.player_id=cp.player_id
             AND lp.stato='DISPONIBILE'
            LEFT JOIN league_player_catalog g
              ON g.league_id=cp.league_id
             AND g.player_id=cp.player_id
            WHERE cp.league_id=?
              AND cp.active=1
              AND UPPER(COALESCE(cp.fonte,''))='SKIPPED'
            ORDER BY cp.called_at DESC, cp.id DESC
            LIMIT 1
        """, (league_id,))
        row = cur.fetchone()
        if not row:
            raise ValueError("Non ci sono giocatori skippati richiamabili.")

        player_id = int(row[0])
        nome = str(row[1] or "")

        cur.execute("""
            SELECT COALESCE(skipped_players_json,'[]'),
                   COALESCE(random_queue_json,'[]')
            FROM auction_mode_state
            WHERE league_id=?
            LIMIT 1
        """, (league_id,))
        state = cur.fetchone() or ('[]','[]')
        try:
            skipped = {int(x) for x in json.loads(state[0] or '[]')}
        except Exception:
            skipped = set()
        try:
            random_queue = [int(x) for x in json.loads(state[1] or '[]')]
        except Exception:
            random_queue = []

        skipped.discard(player_id)

        # In RANDOM il ripristinato deve diventare davvero il prossimo, non solo
        # rientrare genericamente nella coda casuale.
        if tipo_asta == "RANDOM":
            random_queue = [x for x in random_queue if int(x) != player_id]
            random_queue.insert(0, player_id)

        cur.execute("""
            UPDATE auction_mode_state
            SET skipped_players_json=?,
                random_queue_json=?,
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=?
        """, (
            json.dumps(sorted(skipped)),
            json.dumps(random_queue),
            league_id
        ))

        # Lo skip viene annullato anche nello Storico/contatore.
        cur.execute("""
            UPDATE auction_called_players
            SET active=0,
                updated_at=CURRENT_TIMESTAMP
            WHERE league_id=?
              AND player_id=?
              AND UPPER(COALESCE(fonte,''))='SKIPPED'
        """, (league_id, player_id))

        cur.execute("""
            INSERT INTO audit_log (
                league_id,user_id,azione,entita,entita_id,
                dettagli_json,created_at
            )
            VALUES (?,?,'PLAYER_SKIP_UNDONE','PLAYER',?,?,CURRENT_TIMESTAMP)
        """, (
            league_id,
            int(st.session_state.get("auth_user_id") or 0),
            str(player_id),
            json.dumps({"nome": nome, "modalita": tipo_asta}, ensure_ascii=False)
        ))

        conn.commit()
        return {"player_id": player_id, "nome": nome}

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)



def _snapshot_navigazione_da_conn_v197(cur, league_id, tipo_asta, skipped, random_queue):
    """Build the RANDOM/ALFABETICO idle snapshot using the already-open connection."""
    league_id = int(league_id)
    tipo_asta = str(tipo_asta or "").strip().upper()

    cur.execute("""
        SELECT COUNT(*)
        FROM league_players
        WHERE league_id=? AND stato='DISPONIBILE'
    """, (league_id,))
    disponibili_count = int((cur.fetchone() or (0,))[0] or 0)

    out = {
        "tipo_asta": tipo_asta,
        "disponibili_count": disponibili_count,
        "turno": None,
        "pending": None,
        "prossimo": None,
        "precedente": None,
    }
    if disponibili_count <= 0:
        return out

    # ultimo skip ancora attivo: una query minimale, stessa connessione
    cur.execute("""
        SELECT cp.player_id,COALESCE(g.nome,'')
        FROM auction_called_players cp
        JOIN league_players lp
          ON lp.league_id=cp.league_id
         AND lp.player_id=cp.player_id
         AND lp.stato='DISPONIBILE'
        LEFT JOIN league_player_catalog g
          ON g.league_id=cp.league_id AND g.player_id=cp.player_id
        WHERE cp.league_id=?
          AND cp.active=1
          AND UPPER(COALESCE(cp.fonte,''))='SKIPPED'
        ORDER BY cp.called_at DESC,cp.id DESC
        LIMIT 1
    """, (league_id,))
    pr = cur.fetchone()
    if pr:
        out["precedente"] = {"player_id": int(pr[0]), "nome": str(pr[1] or "")}

    if tipo_asta == "ALFABETICO":
        # Fetch only until the first non-skipped available player.
        cur.execute("""
            SELECT g.player_id,COALESCE(g.nome,''),COALESCE(g.squadra,''),
                   COALESCE(g.ruolo_mantra,''),COALESCE(g.fvm_mantra,g.fvm,0)
            FROM league_players lp
            JOIN league_player_catalog g
              ON g.league_id=lp.league_id AND g.player_id=lp.player_id
            WHERE lp.league_id=? AND lp.stato='DISPONIBILE'
            ORDER BY g.nome COLLATE NOCASE,g.player_id
        """, (league_id,))
        for row in (cur.fetchall() or []):
            pid=int(row[0])
            if pid in skipped:
                continue
            out["prossimo"]={
                "player_id":pid,"nome":str(row[1] or ""),"squadra":str(row[2] or ""),
                "ruolo_mantra":str(row[3] or ""),"fvm":float(row[4] or 0),
            }
            break
        return out

    if tipo_asta == "RANDOM":
        cur.execute("""
            SELECT player_id
            FROM league_players
            WHERE league_id=? AND stato='DISPONIBILE'
        """, (league_id,))
        available={int(r[0]) for r in (cur.fetchall() or [])}
        selected=next(
            (pid for pid in random_queue if pid in available and pid not in skipped),
            None
        )
        if selected is None:
            candidates=[pid for pid in available if pid not in skipped]
            if candidates:
                import random
                random.shuffle(candidates)
                random_queue[:] = candidates
                selected=candidates[0]
                cur.execute("""
                    UPDATE auction_mode_state
                    SET random_queue_json=?,random_index=0,updated_at=CURRENT_TIMESTAMP
                    WHERE league_id=?
                """,(json.dumps(random_queue),league_id))
        if selected is not None:
            cur.execute("""
                SELECT player_id,COALESCE(nome,''),COALESCE(squadra,''),
                       COALESCE(ruolo_mantra,''),COALESCE(fvm_mantra,fvm,0)
                FROM league_player_catalog
                WHERE league_id=? AND player_id=?
                LIMIT 1
            """,(league_id,int(selected)))
            row=cur.fetchone()
            if row:
                out["prossimo"]={
                    "player_id":int(row[0]),"nome":str(row[1] or ""),
                    "squadra":str(row[2] or ""),"ruolo_mantra":str(row[3] or ""),
                    "fvm":float(row[4] or 0),
                }
    return out


def naviga_giocatore_fast_v197(league_id, tipo_asta, direzione, player_id=None, nome=""):
    """
    NEXT/PREV in una sola transazione/connessione.
    Prepara anche lo snapshot successivo: il rerender non deve interrogare il DB.
    """
    league_id=int(league_id)
    tipo_asta=str(tipo_asta or "").strip().upper()
    direzione=str(direzione or "").strip().upper()
    if tipo_asta not in ("RANDOM","ALFABETICO"):
        raise ValueError("Navigazione rapida disponibile solo per RANDOM/ALFABETICO.")

    conn=_portal_raw_connection()
    cur=conn.cursor()
    try:
        cur.execute("""
            SELECT COALESCE(skipped_players_json,'[]'),
                   COALESCE(random_queue_json,'[]')
            FROM auction_mode_state
            WHERE league_id=?
            LIMIT 1
        """,(league_id,))
        state=cur.fetchone() or ('[]','[]')
        try:
            skipped={int(x) for x in json.loads(state[0] or '[]')}
        except Exception:
            skipped=set()
        try:
            random_queue=[int(x) for x in json.loads(state[1] or '[]')]
        except Exception:
            random_queue=[]

        user_id=int(st.session_state.get("auth_user_id") or 0)

        if direzione=="NEXT":
            if player_id is None:
                raise ValueError("Giocatore corrente non valido.")
            player_id=int(player_id)

            # One authoritative UPSERT. A pure skip always clears stale lot_id.
            cur.execute("""
                INSERT INTO auction_called_players(
                    league_id,player_id,fonte,lot_id,called_by_user_id,
                    called_at,updated_at,active
                )
                VALUES (?,?,'SKIPPED',NULL,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1)
                ON CONFLICT(league_id,player_id)
                DO UPDATE SET fonte='SKIPPED',lot_id=NULL,active=1,
                              called_by_user_id=excluded.called_by_user_id,
                              called_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP
            """,(league_id,player_id,user_id))
            skipped.add(player_id)

        elif direzione=="PREV":
            # The active SKIPPED row is the stack top.
            cur.execute("""
                SELECT cp.player_id,COALESCE(g.nome,'')
                FROM auction_called_players cp
                JOIN league_players lp
                  ON lp.league_id=cp.league_id AND lp.player_id=cp.player_id
                 AND lp.stato='DISPONIBILE'
                LEFT JOIN league_player_catalog g
                  ON g.league_id=cp.league_id AND g.player_id=cp.player_id
                WHERE cp.league_id=? AND cp.active=1
                  AND UPPER(COALESCE(cp.fonte,''))='SKIPPED'
                ORDER BY cp.called_at DESC,cp.id DESC
                LIMIT 1
            """,(league_id,))
            row=cur.fetchone()
            if not row:
                raise ValueError("Non ci sono giocatori skippati richiamabili.")
            player_id=int(row[0])
            nome=str(row[1] or "")
            skipped.discard(player_id)
            cur.execute("""
                UPDATE auction_called_players
                SET active=0,updated_at=CURRENT_TIMESTAMP
                WHERE league_id=? AND player_id=?
                  AND UPPER(COALESCE(fonte,''))='SKIPPED'
            """,(league_id,player_id))
            if tipo_asta=="RANDOM":
                random_queue=[x for x in random_queue if int(x)!=player_id]
                random_queue.insert(0,player_id)
        else:
            raise ValueError("Direzione navigazione non valida.")

        cur.execute("""
            UPDATE auction_mode_state
            SET skipped_players_json=?,random_queue_json=?,updated_at=CURRENT_TIMESTAMP
            WHERE league_id=?
        """,(json.dumps(sorted(skipped)),json.dumps(random_queue),league_id))

        # Build the NEXT visible state before committing, using the SAME connection.
        snap=_snapshot_navigazione_da_conn_v197(
            cur,league_id,tipo_asta,skipped,random_queue
        )
        conn.commit()

        # One-shot snapshot: fragment rerender will make ZERO DB reads.
        st.session_state[f"_v197_nav_snapshot_{league_id}"]=snap
        st.session_state[f"_v197_skip_live_{league_id}"]=True
        invalida_cache_navigazione_asta_v196(league_id)
        st.session_state.pop("auctioneer_error",None)
        return {"player_id":player_id,"nome":nome,"snapshot":snap}

    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        _portal_close(conn)


