    # Se una vecchia pagina è rimasta in sessione, riallinea al contesto.
    pagine_consentite = {p[1] for p in PAGINE}
    if st.session_state.get("pagina") not in pagine_consentite:
        st.session_state["pagina"] = PAGINE[0][1]

